-- ============================================================================
-- [SDWxOWNER-PLANE-CRASH-FIX] SHARED "LOCAL PAWN UNSAFE TO MANIPULATE" GUARD
-- ----------------------------------------------------------------------------
-- ROOT CAUSE of the drop-plane crash: SpinEngine / CharSize / iPadView
-- all write to the LOCAL pawn's MESH + CAMERA. While the player is seated in the
-- drop plane (or any aircraft / vehicle), is attached to a transport actor, or is
-- mid freefall / parachute transition, the ENGINE owns that transform. Writing a
-- relative mesh rotation / scale / camera arm length on top of that attachment
-- fights the engine and produces a native use-after-free / transform assert ->
-- a hard crash right as the plane spawns the players.
--
-- This guard returns TRUE when the local pawn must NOT be touched. It only ever
-- trips on POSITIVE danger signals (never on "unknown"), so it can NEVER silently
-- disable a feature during normal play. Results are cached for a few ms so the
-- per-frame callers (SpinApply + the ReceiveTick hooks) stay allocation-free.
-- ============================================================================
do
    local _lpLastProbe  = -1000
    local _lpLastResult = false
    local _LP_TTL       = 0.04          -- 25 Hz probe; cheap for per-frame callers
    local _hsEverNumeric = false        -- once HealthStatus is proven readable, a nil
                                        -- value reliably means "pawn not fully spawned"

    -- Cheap class-name test used to confirm an attachment parent is a transport.
    -- [SDWxOWNER-PERF] Hoisted probes (closure-free). This runs from the per-frame FOV gate,
    -- so the old inline pcall(function() ... end) bodies created constant garbage.
    local _lpA, _lpHit = nil, false
    local function _lpCheckIsA()
        local a = _lpA
        if a.IsA then
            if a:IsA("Aircraft") or a:IsA("Vehicle") or a:IsA("Plane")
               or a:IsA("TransportAircraft") or a:IsA("TransportVehicle") then
                _lpHit = true
            end
        end
    end
    local function _lpCheckClass()
        local a = _lpA
        local cls = a.GetClass and a:GetClass()
        if cls and cls.GetName then
            local n = cls:GetName()
            if type(n) == "string" and (n:find("Aircraft") or n:find("Plane")
               or n:find("Vehicle") or n:find("Transport")) then _lpHit = true end
        end
    end
    local function _lpCheckFields()
        local a = _lpA
        if a.VehicleID or a.AircraftID or a.bIsVehicle == true
           or a.bIsAircraft == true then _lpHit = true end
    end
    local function _lpLooksTransport(actor)
        if not (actor and slua and slua.isValid and slua.isValid(actor)) then return false end
        _lpA = actor; _lpHit = false
        pcall(_lpCheckIsA)
        if _lpHit then return true end
        pcall(_lpCheckClass)
        if _lpHit then return true end
        pcall(_lpCheckFields)
        return _lpHit
    end

    -- [SDWxOWNER-PERF] Hoisted vehicle / attach-parent probes for _lpProbe (closure-free).
    local _lpCh2, _lpVeh = nil, nil
    local function _lpGetVeh() if _lpCh2.GetCurrentVehicle then _lpVeh = _lpCh2:GetCurrentVehicle() end end
    local function _lpGetVehField() _lpVeh = _lpCh2.CurrentVehicle end
    local _lpCh3, _lpParent = nil, nil
    local function _lpGetParent() if _lpCh3.GetAttachParentActor then _lpParent = _lpCh3:GetAttachParentActor() end end

    local function _lpProbe(ch)
        if not (ch and slua and slua.isValid and slua.isValid(ch)) then return true end

        -- (1) Dying / knocked / groggy -> mesh is mid-teardown.
        if ch.bIsDying == true or ch.bIsGroggy == true or ch.bIsGrogggy == true then return true end
        local hs = ch.HealthStatus
        if type(hs) == "number" then _hsEverNumeric = true end
        if _hsEverNumeric then
            -- 1 = knocked, 2 = dead; nil = pawn not fully spawned yet.
            if hs == 1 or hs == 2 or hs == nil then return true end
        end

        -- (2) Seated in a vehicle / aircraft (the drop plane reports here on many builds).
        local veh = nil
        _lpCh2 = ch; _lpVeh = nil
        pcall(_lpGetVeh)
        veh = _lpVeh
        if veh == nil then _lpCh2 = ch; _lpVeh = nil; pcall(_lpGetVehField); veh = _lpVeh end
        if veh and slua.isValid(veh) then return true end

        -- (3) Explicit in-vehicle / in-aircraft flags.
        if ch.bIsInVehicle == true or ch.bInVehicle == true
           or ch.bIsInAircraft == true or ch.bInAircraft == true
           or ch.bIsRidingVehicle == true then return true end

        -- (4) Freefall / parachute / skydive transition (engine owns the transform).
        if ch.bIsParachuting == true or ch.bIsParachute == true
           or ch.bIsSkydiving == true or ch.bIsFreefall == true
           or ch.bIsInFreefall == true or ch.bIsInAirDrop == true
           or ch.bIsOnParachute == true then return true end

        -- (5) Attached to a transport actor (plane) that is not our own mesh/root.
        local parent = nil
        _lpCh3 = ch; _lpParent = nil
        pcall(_lpGetParent)
        parent = _lpParent
        if parent and slua.isValid(parent) and parent ~= ch then
            if _lpLooksTransport(parent) then return true end
        end

        return false
    end

    -- [SDWxOWNER-PERF] Hoisted local-pawn resolution probes (closure-free).
    local _lpPawn = nil
    local function _lpGetPawnA()
        if GameplayData and GameplayData.GetPlayerCharacter then _lpPawn = GameplayData.GetPlayerCharacter() end
    end
    local function _lpGetPawnB()
        local pc = GameplayData and GameplayData.GetPlayerController and GameplayData.GetPlayerController()
        if pc and pc.GetPlayerCharacterSafety then _lpPawn = pc:GetPlayerCharacterSafety() end
    end

    -- [SDWxOWNER-PERF FIX #2] Per-actor short-TTL cache. Passing a pawn used to probe it
    -- UNCACHED on every call, so the per-frame ApplyiPadView caller re-ran 10+ native engine
    -- reflection checks (GetCurrentVehicle / IsA / GetClass / GetAttachParentActor ...) on EVERY
    -- single frame. The result is now memoised per actor for the same _LP_TTL window (25 Hz),
    -- which is far below the frame rate yet far above any real state transition. Weak keys so a
    -- despawned pawn is never retained.
    local _lpActorT = setmetatable({}, { __mode = "k" })
    local _lpActorR = setmetatable({}, { __mode = "k" })

    -- Public API. Pass a pawn to probe it (short per-actor TTL); pass nil to probe the
    -- cached local pawn (short TTL). Returns TRUE when it is UNSAFE to manipulate.
    function _G.SDW_LocalPawnUnsafe(ch)
        local now = os.clock()
        if ch ~= nil then
            local t = _lpActorT[ch]
            if t and (now - t) < _LP_TTL then return _lpActorR[ch] end
            local r = _lpProbe(ch)
            _lpActorT[ch] = now
            _lpActorR[ch] = r
            return r
        end
        if (now - _lpLastProbe) < _LP_TTL then return _lpLastResult end
        _lpLastProbe = now
        local pawn = nil
        _lpPawn = nil
        pcall(_lpGetPawnA)
        pawn = _lpPawn
        if not (pawn and slua and slua.isValid and slua.isValid(pawn)) then
            _lpPawn = nil
            pcall(_lpGetPawnB)
            pawn = _lpPawn
        end
        _lpLastResult = _lpProbe(pawn)
        return _lpLastResult
    end

    -- Convenience inverse + a hard reset (called on match change).
    function _G.SDW_SafeToManipulate(ch) return not _G.SDW_LocalPawnUnsafe(ch) end
    function _G.SDW_ResetUnsafeCache()
        _lpLastProbe = -1000; _lpLastResult = false
        -- [SDWxOWNER-PERF FIX #2] Drop the per-actor probe memo on match change.
        _lpActorT = setmetatable({}, { __mode = "k" })
        _lpActorR = setmetatable({}, { __mode = "k" })
    end
end

local function safeFind(s, ...)
    if type(s) ~= "string" then return nil end
    return s:find(...)
end
_G.safeFind = safeFind

local function LogError(ctx, err)
end

local function SafeToggle(key, fn)
    _G._ToggleCooldowns = _G._ToggleCooldowns or {}
    local now = os.time()
    local last = _G._ToggleCooldowns[key] or 0
    if now - last < 1 then return end
    _G._ToggleCooldowns[key] = now
    _G._ConfigDirty = true
    local ok, err = pcall(fn)
    if not ok then LogError("SafeToggle:"..tostring(key), err) end
    pcall(function() if _G.SaveModSettings then _G.SaveModSettings(true) end end)
end

