    _G.EXPIRE_DATE = EXPIRE_DATE
end


do
    local function GetConfigPaths(fileName)
        -- [SDWxOWNER-iOS] iOS paths first on iOS; Android paths skipped on iOS.
        local paths = {}
        local function add(p) paths[#paths + 1] = p end

        pcall(function()
            if Client and Client.ProjectSavedDir then
                local d = Client.ProjectSavedDir() or ""
                if d ~= "" then
                    if d:sub(-1) ~= "/" then d = d .. "/" end
                    add(d .. fileName)
                    add(d .. "Paks/" .. fileName)
                    add(d .. "SaveGames/" .. fileName)
                end
            end
        end)

        -- iOS sandbox (HOME/Documents/...) — always added; harmless on Android.
        pcall(function()
            if os and os.getenv then
                local h = os.getenv("HOME")
                if h and h ~= "" then
                    add(h .. "/Documents/ShadowTrackerExtra/Saved/Paks/" .. fileName)
                    add(h .. "/Documents/ShadowTrackerExtra/Saved/SaveGames/" .. fileName)
                    add(h .. "/Documents/ShadowTrackerExtra/Saved/Gamelet/logs/" .. fileName)
                    add(h .. "/ShadowTrackerExtra/Saved/SaveGames/" .. fileName)
                    add(h .. "/ShadowTrackerExtra/Saved/Gamelet/logs/" .. fileName)
                    add(h .. "/Library/ShadowTrackerExtra/Saved/SaveGames/" .. fileName)
                end
            end
        end)

        if not _G.SDW_IsIOS then
            add("//storage/emulated/0/Android/data/com.tencent.ig/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Paks/" .. fileName)
            add("//storage/emulated/0/Android/data/com.vng.pubgmobile/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Paks/" .. fileName)
            add("//storage/emulated/0/Android/data/com.pubg.krmobile/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Paks/" .. fileName)
            add("//storage/emulated/0/Android/data/com.rekoo.pubgm/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Paks/" .. fileName)
            add("//storage/emulated/0/Android/data/com.pubg.imobile/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Paks/" .. fileName)
        end

        add("/Documents/ShadowTrackerExtra/Saved/Paks/" .. fileName)
        add("/Documents/ShadowTrackerExtra/Saved/Paks/puffer_temp/" .. fileName)
        add("/com.tencent.ig/Documents/ShadowTrackerExtra/Saved/Paks/" .. fileName)
        add("/com.vng.pubgmobile/Documents/ShadowTrackerExtra/Saved/Paks/" .. fileName)
        add("/com.pubg.krmobile/Documents/ShadowTrackerExtra/Saved/Paks/" .. fileName)
        add("/com.rekoo.pubgm/Documents/ShadowTrackerExtra/Saved/Paks/" .. fileName)
        add("/com.pubg.imobile/Documents/ShadowTrackerExtra/Saved/Paks/" .. fileName)
        add("ShadowTrackerExtra/Saved/Paks/" .. fileName)
        add("../../ShadowTrackerExtra/Saved/Paks/" .. fileName)
        add("../../../ShadowTrackerExtra/Saved/Paks/" .. fileName)
        add("../../../../ShadowTrackerExtra/Saved/Paks/" .. fileName)
        add(fileName)
        return paths
    end

    _G.GetConfigPaths = GetConfigPaths
    local ConfigFileName = "sdwxowner_settings.txt"
    _G.LastConfigSaveStr = ""

    local function serializeVal(v)
        if type(v) == "string" then
            return string.format("%q", v)
        elseif type(v) == "boolean" or type(v) == "number" then
            return tostring(v)
        else
            return string.format("%q", tostring(v))
        end
    end

    _G._ConfigDirty = false
    _G.SaveModSettings = function(force)
        pcall(function()
            local data = "return {\nSDWConfig = {\n"
            for k, v in pairs(_G.SDWConfig or {}) do
                data = data .. "  [\"" .. tostring(k) .. "\"] = " .. serializeVal(v) .. ",\n"
            end
            data = data .. "},\nCustomTextData = {\n"
            if _G.SDWState and _G.SDWState.CustomTextData then
                for k, v in pairs(_G.SDWState.CustomTextData) do
                    data = data .. "  [\"" .. tostring(k) .. "\"] = " .. serializeVal(v) .. ",\n"
                end
            end
            data = data .. "}\n}"

            if not force and data == _G.LastConfigSaveStr then
                _G._ConfigDirty = false
                return
            end
            _G.LastConfigSaveStr = data

            local paths = GetConfigPaths(ConfigFileName)
            for _, path in ipairs(paths) do
                local file = io.open(path, "w")
                if file then
                    file:write(data)
                    file:close()
                    _G._ConfigDirty = false
                    break
                end
            end
        end)
    end

    _G.LoadModSettings = function()
        pcall(function()
            local paths = GetConfigPaths(ConfigFileName)
            local content = nil
            for _, path in ipairs(paths) do
                local file = io.open(path, "r")
                if file then
                    content = file:read("*a")
                    file:close()
                    if content and #content > 10 then
                        break
                    end
                end
            end
            if content and #content > 10 then
                local func = load(content)
                if func then
                    local okExec, savedData = pcall(func)
                    if okExec and savedData and type(savedData) == "table" then
                        if savedData.SDWConfig and type(savedData.SDWConfig) == "table" then
                            for k, v in pairs(savedData.SDWConfig) do
                                _G.SDWConfig[k] = v
                            end
                        end
                        if savedData.CustomTextData and type(savedData.CustomTextData) == "table" then
                            _G.SDWState.CustomTextData = _G.SDWState.CustomTextData or {}
                            for k, v in pairs(savedData.CustomTextData) do
                                _G.SDWState.CustomTextData[k] = v
                            end
                        end
                    end
                end
            end
        end)
        -- [SDWxOWNER-MIGRATION] Force "Ignore Knock" ON once (old default was broken);
        -- after that the user's choice is respected.
        if (tonumber(_G.SDWConfig.ConfigVersion) or 0) < 2 then
            _G.SDWConfig.SDWAimIgnoreKnock = true
            _G.SDWConfig.ConfigVersion = 2
            _G._ConfigDirty = true
        end
        -- [SDWxOWNER-MIGRATION] Aim speed default changed 15 -> 10. Applied once so existing
        -- saved configs (which stored the old 15 default) pick up the new default; afterwards the
        -- user's own slider choice is respected.
        if (tonumber(_G.SDWConfig.ConfigVersion) or 0) < 3 then
            local _curSpd = tonumber(_G.SDWConfig.SDWAimSpeed)
            if _curSpd == nil or _curSpd >= 15 then _G.SDWConfig.SDWAimSpeed = 10 end
            _G.SDWConfig.ConfigVersion = 3
            _G._ConfigDirty = true
        end
        -- [SDWxOWNER-MIGRATION] Enemy Counter text colour: base default is now Yellow (2) and
        -- the White (5) option was removed. Applied once so a saved White choice becomes Yellow;
        -- afterwards the user's own choice is respected.
        if (tonumber(_G.SDWConfig.ConfigVersion) or 0) < 4 then
            local _ctc = tonumber(_G.SDWConfig.CounterTextColor)
            if _ctc == nil or _ctc == 5 then _G.SDWConfig.CounterTextColor = 2 end
            _G.SDWConfig.ConfigVersion = 4
            _G._ConfigDirty = true
        end
        -- [SDWxOWNER-MIGRATION] Wallhack enemy colour: enemy visible + enemy behind
        -- (occluded) + bot visible now default to RED, so every enemy reads red out of the
        -- box. Applied once so a saved Green choice becomes Red; the user's own pick is
        -- respected afterwards.
        if (tonumber(_G.SDWConfig.ConfigVersion) or 0) < 5 then
            _G.SDWConfig.ColorEnemyWHVis = 0
            _G.SDWConfig.ColorEnemyWHOcc = 0
            _G.SDWConfig.ColorBotWHVis = 0
            _G.SDWConfig.ConfigVersion = 5
            _G._ConfigDirty = true
        end
        -- [SDWxOWNER-MIGRATION] Wallhack colours: VISIBLE enemies/bots now default to GREEN
        -- and INVISIBLE (occluded) enemies/bots to RED. Also re-enable the bullet-drop
        -- compensation by default so the aim lands a touch LOWER (pelvis), matching eg.lua
        -- (velocity lead stays OFF -> no side/right drift). Applied once; the user's own
        -- picks are respected afterwards.
        if (tonumber(_G.SDWConfig.ConfigVersion) or 0) < 6 then
            _G.SDWConfig.ColorEnemyWHVis = 3
            _G.SDWConfig.ColorEnemyWHOcc = 0
            _G.SDWConfig.ColorBotWHVis = 3
            _G.SDWConfig.ColorBotWHOcc = 0
            _G.SDWConfig.SDWAimDrop = true
            _G.SDWConfig.SDWAimLead = false
            _G.SDWConfig.ConfigVersion = 6
            _G._ConfigDirty = true
        end
        -- [SDWxOWNER-MIGRATION] Aim speed default raised 10 -> 15 and the ceiling is 20
        -- (range 5..20). The aim chain is single-chain (1x), so a saved old-default (10)
        -- picks up the new default and any saved value above the ceiling is clamped to 15;
        -- a custom value in range is respected afterwards.
        if (tonumber(_G.SDWConfig.ConfigVersion) or 0) < 7 then
            local _curSpd = tonumber(_G.SDWConfig.SDWAimSpeed)
            if _curSpd == nil or _curSpd == 10 or _curSpd > 20 then _G.SDWConfig.SDWAimSpeed = 15 end
            _G.SDWConfig.ConfigVersion = 7
            _G._ConfigDirty = true
        end
        -- [SDWxOWNER-MIGRATION] Aim bone default is now PELVIS (3), matching 1.lua
        -- (1 Chest, 2 Stomach, 3 Pelvis). Applied once so a saved old value picks up the
        -- pelvis default; the user's own pick is respected afterwards.
        if (tonumber(_G.SDWConfig.ConfigVersion) or 0) < 8 then
            _G.SDWConfig.SDWAimBone = 3
            _G.SDWConfig.ConfigVersion = 8
            _G._ConfigDirty = true
        end
        -- [SDWxOWNER-MIGRATION] Aim speed default lowered 20 -> 15. Applied once so a saved
        -- old-default (20) picks up the new default; a custom value is respected afterwards.
        if (tonumber(_G.SDWConfig.ConfigVersion) or 0) < 9 then
            local _curSpd = tonumber(_G.SDWConfig.SDWAimSpeed)
            if _curSpd == nil or _curSpd == 20 then _G.SDWConfig.SDWAimSpeed = 15 end
            _G.SDWConfig.ConfigVersion = 9
            _G._ConfigDirty = true
        end
        -- [SDWxOWNER-MIGRATION] v4 enemy counter size / position are now LOCKED to their
        -- defaults (the +/- controls were removed from BOTH menus on request). Applied once
        -- so any previously saved custom size / offset is reset to the default.
        if (tonumber(_G.SDWConfig.ConfigVersion) or 0) < 10 then
            _G.SDWConfig.EnemyCounterHDSize = 125
            _G.SDWConfig.EnemyCounterHDPosX = 0
            _G.SDWConfig.EnemyCounterHDPosY = -53
            _G.SDWConfig.ConfigVersion = 10
            _G._ConfigDirty = true
        end
        -- [SDWxOWNER-AIMBONE] Aim bone is LOCKED to PELVIS. The menu rows were removed
        -- and this unconditional assignment guarantees a saved/legacy value can never
        -- override it. 1 Chest, 2 Stomach, 3 Pelvis.
        _G.SDWConfig.SDWAimBone = 3
        -- [SDWxOWNER-MIGRATION] Aim speed default lowered to 10. Applied once so a saved
        -- old default picks up the new default; afterwards the user's own slider choice
        -- is respected.
        if (tonumber(_G.SDWConfig.ConfigVersion) or 0) < 11 then
            _G.SDWConfig.SDWAimSpeed = 10
            _G.SDWConfig.ConfigVersion = 11
            _G._ConfigDirty = true
        end
    end

    -- [SDWxOWNER-PERF FIX #2] Disk-I/O throttle. The old loop beat every 5 s and, whenever the
    -- config was dirty, performed a SYNCHRONOUS io.open/write/close on the game thread -- a save
    -- landing mid-match stalled the render thread (the recurring 5-second hitch). Now: (a) the beat
    -- is 30 s, and (b) a save only runs when the config is dirty AND the local player is NOT in an
    -- active match. Nothing is lost: the direct menu saves still write immediately, and any dirty
    -- flag that is waiting for the match to end is flushed on the first out-of-match beat.
    local function AutoSaveLoop()
        if _G._ConfigDirty and _G.SaveModSettings
           and not (_G.SDWState and _G.SDWState.MatchStarted) then
            pcall(_G.SaveModSettings, true)
        end
        local timerSet = false
        pcall(function()
            if _G.Game and _G.Game.AddGameTimer and not _G._MOD_EXPIRED then
                _G.Game:AddGameTimer(30.0, false, AutoSaveLoop)
                timerSet = true
            end
        end)
        if not timerSet then
            pcall(function()
                local ok, t = pcall(require, "common.time_ticker")
                if ok and t and t.AddTimerOnce and not _G._MOD_EXPIRED then
                    t.AddTimerOnce(30.0, AutoSaveLoop)
                end
            end)
        end
    end
    if not _G.ModConfigLoaded then _G.LoadModSettings(); AutoSaveLoop(); _G.ModConfigLoaded = true end

    _G.ReadLiveConfig = function()
        if _G.SaveModSettings then _G.SaveModSettings() end
    end


    _G.SaveSDWConfig = SaveSDWConfig
    _G.LoadSDWConfig = LoadSDWConfig
end

do
    local _CF_WORKER_URL = "https://sdw-vip.opjody65.workers.dev"
    local _LAST_LOOP_TIME = 0
