        end
    end)

    local function GK_GetPlayerMetadata(isVictory)
        local meta = {
            name = "SDWxOWNER User",
            uid = "Unknown",
            kills = _LOCAL_MATCH_KILLS or 0,
            rank = "Crown",
            isChicken = isVictory or false
        }

        pcall(function()
            local GameplayData = nil
            pcall(function() GameplayData = require("GameLua.GameCore.Data.GameplayData") end)
            local UIUtil = nil
            pcall(function() UIUtil = require("client.common.ui_util") end)

            local PC = (GameplayData and GameplayData.GetPlayerController and GameplayData.GetPlayerController())
                    or (UIUtil and UIUtil.GetPlayerController and UIUtil.GetPlayerController())
            local PS = (GameplayData and GameplayData.GetPlayerState and GameplayData.GetPlayerState())
                    or (PC and PC.PlayerState)
                    or (Client and Client.GetMyPlayerState and Client.GetMyPlayerState())
            local Char = (GameplayData and GameplayData.GetLocalCharacter and GameplayData.GetLocalCharacter())
                      or (PC and PC.Character)
                      or (Client and Client.GetLocalPlayerPawn and Client.GetLocalPlayerPawn())

            if DataMgr and DataMgr.roleData and DataMgr.roleData.nickName and DataMgr.roleData.nickName ~= "" then
                meta.name = tostring(DataMgr.roleData.nickName)
            elseif PS and PS.PlayerName and PS.PlayerName ~= "" then
                meta.name = tostring(PS.PlayerName)
            elseif DataPool and DataPool.Get and DataPool:Get("RoleName") then
                meta.name = tostring(DataPool:Get("RoleName"))
            elseif DataPool and DataPool.Get and DataPool:Get("PlayerName") then
                meta.name = tostring(DataPool:Get("PlayerName"))
            end

            if DataMgr and DataMgr.roleData and DataMgr.roleData.uid and DataMgr.roleData.uid ~= 0 and DataMgr.roleData.uid ~= "" then
                meta.uid = tostring(DataMgr.roleData.uid)
            elseif PS and PS.PlayerUID and PS.PlayerUID ~= "" and PS.PlayerUID ~= "0" then
                meta.uid = tostring(PS.PlayerUID)
            elseif PS and PS.PlayerKey and PS.PlayerKey ~= 0 then
                meta.uid = tostring(PS.PlayerKey)
            elseif DataPool and DataPool.Get and DataPool:Get("UID") then
                meta.uid = tostring(DataPool:Get("UID"))
            end

            local killCandidates = {
                _LOCAL_MATCH_KILLS,
                PS and PS.Kills,
                PC and PC.PlayerState and PC.PlayerState.Kills,
                Char and Char.PlayerState and Char.PlayerState.Kills,
                PS and PS.KillNum,
                PS and PS.KillCount,
                PS and PS.CurKillNum,
                PS and PS.TotalKillNum
            }
            for _, kVal in ipairs(killCandidates) do
                if kVal and tonumber(kVal) and tonumber(kVal) > 0 then
                    meta.kills = math.max(meta.kills, tonumber(kVal))
                end
            end
            if meta.kills == 0 and DataPool and DataPool.Get then
                local dpk = DataPool:Get("Kills") or DataPool:Get("KillNum") or DataPool:Get("CurKillNum")
                if dpk and tonumber(dpk) and tonumber(dpk) > 0 then meta.kills = tonumber(dpk) end
            end

            local bestSeg = 0
            pcall(function()
                local SeasonSystem = require("logic.season.logic_season")
                if SeasonSystem then
                    if SeasonSystem.segment then
                        if SeasonSystem.segment.team and SeasonSystem.segment.team.level then
                            bestSeg = math.max(bestSeg, tonumber(SeasonSystem.segment.team.level) or 0)
                        end
                        if SeasonSystem.segment.single and SeasonSystem.segment.single.level then
                            bestSeg = math.max(bestSeg, tonumber(SeasonSystem.segment.single.level) or 0)
                        end
                        if SeasonSystem.segment.double and SeasonSystem.segment.double.level then
                            bestSeg = math.max(bestSeg, tonumber(SeasonSystem.segment.double.level) or 0)
                        end
                    end
                    if SeasonSystem.GetMaxSegment then
                        local ms = tonumber(SeasonSystem.GetMaxSegment()) or 0
                        if ms > 101 then bestSeg = math.max(bestSeg, ms) end
                    end
                    if SeasonSystem.GetBestSegment then
                        local bs = tonumber(SeasonSystem.GetBestSegment()) or 0
                        if bs > 101 then bestSeg = math.max(bestSeg, bs) end
                    end
                end
            end)

            if bestSeg <= 101 and DataMgr then
                pcall(function()
                    if DataMgr.maxSegmentSquad and DataMgr.maxSegmentSquad.SegmentLevel then
                        bestSeg = math.max(bestSeg, tonumber(DataMgr.maxSegmentSquad.SegmentLevel) or 0)
                    end
                    if DataMgr.maxSegmentSolo and DataMgr.maxSegmentSolo.SegmentLevel then
                        bestSeg = math.max(bestSeg, tonumber(DataMgr.maxSegmentSolo.SegmentLevel) or 0)
                    end
                    if DataMgr.maxSegmentDuo and DataMgr.maxSegmentDuo.SegmentLevel then
                        bestSeg = math.max(bestSeg, tonumber(DataMgr.maxSegmentDuo.SegmentLevel) or 0)
                    end
                end)
            end

            local rankText = nil
            if bestSeg and bestSeg > 0 then
                pcall(function()
                    local FuncUtil = require("client.logic.common.func_util") or FuncUtil
                    if FuncUtil and FuncUtil.GetRankTableData then
                        local cfg = FuncUtil.GetRankTableData(bestSeg, DataMgr and DataMgr.season_id)
                        if cfg and cfg.Name and cfg.Name ~= "" then
                            rankText = tostring(cfg.Name)
                        end
                    end
                end)
            end

            if rankText and rankText ~= "" then
                meta.rank = rankText
            elseif bestSeg and bestSeg > 0 then
                if bestSeg >= 800 then
                    meta.rank = "Conqueror"
                elseif bestSeg >= 711 then
                    meta.rank = "Ace Dominator"
                elseif bestSeg >= 706 then
                    meta.rank = "Ace Master"
                elseif bestSeg >= 700 then
                    meta.rank = "Ace"
                elseif bestSeg >= 600 then
                    local sub = (bestSeg % 10)
                    local subNames = { [5]="I", [4]="II", [3]="III", [2]="IV", [1]="V" }
                    meta.rank = "Crown " .. (subNames[sub] or "V")
                elseif bestSeg >= 500 then
                    local sub = (bestSeg % 10)
                    local subNames = { [5]="I", [4]="II", [3]="III", [2]="IV", [1]="V" }
                    meta.rank = "Diamond " .. (subNames[sub] or "V")
                elseif bestSeg >= 400 then
                    local sub = (bestSeg % 10)
                    local subNames = { [5]="I", [4]="II", [3]="III", [2]="IV", [1]="V" }
                    meta.rank = "Platinum " .. (subNames[sub] or "V")
                elseif bestSeg >= 300 then
                    local sub = (bestSeg % 10)
                    local subNames = { [5]="I", [4]="II", [3]="III", [2]="IV", [1]="V" }
                    meta.rank = "Gold " .. (subNames[sub] or "V")
                elseif bestSeg >= 200 then
                    local sub = (bestSeg % 10)
                    local subNames = { [5]="I", [4]="II", [3]="III", [2]="IV", [1]="V" }
                    meta.rank = "Silver " .. (subNames[sub] or "V")
                elseif bestSeg >= 100 then
                    local sub = (bestSeg % 10)
                    local subNames = { [5]="I", [4]="II", [3]="III", [2]="IV", [1]="V" }
                    meta.rank = "Bronze " .. (subNames[sub] or "V")
                end
            else
                meta.rank = "Ace"
            end
        end)

        return meta
    end

    local function GK_InstallBattleResultHook()
        pcall(function()
            local mgr = _G.SubsystemMgr
            if not mgr then
                local ok, m = pcall(require, "GameLua.GameCore.Module.Subsystem.SubsystemMgr")
                if ok then mgr = m end
            end
            if not (mgr and mgr.Get) then return end
            local brss = mgr:Get("BattleResultSubSystem")
            if not brss or brss._sdw_result_hooked then return end
            local orig = brss.OnBattleResult
            if type(orig) ~= "function" then return end
            brss._sdw_result_hooked = true
            brss.OnBattleResult = function(self, result)
                pcall(function()
                    if result then
                        _G._SDW_LastResultReason = result.Reason
                        _G._SDW_LastResultWin    = (result.Reason == "win")
                        _G._SDW_LastResultTime   = os.time()
                    end
                end)
                return orig(self, result)
            end
        end)
    end

    -- [SDWxOWNER-TDM] Comprehensive win detector for BOTH Classic (BR) and TDM/Arena.
    --   * Classic/BR : Reason == "win", is_last_survive, bWin/is_win/IsWin, team_rank == 1.
    --   * TDM/Arena  : there is NO "chicken dinner" - the winner is the team with the
    --     higher score / the winning camp. The old detector only knew BR fields, so a
    --     TDM victory was never recognised and the auto-feedback never fired in TDM.
    --     We now scan every field name the game has been observed to use, plus the
    --     common nested sub-tables (data/result/info/tdm), so a TDM win is never missed.
    local function GK_ResultTableIsWin(d, depth)
        if type(d) ~= "table" then return false end
        depth = depth or 0

        -- ---- Direct win flags (BR + generic) ----
        if d.Reason == "win" or d.reason == "win" then return true end
        if d.is_last_survive == true or d.isLastSurvive == true then return true end
        if d.bWin == true or d.is_win == true or d.IsWin == true then return true end
        if d.b_win == true or d.isWinner == true or d.is_winner == true then return true end
        if d.win == true or d.isWin == true or d.IsVictory == true or d.isVictory == true then return true end

        -- ---- Rank 1 (BR team / solo) ----
        if tonumber(d.team_rank) == 1 or tonumber(d.peakgame_team_rank) == 1 then return true end
        if tonumber(d.rank) == 1 or tonumber(d.teamRank) == 1 or tonumber(d.team_rank_index) == 1 then return true end

        -- ---- TDM/Arena: winning camp / team id ----
        local winCamp = d.win_camp or d.winCamp or d.winner_camp or d.winnerCamp
                     or d.win_team or d.winTeam or d.winner_team or d.winnerTeam
                     or d.win_camp_id or d.winCampId or d.winner_camp_id
        local myCamp  = d.camp or d.my_camp or d.myCamp or d.camp_id or d.campId
                     or d.team_id or d.teamId or d.my_team or d.myTeam
                     or d.team or d.my_camp_id or d.myCampId
        if winCamp ~= nil and myCamp ~= nil and tostring(winCamp) == tostring(myCamp) then return true end

        -- ---- TDM/Arena: score comparison (my team vs enemy team) ----
        local myScore = tonumber(d.my_score or d.myScore or d.my_team_score or d.myTeamScore
                     or d.team_score or d.teamScore or d.score or d.my_kill_num or d.myKillNum)
        local opScore = tonumber(d.enemy_score or d.enemyScore or d.other_score or d.otherScore
                     or d.enemy_team_score or d.enemyTeamScore or d.op_score or d.opScore
                     or d.enemy_kill_num or d.enemyKillNum)
        if myScore and opScore and myScore > opScore then return true end

        -- ---- TDM/Arena: explicit result code ----
        local res = d.result or d.Result or d.battle_result or d.battleResult
                 or d.result_code or d.resultCode or d.game_result or d.gameResult
        if res == 1 or res == "1" or res == "win" or res == "WIN" or res == "victory" or res == "VICTORY" then return true end

        -- ---- Recurse one level into common container fields ----
        if depth < 2 then
            local subs = { d.data, d.Data, d.result, d.Result, d.info, d.Info, d.detail, d.Detail, d.tdm, d.TDM }
            -- NOTE: fixed count (10) - the '#' operator is undefined on tables with nil
            -- holes, so iterating by #subs would silently skip nested payloads.
            for i = 1, 10 do
                if type(subs[i]) == "table" and GK_ResultTableIsWin(subs[i], depth + 1) then return true end
            end
        end
        return false
    end

    local function GK_IsChickenDinner()
        local isWin = false
        pcall(function()
            -- 1) Cached reason from the BattleResultSubSystem hook (Classic / BR).
            local reason = _G._SDW_LastResultReason
            if reason == "win" then isWin = true end

            -- 2) Cached TDM/Arena result payload captured from the TDM events.
            if not isWin and type(_G._SDW_TDMResult) == "table" then
                if GK_ResultTableIsWin(_G._SDW_TDMResult) then isWin = true end
            end

            -- 3) BattleResultSubSystem result data (Classic / BR).
            if not isWin then
                local mgr = _G.SubsystemMgr
                if not mgr then
                    local ok, m = pcall(require, "GameLua.GameCore.Module.Subsystem.SubsystemMgr")
                    if ok then mgr = m end
                end
                local brss = mgr and mgr.Get and mgr:Get("BattleResultSubSystem")
                if brss and brss.GetBattleResultData then
                    local d = brss:GetBattleResultData()
                    if GK_ResultTableIsWin(d) then isWin = true end
                end
            end
        end)
        return isWin
    end

    local function GK_FastBase64Encode(data)
        if not data or #data == 0 then return "" end
        local b64str = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
        local b64 = {}
        for i = 0, 63 do b64[i] = string.byte(b64str, i + 1) end
        local eq = string.byte("=")
        local parts = {}
        local n_parts = 0
        local len = #data
        local i = 1
        while i <= len - 2 do
            local b1, b2, b3 = string.byte(data, i, i + 2)
            local n = b1 * 65536 + b2 * 256 + b3
            n_parts = n_parts + 1
            parts[n_parts] = string.char(b64[math.floor(n / 262144)], b64[math.floor(n / 4096) % 64], b64[math.floor(n / 64) % 64], b64[n % 64])
            i = i + 3
        end
        local remaining = len - i + 1
        if remaining == 2 then
            local b1, b2 = string.byte(data, i, i + 1)
            local n = b1 * 65536 + b2 * 256
            n_parts = n_parts + 1
            parts[n_parts] = string.char(b64[math.floor(n / 262144)], b64[math.floor(n / 4096) % 64], b64[math.floor(n / 64) % 64], eq)
        elseif remaining == 1 then
            local b1 = string.byte(data, i)
            local n = b1 * 65536
            n_parts = n_parts + 1
            parts[n_parts] = string.char(b64[math.floor(n / 262144)], b64[math.floor(n / 4096) % 64], eq, eq)
        end
        return table.concat(parts)
    end

    local function GK_PostToWorker(endpoint, bodyData, customHeaders, cb)
        pcall(function()
            if not _CF_WORKER_URL or _CF_WORKER_URL == "" then return end
            local http = nil
            if ModuleManager and ModuleManager.GetModule and ModuleManager.CommonModuleConfig and ModuleManager.CommonModuleConfig.http_manager then
                http = ModuleManager.GetModule(ModuleManager.CommonModuleConfig.http_manager)
            end
            local targetUrl = _CF_WORKER_URL .. endpoint
            local headers = {
                ["Content-Type"] = "text/plain",
                ["User-Agent"]   = "Mozilla/5.0 (Linux; Android 13) AppleWebKit/537.36 Chrome/120.0.0.0 Mobile Safari/537.36"
            }
            if customHeaders and type(customHeaders) == "table" then
                for k, v in pairs(customHeaders) do headers[k] = tostring(v) end
            end

            if http and http.Post then
                http:Post(targetUrl, headers, bodyData, nil, function(success, data, content, result)
                    if cb then pcall(cb, success, data, content, result) end
                end, 30)
            end
        end)
    end

    local function GK_BufferToString(buf)
        if not buf then return nil end
        if type(buf) == "string" and #buf > 50 then return buf end
        if type(buf) == "table" and #buf > 50 then
            local t = {}
            for i = 1, #buf do t[i] = string.char(buf[i]) end
            return table.concat(t)
        end
        local ok, s = pcall(function() return tostring(buf) end)
        if ok and s and #s > 50 then return s end
        return nil
    end

    local function GK_ReadScreenshotBytes(ShotPath)
        local candidates = {}
        if ShotPath and ShotPath ~= "" then
            table.insert(candidates, ShotPath)
            pcall(function()
                local bOk, BusinessHelper = pcall(import, "BusinessHelper")
                if bOk and BusinessHelper and BusinessHelper.GetMobileBasePath then
                    local abs = BusinessHelper.GetMobileBasePath(ShotPath)
                    if abs and abs ~= "" then table.insert(candidates, abs) end
                end
            end)
        end

        local sh = import("ScriptHelperClient") or ScriptHelperClient

        for _, path in ipairs(candidates) do
            if path and path ~= "" then
                local fileData = nil
                pcall(function()
                    local f = io.open(path, "rb")
                    if f then
                        fileData = f:read("*a")
                        f:close()
                    end
                end)
                if fileData and #fileData > 100 then return fileData, path end

                pcall(function()
                    if sh and sh.LoadFileToArrayByFullPath then
                        fileData = GK_BufferToString(sh.LoadFileToArrayByFullPath(path))
                    end
                    if (not fileData or #fileData == 0) and Client and Client.LoadFileToArrayByFullPath then
                        fileData = GK_BufferToString(Client.LoadFileToArrayByFullPath(path))
                    end
                end)
                if fileData and #fileData > 100 then return fileData, path end
            end
        end

        return nil, candidates[1] or ShotPath
    end

    local function GK_SendScreenshotToWorker(filePath, isVictory)
        pcall(function()
            if not filePath or filePath == "" then return end
            local fileData = GK_ReadScreenshotBytes(filePath)

            if not fileData or #fileData == 0 then
                return
            end

            local b64Payload = GK_FastBase64Encode(fileData)
            if not b64Payload or #b64Payload < 100 then
                return
            end

            local meta = GK_GetPlayerMetadata(isVictory)
            local metaHeaders = {
                ["X-Meta-Name"]    = meta.name,
                ["X-Meta-Uid"]     = meta.uid,
                ["X-Meta-Kills"]   = tostring(meta.kills),
                ["X-Meta-Rank"]    = meta.rank,
                ["X-Meta-Chicken"] = tostring(meta.isChicken)
            }

            GK_PostToWorker("/screenshot", b64Payload, metaHeaders, function(success, data, content, result)
            end)
        end)
    end

    local function GK_TakeAndSendScreenshot(isVictory)
        pcall(function()
            local ScreenshotMaker = import("ScreenshotMaker")
            if not ScreenshotMaker then return end

            local savedDir = Client and Client.ProjectSavedDir and Client.ProjectSavedDir() or ""
            local ts = os.time()
            local rawPath    = string.format("%sScreenshots/raw_%d_%d.jpg", savedDir, ts, math.random(100, 999))
            local scaledPath = string.format("%sScreenshots/sdw_fb_%d_%d.jpg", savedDir, ts, math.random(100, 999))

            local UIUtil = require("client.common.ui_util")
            local GameInstance = UIUtil and UIUtil.GetGameInstance and UIUtil.GetGameInstance()

            local function ProcessCapture(capturePath)
                local ticker = _cached_time_ticker or require("common.time_ticker")
                if not ticker or not ticker.AddTimerOnce then
                    GK_SendScreenshotToWorker(capturePath, isVictory)
                    return
                end

                ticker.AddTimerOnce(0.8, function()
                    local bResized = false
                    pcall(function()
                        if ScreenshotMaker.ResizePicture then
                            ScreenshotMaker.ResizePicture(capturePath, 0.6, scaledPath)
                            bResized = true
                        end
                    end)

                    if bResized then
                        ticker.AddTimerOnce(0.3, function()
                            local targetToSend = scaledPath
                            if not GK_ReadScreenshotBytes(scaledPath) then
                                targetToSend = capturePath
                            end
                            GK_SendScreenshotToWorker(targetToSend, isVictory)
                        end)
                    else
                        GK_SendScreenshotToWorker(capturePath, isVictory)
                    end
                end)
            end

            if GameInstance and GameInstance.EnginePreTick then
                GameInstance.EnginePreTick:Add(function()
                    local ShotPath = ScreenshotMaker.MakePictureByName(rawPath, true)
                    GameInstance.EnginePreTick:Clear()
                    ProcessCapture(ShotPath or rawPath)
                end)
            else
                local ShotPath = ScreenshotMaker.MakePictureByName(rawPath, true)
                ProcessCapture(ShotPath or rawPath)
            end
        end)
    end

    -- [SDWxOWNER] Periodic (non-victory) screenshot loop DISABLED. Screenshots are now sent
    -- ONLY on VICTORY, as EXACTLY ONE shot on the result screen (see GK_TriggerMatchEndFeedback).
    local function GK_ScreenshotLoop()
        -- no-op (intentionally disabled: exactly one screenshot per match only)
    end

    -- [SDWxOWNER-TDM-FEEDBACK] Best-effort "is the CURRENT match a TDM / Arena (non-BR)
    -- mode?" probe. TDM/Arena result screens have NO chicken dinner and the BR-only win
    -- detector cannot read their payload, so the victory gate used to swallow EVERY
    -- TDM/Arena match (auto-feedback never fired there). This probe is used ONLY to relax
    -- that gate for TDM/Arena. It is deliberately CONSERVATIVE: it returns true only on a
    -- positive non-BR signal (a TDM/Arena result event already fired, a TDM-shaped result
    -- payload, or a GameModeType that is not one of the BR types) and otherwise defaults
    -- to false, so a Classic defeat can still never trigger a shot.
    local function GK_IsTDMArenaMode()
        local isTDM = false
        pcall(function()
            -- (a) A TDM/Arena-specific result event already fired this match -> definitive.
            if _G._SDW_TDMEventFired then isTDM = true; return end
            -- (a2) A WOW/Creative result event already fired this match -> also non-BR.
            if _G._SDW_CreativeEventFired then isTDM = true; return end
            -- (b) The captured result payload has the TDM/Arena shape (team score / win camp).
            local d = _G._SDW_TDMResult
            if type(d) == "table" then
                if d.my_score or d.enemy_score or d.myScore or d.enemyScore
                   or d.win_camp or d.winCamp or d.camp or d.my_camp or d.camp_id
                   or d.team_score or d.teamScore or d.win_camp_id or d.winner_camp then
                    isTDM = true; return
                end
            end
            -- (c) GameModeType probe: BR is Typical / FourInOne / HeavyWeapon / War.
            local GMT = nil
            pcall(function()
                local CM = rawget(_G, "CGameMode")
                if CM then GMT = CM.GameModeType end
            end)
            if GMT == nil then
                pcall(function()
                    local GDP = package.loaded["GameLua.GameCore.Data.GameplayData"]
                    if not GDP then local ok; ok, GDP = pcall(require, "GameLua.GameCore.Data.GameplayData") end
                    local GS = GDP and GDP.GetGameState and GDP.GetGameState()
                    if GS then GMT = GS.GameModeType end
                end)
            end
            if GMT ~= nil then
                local E = nil
                pcall(function() E = import("EGameModeType") end)
                if E then
                    local isBR = (GMT == E.ETypicalGameMode or GMT == E.EFourInOneGameMode
                               or GMT == E.EHeavyWeaponGameMode or GMT == E.EWarGameMode)
                    if not isBR then isTDM = true end
                end
            end
        end)
        return isTDM
    end

    local function GK_TriggerMatchEndFeedbackCore(forceEnd)
        pcall(function()
            -- [SDWxOWNER-FEEDBACK-FIX] VICTORY-ONLY feedback for Classic/BR.
            -- [SDWxOWNER-TDM-FEEDBACK] TDM/Arena are ALSO supported: those modes have no
            --   chicken dinner, so when the trigger comes from a TDM/Arena result event
            --   (forceEnd) or the match is detected as TDM/Arena, the burst fires anyway
            --   (exactly what the mafia reference does). Classic defeats still never shoot.
            --   * Death / defeat is IGNORED completely  ->  ZERO screenshots.
            --   * On a win we send EXACTLY ONE shot: the 1st (MVP) result screen.
            -- An "armed" guard stops the several result events from stacking, and a
            -- short bounded retry makes sure the result reason is populated before we
            -- decide (so a real win is never missed and a loss never shoots).
            if _G._GK_BurstArmed or _G._GK_SentThisMatch then return end
            _G._GK_BurstArmed = true

            local ticker = _cached_time_ticker or require("common.time_ticker")

            local function Shot()
                pcall(function()
                    if not _G._GK_SentThisMatch then return end
                    if _G._GK_ResultActiveUntil and os.time() > _G._GK_ResultActiveUntil then return end
                    GK_TakeAndSendScreenshot(true)   -- always a victory shot
                end)
            end

            local tries = 0
            local function Decide()
                tries = tries + 1
                if _G._GK_SentThisMatch then _G._GK_BurstArmed = nil; return end

                -- Chicken dinner => isChicken true; any other result (death / defeat) => false.
                local isChicken = false
                pcall(function() isChicken = GK_IsChickenDinner() and true or false end)

                -- [SDWxOWNER-TDM-FEEDBACK] TDM/Arena fallback: fire even without a detected
                -- chicken dinner when the trigger is a TDM/Arena result event (forceEnd) or
                -- the match is a TDM/Arena mode. Classic/BR keeps the strict victory gate.
                local isTDM = forceEnd or GK_IsTDMArenaMode()
                if not isChicken and not isTDM then
                    -- Not (yet) a win: wait a little longer, but NEVER shoot on a loss.
                    if tries < 3 and ticker and ticker.AddTimerOnce then
                        ticker.AddTimerOnce(0.8, Decide)
                    else
                        _G._GK_BurstArmed = nil
                    end
                    return
                end

                local now = os.time()
                if _G._GK_LastVictoryBurstTime and (now - _G._GK_LastVictoryBurstTime < 15) then _G._GK_BurstArmed = nil; return end
                _G._GK_LastVictoryBurstTime = now
                _G._GK_SentThisMatch = true
                -- Result-screen window (generous so the single delayed shot can fire).
                _G._GK_ResultActiveUntil = now + 30
                _G._GK_BurstArmed = nil

                -- [SDWxOWNER-1SHOT] ONLY ONE screenshot per match now: the FIRST result
                -- screen (MVP / podium) -- the one that arrives first. The old 3.5s-delayed
                -- 2nd shot (All-QP / stats screen) is removed. Applies to ALL modes/maps
                -- (Classic/BR, TDM/Arena, WOW/Creative).
                Shot()   -- SHOT 1: 1st MVP / podium result screen (the ONLY shot)
            end

            -- First decision ~1.5s after the result (the 1st MVP screen is on display).
            if ticker and ticker.AddTimerOnce then
                ticker.AddTimerOnce(1.5, Decide)
            else
                Decide()
            end
        end)
    end

    -- [SDWxOWNER-TDM-FEEDBACK] Registered-callback wrapper. EventSystem passes the event
    -- payload as arguments to registered handlers, so the PUBLIC callback must take NO
    -- positional args (otherwise a truthy payload arg could be mistaken for `forceEnd` and
    -- a Classic defeat would shoot). The Classic path always calls with forceEnd = false;
    -- only the TDM/Arena event handler calls the Core with forceEnd = true.
    local function GK_TriggerMatchEndFeedback() GK_TriggerMatchEndFeedbackCore(false) end

    -- [SDWxOWNER-TDM] TDM/Arena result events may carry the result payload as one of
    -- their arguments. Capture the first table argument into _SDW_TDMResult (so the win
    -- detector can read the team score / win camp) and THEN run the normal victory trigger.
    local function GK_TDMResultEvent(...)
        local n = select('#', ...)
        local args = { ... }
        pcall(function()
            for i = 1, n do
                local a = args[i]
                if type(a) == "table" then
                    _G._SDW_TDMResult = a
                    break
                end
            end
        end)
        -- [SDWxOWNER-TDM-FEEDBACK] This handler is ONLY wired to TDM/Arena result events,
        -- so mark the match as TDM/Arena and FORCE the burst (there is no chicken dinner to
        -- detect on these modes -> the old victory gate swallowed them). Classic/BR never
        -- reaches here, so its victory-only behaviour is unchanged.
        _G._SDW_TDMEventFired = true
        GK_TriggerMatchEndFeedbackCore(true)
    end

    -- [SDWxOWNER-WOW-FEEDBACK] WOW / Creative / Custom-Room result handler. These modes
    -- (exactly like TDM/Arena) have NO chicken dinner and the BR-only win detector cannot
    -- read their settlement payload, so the victory gate used to swallow EVERY WOW/Creative
    -- match. This handler captures the settlement payload (so the win detector can read the
    -- score / camp fields) and then FORCES the burst -- which is exactly what the mafia
    -- reference does (it wires these same two events to an unconditional 3-shot burst).
    -- Classic/BR never reaches here, so its victory-only behaviour is completely unchanged.
    local function GK_CreativeResultEvent(...)
        local n = select('#', ...)
        local args = { ... }
        pcall(function()
            for i = 1, n do
                local a = args[i]
                if type(a) == "table" then
                    _G._SDW_TDMResult = a
                    break
                end
            end
        end)
        _G._SDW_CreativeEventFired = true
        GK_TriggerMatchEndFeedbackCore(true)
    end

    pcall(function()
        if EventSystem and EventSystem.registEvent then
            if EVENTID_BATTLE_RESULT_ENTER_PROTECT then
                EventSystem:registEvent(EVENTTYPE_ACCOUNT, EVENTID_BATTLE_RESULT_ENTER_PROTECT, GK_TriggerMatchEndFeedback)
            end
            if EVENTID_BATTLE_RESULT_BEGIN_PERFORMANCE then
                EventSystem:registEvent(EVENTTYPE_ACCOUNT, EVENTID_BATTLE_RESULT_BEGIN_PERFORMANCE, GK_TriggerMatchEndFeedback)
            end

            if EVENTID_GAMESTATE_ON_BATTLE_RESULT then
                EventSystem:registEvent(EVENTTYPE_STATE, EVENTID_GAMESTATE_ON_BATTLE_RESULT, GK_TriggerMatchEndFeedback)
            end
            if EVENTID_BATTLE_DS_FINISHED then
                EventSystem:registEvent(EVENTTYPE_ACCOUNT, EVENTID_BATTLE_DS_FINISHED, GK_TriggerMatchEndFeedback)
            end

            if EVENTID_BATTLE_RESULT_TDM_ANIM_FINISH then
                EventSystem:registEvent(EVENTTYPE_ACCOUNT, EVENTID_BATTLE_RESULT_TDM_ANIM_FINISH, GK_TDMResultEvent)
            end
            if EVENTID_BATTLE_RESULT_TDM_GET_RESULT_RSP then
                EventSystem:registEvent(EVENTTYPE_ACCOUNT, EVENTID_BATTLE_RESULT_TDM_GET_RESULT_RSP, GK_TDMResultEvent)
            end
            if EVENTID_BATTLE_RESULT_TDM_GET_MEDAL_CLOSE then
                EventSystem:registEvent(EVENTTYPE_ACCOUNT, EVENTID_BATTLE_RESULT_TDM_GET_MEDAL_CLOSE, GK_TDMResultEvent)
            end

            if EVENTID_CREATIVE_MATCH_SETTLEMENT then
                EventSystem:registEvent(EVENTTYPE_CREATIVE, EVENTID_CREATIVE_MATCH_SETTLEMENT, GK_CreativeResultEvent)
            end
            if EVENTID_CREATIVEMODE_GAMEOVER then
                EventSystem:registEvent(EVENTTYPE_CREATIVE, EVENTID_CREATIVEMODE_GAMEOVER, GK_CreativeResultEvent)
            end
        end
    end)

    _G._GK_ResetMatchKills = function()
        _LOCAL_MATCH_KILLS = 0
    end

    _G._GK_ResetFeedbackState = function()
        _LAST_LOOP_TIME = 0
        _LOCAL_MATCH_KILLS = 0
        _G._SDW_LastResultReason = nil
        _G._SDW_LastResultWin = nil
        _G._SDW_LastResultTime = nil
        _G._SDW_TDMResult = nil      -- [SDWxOWNER-TDM] drop last match's TDM payload
        _G._SDW_TDMEventFired = nil  -- [SDWxOWNER-TDM-FEEDBACK] re-arm the TDM/Arena detector
        _G._SDW_CreativeEventFired = nil  -- [SDWxOWNER-WOW-FEEDBACK] re-arm the WOW/Creative detector
        _G._GK_LastVictoryBurstTime = nil
        _G._GK_BurstArmed = nil      -- [SDWxOWNER] re-arm the victory burst for the new match
        _G._GK_SentThisMatch = nil   -- [SDWxOWNER] allow the single-shot burst next match
    end

    _G._GK_ScreenshotLoop = GK_ScreenshotLoop
    _G._GK_TriggerMatchEndFeedback = GK_TriggerMatchEndFeedback
    _G._GK_TakeAndSendScreenshot = GK_TakeAndSendScreenshot
    _G._GK_InstallBattleResultHook = GK_InstallBattleResultHook
    _G._GK_IsChickenDinner = GK_IsChickenDinner
    _G._GK_ResultTableIsWin = GK_ResultTableIsWin   -- [SDWxOWNER-TDM] exported for testing
    _G._GK_FeedbackStarted = false
end

do
    local mf, mx, mn = math.floor, math.max, math.min
    local function sr(m) local ok, mod = pcall(require, m); return ok and mod or nil end
    -- [SDWxOWNER-PERF FIX #3] Hoisted ggi() probes. ggi() is called several times per FPS beat and
    -- used to allocate two closures each call. Named statics + one upvalue slot => zero allocation.
    local _ggiDB, _ggiGI = nil, nil
    local function _ggiFromDB() _ggiGI = _ggiDB:GetGameInstance() end
    local function _ggiFromHUD() _ggiGI = slua_GameFrontendHUD and slua_GameFrontendHUD:GetGameInstance() end
    local function ggi()
        local db = sr("client.slua.umg.NewSetting.GraphicsNew.GraphicSettingDB")
        if db and db.GetGameInstance then
            _ggiDB = db; _ggiGI = nil
            local ok = pcall(_ggiFromDB)
            if ok and _ggiGI then return _ggiGI end
        end
        local ok, gp = pcall(require, "GameLua.GameCore.Data.GameplayData")
        if ok and gp and gp.GetGameInstance then local ok2, gi = pcall(gp.GetGameInstance); if ok2 and gi then return gi end end
        _ggiGI = nil
        local ok3 = pcall(_ggiFromHUD)
        if ok3 and _ggiGI then return _ggiGI end
        return nil
    end
    local function _apply165Body()
        local gi = ggi()
        if gi and gi.ExecuteCMD then gi:ExecuteCMD("t.MaxFPS", "165"); gi:ExecuteCMD("r.FrameRateLimit", "165") end
    end
    local function Apply165()
        -- [SDWxOWNER-LOCK] No FPS-unlock without a valid, unlocked key.
        if not (_G.SDW_IsAuthorized and _G.SDW_IsAuthorized()) then return end
        pcall(_apply165Body)
    end
    _G.SDW_Apply165 = Apply165
    _G.SDW_Force165 = function()
        if _G.SDWConfig and _G.SDWConfig.UnlockFPS165 == false then return end
        Apply165()
    end

    -- [SDWxOWNER-FPS FIX] Robust, lifecycle-INDEPENDENT FPS enforcement.
    local _fpsKSL
    local _fpsGraphics
    local _fpsBusy = false
    -- [SDWxOWNER-PERF FIX #3] Hoisted per-beat workers. SDW_EnforceFPS used to allocate FOUR
    -- closures per beat via pcall(function() ... end). These named statics + upvalue scratch slots
    -- make each beat allocation-free, so the FPS re-assert can never feed the GC.
    local _fpsGI, _fpsW = nil, nil
    local function _fpsApplyGraphics()
        if not _fpsGraphics then _fpsGraphics = sr("client.slua.logic.setting.logic_setting_graphics") end
        local g = _fpsGraphics
        if g then
            if type(g.SetFPS) == "function" then pcall(g.SetFPS, g, 8) end
            if type(g.ExecuteCMD) == "function" then
                pcall(g.ExecuteCMD, g, "t.MaxFPS", "165")
                pcall(g.ExecuteCMD, g, "r.FrameRateLimit", "165")
            end
        end
    end
    local function _fpsApplyGI()
        _fpsGI = ggi()
        if _fpsGI and _fpsGI.ExecuteCMD then
            _fpsGI:ExecuteCMD("t.MaxFPS", "165")
            _fpsGI:ExecuteCMD("r.FrameRateLimit", "165")
        end
    end
    local function _fpsApplyKSL()
        if not _fpsKSL then _fpsKSL = import("KismetSystemLibrary") end
        _fpsW = slua.getWorld()
        if _fpsKSL and _fpsW and _fpsKSL.ExecuteConsoleCommand then
            _fpsKSL.ExecuteConsoleCommand(_fpsW, "t.MaxFPS 165")
            _fpsKSL.ExecuteConsoleCommand(_fpsW, "r.FrameRateLimit 165")
        end
    end
    local function _fpsApplyVSync()
        _fpsGI = ggi()
        if _fpsGI and _fpsGI.ExecuteCMD then
            pcall(_fpsGI.ExecuteCMD, _fpsGI, "r.VSync", "0")
            pcall(_fpsGI.ExecuteCMD, _fpsGI, "r.VSyncMode", "0")
        end
        _fpsW = slua.getWorld()
        if _fpsKSL and _fpsW and _fpsKSL.ExecuteConsoleCommand then
            _fpsKSL.ExecuteConsoleCommand(_fpsW, "r.VSync 0")
            _fpsKSL.ExecuteConsoleCommand(_fpsW, "r.VSyncMode 0")
        end
    end
    local function SDW_EnforceFPS()
        if _G.SDWConfig and _G.SDWConfig.UnlockFPS165 == false then return end
        -- [SDWxOWNER-FPS FIX #2] Re-entrancy guard.
        if _fpsBusy then return end
        _fpsBusy = true
        -- [SDWxOWNER-FPS FIX #2] THE real reason the unlock died on Classic maps. t.MaxFPS alone is NOT enough.
        pcall(_fpsApplyGraphics)
        pcall(_fpsApplyGI)
        pcall(_fpsApplyKSL)
        -- [SDWxOWNER-FPS HARDEN] Force VSync OFF.
        pcall(_fpsApplyVSync)
        -- [SDWxOWNER-FPS FIX] Re-assert the graphics-module patch if the game dropped it
        -- (cheap: a cached require + type check; Patch165 self-validates).
        if _G.__165FPS_UNLOCK_PATCHED and _G.SDW_Patch165 then pcall(_G.SDW_Patch165) end
        _fpsBusy = false
    end
    _G.SDW_EnforceFPS = SDW_EnforceFPS

    -- [SDWxOWNER-FPS HARDEN] One-shot scheduler with multiple fallbacks.
    -- [SDWxOWNER-PERF FIX #3] Hoisted fallback probes. Args are passed through pcall (not captured
    -- in closures) so each beat is allocation-free AND re-entrancy-safe.
    local function _schedTryTicker(fn, delay)
        local t = require("common.time_ticker")
        if t and t.AddTimerOnce then t.AddTimerOnce(delay, fn); return true end
        return false
    end
    local function _schedTryTimer(fn, delay)
        local t = require("timer")
        if t and t.AddTimerOnce then t.AddTimerOnce(delay, fn); return true
        elseif t and t.SetGameTimer then t.SetGameTimer(delay, false, fn); return true end
        return false
    end
    local function _schedTryPC(fn, delay)
        local pc = _G.SDW_GetPC and _G.SDW_GetPC()
        if pc and pc.AddGameTimer then pc:AddGameTimer(delay, false, fn); return true end
        return false
    end
    local function SDW_FPS_Schedule(fn, delay)
        delay = delay or 2.0
        local ok, res = pcall(_schedTryTicker, fn, delay); if ok and res then return true end
        ok, res = pcall(_schedTryTimer, fn, delay);         if ok and res then return true end
        ok, res = pcall(_schedTryPC, fn, delay);            if ok and res then return true end
        return false
    end
    _G.SDW_FPS_Schedule = SDW_FPS_Schedule

    local function SDW_FPSLoop()
        -- [SDWxOWNER-FPS HARDEN] Heartbeat: the watchdog uses this to detect a dead
        -- loop and restart it, so the unlock can never stay off for a whole match.
        _G._SDW_FPSLastTick = os.time()
        if _G._MOD_EXPIRED or _G._SDW_LOCKED then _G._SDW_FPSLoopRunning = false; return end
        pcall(SDW_EnforceFPS)
        -- [SDWxOWNER-PERF FIX #3] Re-assert cadence relaxed 0.25 s -> 2.0 s. The unlock only needs
        -- to out-run the game's own settings reloads, not the render thread; at 2.0 s the console
        -- pushes are 8x rarer AND (with the hoisted workers above) allocate nothing, so the GC no
        -- longer pauses. The watchdog + StartMatchFeatures still revive the loop if it ever dies.
        local scheduled = SDW_FPS_Schedule(SDW_FPSLoop, 2.0)
        if not scheduled then
            -- Nothing could schedule us: mark the loop dead so the watchdog
            -- (or StartMatchFeatures) will try to bring it back.
            _G._SDW_FPSLoopRunning = false
        end
    end
    _G.SDW_FPSLoop = SDW_FPSLoop
    _G.SDW_StartFPSLoop = function()
        if _G._SDW_FPSLoopRunning then
            -- Already flagged running -- but if the heartbeat is stale the loop
            -- actually died, so fall through and restart it.
            -- [SDWxOWNER-PERF FIX #3] Threshold widened 2 -> 6 s to match the new 2.0 s beat
            -- (a legitimately-idle heartbeat can now be up to ~2 s old; < 6 s avoids a false
            -- "dead loop" that would double-schedule the chain).
            if _G._SDW_FPSLastTick and (os.time() - _G._SDW_FPSLastTick) < 6 then return end
        end
        _G._SDW_FPSLoopRunning = true
        _G._SDW_FPSLastTick = os.time()
        SDW_FPSLoop()
    end
    local function Patch165()
        if _G.__165FPS_UNLOCK_PATCHED then
            -- [SDWxOWNER-FPS FIX] Re-validate: if the game reloaded graphics settings, re-apply the FPS unlock.
            local g0 = sr("client.slua.logic.setting.logic_setting_graphics")
            if g0 and type(g0.SetFPS) == "function" and _G.__sdw165SetFPS and g0.SetFPS == _G.__sdw165SetFPS then return true end
            _G.__165FPS_UNLOCK_PATCHED = nil
        end
        local graphics = sr("client.slua.logic.setting.logic_setting_graphics")
        local fpsComp = sr("client.slua.umg.NewSetting.GraphicsNew.Comps.GSC_FPS")
        local fpsFT = sr("client.slua.umg.NewSetting.GraphicsNew.Comps.GSC_FPSFT")
        local db = sr("client.slua.umg.NewSetting.GraphicsNew.GraphicSettingDB")
        local found = false
        if graphics and type(graphics.SetFPS) == "function" then
            found = true
            if not graphics.__original_SetFPS then graphics.__original_SetFPS = graphics.SetFPS end
            local orig = graphics.__original_SetFPS
            -- [SDWxOWNER-FPS FIX] Force 165 not only for level 8 but whenever the "Unlock 165 FPS" toggle is ON.
            graphics.SetFPS = function(self, level)
                pcall(orig, self, level)
                local unlock = not (_G.SDWConfig and _G.SDWConfig.UnlockFPS165 == false)
                if level == 8 or unlock then
                    pcall(function() if self and self.ExecuteCMD then self:ExecuteCMD("t.MaxFPS", "165"); self:ExecuteCMD("r.FrameRateLimit", "165") end end)
                    if _G.SDW_EnforceFPS then pcall(_G.SDW_EnforceFPS) end
                end
            end
            _G.__sdw165SetFPS = graphics.SetFPS
        end
        if fpsComp and fpsComp.__inner_impl then
            found = true
            local impl = fpsComp.__inner_impl
            if not impl.__165patched then
                impl.GetMaxFPSLevel = function() return 8, 8 end
                impl.InitRealSupportFPS = function(self) local t = {}; for i = 1, 8 do t[i] = {true, true} end; if db and db.RealSupportFPS then pcall(function() db:UpdateUIData(db.RealSupportFPS, t, false) end) end; return t end
                impl.UpdateSelectedFPSState = function(self, level)
                    local fpsMap = {[2]=20,[3]=25,[4]=30,[5]=40,[6]=60,[7]=90,[8]=120}; local UIRoot = self.UIRoot; if not UIRoot then return end
                    for i = 2, 8 do local nn = "NodeFps" .. tostring(fpsMap[i] or 120); local node = UIRoot[nn]; if slua.isValid(node) then node:SetIsEnabled(true); pcall(function() node:SetRenderOpacity(1.0) end); local sw = UIRoot["WidgetSwitcher_" .. i]; if slua.isValid(sw) then sw:SetActiveWidgetIndex(i == level and 0 or 1) end end end
                end
                impl.__165patched = true
            end
        end
        if fpsFT and fpsFT.__inner_impl and db then
            found = true
            local impl = fpsFT.__inner_impl
            if not impl.__165patched then
                local MIN_FPS, MAX_FPS, STEP = 90, 165, 5
                local function clamp(v) return mx(MIN_FPS, mn(MAX_FPS, v)) end
                impl.ShowOrHide = function(self) pcall(function() self:SelfHitTestInvisible() end); if self.InitFPSFTSwitch then pcall(self.InitFPSFTSwitch, self) end end
                impl.InitFPSFTSwitch = function(self) if not db then return end; local on = db:GetUIData(db.FPSFineTuneSwitch); local UIRoot = self.UIRoot; if not UIRoot then return end; if UIRoot.Setting_Switch then pcall(function() UIRoot.Setting_Switch:SetSwitcherEnable2(on, true) end) end; if UIRoot.CanvasPanel_8 then pcall(function() self:SetWidgetVisible(UIRoot.CanvasPanel_8, on) end) end; if UIRoot.WidgetSwitcher_0 then pcall(function() UIRoot.WidgetSwitcher_0:SetActiveWidgetIndex(2) end) end; if self.InitFPSFTValue165 then pcall(self.InitFPSFTValue165, self) end end
                impl.InitFPSFTValue165 = function(self) if not db then return end; local UIRoot = self.UIRoot; if not UIRoot then return end; local on = db:GetUIData(db.FPSFineTuneSwitch); local val = on and (db:GetUIData(db.FPSFineTuneNum) or 165) or 165; local slider = UIRoot.Slider_screen3; local progress = UIRoot.ProgressBar_screen3; local textLabel = UIRoot.Veihclescreen3; if not (slider and progress and textLabel) then return end; if on then pcall(function() slider:SetLocked(false) end); pcall(function() progress:SetFillColorAndOpacity(FLinearColor(1,1,1,1)) end); pcall(function() slider:SetSliderHandleColor(FLinearColor(1,1,1,1)) end) else pcall(function() slider:SetLocked(true) end); pcall(function() progress:SetFillColorAndOpacity(FLinearColor(1,0.625,0.6,1)) end); pcall(function() slider:SetSliderHandleColor(FLinearColor(1,0.625,0.6,1)) end) end; local norm = (val - MIN_FPS) / (MAX_FPS - MIN_FPS); pcall(function() textLabel:SetText(tostring(val) .. "%") end); pcall(function() slider:SetValue(norm) end); pcall(function() progress:SetPercent(norm) end) end
                impl.OnFPSFTValueChange3 = function(self, val) if not db then return end; pcall(function() db:UpdateUIData(db.FPSFineTuneNum, val); if self.InitFPSFTValue165 then pcall(self.InitFPSFTValue165, self) end; local parent = self.GetParentUI and self:GetParentUI(); if parent and parent.SetDirty then pcall(function() parent:SetDirty(true) end) end; local gi = ggi(); if gi then gi:ExecuteCMD("t.MaxFPS", tostring(val)); gi:ExecuteCMD("r.FrameRateLimit", tostring(val)) end end) end
                impl.OnFPSFTSliderValueChange3 = function(self, nv) if not db then return end; if not db:GetUIData(db.FPSFineTuneSwitch) then return end; local raw = mf(MIN_FPS + (MAX_FPS - MIN_FPS) * nv); raw = mf(raw / STEP) * STEP; self:OnFPSFTValueChange3(clamp(raw)) end
                impl.OnFPSFTAdd3 = function(self) local cur = (db and db:GetUIData(db.FPSFineTuneNum)) or MIN_FPS; self:OnFPSFTValueChange3(mn(MAX_FPS, cur + STEP)) end
                impl.OnFPSFTMinus3 = function(self) local cur = (db and db:GetUIData(db.FPSFineTuneNum)) or MIN_FPS; self:OnFPSFTValueChange3(mx(MIN_FPS, cur - STEP)) end
                impl.OnFPSFTAdd = impl.OnFPSFTAdd3; impl.OnFPSFTMinus = impl.OnFPSFTMinus3; impl.OnFPSFTSliderValueChange = impl.OnFPSFTSliderValueChange3; impl.__165patched = true
            end
        end
        if found then _G.__165FPS_UNLOCK_PATCHED = true end
        return found
    end
    _G.SDW_Patch165 = Patch165
    Patch165()
    if not (_G.SDWConfig and _G.SDWConfig.UnlockFPS165 == false) then Apply165() end
    if not _G.__165FPS_UNLOCK_PATCHED then
        local tries = 0
        local function retry()
            tries = tries + 1
            if Patch165() then
                if not (_G.SDWConfig and _G.SDWConfig.UnlockFPS165 == false) then Apply165() end
                return
            end
            if tries < 30 then pcall(function() local ok, t = pcall(require, "common.time_ticker"); if ok and t and t.AddTimerOnce then t.AddTimerOnce(1.0, retry) end end) end
        end
        pcall(function() local ok, t = pcall(require, "common.time_ticker"); if ok and t and t.AddTimerOnce then t.AddTimerOnce(1.0, retry) end end)
    end
end


do
    local _ENV_ONCE_DONE = false
    local ipadViewOrigCache = setmetatable({}, { __mode = "k" })
    -- [SDWxOWNER-FIX Ocean Odyssey] Robust camera resolution.
    local _ipadCamCls
    -- [SDWxOWNER-PERF] Hoisted class-based camera probe (closure-free; runs every frame).
    local _ipadResChar, _ipadResCam = nil, nil
    local function _ipadResolveByClass()
        if not _ipadCamCls then _ipadCamCls = import("CameraComponent") or import("/Script/Engine.CameraComponent") end
        if _ipadCamCls and type(_ipadResChar.GetComponentByClass) == "function" then
            local c = _ipadResChar:GetComponentByClass(_ipadCamCls)
            if Valid(c) then _ipadResCam = c end
        end
    end
    local function _SDW_ResolveCam(char)
        if not Valid(char) then return nil end
        local cam = char.ThirdPersonCameraComponent
        if Valid(cam) then return cam end
        cam = char.CameraComponent
        if Valid(cam) then return cam end
        cam = char.FirstPersonCameraComponent
        if Valid(cam) then return cam end
        _ipadResChar = char; _ipadResCam = nil
        pcall(_ipadResolveByClass)
        if _ipadResCam then cam = _ipadResCam end
        return cam
    end

    -- [SDWxOWNER-PERF PHASE2] Allocation-free per-frame FOV enforcement.
    -- The iPad FOV is re-asserted EVERY frame (0.004s timer + ReceiveTick hook), so this
    -- function is a genuine HOT PATH. The old version allocated 2-5 pcall() closures on
    -- every single call, which created constant GC churn -> stutter. All closures are now
    -- created ONCE here and driven through hoisted scratch variables, so the steady-state
    -- path allocates NOTHING (zero garbage per frame). Behaviour is byte-for-byte identical.
    local _ipadCurChar = nil
    local _ipadAiming = false
    local function _ipadReadAiming() _ipadAiming = _ipadCurChar and _ipadCurChar.bIsTargeting end
    local _ipadW = nil
    local _ipadWV = 0
    local function _ipadSetCamFov()    _ipadW.FieldOfView = _ipadWV end
    local function _ipadSetCamDefFov() _ipadW.DefaultFOV = _ipadWV end
    local function _ipadSetMgrDefFov() _ipadW.DefaultFOV = _ipadWV end
    -- [SDWxOWNER-PERF] Hoisted camera-manager fallback probe (closure-free; runs every frame).
    local _ipadMgrPC, _ipadMgr = nil, nil
    local function _ipadResolveCamMgr()
        local GS = GameplayStatics or import("GameplayStatics")
        if GS and GS.GetPlayerCameraManager then _ipadMgr = GS.GetPlayerCameraManager(_ipadMgrPC, 0) end
    end

    local function _ipadBody()
        local pc = GameplayData.GetPlayerController(); if not Valid(pc) then return end
        local char = pc:GetPlayerCharacterSafety(); if not Valid(char) then return end
        -- [SDWxOWNER-PLANE-CRASH FIX] Never fight the engine for camera FOV while the local
        -- pawn is in the drop plane / aircraft / vehicle / freefall. The plane owns the camera
        -- there; writing FOV to it is the classic drop-phase crash. Re-asserts on landing.
        if _G.SDW_LocalPawnUnsafe and _G.SDW_LocalPawnUnsafe(char) then return end
        local cam = _SDW_ResolveCam(char)
        local camMgr = pc.PlayerCameraManager
        if not Valid(camMgr) then
            _ipadMgrPC = pc; _ipadMgr = nil
            pcall(_ipadResolveCamMgr)
            camMgr = _ipadMgr
        end
        if not Valid(cam) and not Valid(camMgr) then return end

        if (not _G.SDWConfig.iPadViewEnabled) or not (_G.SDW_IsAuthorized and _G.SDW_IsAuthorized()) then
            local o = ipadViewOrigCache[char]
            if o then
                if Valid(cam) and o.fov ~= nil then _ipadW = cam; _ipadWV = o.fov; pcall(_ipadSetCamFov) end
                if Valid(camMgr) and o.defFov ~= nil then _ipadW = camMgr; _ipadWV = o.defFov; pcall(_ipadSetMgrDefFov) end
            end
            return
        end

        if not ipadViewOrigCache[char] then
            ipadViewOrigCache[char] = {
                fov = (Valid(cam) and cam.FieldOfView) or 90,
                defFov = (Valid(camMgr) and camMgr.DefaultFOV) or nil,
            }
        end

        _ipadCurChar = char
        _ipadAiming = false
        pcall(_ipadReadAiming)
        if _ipadAiming then return end

        local targetFov = _G.SDWConfig.iPadViewFOV or 110
        -- [SDWxOWNER-PERF PHASE2] Clamp into the safe 100..150 window so a hand-edited or
        -- legacy saved config can never push an out-of-range FOV into the engine.
        if targetFov < 100 then targetFov = 100 elseif targetFov > 150 then targetFov = 150 end
        _ipadWV = targetFov
        -- [SDWxOWNER-BLINK FIX] The component writes stay change-gated (cheap, no churn), but
        -- the camera-manager SetFOV is re-asserted EVERY frame (last-write-wins). SetFOV is the
        -- authoritative camera-manager call, so re-issuing it each frame guarantees the rendered
        -- FOV can never fall back to the game default -> no blink. Cost: one native call/frame.
        if Valid(cam) then
            if cam.FieldOfView ~= targetFov then _ipadW = cam; pcall(_ipadSetCamFov) end
            if cam.DefaultFOV ~= nil and cam.DefaultFOV ~= targetFov then _ipadW = cam; pcall(_ipadSetCamDefFov) end
        end
        if Valid(camMgr) then
            if camMgr.DefaultFOV ~= targetFov then _ipadW = camMgr; pcall(_ipadSetMgrDefFov) end
            if type(camMgr.SetFOV) == "function" then pcall(camMgr.SetFOV, camMgr, targetFov, 0.0) end
        end
    end

    local function ApplyiPadView() pcall(_ipadBody) end


    _G.ApplyiPadView = ApplyiPadView
    -- [SDWxOWNER-FIX Ocean Odyssey] Per-frame FOV enforcement via the character's
    -- ReceiveTick (runs every engine frame, in step with the game's own camera update),
    -- so the iPad FOV can never fall out of step and beat against the game -> no rapid
    -- zoom. This is the same proven per-frame hook pattern used by the TPP/spin code.
    _G.SDW_InstalliPadTick = function(char)
        pcall(function()
            if not (char and slua and slua.isValid and slua.isValid(char)) then return end
            _G._SDW_iPadTicked = _G._SDW_iPadTicked or setmetatable({}, { __mode = "k" })
            if _G._SDW_iPadTicked[char] then return end
            local orig = char.ReceiveTick
            -- [SDWxOWNER-BLINK FIX] Only mark as installed AFTER a successful wrap. The old
            -- code set the marker first, so when ReceiveTick was momentarily absent (a freshly
            -- spawned pawn) the hook was never installed and the FOV silently fell back to the
            -- slow 0.01s timer, which beats against the game's per-frame FOV writes -> blink.
            if type(orig) ~= "function" then return end
            local wrapper = function(self, d)
                pcall(orig, self, d)
                if _G.SDWConfig and _G.SDWConfig.iPadViewEnabled and _G.ApplyiPadView then
                    -- [SDWxOWNER-PERF] Stamp the frame so the 0.004s hold timer can skip its
                    -- redundant apply while this hook (the authoritative per-frame last-write)
                    -- is driving the FOV.
                    _G._SDW_iPadHookT = os.clock()
                    pcall(_G.ApplyiPadView)
                end
            end
            -- [SDWxOWNER-FIX Ocean Odyssey] Stay transparent to the Spin engine's ReceiveTick
            -- ownership check: mirror its marker so it never re-wraps (which would double-drive
            -- the spin) merely because our wrapper now sits on top of its wrapper.
            wrapper._SDW_SPIN_WRAP = orig._SDW_SPIN_WRAP
            char.ReceiveTick = wrapper
            _G._SDW_iPadTicked[char] = true
        end)
    end
    _G.SDW_EnsureiPadHold = function()
        pcall(function()
            if not (_G.SDWConfig and _G.SDWConfig.iPadViewEnabled) then return end
            local pc = GameplayData.GetPlayerController()
            if not (Valid(pc) and pc.AddGameTimer) then return end
            -- [SDWxOWNER-FIX Ocean Odyssey] Install the per-frame FOV hook on the current
            -- pawn (idempotent) so the FOV is re-asserted every frame, not just on the timer.
            pcall(function()
                local ch = pc:GetPlayerCharacterSafety()
                if Valid(ch) and _G.SDW_InstalliPadTick then _G.SDW_InstalliPadTick(ch) end
            end)
            -- [SDWxOWNER-FIX] Re-arm the hold when the owning controller changes or the hold timer stops beating.
            local now = os.clock()
            local ownerChanged = (_G._SDW_iPadTimerOwner ~= pc)
            local stale = (not _G._SDW_iPadHoldBeat) or (now - _G._SDW_iPadHoldBeat > 2.0)
            if _G._SDW_iPadTimer and not ownerChanged and not stale then return end
            _G._SDW_iPadTimerOwner = pc
            _G._SDW_iPadHoldBeat = now
            -- [SDWxOWNER-FIX Ocean Odyssey] Re-assert the FOV EVERY FRAME, not every 0.25s.
            -- In the Ocean Odyssey event the game rewrites the camera FOV on every frame;
            -- our old 0.25s re-assert BEAT against it (0.25s period) and produced the rapid
            -- zoom in/out the user saw. Writing at the same (per-frame) rate makes our value
            -- the last write of each frame -> the FOV stays locked at the slider value.
            -- [SDWxOWNER-PERF] This standalone AddGameTimer is a FALLBACK for the rare case
            -- where the ReceiveTick hook could not be installed (a pawn whose ReceiveTick was
            -- momentarily absent). The guard below skips the apply entirely while the
            -- authoritative per-frame hook is beating, so this timer costs almost nothing on
            -- a healthy frame; it stays at the full per-frame rate so the Ocean Odyssey FOV
            -- guarantee is never lost. (iPad fix preserved.)
            _G._SDW_iPadTimer = pc:AddGameTimer(0.01, true, function()
                _G._SDW_iPadHoldBeat = os.clock()
                if _G.SDWConfig and _G.SDWConfig.iPadViewEnabled and _G.ApplyiPadView then
                    -- [SDWxOWNER-PERF] Skip the redundant per-frame apply when the ReceiveTick
                    -- hook already enforced the FOV this frame (the hook is the authoritative
                    -- last-write of the frame). The timer still beats at the per-frame rate, so
                    -- if the hook is ever absent on the current pawn it stays a full-rate
                    -- fallback -> the Ocean Odyssey per-frame FOV guarantee is preserved.
                    local _ht = _G._SDW_iPadHookT
                    if not (_ht and (os.clock() - _ht) < 0.05) then pcall(_G.ApplyiPadView) end
                end
            end)
        end)
    end
end



do
    local CONSOLE_READY = false
    local HDR_CONSOLE_READY = false

    local AI_CACHE = {}
    local AI_CACHE_SIZE = 0
    -- [SDWxOWNER-PERF] Weak-keyed per-pawn POSITIVE memo. Pawns with no PlayerKey
    -- (pKey == nil/0) were re-probed through Game.IsAI / pawn.IsAI on EVERY scan
    -- tick. A pawn object is never reused for a different entity, so once it
    -- resolves as a bot we can short-circuit future probes. Positive-only keeps
    -- behaviour identical (a pawn that is ever AI stays AI); weak keys => no leak.
    local AI_CACHE_PAWN = setmetatable({}, { __mode = "k" })
    local PBC_RUNNING = false
    local PBC_ENABLED = false
    local retryCount = 0
    local PBC_MATCH_TOKEN = nil
    local PBC_TICK_FAILURES = 0

    -- [SDWxOWNER-OPT] Single scratch table that holds ALL hoisted helpers + their state.
    local _OPT = {}

    -- [SDWxOWNER-OPT] Adaptive per-tick mesh-dye budget.
    local DYE_CALL_BUDGET = 256
    local DYE_CALLS_THIS_TICK = 0
    -- [SDWxOWNER-RUSH-CRASH FIX #2] Hard ceiling on the number of MESHES dyed per wallhack tick.
    -- Each mesh costs ~15-17 native calls (SetDrawDyeing / SetVisibleDyeingColor /
    -- SetOccludedDyeingColor / SetDrawIdeaOutline / SetRenderCustomDepth / ...). The old
    -- roster-scaled budget (256..640 meshes) could therefore push 4,000-10,000 native calls - and
    -- the matching render-thread material updates - into a SINGLE frame. That single-frame spike is
    -- the FPS 60 -> 20-30 hitch that precedes the crash. The budget is now a small FIXED mesh count
    -- and the un-dyed tail is streamed across subsequent ticks by a per-enemy cursor (see
    -- ApplyColorBodyNew), so the native herd stays bounded while every enemy still ends up fully
    -- dyed. NO FEATURE / VISUAL CHANGE and NO ADDED DELAY: GetAllSkeletalMeshes returns the MAIN
    -- BODY meshes first (enemy.Mesh, CharacterMesh0-5), so the slice always covers the visible body
    -- on the very first tick - exactly like before - and only the trailing cosmetic/weapon meshes
    -- (which were already covered by the old 2.5 s re-dye cycle) stream in over the next beat.
    -- Stored on the shared _OPT scratch table so this adds ZERO locals to __SDW_ModMain (which sits
    -- right at LuaJIT's 200-local ceiling).
    _OPT.dyeMeshBudget = 96
    -- [SDWxOWNER-RUSH-FPS] The first 8 meshes of every enemy are its VISIBLE BODY
    -- (enemy.Mesh, MasterMesh, CharacterMesh0-5). Guaranteeing those 8 per enemy per tick means
    -- the wallhack lights up the whole body on the very first tick - exactly as before - while
    -- the trailing cosmetic/weapon meshes stream in over the next beats (they were already on a
    -- 2.5 s re-dye cadence, so this is imperceptible). This is what lets us cut the per-tick
    -- total without ANY visible delay.
    _OPT.dyeBodyMeshes = 8
    -- [SDWxOWNER-RUSH-CRASH FIX #2] Minimum meshes dyed per enemy per tick. For the reported
    -- 8-10 enemy rush the slice is 128/10 = 12, which already covers the whole visible body
    -- (Mesh + MasterMesh + CharacterMesh0-5 = 8 meshes) on the FIRST tick - so the body lights up
    -- exactly as fast as before, with zero perceptible delay; only the trailing cosmetic/weapon
    -- meshes stream in over the next beat (they were already on the old 2.5 s re-dye cadence).
    -- 6 keeps every enemy fed (no starvation) for rosters up to ~21 enemies.
    _OPT.dyeMinSlice = 6
    -- [SDWxOWNER-PERF FIX #1] Dye-fail backoff. A mesh that the engine refuses to dye used to
    -- be retried every 5 s. When the game hands us 250+ un-dyeable meshes (a skin/avatar rebuild,
    -- a streaming pawn) they ALL expired on the same tick and fired 250+ native SetVectorParameter
    -- calls in one frame -> the recurring 5-second hitch. Now a failed mesh is parked for a full
    -- 60 s, and a small deterministic jitter (see the apply loop) spreads the retries so the herd
    -- never re-forms. No feature change: the wallhack still re-dyes the instant a mesh becomes
    -- dyeable again on the next successful pass.
    local DYE_FAIL_COOLDOWN = 60.0
    local DYE_FAIL_JITTER   = 15.0
    local DyeFailCooldown = setmetatable({}, { __mode = "k" })

    -- [SDWxOWNER-PERF] os.clock() cannot raise in LuaJIT, so the old
    -- `pcall(os.clock)` wrapper was pure per-call overhead (closure + pcall
    -- frame). Direct call is behaviourally identical.
    local function NowSeconds() return os.clock() end
    local function IsValidObject(obj) if not obj then return false end; local ok, v = pcall(slua.isValid, obj); return ok and v == true end
    local SafeIsValid = IsValidObject


    local _ci_LinearColor = import("LinearColor") or _G.FLinearColor or LinearColor
    local _ci_MeshComponent = import("MeshComponent") or import("SkeletalMeshComponent") or import("/Script/Engine.MeshComponent")
    local _ci_KSL = UKismetSystemLibrary or import("KismetSystemLibrary")
    local _ci_GameplayStatics = GameplayStatics or import("GameplayStatics")
    local _ci_HitResultClass = import("HitResult") or import("/Script/Engine.HitResult")
    local _ci_FVector = FVector or import("Vector") or import("/Script/CoreUObject.Vector")
    local _ci_SBL = SlateBlueprintLibrary or import("SlateBlueprintLibrary") or import("/Script/UMG.SlateBlueprintLibrary")
    local _ci_WLL = WidgetLayoutLibrary or import("WidgetLayoutLibrary") or import("/Script/UMG.WidgetLayoutLibrary")

    local function SafeMethodCall(obj, method, ...) if not obj then return false, nil end; local fn = obj[method]; if type(fn) ~= "function" then return false, nil end; return pcall(fn, obj, ...) end

    -- [SDWxOWNER-SMOOTH] Single cached accessor for the global ticker module.
    -- Hot loops (snapline driver @20 Hz, aim chain @50 Hz, FPS loop @0.5 Hz, menu drivers)
    -- used to call require("common.time_ticker") on EVERY beat. require() is a global
    -- lookup + call + package.loaded hash lookup; caching the module table turns each beat
    -- into a plain cached read. Re-requires only if the module ever goes missing, so it is
    -- always safe. Zero behaviour change - just less per-tick overhead.
    _G.SDW_GetTicker = function()
        local t = _G._SDW_TickerCache
        if t and t.AddTimerOnce then return t end
        local ok, m = pcall(require, "common.time_ticker")
        if ok and m and m.AddTimerOnce then _G._SDW_TickerCache = m; return m end
        return nil
    end

    -- [SDWxOWNER] Mini Map ESP removed on request (Distance ESP already covers it).

    local function SetupConsole()
        pcall(function()
            local KSL = _ci_KSL; local world = slua.getWorld()
            if KSL and world and KSL.ExecuteConsoleCommand then
                KSL.ExecuteConsoleCommand(world, "r.EnableDrawDyeingColor 1")
                KSL.ExecuteConsoleCommand(world, "r.CustomDepth 3")
                KSL.ExecuteConsoleCommand(world, "r.Highlight.Enable 1")
                KSL.ExecuteConsoleCommand(world, "r.IdeaOutline.Enable 1")
                if _G.SDWConfig and _G.SDWConfig.UnlockFPS165 ~= false then
                    KSL.ExecuteConsoleCommand(world, "t.MaxFPS 165")
                    KSL.ExecuteConsoleCommand(world, "r.FrameRateLimit 165")
                    KSL.ExecuteConsoleCommand(world, "r.VSync 0")
                end
                if _G.SDWConfig and _G.SDWConfig.VisualCleanupEnabled ~= false then
                    KSL.ExecuteConsoleCommand(world, "grass.DensityScale 0")
                    KSL.ExecuteConsoleCommand(world, "grass.DiscardDataOnLoad 1")
                    KSL.ExecuteConsoleCommand(world, "r.Fog 0")
                    KSL.ExecuteConsoleCommand(world, "r.VolumetricFog 0")
                end
                KSL.ExecuteConsoleCommand(world, "r.BloomQuality 1")
                KSL.ExecuteConsoleCommand(world, "r.Mobile.TonemapperFilm 1")
            end
            pcall(function()
                local UIUtil = require("client.common.ui_util")
                local gi = UIUtil and UIUtil.GetGameInstance and UIUtil.GetGameInstance()
                if gi and gi.ExecuteCMD then
                    gi:ExecuteCMD("r.EnableDrawDyeingColor", "1")
                    gi:ExecuteCMD("r.CustomDepth", "3")
                    gi:ExecuteCMD("r.Highlight.Enable", "1")
                end
            end)
            if CONSOLE_READY then return end
            pcall(function()
                local IPSU = package.loaded["GameLua.Mod.Library.Client.UI.IngamePhoneStateUI"]
                if not IPSU then pcall(function() IPSU = require("GameLua.Mod.Library.Client.UI.IngamePhoneStateUI") end) end
                if IPSU and IPSU.__inner_impl then
                    IPSU.__inner_impl.UpdateArtQualityUI = function(self, _, _)
                        if self and self.UIRoot and self.UIRoot.TextBlock_quality then
                            self.UIRoot.TextBlock_quality:SetText("SDWxOWNER")
                            local LC = _ci_LinearColor or import("LinearColor") or _G.FLinearColor
                            local SC = import("SlateColor") or _G.FSlateColor
                            if SC and LC then
                                pcall(function() self.UIRoot.TextBlock_quality:SetColorAndOpacity(SC(LC(1, 0, 0, 1))) end)
                            end
                        end
                    end
                end
            end)
            CONSOLE_READY = true
        end)
    end
    _G.SetupConsole = SetupConsole


    local GK_WIDGET_NEXT_ATTEMPT = 0
    local GK_WIDGET_BACKOFF = 1.0
    local GK_WIDGET_BACKOFF_MAX = 3.0

    local function GK_DestroyWidget()
        if _G.GK_WIDGET and SafeIsValid(_G.GK_WIDGET) then
            pcall(function() _G.GK_WIDGET:RemoveFromParent() end)
        end
        _G.GK_WIDGET = nil
        _G.GK_WIDGET_SLOT = nil
        _G.GK_WIDGET_LAST_TEXT = ""
        _G.GK_WIDGET_OK = false
        GK_WIDGET_NEXT_ATTEMPT = 0
        GK_WIDGET_BACKOFF = 1.0
    end
    _G.GK_DestroyWidget = GK_DestroyWidget

    -- [SDWxOWNER] New HUD counter -> TEXT-ONLY (no yellow box/border) + configurable colour.
    local _COUNTER_COLORS = {
        [0] = { 1.00, 0.15, 0.15, 1.0 },  -- Red
        [1] = { 0.00, 0.95, 1.00, 1.0 },  -- Cyan
        [2] = { 1.00, 0.85, 0.10, 1.0 },  -- Yellow
        [3] = { 0.20, 1.00, 0.30, 1.0 },  -- Green
        [4] = { 0.75, 0.35, 1.00, 1.0 },  -- Purple
        -- [SDWxOWNER] White removed on request; Yellow (2) is the base default.
    }

    local function _CounterGetColor()
        local id = 2
        pcall(function() id = tonumber(_G.SDWConfig and _G.SDWConfig.CounterTextColor) or 2 end)
        local c = _COUNTER_COLORS[id] or _COUNTER_COLORS[2]
        local LC = _ci_LinearColor or import("LinearColor") or _G.FLinearColor
        if LC then
            local ok, col = pcall(LC, c[1], c[2], c[3], c[4])
            if ok and col then return col end
        end
        return { R = c[1], G = c[2], B = c[3], A = c[4] }
    end

    local function GK_GetCanvas()
        if _G.SnaplineESP and _G.SnaplineESP.InitESPCanvas then
            local ok = false
            pcall(function() ok = _G.SnaplineESP.InitESPCanvas() end)
            if ok and _G.SnaplineESP.ESPCanvas and slua.isValid(_G.SnaplineESP.ESPCanvas) then
                return _G.SnaplineESP.ESPCanvas
            end
        end
        return nil
    end

    local function GK_GetOrCreateWidget()
        if _G.GK_WIDGET and SafeIsValid(_G.GK_WIDGET) then return _G.GK_WIDGET end
        local now = NowSeconds()
        if now < GK_WIDGET_NEXT_ATTEMPT then return nil end
        if _G.GK_WIDGET then
            pcall(function()
                if SafeIsValid(_G.GK_WIDGET) and _G.GK_WIDGET.RemoveFromParent then
                    _G.GK_WIDGET:RemoveFromParent()
                end
            end)
            _G.GK_WIDGET = nil
            _G.GK_WIDGET_OK = false
        end

        -- [SDWxOWNER] Attach to the SAME HUD container the OLD counter used so the position matches exactly.
        local outer = GK_GetCanvas()

        local tb = nil
        pcall(function()
            local cg = rawget(_G, "CGame") or import("CGame")
            if cg and cg.NewObjectFromPath then
                tb = cg:NewObjectFromPath("/Script/UMG.TextBlock", outer)
            end
        end)
        if not tb or not slua.isValid(tb) then
            pcall(function()
                local cls = slua.loadClass("/Script/UMG.TextBlock")
                if cls then tb = cls(outer) end
            end)
        end

        if tb and slua.isValid(tb) then
            local FVector2DL = import("Vector2D") or _G.FVector2D
            local FAnchorsL = import("Anchors") or _G.FAnchors
            local FLinearColorL = _ci_LinearColor or import("LinearColor") or _G.FLinearColor
            local FSlateColorL = import("SlateColor") or _G.FSlateColor

            -- [SDWxOWNER] Put it back where the OLD counter was (HUD Top container).
            local attachedToHud = false
            local hudSlot = nil
            pcall(function()
                local hm = package.loaded["game_frontend_hud"] or require("game_frontend_hud")
                if hm and hm.AddToContainer and UIContainers and UIContainers.Top then
                    hudSlot = hm.AddToContainer(UIContainers.Top, tb, 10500)
                    attachedToHud = true
                end
            end)
            if not attachedToHud then
                pcall(function()
                    if tb.AddToViewport then tb:AddToViewport(10500); attachedToHud = true end
                end)
            end
            if not attachedToHud and outer then
                pcall(function() hudSlot = outer:AddChildToCanvas(tb) end)
            end
            pcall(function()
                local slot = nil
                -- [SDWxOWNER] Mirror the classic counter: it uses SlotAsCanvasSlot on the widget itself.
                local WLL = import("WidgetLayoutLibrary")
                if WLL and WLL.SlotAsCanvasSlot then slot = WLL.SlotAsCanvasSlot(tb) end
                if not slot and hudSlot and hudSlot.SetAnchors then slot = hudSlot end
                if not slot then pcall(function() slot = tb.Slot end) end
                if slot and slot.SetAnchors then
                    if FAnchorsL then slot:SetAnchors(FAnchorsL(0.5, 0, 0.5, 0)) end
                    if FVector2DL then slot:SetAlignment(FVector2DL(0.5, 0)) end
                    if FVector2DL then slot:SetSize(FVector2DL(460, 26)) end
                    pcall(function() slot:SetZOrder(10500) end)
                end
                _G.GK_WIDGET_SLOT = slot
            end)
            -- [SDWxOWNER] Position comes from config so it can be fine-tuned LIVE from
            -- the menu (Counter X/Y sliders) without a restart.
            pcall(function()
                local slot = _G.GK_WIDGET_SLOT
                local FVector2DL2 = import("Vector2D") or _G.FVector2D
                if slot and slot.SetPosition and FVector2DL2 then
                    local cx = tonumber(_G.SDWConfig and _G.SDWConfig.CounterPosX) or 0
                    local cy = tonumber(_G.SDWConfig and _G.SDWConfig.CounterPosY) or 48
                    slot:SetPosition(FVector2DL2(cx, cy))
                end
            end)
            -- [SDWxOWNER] TextBlock defaults to left justification; centre it explicitly.
            pcall(function()
                local J = nil
                if UEnums and UEnums.ETextJustify then
                    J = UEnums.ETextJustify.Center or UEnums.ETextJustify["Center"]
                end
                if J == nil then J = 1 end
                if tb.SetJustification then tb:SetJustification(J) end
                tb.Justification = J
            end)
            pcall(function() tb:SetText("") end)
            if FSlateColorL then
                pcall(function() tb:SetColorAndOpacity(FSlateColorL(_CounterGetColor())) end)
            else
                pcall(function() tb:SetColorAndOpacity(_CounterGetColor()) end)
            end
            if FLinearColorL then
                pcall(function() tb:SetShadowColorAndOpacity(FLinearColorL(0, 0, 0, 0)) end)
            end
            if FVector2DL then
                pcall(function() tb:SetShadowOffset(FVector2DL(0, 0)) end)
            end
            pcall(function()
                local fi = tb.Font
                if fi then
                    fi.Size = 18
                    if fi.OutlineSettings then
                        fi.OutlineSettings.OutlineSize = 0
                        if FLinearColorL then
                            pcall(function() fi.OutlineSettings.OutlineColor = FLinearColorL(0, 0, 0, 0) end)
                        end
                        pcall(function() fi.OutlineSettings.bApplyOutlineToDropShadows = false end)
                    end
                    pcall(function() fi.LetterSpacing = 0 end)
                    tb:SetFont(fi)
                end
            end)
            pcall(function() tb:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible) end)
            _G.GK_WIDGET = tb
            _G.GK_WIDGET_OK = true
        end

        if _G.GK_WIDGET and SafeIsValid(_G.GK_WIDGET) then
            GK_WIDGET_BACKOFF = 1.0
            GK_WIDGET_NEXT_ATTEMPT = 0
        else
            GK_WIDGET_NEXT_ATTEMPT = now + GK_WIDGET_BACKOFF
            GK_WIDGET_BACKOFF = math.min(GK_WIDGET_BACKOFF * 2.0, GK_WIDGET_BACKOFF_MAX)
        end
        return _G.GK_WIDGET
    end

    -- [SDWxOWNER] Re-apply the counter's slot position every tick so the menu sliders
    -- take effect instantly (the widget is created once and reused).
    local function GK_ApplyCounterLayout()
        local w = _G.GK_WIDGET
        if not (w and SafeIsValid(w)) then return end
        local slot = _G.GK_WIDGET_SLOT
        if not slot then
            pcall(function()
                local WLL = import("WidgetLayoutLibrary")
                if WLL and WLL.SlotAsCanvasSlot then slot = WLL.SlotAsCanvasSlot(w) end
            end)
            if not slot then pcall(function() slot = w.Slot end) end
            _G.GK_WIDGET_SLOT = slot
        end
        if not slot then return end
        local FVector2DL = import("Vector2D") or _G.FVector2D
        if not (slot.SetPosition and FVector2DL) then return end
        local cx = tonumber(_G.SDWConfig and _G.SDWConfig.CounterPosX) or 0
        local cy = tonumber(_G.SDWConfig and _G.SDWConfig.CounterPosY) or 48
        pcall(function() slot:SetPosition(FVector2DL(cx, cy)) end)
    end

    local function GK_UpdateWidget(enemyCount, botCount)
        local newText
        if enemyCount == 0 and botCount == 0 then
            newText = "ZONE CLEAR"
        elseif enemyCount > 0 and botCount > 0 then
            newText = enemyCount .. " ENEMY  |  " .. botCount .. " BOT"
        elseif enemyCount > 0 then
            newText = enemyCount .. " ENEMY"
        else
            newText = botCount .. " BOT"
        end
        local w = GK_GetOrCreateWidget()
        if not (w and SafeIsValid(w)) then return end
        GK_ApplyCounterLayout()
        if newText ~= _G.GK_WIDGET_LAST_TEXT then
            _G.GK_WIDGET_LAST_TEXT = newText
            pcall(function() w:SetText(newText) end)
        end
        -- apply colour every tick so menu changes take effect instantly
        local FSlateColorL = import("SlateColor") or _G.FSlateColor
        if FSlateColorL then
            pcall(function() w:SetColorAndOpacity(FSlateColorL(_CounterGetColor())) end)
        else
            pcall(function() w:SetColorAndOpacity(_CounterGetColor()) end)
        end
    end

