        [1987000] = "Horse",
        [1988000] = "Hovercraft"
    }
    local VEH_CFG_KEYS = {}
    for _, name in pairs(VEH_NAMES) do
        VEH_CFG_KEYS[name] = "VehESP_" .. string.gsub(name, "[%s%-%(%)%_]", "")
    end

    local function GetVehicleNameAndKey(veh)
        if not SafeIsValid(veh) then return "Vehicle", "VehESP_Vehicle" end
        local cached = VEH_NAME_RESOLVE_CACHE[veh]
        if cached then return cached[1], cached[2] end

        local n = veh.DisplayName
        if not n or n == "" then
            local av = veh.VehicleAvatar
            if SafeIsValid(av) and av.GetDefaultAvatarID then
                local okId, id = SafeMethodCall(av, "GetDefaultAvatarID")
                id = okId and id or 0
                if id and id > 0 then
                    local baseId = math.floor(id / 1000) * 1000
                    n = VEH_NAMES[baseId] or VEH_NAMES[id]
                end
            end
        end

        if not n or n == "" then
            local okCls, clsObj = pcall(function() return veh:GetClass() end)
            if okCls and clsObj and clsObj.GetName then
                local okName, clsName = pcall(function() return clsObj:GetName() end)
                if okName and clsName then
                    if clsName:find("UAZ") then n = "UAZ"
                    elseif clsName:find("Buggy") then n = "Buggy"
                    elseif clsName:find("Dacia") then n = "Dacia"
                    elseif clsName:find("Motorcycle") or clsName:find("Motorbike") then n = "Motorcycle"
                    elseif clsName:find("BRDM") then n = "BRDM-2"
                    elseif clsName:find("Coupe") then n = "Coupe RB"
                    elseif clsName:find("Mirado") then n = "Mirado"
                    elseif clsName:find("Rony") then n = "Rony"
                    elseif clsName:find("Tuk") then n = "Tukshai"
                    elseif clsName:find("Scooter") then n = "Scooter"
                    elseif clsName:find("Snowmobile") then n = "Snowmobile"
                    elseif clsName:find("Glider") then n = "Motor Glider"
                    elseif clsName:find("Monster") then n = "Monster Truck"
                    elseif clsName:find("Boat") or clsName:find("PG117") then n = "PG-117 (Boat)"
                    elseif clsName:find("JetSki") or clsName:find("Aqua") then n = "Aquarail (Jet Ski)"
                    elseif clsName:find("UTV") then n = "UTV"
                    elseif clsName:find("Bike") then n = "Mountain Bike"
                    elseif clsName:find("Hovercraft") then n = "Hovercraft"
                    elseif clsName:find("Horse") then n = "Horse"
                    end
                end
            end
        end

        n = n or "Vehicle"
        if n == "" then n = "Vehicle" end
        local cfgKey = VEH_CFG_KEYS[n]
        if not cfgKey then
            cfgKey = "VehESP_" .. string.gsub(n, "[%s%-%(%)%_]", "")
            VEH_CFG_KEYS[n] = cfgKey
        end
        VEH_NAME_RESOLVE_CACHE[veh] = { n, cfgKey }
        return n, cfgKey
    end

    local function ResolveIsAI(pKey, pawn)
        -- [SDWxOWNER-PERF] Fast per-pawn positive memo (avoids repeated native
        -- Game.IsAI / pawn.IsAI probes for bots that have no PlayerKey).
        if pawn and AI_CACHE_PAWN[pawn] then return true end
        if pKey and pKey ~= 0 and AI_CACHE[pKey] ~= nil then return AI_CACHE[pKey] end
        local isAI = false
        if Game and Game.IsAI and pawn then
            local s, r = pcall(Game.IsAI, Game, pawn)
            if s and r == true then isAI = true end
        end
        if not isAI and pawn then
            if pawn.bIsAI == true or pawn.bAI == true then isAI = true end
            if not isAI and type(pawn.IsAI) == "function" then
                local s, r = pcall(pawn.IsAI, pawn)
                if s and r == true then isAI = true end
            end
            if not isAI and (not pKey or pKey == 0) then
                pcall(function()
                    if pawn.PlayerState and (pawn.PlayerState.bIsABot == true or pawn.PlayerState.bIsAI == true) then
                        isAI = true
                    end
                end)
            end
        end
        if isAI and pawn then AI_CACHE_PAWN[pawn] = true end
        if pKey and pKey ~= 0 and (AI_CACHE_SIZE or 0) < 512 then
            AI_CACHE_SIZE = (AI_CACHE_SIZE or 0) + 1
            AI_CACHE[pKey] = isAI
        end
        return isAI
    end

    _G.NAME_CACHE = _G.NAME_CACHE or {}
    _G.NAME_LOOKUP_DONE = _G.NAME_LOOKUP_DONE or {}
    local NAME_CACHE_SIZE = 0
    local NAME_CACHE_MAX = 256

    local function GetEnemyName(pawn)
        if not pawn then return "ENEMY" end

        local cKey = pawn.PlayerKey
        if not cKey or cKey == 0 then return "ENEMY" end
        if _G.NAME_CACHE[cKey] ~= nil then
            return _G.NAME_CACHE[cKey]
        end

        if _G.NAME_LOOKUP_DONE[cKey] then
            return "ENEMY"
        end
        _G.NAME_LOOKUP_DONE[cKey] = true

        local eName = "ENEMY"
        local getter = pawn.GetPlayerNameSafety
        if getter then
            local ok, name = pcall(getter, pawn)
            if ok and type(name) == "string" and name ~= "" then
                eName = name
            end
        end

        _G.NAME_CACHE[cKey] = eName
        NAME_CACHE_SIZE = NAME_CACHE_SIZE + 1
        if NAME_CACHE_SIZE > NAME_CACHE_MAX then
            _G.NAME_CACHE = {}
            _G.NAME_LOOKUP_DONE = {}
            NAME_CACHE_SIZE = 0
        end
        return eName
    end

    local COLOR_PALETTE = {
        [0] = { R=255, G=0, B=0, A=255, r=255, g=0, b=0, a=255 },
        [1] = { R=0, G=255, B=255, A=255, r=0, g=255, b=255, a=255 },
        [2] = { R=255, G=255, B=0, A=255, r=255, g=255, b=0, a=255 },
        [3] = { R=0, G=255, B=0, A=255, r=0, g=255, b=0, a=255 },
        [4] = { R=128, G=0, B=255, A=255, r=128, g=0, b=255, a=255 },
        [5] = { R=255, G=255, B=255, A=255, r=255, g=255, b=255, a=255 }
    }
    local function GetColorTable(idx) return COLOR_PALETTE[idx] or COLOR_PALETTE[0] end
    local LINEAR_COLOR_CACHE = {}
    local function GetLinearColor(idx)
        local intensity = (_G.SDWConfig and _G.SDWConfig.GlowIntensity) or 60
        local cacheKey = (idx * 1000) + math.floor(intensity)
        if LINEAR_COLOR_CACHE[cacheKey] then return LINEAR_COLOR_CACHE[cacheKey] end
        local c = GetColorTable(idx)
        local mult = (intensity / 100.0) * 100.0
        if mult < 1.0 then mult = 1.0 end
        local LinearColorClass = _ci_LinearColor
        local lc
        if LinearColorClass then
            lc = LinearColorClass((c.R / 255.0) * mult, (c.G / 255.0) * mult, (c.B / 255.0) * mult, 1.0)
        else
            lc = { R = (c.R / 255.0) * mult, G = (c.G / 255.0) * mult, B = (c.B / 255.0) * mult, A = 1.0 }
        end
        LINEAR_COLOR_CACHE[cacheKey] = lc
        return lc
    end

    local _ci_SkeletalMeshComponent = import("SkeletalMeshComponent") or import("/Script/Engine.SkeletalMeshComponent")
    local _ci_StaticMeshComponent = import("StaticMeshComponent") or import("/Script/Engine.StaticMeshComponent")
    local _ci_SlotViewAvatarComponent = import("SlotViewAvatarComponent") or import("CharacterAvatarComponent")

    -- [SDWxOWNER-OPT] Hoisted mesh-collection helpers for GetAllSkeletalMeshes.
    _OPT.gasmMeshes = nil
    _OPT.gasmSeen = nil
    _OPT.gasmEnemy = nil
    function _OPT.gasmAddMesh(m)
        if m and SafeIsValid(m) and not _OPT.gasmSeen[m] then
            _OPT.gasmSeen[m] = true
            _OPT.gasmMeshes[#_OPT.gasmMeshes + 1] = m
        end
    end
    _OPT.gasmClasses = { _ci_MeshComponent, _ci_SkeletalMeshComponent, _ci_StaticMeshComponent }
    function _OPT.gasmCollectAvatar()
        local enemy = _OPT.gasmEnemy
        local avatarComp = enemy.CharacterAvatarComp2_BP or (enemy.getAvatarComponent2 and enemy:getAvatarComponent2())
        if not SafeIsValid(avatarComp) and _ci_SlotViewAvatarComponent and type(enemy.GetComponentByClass) == "function" then
            avatarComp = enemy:GetComponentByClass(_ci_SlotViewAvatarComponent)
        end
        if SafeIsValid(avatarComp) then
            for slot = 0, 30 do
                if type(avatarComp.GetMeshCompBySlotID) == "function" then
                    local m = avatarComp:GetMeshCompBySlotID(slot)
                    if SafeIsValid(m) then _OPT.gasmAddMesh(m) end
                elseif type(avatarComp.GetMeshCompBySlot) == "function" then
                    local m = avatarComp:GetMeshCompBySlot(slot)
                    if SafeIsValid(m) then _OPT.gasmAddMesh(m) end
                end
            end
        end
    end
    function _OPT.gasmCollectComponents()
        local enemy = _OPT.gasmEnemy
        for _, cls in ipairs(_OPT.gasmClasses) do
            if cls and type(enemy.GetComponentsByClass) == "function" then
                local childs = enemy:GetComponentsByClass(cls)
                if childs then
                    local count = type(childs.Num) == "function" and childs:Num() or #childs
                    for i = 1, count do
                        local comp = type(childs.Get) == "function" and childs:Get(i-1) or childs[i]
                        _OPT.gasmAddMesh(comp)
                    end
                end
            end
        end
    end
    function _OPT.gasmCollectWeapon()
        local enemy = _OPT.gasmEnemy
        local weapon = nil
        if type(enemy.GetCurrentWeapon) == "function" then
            weapon = enemy:GetCurrentWeapon()
        elseif enemy.CurrentWeapon then
            weapon = enemy.CurrentWeapon
        end
        if SafeIsValid(weapon) then
            _OPT.gasmAddMesh(weapon.Mesh)
            if type(weapon.GetComponentsByClass) == "function" and _ci_MeshComponent then
                local wMeshes = weapon:GetComponentsByClass(_ci_MeshComponent)
                if wMeshes then
                    local count = type(wMeshes.Num) == "function" and wMeshes:Num() or #wMeshes
                    for i = 1, count do
                        local comp = type(wMeshes.Get) == "function" and wMeshes:Get(i-1) or wMeshes[i]
                        _OPT.gasmAddMesh(comp)
                    end
                end
            end
        end
    end

    local function GetAllSkeletalMeshes(enemy, markData)
        -- [SDWxOWNER-RUSH-CRASH v2] Hard owner fence. Every line below reads native UObject
        -- properties off `enemy` (Mesh / MasterMesh / CharacterMesh0..5) and calls
        -- GetComponentsByClass on it. If the pawn was torn down a frame ago those reads are
        -- use-after-free. Re-validating here (cheap, 1 call) protects BOTH callers - the dye
        -- path AND the undo path - instead of relying on each of them to remember.
        if not enemy or not SafeIsValid(enemy) then return nil end
        local curTime = os.clock()
        -- [SDWxOWNER-PERF] The mesh cache window matches the 2.5 s dye re-apply interval used by ApplyColorBodyNew.
        if markData and markData.CachedMeshes and markData.CachedMeshTime and (curTime - markData.CachedMeshTime < 2.5) then
            local valid = true
            for i = 1, #markData.CachedMeshes do
                if not SafeIsValid(markData.CachedMeshes[i]) then
                    valid = false
                    break
                end
            end
            if valid and #markData.CachedMeshes > 0 then
                return markData.CachedMeshes
            end
        end

        local meshes = {}
        local seen = {}
        -- [SDWxOWNER-OPT] Wire the hoisted helpers to this call's output tables.
        _OPT.gasmMeshes = meshes
        _OPT.gasmSeen = seen
        _OPT.gasmEnemy = enemy

        _OPT.gasmAddMesh(enemy.Mesh)
        _OPT.gasmAddMesh(enemy.MasterMesh)

        _OPT.gasmAddMesh(enemy.CharacterMesh0)
        _OPT.gasmAddMesh(enemy.CharacterMesh1)
        _OPT.gasmAddMesh(enemy.CharacterMesh2)
        _OPT.gasmAddMesh(enemy.CharacterMesh3)
        _OPT.gasmAddMesh(enemy.CharacterMesh4)
        _OPT.gasmAddMesh(enemy.CharacterMesh5)

        pcall(_OPT.gasmCollectAvatar)
        pcall(_OPT.gasmCollectComponents)
        pcall(_OPT.gasmCollectWeapon)

        if markData then
            markData.CachedMeshes = meshes
            -- [SDWxOWNER-RUSH-FPS] STAGGER the 2.5 s mesh-cache refresh per enemy. Re-enumerating
            -- one enemy costs 3x GetComponentsByClass (each a native TArray alloc) + up to 31
            -- avatar slot probes + the weapon pass. When 10 enemies share the same 2.5 s window
            -- they all refresh on the SAME tick -> one big native burst (the rush hitch). Giving
            -- each enemy a fixed 0..0.75 s phase spreads those refreshes across ~8 ticks. The
            -- cache is still re-validated on every read (SafeIsValid loop), so no stale mesh can
            -- ever be dyed - only the refresh MOMENT moves.
            if not markData._meshJit then
                _OPT.meshJitSeq = ((_OPT.meshJitSeq or 0) + 1) % 8
                markData._meshJit = _OPT.meshJitSeq * 0.09375   -- 0 .. 0.65625 s
            end
            markData.CachedMeshTime = curTime - markData._meshJit
        end
        return meshes
    end

    -- [SDWxOWNER-OPT] Hoisted mesh-dye applier.
    _OPT.dyeMesh = nil
    _OPT.dyeVis = nil
    _OPT.dyeOcc = nil
    _OPT.dyeVisRaw = nil
    -- ========================================================================
    -- [SDWxOWNER-WALLHACK v4] CRASH-FREE SEE-THROUGH + COLOUR  (MID method)
    -- ------------------------------------------------------------------------
    -- WHY v3 WAS THROWN OUT: v3 restored sdw.lua's DYEING herd
    -- (SetDrawDyeing / SetVisibleDyeingColor / OverrideIdeaOutlineColor /
    -- OverrideIdeaOutlineThickness / SetIdeaOverrideOutlineAndOcclusion ...).
    -- Every one of those setters rebuilds the render proxy AND the idea-outline
    -- pass. With Guard / the anti-cheat pass live that combination is exactly
    -- what hard-crashed the old menu - which is why this wallhack was replaced
    -- in the first place. Restoring it would just bring the crash back.
    --
    -- v4 uses the SAME crash-free "WALLHACK + COLOR" method (MID tint), the one
    -- that is known NOT to crash:
    --   1. SEE-THROUGH : SetRenderCustomDepth(true) + SetCustomDepthStencilValue(252)
    --                    + baseMat.bDisableDepthTest = true + baseMat.BlendMode = 2
    --   2. COLOUR      : one cached Material Instance Dynamic per (mesh, slot) and
    --                    SetVectorParameterValue() on every known tint parameter.
    -- No dyeing pass, no idea-outline pass, no render-proxy rebuild storm, so the
    -- crash surface of v3 is gone while the mesh is still fully tinted.
    --
    -- [SDWxOWNER-OPT] MIDs are created ONCE per mesh/slot and cached in a weak-keyed
    -- table (a dead pawn's cache is collected automatically). The colour is part of
    -- the hibernation key, so a menu colour change forces exactly ONE re-apply per
    -- mesh, and a settled mesh costs ZERO native calls for 30 s at a time.
    -- ========================================================================
    _OPT.whState = _OPT.whState or setmetatable({}, { __mode = "k" })
    _OPT.midCache = _OPT.midCache or setmetatable({}, { __mode = "k" })
    _OPT.whReassert = 30.0
    _OPT.dyeKey = "wh_v4"
    _OPT.whiteColor = { R = 1.0, G = 1.0, B = 1.0, A = 1.0 }
    -- ========================================================================
    -- [SDWxOWNER-WALLHACK v6] BRIGHTNESS **WITHOUT** THE CRASH
    -- ------------------------------------------------------------------------
    -- v5 crashed. Reason: it wrote 112 native MID parameters per mesh-slot
    -- (17 tint + 22 emissive + 19 scalar, twice over) instead of v4's 24. That is
    -- ~5x the native binding traffic per mesh, multiplied by every mesh of every
    -- enemy in the same tick -> the engine's material-update queue overflows and
    -- the game hard-crashes. Native call COUNT is the crash budget, not the
    -- number of features.
    --
    -- v6 keeps the EXACT 12 parameters of the proven crash-free method (same list
    -- the known-good "WALLHACK + COLOR" uses) so the native call count is
    -- identical to v4 - but the COLOUR VALUE itself is now HDR:
    --     value = colour * GlowIntensity      (10 .. 100)
    -- Both the albedo params and the emissive params receive that HDR value, so
    -- the mesh glows exactly like the old dyeing path did while the number of
    -- native calls stays at 12 per slot. Brightness is a VALUE change, not an
    -- extra-call change - that is the whole trick.
    -- No SetScalarParameterValue at all (that family was part of the v5 crash).
    -- ========================================================================
    _OPT.midParams = {
        "\233\162\156\232\137\178", -- 颜色 (Color)
        "Extra Light Color", "Para_Color", "Para_ColorTint", "Para_Color_1",
        "Tint", "Color", "BaseColor", "BodyColor", "MainColor",
        "DiffuseColor", "EmissiveColor",
    }
    -- [SDWxOWNER-OPT] Hoisted MID writer: one shared closure (zero alloc).
    -- col = final HDR colour (already multiplied by GlowIntensity).
    function _OPT.applyMid(mid, col)
        if not mid or not col then return end
        local pr = _OPT.midParams
        for p = 1, #pr do
            mid:SetVectorParameterValue(pr[p], col)
        end
    end

    function _OPT.dyeMeshApply()
        local mesh = _OPT.dyeMesh
        if not mesh then return end
        do
            local okV, v = pcall(slua.isValid, mesh)
            if not (okV and v == true) then return end
        end
        -- Final UAF fence: a mesh mid-teardown can still report valid for a frame.
        if mesh.bIsBeingDestroyed == true or mesh.bPendingKill == true then return end

        local raw = _OPT.dyeVisRaw
        -- [SDWxOWNER-WALLHACK v5] HDR emissive colour + strength from the Glow
        -- Intensity slider (same 10..100 range the old dyeing path used, so the
        -- brightness now matches what the menu promises).
        local boost = (_G.SDWConfig and tonumber(_G.SDWConfig.GlowIntensity)) or 60
        if boost < 1 then boost = 1 end
        -- [SDWxOWNER-WALLHACK v6] ONE HDR colour, ONE pass, 12 native calls.
        -- The old dyeing path multiplied by GlowIntensity; doing the same to the
        -- value (instead of adding more parameters) gives the same brightness at
        -- v4's exact native-call cost, so it cannot crash.
        local tint = raw
        if raw then
            tint = { R = raw.R * boost, G = raw.G * boost, B = raw.B * boost, A = 1.0 }
        end

        -- [SDWxOWNER-OPT] Hibernation short-circuit (colour-aware key).
        local nowT = os.clock()
        local stateKey = _OPT.dyeKey or "wh_v4"
        local st = _OPT.whState[mesh]
        if st and st.key == stateKey and (nowT - st.t) < _OPT.whReassert and not _G._WH_ForceUpdate then
            return
        end

        local cache = _OPT.midCache[mesh]
        if not cache then cache = {}; _OPT.midCache[mesh] = cache end

        pcall(function()
            -- ---- 1. SEE-THROUGH (custom depth pass, the cheap non-crashing one) ----
            if type(mesh.SetRenderCustomDepth) == "function" then mesh:SetRenderCustomDepth(true) end
            if type(mesh.SetCustomDepthStencilValue) == "function" then mesh:SetCustomDepthStencilValue(252) end
            -- Long draw distance so a tinted enemy never pops out at range.
            pcall(function()
                mesh.LDMaxDrawDistance = -99999
                mesh.MaxDrawDistanceOffset = -99999
                mesh.CachedMaxDrawDistance = -99999
                mesh.UseScopeDistanceCulling = true
            end)

            -- ---- 2. MATERIAL: depth test off, blend mode 2, MID tint ----
            if type(mesh.GetMaterial) == "function" then
                for i = 0, 10 do
                    local matInterface = mesh:GetMaterial(i)
                    if not matInterface or not SafeIsValid(matInterface) then break end
                    local baseMat = matInterface.GetBaseMaterial and matInterface:GetBaseMaterial() or nil
                    if baseMat and SafeIsValid(baseMat) then
                        baseMat.bDisableDepthTest = true
                        baseMat.BlendMode = 2
                        if raw and type(mesh.CreateAndSetMaterialInstanceDynamic) == "function" then
                            local mid = cache[i]
                            if not (mid and SafeIsValid(mid)) then
                                local okC, newMid = pcall(mesh.CreateAndSetMaterialInstanceDynamic, mesh, i)
                                mid = (okC and newMid) or nil
                                cache[i] = mid
                            end
                            if mid and SafeIsValid(mid) then
                                pcall(_OPT.applyMid, mid, tint)
                            end
                        end
                    end
                end
            end
        end)
        _OPT.whState[mesh] = { key = stateKey, t = nowT }
    end

    -- [SDWxOWNER-WALLHACK v4] Restore a mesh to normal rendering.
    _OPT.undoMesh = nil
    function _OPT.undoMeshApply()
        local mesh = _OPT.undoMesh
        if not mesh then return end
        do
            local okV, v = pcall(slua.isValid, mesh)
            if not (okV and v == true) then return end
        end
        local cache = _OPT.midCache[mesh]
        pcall(function()
            if type(mesh.SetRenderCustomDepth) == "function" then mesh:SetRenderCustomDepth(false) end
            if type(mesh.GetMaterial) == "function" then
                for i = 0, 10 do
                    local matInterface = mesh:GetMaterial(i)
                    if not matInterface or not SafeIsValid(matInterface) then break end
                    local baseMat = matInterface.GetBaseMaterial and matInterface:GetBaseMaterial() or nil
                    if baseMat and SafeIsValid(baseMat) then
                        baseMat.bDisableDepthTest = false
                    end
                    local mid = cache and cache[i]
                    if mid and SafeIsValid(mid) then
                        pcall(_OPT.applyMid, mid, _OPT.whiteColor)
                    end
                end
            end
        end)
        _OPT.whState[mesh] = nil
    end

    local function ApplyColorBodyNew(enemy, markData)
        if not enemy or not SafeIsValid(enemy) then return end

        pcall(function()
            local isBot = (markData and markData.AK_IS_BOT) or false
            local eVisChoice = (_G.SDWConfig and _G.SDWConfig.ColorEnemyWHVis) or 0
            local eOccChoice = (_G.SDWConfig and _G.SDWConfig.ColorEnemyWHOcc) or 0
            local bVisChoice = (_G.SDWConfig and _G.SDWConfig.ColorBotWHVis) or 0
            local bOccChoice = (_G.SDWConfig and _G.SDWConfig.ColorBotWHOcc) or 5
            local glowInt = (_G.SDWConfig and _G.SDWConfig.GlowIntensity) or 60

            -- [SDWxOWNER-RUSH-CRASH FIX] Re-check liveness IMMEDIATELY before the native dye herd.
            -- Tick_Wallhack already skips dead pawns, but a pawn can die in the microseconds between
            -- that check and this call (very likely during a close-range RUSH). Dyeing a torn-down
            -- skeletal mesh (GetAllSkeletalMeshes/SetDrawDyeing) is a native use-after-free -> crash.
            local _hsNow = enemy.HealthStatus
            -- [SDWxOWNER-KNOCK-CRASH FIX v2] NO FEATURE LOSS. Dead / torn-down -> never dye.
            if _hsNow == 2 or _hsNow == 3 or enemy.bIsDead == true or enemy.bDead == true
                or enemy.bIsBeingDestroyed == true or enemy.bPendingKill == true
                or enemy.bActorIsBeingDestroyed == true then return end
            -- KNOCKED (hs == 1): the engine swaps to the groggy mesh and detaches the weapon in
            -- the knock frame. Dyeing DURING that swap is the native UAF. But once the swap has
            -- settled the downed mesh is a perfectly valid mesh - so we skip only a short grace
            -- window (~1 s) after the knock and then dye the downed enemy normally again.
            -- Net effect: knocked enemies STILL get chams (just ~1 s later), crash stays closed.
            local _downNow = (_hsNow == 1) or enemy.bIsGroggy == true or enemy.bIsGrogggy == true
                or enemy.bIsKnocked == true or enemy.bIsDying == true
            if _downNow then
                local _tNow = os.clock()
                if not (markData and markData.KnockT) then
                    if markData then
                        markData.KnockT = _tNow
                        -- Mesh identity changed (body -> groggy): drop the stale mesh cache so the
                        -- next pass enumerates the DOWNED mesh instead of the old body meshes.
                        markData.CachedMeshes = nil
                        markData.CachedMeshTime = nil
                        markData.DyeCursor = nil
                        markData.DyeCursorColorHash = nil
                        markData.LastColorNewHash = 0
                    end
                    return
                end
                if (_tNow - markData.KnockT) < 1.0 then return end
            elseif markData and markData.KnockT then
                -- Revived / stood back up: clear the grace stamp.
                markData.KnockT = nil
                markData.CachedMeshes = nil
                markData.CachedMeshTime = nil
                markData.DyeCursor = nil
                markData.DyeCursorColorHash = nil
                markData.LastColorNewHash = 0
            end
            local meshes = GetAllSkeletalMeshes(enemy, markData)
            if not meshes or #meshes == 0 then return end

            local currentMeshCount = #meshes
            -- [SDWxOWNER-RUSH-CRASH FIX #2] Split the hash into a COLOUR hash (drives whether the
            -- streaming cursor must restart) and the full state hash (drives the cooldown). A pure
            -- mesh-count change during a rush (a weapon/cosmetic mesh streaming in) must NOT throw
            -- away the streaming progress - only a real colour/mode change does.
            local colorHash = (isBot and 1000000 or 0)
                + eVisChoice * 10000 + eOccChoice * 1000 + bVisChoice * 100 + bOccChoice * 10 + (glowInt % 100)
            local stateHash = colorHash + currentMeshCount * 100000

            local nowTime = os.clock()
            -- [SDWxOWNER-RUSH-CRASH FIX #2] Cooldown short-circuit. Only a COMPLETED pass stamps
            -- LastColorApplyTime (see the stamp below), so a streamed (partial) pass keeps resuming
            -- on the next tick instead of being frozen for 2.5 s with the tail left un-dyed.
            if markData and markData.LastColorNewHash == stateHash
                and markData.LastColorApplyTime and (nowTime - markData.LastColorApplyTime < 2.5) then
                return
            end

            local visColor = isBot and GetLinearColor(bVisChoice) or GetLinearColor(eVisChoice)
            local occColor = isBot and GetLinearColor(bOccChoice) or GetLinearColor(eOccChoice)
            -- [SDWxOWNER-WALLHACK v4] Raw 0..1 tint used by the MID colour path.
            -- (GetLinearColor multiplies by GlowIntensity for the old dyeing glow; a
            --  material vector parameter needs the plain 0..1 colour instead.)
            do
                local rawIdx = isBot and bVisChoice or eVisChoice
                local rc = GetColorTable(rawIdx)
                if rc then
                    _OPT.dyeVisRaw = { R = rc.R / 255.0, G = rc.G / 255.0, B = rc.B / 255.0, A = 1.0 }
                end
            end

            -- [SDWxOWNER-RUSH-CRASH FIX #2] Streaming cursor + fair per-enemy slice. The old loop
            -- always restarted at mesh 1 and only stopped at the shared budget, so a partial pass
            -- re-dyed the SAME leading meshes every tick (wasted native work) while the tail was
            -- frozen for 2.5 s. Now each enemy resumes exactly where the last tick stopped and dyes
            -- at most _OPT.dyeSlice meshes, so the per-tick native herd is bounded AND every enemy
            -- still completes - no enemy is starved, no mesh is re-dyed needlessly.
            local slice = _OPT.dyeSlice or DYE_CALL_BUDGET
            local cursor = markData and markData.DyeCursor
            if markData and markData.DyeCursorColorHash ~= colorHash then cursor = nil end
            if not cursor or cursor < 1 or cursor > currentMeshCount then cursor = 1 end
            local sliceEnd = cursor + slice - 1
            if sliceEnd > currentMeshCount then sliceEnd = currentMeshCount end

            local nowClock = nowTime
            local i = cursor
            while i <= sliceEnd do
                if DYE_CALLS_THIS_TICK >= DYE_CALL_BUDGET then break end
                -- [SDWxOWNER-RUSH-FPS] Wall-clock guard. The first 8 meshes (the visible body)
                -- are ALWAYS applied; beyond that, stop once this tick has already spent > 8 ms
                -- in the dye path. The cursor below saves `i`, so the remaining meshes resume on
                -- the next tick. This makes a 10-enemy rush impossible to turn into a 1-frame
                -- render-proxy storm (the FPS 20-30 drop), while the body still lights up at once.
                if i > 8 and _OPT.dyeTickStart and (os.clock() - _OPT.dyeTickStart) > 0.008 then break end
                local mesh = meshes[i]
                i = i + 1
                if SafeIsValid(mesh) and SafeIsValid(enemy) then
                    -- [SDWxOWNER-RUSH-FPS] Extra UAF guard: a mesh whose owner is mid-teardown can
                    -- still report slua.isValid()==true for a frame, but its skinned-mesh resource
                    -- is already gone -> SetDrawDyeing dereferences NULL -> hard crash right at the
                    -- kill moment during a rush. Skip anything flagged as being destroyed.
                    if mesh.bIsBeingDestroyed ~= true and mesh.bPendingKill ~= true then
                    local failUntil = DyeFailCooldown[mesh]
                    if not (failUntil and nowClock < failUntil) then
                        DYE_CALLS_THIS_TICK = DYE_CALLS_THIS_TICK + 1
                        -- [SDWxOWNER-OPT] Hoisted applier (no per-mesh closure alloc).
                        _OPT.dyeMesh = mesh
                        _OPT.dyeVis = visColor
                        _OPT.dyeOcc = occColor
                        -- [SDWxOWNER-WALLHACK v3] Colour-aware hibernation key: a colour
                        -- change in the menu must force ONE full re-apply per mesh.
                        _OPT.dyeKey = "wh_v4_" .. tostring(colorHash)
                        local okDye = pcall(_OPT.dyeMeshApply)
                        if not okDye then
                            -- [SDWxOWNER-PERF FIX #1] Park the failed mesh for 60 s and spread the
                            -- retries with a rotating 0..15 s jitter held on the existing scratch
                            -- table (zero new locals, zero allocation). This stops 250+ failures
                            -- from all expiring on the same tick and re-firing the native-call herd.
                            _OPT.dyeJitSeq = ((_OPT.dyeJitSeq or 0) + 1) % 7
                            DyeFailCooldown[mesh] = nowClock + DYE_FAIL_COOLDOWN + _OPT.dyeJitSeq * (DYE_FAIL_JITTER / 7)
                        end
                    end
                    end
                end
            end

            -- [SDWxOWNER-RUSH-CRASH FIX #2] Stamp the cooldown ONLY when the enemy is fully dyed.
            -- A partial pass remembers its cursor (and the colour it was built for) so the next tick
            -- continues the stream; a full pass stamps LastColorNewHash + LastColorApplyTime so the
            -- native herd cannot re-fire for 2.5 s. This keeps the per-tick work bounded WITHOUT
            -- leaving any enemy permanently un-dyed (the old code stamped unconditionally, which
            -- froze the un-dyed tail for 2.5 s and re-dyed the leading meshes on every tick).
            if markData then
                markData.ColorNewApplied = true
                if i > currentMeshCount then
                    markData.DyeComplete = true
                    markData.DyeCursor = nil
                    markData.DyeCursorColorHash = nil
                    markData.LastColorNewHash = stateHash
                    markData.LastColorApplyTime = nowTime
                else
                    markData.DyeComplete = false
                    markData.DyeCursor = i
                    markData.DyeCursorColorHash = colorHash
                end
            end
        end)
    end

    local function UndoColorBodyNew(enemy, markData)
        if not markData or not markData.ColorNewApplied then return end
        pcall(function()
            if SafeIsValid(enemy) then
                -- [SDWxOWNER-RUSH-CRASH FIX] Reuse the SAME cached mesh list that was dyed
                -- (pass markData). Previously this called GetAllSkeletalMeshes(enemy) with no
                -- markData, which re-enumerated every component (3x GetComponentsByClass +
                -- ~31 avatar slot probes + weapon pass) for EVERY enemy leaving range at the
                -- same time -> a native burst during a squad wipe / rush. The cache is
                -- re-validated below, so a destroyed mesh still falls back to a fresh scan.
                local meshes = GetAllSkeletalMeshes(enemy, markData)
                for _, mesh in ipairs(meshes) do
                    if SafeIsValid(mesh) and mesh.bIsBeingDestroyed ~= true and mesh.bPendingKill ~= true then
                        -- [SDWxOWNER-OPT] Hoisted remover (no per-mesh closure alloc).
                        _OPT.undoMesh = mesh
                        pcall(_OPT.undoMeshApply)
                        DyeFailCooldown[mesh] = nil
                    end
                end
            end
            markData.ColorNewApplied = false
            markData.DyeComplete = false
            markData.LastColorNewHash = 0
            -- [SDWxOWNER-RUSH-CRASH FIX #2] Drop the streaming cursor so the next enable starts clean.
            markData.DyeCursor = nil
            markData.DyeCursorColorHash = nil
        end)
    end
    local function ResetRuntimeCachesForMatchChange()
        AI_CACHE = {}; AI_CACHE_SIZE = 0; VEH_CACHE = {}; VEH_CACHE_TIME = 0; _G.NAME_CACHE = {}; _G.NAME_LOOKUP_DONE = {}; _G.POS_CACHE = {}
        CONSOLE_READY = false
        HDR_CONSOLE_READY = false
        if _G.SDW_ResetNativeHPInit then pcall(_G.SDW_ResetNativeHPInit) end
        if _G.SDW_ClearNativeHPMarks then pcall(_G.SDW_ClearNativeHPMarks) end
        -- [SDWxOWNER-RUSH-CRASH v2] Drop every parked-mesh entry on match change. The table is
        -- weak-keyed, but a mesh object that survives the map transition would otherwise stay
        -- "parked" into the next match and never be dyed again (silent wallhack hole).
        if DyeFailCooldown then
            for k in pairs(DyeFailCooldown) do DyeFailCooldown[k] = nil end
        end
        InvalidatePawnCache()
        _FrameCache.frame = -1; _FrameCache.pawn = nil; _FrameCache.pos = nil; _FrameCache.hud = nil; _FrameCache.pc = nil; _FrameCache.team = 0
        if rawget(_G, "SnaplineESP") then pcall(function() if SnaplineESP.HardClear then SnaplineESP.HardClear() else SnaplineESP.ClearAllSnapLines(); SnaplineESP.ESPCanvas = nil end end) end
        if GK_DestroyWidget then GK_DestroyWidget() end
        -- [SDWxOWNER-CRASH FIX] Tear the watermark down on match change too, so no orphan widget
        -- survives into the next match (that orphan is what made the watermark text DOUBLED on
        -- match 2). Belt-and-braces with the gen-check inside SDW_EnsurePaidWatermark.
        if _G.SDW_DestroyWatermark then pcall(_G.SDW_DestroyWatermark) end
        -- [SDWxOWNER] V3 iOS counter: tear the capsule widgets down on map change so
        -- no orphan widgets survive into the next match (crash-safe).
        if _G.SDW_StopV3Counter then pcall(_G.SDW_StopV3Counter)
        elseif _G.SDW_V3Counter and _G.SDW_V3Counter.Destroy then pcall(_G.SDW_V3Counter.Destroy) end
        -- [SDWxOWNER] V4 HD Image counter: same crash-safe teardown on map change.
        if _G.SDW_StopV4Counter then pcall(_G.SDW_StopV4Counter)
        elseif _G.SDW_V4Counter and _G.SDW_V4Counter.Destroy then pcall(_G.SDW_V4Counter.Destroy) end
        -- [SDWxOWNER] V5 "Player / Bot" counter: same crash-safe teardown on map change.
        if _G.SDW_StopV5Counter then pcall(_G.SDW_StopV5Counter)
        elseif _G.SDW_V5Counter and _G.SDW_V5Counter.Destroy then pcall(_G.SDW_V5Counter.Destroy) end
        if _G.SDWState and _G.SDWState.EnemyMarks then
            for _, md in pairs(_G.SDWState.EnemyMarks) do
                if md and md.enemy and UndoColorBodyNew then UndoColorBodyNew(md.enemy, md) end
            end
            _G.SDWState.EnemyMarks = {}
        end
        if rawget(_G, "SnaplineESP") then pcall(function() if SnaplineESP.HardClear then SnaplineESP.HardClear() else SnaplineESP.Clear() end end) end
        -- Reset the plane/transport guard cache so the new match starts clean.
        if _G.SDW_ResetUnsafeCache then _G.SDW_ResetUnsafeCache() end
    end

    -- [SDWxOWNER] Distance+ Bot Tag vertical anchor. Raised from 15 (pelvis) to 75 so
    -- the text (distance on top) sits at NECK / upper-chest height.
    local TEXT_OFFSET = { X = 0, Y = 0, Z = 75 }
    local _PAWN_CACHE = nil
    local _PAWN_CACHE_TIME = 0
    local _PAWN_CACHE_TTL = 0.5
    local function InvalidatePawnCache()
        _PAWN_CACHE = nil
        _PAWN_CACHE_TIME = 0
    end
    -- [SDWxOWNER-OPT] Hoisted roster-collection helpers for GetCachedPlayerPawns.
    _OPT.pcpList = nil
    _OPT.pcpSeen = nil
    function _OPT.pcpAddPawn(p)
        if p and SafeIsValid(p) and not _OPT.pcpSeen[p] then
            _OPT.pcpSeen[p] = true
            _OPT.pcpList[#_OPT.pcpList + 1] = p
        end
    end
    -- [SDWxOWNER-PERF] Cache required modules instead of re-requiring ~2x/second.
    function _OPT.pcpFromGameplayData()
        local gp = _OPT.pcpGDP
        if not gp then
            local okGP; okGP, gp = pcall(require, "GameLua.GameCore.Data.GameplayData")
            if not okGP then gp = nil end
            _OPT.pcpGDP = gp
        end
        if gp and gp.GetAllCharacters then
            local chars = gp.GetAllCharacters()
            if chars then
                for _, c in pairs(chars) do _OPT.pcpAddPawn(c) end
            end
        end
    end
    -- [SDWxOWNER-ALLMAPS] Additional roster sources. Game:GetAllPlayerPawns() (and even
    -- GameplayData.GetAllCharacters) come back EMPTY on several modes (rooms / TDM / FFA /
    -- custom), so we ALSO pull GameplayData.GetAllPlayerCharacters / GameplayData.GameCharacters
    -- -- the exact character lists the aimbot's all-maps gather relies on. De-duplicated through
    -- _OPT.pcpSeen, so this can only ADD pawns the old gather missed (never removes any).
    function _OPT.pcpFromGameplayData2()
        local gp = _OPT.pcpGDP
        if not gp then
            local okGP; okGP, gp = pcall(require, "GameLua.GameCore.Data.GameplayData")
            if not okGP then gp = nil end
            _OPT.pcpGDP = gp
        end
        if not gp then return end
        if gp.GetAllPlayerCharacters then
            local ok, list = pcall(gp.GetAllPlayerCharacters)
            if ok and list then
                for _, c in pairs(list) do _OPT.pcpAddPawn(c) end
            end
        end
        if gp.GameCharacters then
            for _, c in pairs(gp.GameCharacters) do _OPT.pcpAddPawn(c) end
        end
    end
    function _OPT.pcpFromGameState()
        local GS = _OPT.pcpGS
        if not GS then
            local okGS; okGS, GS = pcall(require, "GameLua.GameCore.Data.CGameState")
            if not okGS then GS = nil end
            _OPT.pcpGS = GS
        end
        if GS and GS.GetAllCharacters then
            local chars = GS:GetAllCharacters()
            if chars then
                for _, c in pairs(chars) do _OPT.pcpAddPawn(c) end
            end
        end
    end
    local function GetCachedPlayerPawns()
        local now = os.clock()
        if _PAWN_CACHE and (now - _PAWN_CACHE_TIME) < _PAWN_CACHE_TTL then return true, _PAWN_CACHE end

        local pawnsList = {}
        local seenPawns = {}
        -- [SDWxOWNER-OPT] Wire the hoisted helpers to this refresh's output tables.
        _OPT.pcpList = pawnsList
        _OPT.pcpSeen = seenPawns

        local ok, pawns = SafeMethodCall(Game, "GetAllPlayerPawns")
        if ok and pawns then
            for _, p in pairs(pawns) do _OPT.pcpAddPawn(p) end
        end

        pcall(_OPT.pcpFromGameplayData)
        -- [SDWxOWNER-ALLMAPS] Augment with the extra character lists (TDM / FFA / rooms).
        pcall(_OPT.pcpFromGameplayData2)

        if #pawnsList == 0 then
            pcall(_OPT.pcpFromGameState)
        end

        if #pawnsList > 0 then
            _PAWN_CACHE = pawnsList
            _PAWN_CACHE_TIME = now
            return true, _PAWN_CACHE
        end

        if _PAWN_CACHE then return true, _PAWN_CACHE end
        return ok, pawns
    end

    local function GetESPState()
        if not rawget(_G, "Game") then return end
        local okLocal, localPawn = pcall(GameplayData.GetPlayerCharacter); if not okLocal or not SafeIsValid(localPawn) then return end
        local matchToken = localPawn; local okState, gameState = SafeMethodCall(GameplayData, "GetGameState"); if okState and SafeIsValid(gameState) then matchToken = gameState end
        if PBC_MATCH_TOKEN and PBC_MATCH_TOKEN ~= matchToken then ResetRuntimeCachesForMatchChange() end; PBC_MATCH_TOKEN = matchToken
        if not CONSOLE_READY then SetupConsole() end
        local okPos, myPos = SafeMethodCall(localPawn, "K2_GetActorLocation"); if not okPos or not myPos then return end
        local hud = nil; local pc = nil
        local okPc, retPc = pcall(GameplayData.GetPlayerController)
        if okPc and SafeIsValid(retPc) then pc = retPc end
        if not SafeIsValid(pc) and slua_GameFrontendHUD then local okPc2, retPc2 = SafeMethodCall(slua_GameFrontendHUD, "GetPlayerController"); if okPc2 then pc = retPc2 end end
        if SafeIsValid(pc) then local okHud, retHud = SafeMethodCall(pc, "GetHUD"); if okHud then hud = retHud end end
        return localPawn, myPos, hud, pc
    end

    local FLinearColor = import("LinearColor") or _G.FLinearColor or LinearColor
    local FVector2D = import("Vector2D") or _G.FVector2D
    local FVector = import("Vector") or _G.FVector

    local _SnaplinePawnsPool = {}
    local _tempHeadLoc = FVector and FVector(0, 0, 0) or { X = 0, Y = 0, Z = 0 }

    local SnaplineESP = {
        ESPCanvas = nil,
        SnapLineWidgets = {},
        bUseSnapLines = true,
        SnapLineThickness = 1,   -- [SDWxOWNER] allowed: 0.8 / 1 / 2 only
        SnapLineOriginY = 72.0,   -- [SDWxOWNER] line start Y (matches the menu default)
        SnapLineOriginOffsetX = 0.0,
        SnapLineHeadOffsetX = 0.0,
        SnapLineHeadOffsetY = -6.0,   -- [SDWxOWNER-FIX] end the line right ON the head top (was -14 -> floated above)
        SnapLineEnemyColor = FLinearColor and FLinearColor(1.0, 0.15, 0.15, 0.85) or nil,
        SnapLineEnemyVisibleColor = FLinearColor and FLinearColor(0.0, 1.0, 0.2, 0.95) or nil,
        SnapLineBotColor = FLinearColor and FLinearColor(0.0, 0.9, 1.0, 0.80) or nil,
        SnapLineBotVisibleColor = FLinearColor and FLinearColor(0.3, 1.0, 1.0, 0.95) or nil,
        LineVisColorId = 2,
        LineHidColorId = 1,
        BotLineColorId = 6,   -- [SDWxOWNER] bots always cyan
        _CanvasScaleX = 1.0,
        _CanvasScaleY = 1.0,
        _CanvasOffsetX = 0.0,
        _CanvasOffsetY = 0.0,
        _lastTransformTime = 0,
        _CachedTopCenterPixel = FVector2D and FVector2D(0, 0) or { X = 0, Y = 0 },
        _cachedViewportW = 1920,
        _cachedViewportH = 1080,
        _CachedFromX = 0,
        _CachedFromY = 0,
        _lastStartPosTime = 0,
        _tempScreenPixelPos = FVector2D and FVector2D(0, 0) or { X = 0, Y = 0 },
        _tempCanvasPos = FVector2D and FVector2D(0, 0) or { X = 0, Y = 0 },
        _ZeroVector = nil,
        _CachedHitResult = nil,
        _InitGen = -1,
        -- [SDWxOWNER-FULLMATCH FIX] Heartbeats from the snapline ticks so the watchdog can detect a dead tick.
        _LastScanTime = 0,
        _LastFastTime = 0,
    }
    _G.SnaplineESP = SnaplineESP

    function SnaplineESP.LineCol(id, a)
        id = tonumber(id) or 1; a = a or 0.9
        if not FLinearColor then return nil end
        if id == 2 then return FLinearColor(0.0, 1.0, 0.15, a) end
        if id == 3 then return FLinearColor(0.2, 0.5, 1.0, a) end
        if id == 4 then return FLinearColor(1.0, 1.0, 0.0, a) end
        if id == 5 then return FLinearColor(1.0, 1.0, 1.0, a) end
        if id == 6 then return FLinearColor(0.0, 0.9, 1.0, a) end   -- Cyan (bots)
        return FLinearColor(1.0, 0.05, 0.05, a)
    end

    -- [SDWxOWNER-PERF] Hoisted controller/pawn probes (closure-free pcall targets).
    local _gmpPC, _gmpPlayer = nil, nil
    local function _gmpFromHUD() _gmpPC = slua_GameFrontendHUD:GetPlayerController() end
    local function _gmpFromPCSafety() _gmpPlayer = _gmpPC:GetPlayerCharacterSafety() end
    local function _gmpFromPawn() _gmpPlayer = _gmpPC:GetPawn() end

    function SnaplineESP.GetMyControllerAndPlayer()
        local pc, player = nil, nil
        local GDP = _cached_GameplayData
        if not GDP then
            local ok; ok, GDP = pcall(require, "GameLua.GameCore.Data.GameplayData")
            if ok then _cached_GameplayData = GDP end
        end
        if GDP then
            if GDP.GetPlayerController then pc = GDP.GetPlayerController() end
            if GDP.GetPlayerCharacter then player = GDP.GetPlayerCharacter() end
        end
        if not pc and slua_GameFrontendHUD then
            _gmpPC = nil; pcall(_gmpFromHUD); pc = _gmpPC
        end
        if pc and not player and pc.GetPlayerCharacterSafety then
            _gmpPC = pc; _gmpPlayer = nil; pcall(_gmpFromPCSafety); player = _gmpPlayer
        end
        if pc and not player and pc.GetPawn then
            _gmpPC = pc; _gmpPlayer = nil; pcall(_gmpFromPawn); player = _gmpPlayer
        end
        return pc, player
    end

    -- [SDWxOWNER-PERF] Short-lived cache for the snapline pawn roster.
    local _SnaplinePawnsTime = 0
    -- [SDWxOWNER-ZEROLAG] Closure-free fallback collectors. The old fallback built TWO fresh
    -- `pcall(function() ... end)` closures (plus a fresh `seen = {}` table) on every call. These
    -- hoisted versions reuse one persistent seen-set, so the fallback path allocates nothing.
    _OPT.snapFbSeen = _OPT.snapFbSeen or {}
    _OPT.snapFbCount = 0
    function _OPT.snapFbA()
        local seen, pool = _OPT.snapFbSeen, _SnaplinePawnsPool
        if Game and Game.GetAllPlayerPawns then
            local pawns = Game:GetAllPlayerPawns()
            if pawns then
                for _, p in pairs(pawns) do
                    if p and slua.isValid(p) and not seen[p] then
                        seen[p] = true
                        local c = _OPT.snapFbCount + 1
                        _OPT.snapFbCount = c
                        pool[c] = p
                    end
                end
            end
        end
    end
    function _OPT.snapFbB()
        local ok, GS = pcall(require, "GameLua.GameCore.Data.CGameState")
        if ok and GS and GS.GetAllCharacters then
            local chars = GS:GetAllCharacters()
            if chars then
                local seen, pool = _OPT.snapFbSeen, _SnaplinePawnsPool
                for _, c in pairs(chars) do
                    if c and slua.isValid(c) and not seen[c] then
                        seen[c] = true
                        local n = _OPT.snapFbCount + 1
                        _OPT.snapFbCount = n
                        pool[n] = c
                    end
                end
            end
        end
    end

    function SnaplineESP.GetAllPawns()
        -- [SDWxOWNER-FULLMATCH FIX] Use the same de-duplicated roster as Wallhack/BoxESP
        -- (pawns + GameplayData + CGameState) so no enemy is ever missed.
        local okShared, shared = false, nil
        if GetCachedPlayerPawns then okShared, shared = GetCachedPlayerPawns() end
        if okShared and shared and #shared > 0 then
            return shared
        end
        -- Fallback (shared roster unavailable): merged, de-duplicated collection.
        local now = os.clock()
        if _SnaplinePawnsTime > 0 and (now - _SnaplinePawnsTime) < 0.2 then
            return _SnaplinePawnsPool
        end
        _SnaplinePawnsTime = now
        for i = 1, #_SnaplinePawnsPool do _SnaplinePawnsPool[i] = nil end
        local seen = _OPT.snapFbSeen
        for k in pairs(seen) do seen[k] = nil end
        _OPT.snapFbCount = 0
        pcall(_OPT.snapFbA)
        pcall(_OPT.snapFbB)
        return _SnaplinePawnsPool
    end

    function SnaplineESP.InitESPCanvas()
        -- [SDWxOWNER-PERF] Fast path: reuse cached canvas if still alive (avoids require+lookup every tick)
        if SnaplineESP.ESPCanvas and slua.isValid(SnaplineESP.ESPCanvas) and SnaplineESP._InitGen == (_G._SDW_MatchGen or 0) then
            return true
        end
        local ok, InGameUITools = pcall(require, "GameLua.Mod.BaseMod.Common.UI.InGameUITools")
        if not ok or not InGameUITools then return false end
        local MainControlBaseUI = nil
        pcall(function() MainControlBaseUI = InGameUITools.GetMainControlBaseUI and InGameUITools.GetMainControlBaseUI() end)
        if not MainControlBaseUI or not slua.isValid(MainControlBaseUI) then return false end

        local ParentCanvas = nil
        if MainControlBaseUI.CanvasPanel_0 and slua.isValid(MainControlBaseUI.CanvasPanel_0) then
            ParentCanvas = MainControlBaseUI.CanvasPanel_0
        elseif MainControlBaseUI.CanvasPanel_42 and slua.isValid(MainControlBaseUI.CanvasPanel_42) then
            ParentCanvas = MainControlBaseUI.CanvasPanel_42
        end
        if not ParentCanvas or not slua.isValid(ParentCanvas) then return false end

        local gen = _G._SDW_MatchGen or 0
        if SnaplineESP._InitGen ~= gen or SnaplineESP.ESPCanvas ~= ParentCanvas then
            pcall(function() if SnaplineESP.ClearAllSnapLines then SnaplineESP.ClearAllSnapLines() end end)
            SnaplineESP.ESPCanvas = nil
            SnaplineESP.SnapLineWidgets = {}
            SnaplineESP._WidgetPool = {}
            SnaplineESP._lastTransformTime = 0
            SnaplineESP._lastStartPosTime = 0
            SnaplineESP._CachedFromX = 0
            SnaplineESP._CachedFromY = 0
            SnaplineESP._CanvasScaleX = nil
            SnaplineESP._CanvasScaleY = nil
            -- [SDWxOWNER-FULLMATCH FIX] The draw list is stale the moment the canvas is (re)created.
            SnaplineESP._DrawCount = 0
            SnaplineESP._DrawPC = nil
            SnaplineESP._InitGen = gen
        end
        SnaplineESP.ESPCanvas = ParentCanvas
        return true
    end

    function SnaplineESP.ResetForMatch()
        pcall(function() SnaplineESP.ClearAllSnapLines() end)
        SnaplineESP.SnapLineWidgets = {}
        SnaplineESP._WidgetPool = {}
        SnaplineESP.ESPCanvas = nil
        SnaplineESP._InitGen = -1
        _SnaplinePawnsTime = 0
        SnaplineESP._lastTransformTime = 0
        SnaplineESP._lastStartPosTime = 0
        SnaplineESP._CachedFromX = 0
        SnaplineESP._CachedFromY = 0
        SnaplineESP._DrawCount = 0
        SnaplineESP._DrawPC = nil
        -- [SDWxOWNER-PERF 1.5x] Re-arm the fast-tick camera gate for the new match.
        SnaplineESP._fastCamYaw = nil
        SnaplineESP._fastFrame = 0
    end

    -- [SDWxOWNER-ZEROLAG] Hoisted canvas-transform probes. The old body built THREE fresh
    -- `pcall(function() ... end)` closures every time the transform was re-measured. These
    -- plain functions are created once; each returns true when it produced a usable transform.
    function SnaplineESP._uctA()
        local SBL = _ci_SBL
        if not (SBL and SBL.AbsoluteToLocal) then return false end
        local cg = SnaplineESP.ESPCanvas:GetCachedGeometry()
        if not cg then return false end
        local v = SnaplineESP._tempScreenPixelPos
        if not v then v = FVector2D and FVector2D(0, 0) or { X = 0, Y = 0 }; SnaplineESP._tempScreenPixelPos = v end
        v.X = 0; v.Y = 0
        local pt0 = SBL.AbsoluteToLocal(cg, v)
        v.X = 100; v.Y = 100
        local pt1 = SBL.AbsoluteToLocal(cg, v)
        if not (pt0 and pt1) then return false end
        SnaplineESP._CanvasScaleX = (pt1.X - pt0.X) / 100
        SnaplineESP._CanvasScaleY = (pt1.Y - pt0.Y) / 100
        SnaplineESP._CanvasOffsetX = pt0.X
        SnaplineESP._CanvasOffsetY = pt0.Y
        return true
    end
    function SnaplineESP._uctB(PC)
        local WLL = _ci_WLL
        if not (WLL and WLL.ScreenToWidgetLocal) then return false end
        local cg = SnaplineESP.ESPCanvas:GetCachedGeometry()
        if not cg then return false end
        local pt0 = FVector2D and FVector2D(0, 0) or { X = 0, Y = 0 }
        local pt1 = FVector2D and FVector2D(0, 0) or { X = 0, Y = 0 }
        local in0 = FVector2D and FVector2D(0, 0) or { X = 0, Y = 0 }
        local in1 = FVector2D and FVector2D(100, 100) or { X = 100, Y = 100 }
        WLL.ScreenToWidgetLocal(PC, cg, in0, pt0)
        WLL.ScreenToWidgetLocal(PC, cg, in1, pt1)
        SnaplineESP._CanvasScaleX = (pt1.X - pt0.X) / 100
        SnaplineESP._CanvasScaleY = (pt1.Y - pt0.Y) / 100
        SnaplineESP._CanvasOffsetX = pt0.X
        SnaplineESP._CanvasOffsetY = pt0.Y
        return true
    end
    function SnaplineESP._uctC(PC)
        local scale = 1.0
        local WLL = _ci_WLL
        if WLL and WLL.GetViewportScale then scale = WLL.GetViewportScale(PC) or 1.0 end
        SnaplineESP._CanvasScaleX = 1.0 / scale
        SnaplineESP._CanvasScaleY = 1.0 / scale
        SnaplineESP._CanvasOffsetX = 0
        SnaplineESP._CanvasOffsetY = 0
    end

    function SnaplineESP.UpdateCanvasTransform(PC)
        if not SnaplineESP.ESPCanvas or not slua.isValid(SnaplineESP.ESPCanvas) then return end
        local now = os.clock()
        if SnaplineESP._lastTransformTime and (now - SnaplineESP._lastTransformTime < 1.0) and SnaplineESP._CanvasScaleX and SnaplineESP._CanvasScaleX > 0 then
            return
        end
        SnaplineESP._lastTransformTime = now

        local success = false
        local okA, resA = pcall(SnaplineESP._uctA)
        if okA and resA then success = true end
        if not success then
            local okB, resB = pcall(SnaplineESP._uctB, PC)
            if okB and resB then success = true end
        end
        if not success then pcall(SnaplineESP._uctC, PC) end
    end

    function SnaplineESP.ScreenPixelToCanvasLocal(PC, ScreenPixelPos)
        if not ScreenPixelPos then return SnaplineESP._tempCanvasPos end
        local scaleX = SnaplineESP._CanvasScaleX or 1.0
        local scaleY = SnaplineESP._CanvasScaleY or 1.0
        local offsetX = SnaplineESP._CanvasOffsetX or 0
        local offsetY = SnaplineESP._CanvasOffsetY or 0
        local x = ScreenPixelPos.X * scaleX + offsetX
        local y = ScreenPixelPos.Y * scaleY + offsetY
        if not SnaplineESP._tempCanvasPos then
            SnaplineESP._tempCanvasPos = (FVector2D and FVector2D(x, y)) or {X = x, Y = y}
        else
            SnaplineESP._tempCanvasPos.X = x
            SnaplineESP._tempCanvasPos.Y = y
        end
        return SnaplineESP._tempCanvasPos
    end

    -- [SDWxOWNER-PERF] Hoisted projection closure.
    local _projPC, _projWorldLoc, _projOut, _projOK = nil, nil, nil, false
    local function _projDoProject()
        local res = _projPC:ProjectWorldLocationToScreen(_projWorldLoc, _projOut, true)
        if res == true or res == 1 then _projOK = true end
    end
    function SnaplineESP.ProjectWorldToCanvasLocal(PC, WorldLoc)
        if not PC or not slua.isValid(PC) or not WorldLoc then return false, SnaplineESP._tempCanvasPos end
        if not SnaplineESP._tempScreenPixelPos then SnaplineESP._tempScreenPixelPos = FVector2D and FVector2D(0, 0) or {X=0, Y=0} end
        local sp = SnaplineESP._tempScreenPixelPos
        sp.X = 0; sp.Y = 0
        _projPC, _projWorldLoc, _projOut, _projOK = PC, WorldLoc, sp, false
        pcall(_projDoProject)
        -- [SDWxOWNER-FULLMATCH FIX] Trust the engine's success flag; the old (0,0)
        -- heuristic wrongly dropped screen-centred enemies.
        if not _projOK then return false, SnaplineESP._tempCanvasPos end
        local _px, _py = sp.X, sp.Y
        if type(_px) ~= "number" or type(_py) ~= "number" then return false, SnaplineESP._tempCanvasPos end
        if _px ~= _px or _py ~= _py then return false, SnaplineESP._tempCanvasPos end   -- NaN guard
        local CanvasLocalPos = SnaplineESP.ScreenPixelToCanvasLocal(PC, sp)
        return true, CanvasLocalPos
    end

    -- [SDWxOWNER-PERF] Hoisted probes for ProjectWorldToCanvasLocalChecked (per-enemy hot path).
    -- Wrapped in a do-block so these scratch locals are released afterwards and do not count
    -- against LuaJIT's 200-local limit for the main chunk. pcall(fn, ...) allocates NO closure,
    -- unlike the old pcall(function() ... end) which built a fresh one on every enemy, every scan.
    do
    local _pwcPC, _pwcCamLoc, _pwcRot, _pwcFwd = nil, nil, nil, nil
    local function _pwcGetCamLoc()
        local cam = _pwcPC.PlayerCameraManager
        if cam and slua.isValid(cam) then
            if cam.CameraCache and cam.CameraCache.POV then _pwcCamLoc = cam.CameraCache.POV.Location end
            if not _pwcCamLoc and type(cam.GetCameraLocation) == "function" then _pwcCamLoc = cam:GetCameraLocation() end
        end
    end
    local function _pwcGetRot() _pwcRot = _pwcPC:GetControlRotation() end
    local function _pwcGetFwd(KM) _pwcFwd = KM.GetForwardVector(_pwcRot) end
    local _pwcWorldLoc, _pwcOut, _pwcOK = nil, nil, false
    local function _pwcProject()
        local res = _pwcPC:ProjectWorldLocationToScreen(_pwcWorldLoc, _pwcOut, true)
        if res == true or res == 1 then _pwcOK = true end
    end
    local _pwcVW, _pwcVH = 0, 0
    local _pwcVPTime = -1000
    local function _pwcViewport()
        if not SnaplineESP._tempViewportSize then SnaplineESP._tempViewportSize = FVector2D and FVector2D(0, 0) or {X=0, Y=0} end
        local vs = SnaplineESP._tempViewportSize
        _pwcPC:GetViewportSize(vs)
        if vs and vs.X and vs.X > 200 then _pwcVW = vs.X; _pwcVH = vs.Y end
    end

    -- [SDWxOWNER-RUSH-FPS] PER-FRAME PROJECTION CACHE.
    -- ROOT CAUSE of the rush FPS drop: the Box ESP re-projects every enemy TWICE per frame
    -- (head + feet), and EACH projection used to re-read the PlayerCameraManager, the camera
    -- POV, the control rotation, the forward vector AND the viewport size. With 10 enemies at
    -- 60 fps that is ~6,000 native reflection calls + ~3,000 pcall trampolines per second, all
    -- on the game thread -- exactly the 60 -> 20/30 fps collapse reported during a 2-3 squad
    -- rush. The camera basis and the viewport are IDENTICAL for every enemy within one frame,
    -- so we now sample them ONCE per frame (BeginProjectionFrame bumps the stamp) and reuse
    -- them for every projection in that frame. Same math, same result, ~95% fewer native calls.
    local _pwcCamStamp = -1
    local _pwcCachedCamLoc, _pwcCachedFwd = nil, nil
    -- [SDWxOWNER-RUSH-FPS] Per-frame PC validity cache: slua.isValid() is a native
    -- reflection call and the projection is invoked twice per enemy per frame
    -- (head + feet). The controller cannot be destroyed mid-frame, so one probe per
    -- frame is enough -> ~20 fewer native calls per frame during a 10-enemy rush.
    local _pwcPcStamp, _pwcPcObj, _pwcPcOK = -1, nil, true
    function SnaplineESP.BeginProjectionFrame()
        SnaplineESP._projFrame = (SnaplineESP._projFrame or 0) + 1
    end

    -- [SDWxOWNER] Like ProjectWorldToCanvasLocal but also checks the point is in front + in-viewport.
    function SnaplineESP.ProjectWorldToCanvasLocalChecked(PC, WorldLoc)
        if not PC or not WorldLoc then return false, SnaplineESP._tempCanvasPos end
        local _pcStamp = SnaplineESP._projFrame or 0
        if _pwcPcStamp ~= _pcStamp or _pwcPcObj ~= PC then
            _pwcPcStamp, _pwcPcObj = _pcStamp, PC
            _pwcPcOK = slua.isValid(PC) and true or false
        end
        if not _pwcPcOK then return false, SnaplineESP._tempCanvasPos end

        -- (1) Is the point in front of the camera? (dot(forward, toPoint) > 0)
        -- [SDWxOWNER-RUSH-FPS] Camera basis is sampled once per frame, not once per projection.
        local stamp = SnaplineESP._projFrame or 0
        local camLoc, fwd
        if _pwcCamStamp == stamp then
            camLoc, fwd = _pwcCachedCamLoc, _pwcCachedFwd
        else
            _pwcCamStamp = stamp
            _pwcPC = PC; _pwcCamLoc = nil
            pcall(_pwcGetCamLoc)
            camLoc = _pwcCamLoc
            local rot = nil
            _pwcPC = PC; _pwcRot = nil
            pcall(_pwcGetRot)
            rot = _pwcRot
            fwd = nil
            if rot then
                local KM = _ci_KismetMath
                if not KM then KM = import("KismetMathLibrary"); if KM then _ci_KismetMath = KM end end
                if KM and KM.GetForwardVector then
                    _pwcRot = rot; _pwcFwd = nil
                    pcall(_pwcGetFwd, KM)
                    fwd = _pwcFwd
                end
            end
            _pwcCachedCamLoc, _pwcCachedFwd = camLoc, fwd
        end
        if camLoc and fwd then
            local dx = WorldLoc.X - camLoc.X
            local dy = WorldLoc.Y - camLoc.Y
            local dz = WorldLoc.Z - camLoc.Z
            if (dx * fwd.X + dy * fwd.Y + dz * fwd.Z) <= 0 then
                return false, SnaplineESP._tempCanvasPos
            end
        end

        -- (2) Project to screen.
        if not SnaplineESP._tempScreenPixelPos then SnaplineESP._tempScreenPixelPos = FVector2D and FVector2D(0, 0) or {X=0, Y=0} end
        local sp = SnaplineESP._tempScreenPixelPos
        sp.X = 0; sp.Y = 0
        local bOK = false
        _pwcPC = PC; _pwcWorldLoc = WorldLoc; _pwcOut = sp; _pwcOK = false
        pcall(_pwcProject)
        bOK = _pwcOK
        if not bOK then return false, SnaplineESP._tempCanvasPos end
        local x, y = sp.X, sp.Y
        if not (type(x) == "number" and type(y) == "number") then return false, SnaplineESP._tempCanvasPos end
        if x ~= x or y ~= y then return false, SnaplineESP._tempCanvasPos end   -- NaN guard

        -- (3) Is the projected point inside the viewport? (small margin so bars
        --     right at the edge still show instead of popping).
        -- [SDWxOWNER-RUSH-FPS] The viewport size only changes on a resolution / rotation
        -- change, so it is cached for 2 s instead of being re-read twice per enemy per frame.
        local vw, vh = _pwcVW, _pwcVH
        local _vpNow = os.clock()
        if vw <= 200 or (_vpNow - _pwcVPTime) > 2.0 then
            _pwcVPTime = _vpNow
            _pwcPC = PC; _pwcVW = 0; _pwcVH = 0
            pcall(_pwcViewport)
            vw, vh = _pwcVW, _pwcVH
            if vw <= 200 then
                local WLL = _ci_WLL
                if WLL and WLL.GetViewportSize then
                    local ok, vs = pcall(WLL.GetViewportSize, PC)
                    if ok and vs and vs.X and vs.X > 200 then vw = vs.X; vh = vs.Y; _pwcVW = vw; _pwcVH = vh end
                end
            end
            if vw <= 200 then vw = 1920; vh = 1080; _pwcVW = vw; _pwcVH = vh end
        end
        local m = 60
        if x < -m or x > vw + m or y < -m or y > vh + m then return false, SnaplineESP._tempCanvasPos end

        local CanvasLocalPos = SnaplineESP.ScreenPixelToCanvasLocal(PC, sp)
        return true, CanvasLocalPos
    end
    end  -- [SDWxOWNER-PERF] close ProjectWorldToCanvasLocalChecked helper scope

    -- [SDWxOWNER-PERF] Hoisted viewport probes for GetSnapLineStartPos (closure-free).
    -- This runs once per line-origin refresh; the old inline closures allocated 3 tables
    -- per call. Wrapped in a do-block to keep the main chunk under the 200-local limit.
    do
    local _gspPC, _gspW, _gspH, _gspScale = nil, 0, 0, 1.0
    local function _gspViewport()
        if _gspPC and _gspPC.GetViewportSize then
            local vs = SnaplineESP._tempScreenPixelPos or (FVector2D and FVector2D(0, 0) or {X=0,Y=0})
            _gspPC:GetViewportSize(vs)
            if vs and vs.X and vs.X > 200 then _gspW = vs.X; _gspH = vs.Y end
        end
    end
    local function _gspWLLViewport()
        local WLL = _ci_WLL
        if WLL and WLL.GetViewportSize then
            local vs = WLL.GetViewportSize(_gspPC)
            if vs and vs.X and vs.X > 200 then _gspW = vs.X; _gspH = vs.Y end
        end
    end
    local function _gspWLLScale()
        local WLL = _ci_WLL
        if WLL and WLL.GetViewportScale then
            local s = WLL.GetViewportScale(_gspPC)
            if s and type(s) == "number" and s > 0 then _gspScale = s end
        end
    end

    function SnaplineESP.GetSnapLineStartPos(PC)
        local now = os.clock()
        if SnaplineESP._lastStartPosTime and (now - SnaplineESP._lastStartPosTime < 0.5) and SnaplineESP._CachedFromX and SnaplineESP._CachedFromX > 0 then
            return SnaplineESP._CachedFromX, SnaplineESP._CachedFromY
        end
        SnaplineESP._lastStartPosTime = now

        local screenPixelW, screenPixelH = 0, 0
        local scale = 1.0

        _gspPC = PC; _gspW = 0; _gspH = 0
        pcall(_gspViewport)
        screenPixelW, screenPixelH = _gspW, _gspH
        if screenPixelW <= 200 then
            _gspPC = PC; _gspW = 0; _gspH = 0
            pcall(_gspWLLViewport)
            screenPixelW, screenPixelH = _gspW, _gspH
        end
        _gspPC = PC; _gspScale = 1.0
        pcall(_gspWLLScale)
        scale = _gspScale
        if screenPixelW <= 200 then
            screenPixelW = (SnaplineESP._cachedViewportW or 1920) * scale
            screenPixelH = (SnaplineESP._cachedViewportH or 1080) * scale
        end

        if not SnaplineESP._CachedTopCenterPixel then SnaplineESP._CachedTopCenterPixel = FVector2D and FVector2D(0, 0) or {X=0,Y=0} end
        SnaplineESP._CachedTopCenterPixel.X = screenPixelW / 2.0
        SnaplineESP._CachedTopCenterPixel.Y = (SnaplineESP.SnapLineOriginY or 50) * scale

        local fromCanvasPos = SnaplineESP.ScreenPixelToCanvasLocal(PC, SnaplineESP._CachedTopCenterPixel)
        local fromX = fromCanvasPos.X + (SnaplineESP.SnapLineOriginOffsetX or 0)
        local fromY = fromCanvasPos.Y

        SnaplineESP._CachedFromX = fromX
        SnaplineESP._CachedFromY = fromY
        return fromX, fromY
    end
    end  -- [SDWxOWNER-PERF] close GetSnapLineStartPos helper scope

    -- [SDWxOWNER-PERF] Hoisted widget builders for CreateSnapLine (closure-free). A new
    -- enemy line used to allocate ~6 closures; now it allocates none. Wrapped in a do-block
    -- to keep the main chunk under the 200-local limit.
    do
    local _csnCGame, _csnCanvas, _csnBorder, _csnSlot = nil, nil, nil, nil
    local function _csnNewBorder() _csnBorder = _csnCGame:NewObjectFromPath("/Script/UMG.Border", _csnCanvas) end
    local function _csnSetBrush(w, color) w:SetBrushColor(color) end
    local function _csnSetSelfHit(w) w:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible) end
    local function _csnSetPivotProp(w, pv) w.RenderTransformPivot = pv end
    local function _csnSetPivotMethod(w, pv) w:SetRenderTransformPivot(pv) end
    local function _csnAddChild(canvas, border)
        _csnSlot = canvas:AddChildToCanvas(border)
        if _csnSlot then _csnSlot:SetAutoSize(false); _csnSlot:SetZOrder(1) end
    end

    function SnaplineESP.CreateSnapLine(forceNew)
        if not SnaplineESP.InitESPCanvas() then return nil end
        local canvas = SnaplineESP.ESPCanvas
        if not canvas or not slua.isValid(canvas) then return nil end

        -- [SDWxOWNER-PERF] Widget pooling: reuse a collapsed Border instead of allocating a new one
        local pool = SnaplineESP._WidgetPool
        if not pool then pool = {}; SnaplineESP._WidgetPool = pool end
        local Border, Slot = nil, nil
        if not forceNew then
            for i = #pool, 1, -1 do
                local pooled = pool[i]
                if pooled and pooled.Widget and slua.isValid(pooled.Widget) then
                    Border = pooled.Widget
                    Slot = pooled.Slot
                    table.remove(pool, i)
                    break
                end
                table.remove(pool, i)
            end
        end

        if not Border or not slua.isValid(Border) then
            local CGameRef = rawget(_G, "CGame") or CGame
            if CGameRef and CGameRef.NewObjectFromPath then
                _csnCGame = CGameRef; _csnCanvas = canvas; _csnBorder = nil
                pcall(_csnNewBorder)
                Border = _csnBorder
            end
        end
        if not Border or not slua.isValid(Border) then return nil end

        local color = SnaplineESP.SnapLineEnemyColor or (FLinearColor and FLinearColor(1.0, 0.15, 0.15, 0.85) or nil)
        if color then pcall(_csnSetBrush, Border, color) end
        pcall(_csnSetSelfHit, Border)
        local pv = FVector2D and FVector2D(0.0, 0.5) or {X=0,Y=0.5}
        pcall(_csnSetPivotProp, Border, pv)
        pcall(_csnSetPivotMethod, Border, pv)

        if not Slot or not slua.isValid(Slot) then
            _csnSlot = nil
            pcall(_csnAddChild, canvas, Border)
            Slot = _csnSlot
        end
        if not Slot then return nil end
        return { Widget = Border, Slot = Slot, _canvas = canvas, _gen = (_G._SDW_MatchGen or 0) }
    end

    -- [SDWxOWNER-RUSH-FPS] Idle pre-warm for the snapline widget pool. Creating 8-10 new
    -- Borders + canvas insertions in ONE scan tick (the instant 2-3 squads rush into range)
    -- is a native UMG allocation spike that stalls the game thread. We now build ONE spare
    -- line per quiet scan tick (<=2 enemies on screen) so a rush reuses ready widgets instead
    -- of allocating. NO feature change: every enemy still gets its line on the same tick.
    local function _csnCollapse(w) w:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end
    function SnaplineESP.PrewarmLines(target)
        local pool = SnaplineESP._WidgetPool
        if not pool then pool = {}; SnaplineESP._WidgetPool = pool end
        if #pool >= target then return false end
        if not (SnaplineESP.ESPCanvas and slua.isValid(SnaplineESP.ESPCanvas)) then return false end
        local ld = SnaplineESP.CreateSnapLine(true)
        if not ld then return false end
        pcall(_csnCollapse, ld.Widget)
        ld._visState = 0
        pool[#pool + 1] = ld
        return true
    end
    end  -- [SDWxOWNER-PERF] close CreateSnapLine helper scope

    -- [SDWxOWNER-PERF] Hoisted LOS probes for IsPlayerVisible (closure-free; runs per-enemy
    -- on the 10 Hz scan). The old version allocated two closures per enemy per scan.
    -- Wrapped in a do-block to keep the main chunk under the 200-local limit.
    do
    local _ipvPC, _ipvChar, _ipvVis = nil, nil, false
    local function _ipvLineOfSight()
        if _ipvPC.LineOfSightTo then
            if not SnaplineESP._ZeroVector then
                local VT = _ci_FVector
                if VT then SnaplineESP._ZeroVector = VT(0, 0, 0) end
            end
            _ipvVis = _ipvPC:LineOfSightTo(_ipvChar, SnaplineESP._ZeroVector, false)
        end
    end
    local function _ipvTrace()
        local KismetSystemLibrary = _ci_KSL
        if not (KismetSystemLibrary and KismetSystemLibrary.LineTraceSingle) then return end
        local camMgr = nil
        local GameplayStatics = _ci_GameplayStatics
        if GameplayStatics and GameplayStatics.GetPlayerCameraManager then
            camMgr = GameplayStatics.GetPlayerCameraManager(_ipvPC, 0)
        end
        local startLoc = camMgr and camMgr:GetCameraLocation() or (_ipvPC.GetPlayerCharacter and _ipvPC:GetPlayerCharacter() and _ipvPC:GetPlayerCharacter():K2_GetActorLocation())
        local loc = _ipvChar.K2_GetActorLocation and _ipvChar:K2_GetActorLocation()
        if startLoc and loc then
            local headLoc = SnaplineESP.GetHeadLoc(_ipvChar, loc)
            _tempHeadLoc.X = headLoc.X; _tempHeadLoc.Y = headLoc.Y; _tempHeadLoc.Z = headLoc.Z
            if not SnaplineESP._CachedHitResult then
                local HitResultClass = _ci_HitResultClass
                SnaplineESP._CachedHitResult = HitResultClass and HitResultClass() or {}
            end
            local bHit = KismetSystemLibrary.LineTraceSingle(_ipvPC, startLoc, _tempHeadLoc, 0, false, nil, 0, SnaplineESP._CachedHitResult, true)
            if bHit then
                local hitActor = nil
                if type(SnaplineESP._CachedHitResult.GetActor) == "function" then hitActor = SnaplineESP._CachedHitResult:GetActor()
                elseif SnaplineESP._CachedHitResult.Actor then hitActor = SnaplineESP._CachedHitResult.Actor end
                if hitActor and (hitActor == _ipvChar or (type(hitActor.IsChildOf) == "function" and hitActor:IsChildOf(_ipvChar))) then
                    _ipvVis = true
                end
            else
                _ipvVis = true
            end
        end
    end

    function SnaplineESP.IsPlayerVisible(PC, Character)
        if not PC or not slua.isValid(PC) or not Character or not slua.isValid(Character) then return false end
        local now = os.clock()
        -- [SDWxOWNER-PERF T3] LOS cache 1.5s -> 2.5s: each enemy is re-probed far less often.
        if Character._lastVisTime and (now - Character._lastVisTime) < 2.5 then
            return Character._cachedIsVisible or false
        end
        local bVis = false
        _ipvPC = PC; _ipvChar = Character; _ipvVis = false
        pcall(_ipvLineOfSight)
        bVis = _ipvVis
        if not bVis then
            local KismetSystemLibrary = _ci_KSL
            if KismetSystemLibrary and KismetSystemLibrary.LineTraceSingle then
                -- [SDWxOWNER-PERF T3] Per-scan raycast budget. The cheap LineOfSightTo probe
                -- above already ran; the (native, more expensive) LineTraceSingle is only spent
                -- while the budget allows. The budget is refilled once per scan tick (see
                -- Tick_SnaplineESP), capping native traces at 4 per scan regardless of how many
                -- enemies are on screen. Budget-exhausted enemies keep their previous colour and
                -- are re-probed on the next scan tick (their _lastVisTime is left untouched so
                -- they are NOT frozen for the full 2.5s cache window).
                local budget = SnaplineESP._TraceBudget
                if budget == nil or budget > 0 then
                    SnaplineESP._TraceBudget = (budget or 4) - 1
                    _ipvPC = PC; _ipvChar = Character; _ipvVis = false
                    pcall(_ipvTrace)
                    bVis = _ipvVis
                else
                    return Character._cachedIsVisible or false
                end
            end
        end
        Character._lastVisTime = now
        Character._cachedIsVisible = bVis
        return bVis
    end
    end  -- [SDWxOWNER-PERF] close IsPlayerVisible helper scope

    -- [SDWxOWNER-PERF] Hoisted snapline widget writers. UpdateSnapLine runs per-line at
    -- ~20 Hz; the old pcall(function() ... end) bodies allocated a closure on every call.
    -- These plain functions are captured once and reused -> zero garbage on the hot path.
    local function _snapSetCollapsed(w) w:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end
    local function _snapSetSelfHit(w) w:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible) end
    local function _snapSetPivotProp(w, pv) w.RenderTransformPivot = pv end
    local function _snapSetPivotMethod(w, pv) w:SetRenderTransformPivot(pv) end
    local function _snapSetBrush(w, color) w:SetBrushColor(color) end
    local function _snapSetZOrder(slot, z) slot:SetZOrder(z) end
    local function _snapApplyGeom(slot, widget, posVec, sizeVec, angle, doPos, doSize, doAng)
        if doPos then slot:SetPosition(posVec) end
        if doSize then slot:SetSize(sizeVec) end
        if doAng then widget:SetRenderAngle(angle) end
    end
    local function _snapCollapseAndRemove(w)
        if slua.isValid(w) then
            w:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed)
            if w.RemoveFromParent then w:RemoveFromParent() end
        end
    end

    function SnaplineESP.UpdateSnapLine(KeyStr, CanvasPos, bOnScreen, fromX, fromY, Character, PC, isAI, colorKey)
        if not SnaplineESP.ESPCanvas or not slua.isValid(SnaplineESP.ESPCanvas) then return end

        local LineData = SnaplineESP.SnapLineWidgets[KeyStr]

        if not bOnScreen or not CanvasPos or not Character or not slua.isValid(Character) or not PC or not slua.isValid(PC) then
            -- [SDWxOWNER-FULLMATCH FIX] Grace window: a single-frame miss must not blink the line off.
            local _t = os.clock()
            if LineData and LineData._lastOnScreen and (_t - LineData._lastOnScreen) < 0.3 then
                return
            end
            if LineData and LineData.Widget and slua.isValid(LineData.Widget) then
                if LineData._visState ~= 0 then
                    LineData._visState = 0
                    pcall(_snapSetCollapsed, LineData.Widget)
                end
            end
            return
        end

        -- [SDWxOWNER-DOUBLELINE FIX] A widget carried over from a previous match generation
        -- must not be reused (it can leave a ghost line behind the fresh one).
        if LineData and LineData._gen ~= (_G._SDW_MatchGen or 0) then
            SnaplineESP.RemoveSnapLine(KeyStr)
            LineData = nil
        end
        local bIsNew = false
        if not LineData then
            LineData = SnaplineESP.CreateSnapLine()
            if not LineData or not LineData.Widget or not LineData.Slot then return end
            SnaplineESP.SnapLineWidgets[KeyStr] = LineData
            bIsNew = true
        end
        -- [SDWxOWNER-FULLMATCH FIX] Remember the last time this line was genuinely on-screen
        -- (used by the off-screen grace window above).
        LineData._lastOnScreen = os.clock()

        local Widget = LineData.Widget
        local Slot = LineData.Slot

        if LineData._visState ~= 1 then
            LineData._visState = 1
            -- [SDWxOWNER-PERF] Force a geometry write next update so the skip-if-unchanged check can't miss it.
            LineData._lastX, LineData._lastLen, LineData._lastAng = nil, nil, nil
            pcall(_snapSetSelfHit, Widget)
        end

        if not LineData._PivotSet then
            local pv = FVector2D and FVector2D(0.0, 0.5) or {X=0,Y=0.5}
            pcall(_snapSetPivotProp, Widget, pv)
            pcall(_snapSetPivotMethod, Widget, pv)
            LineData._PivotSet = true
        end

        if colorKey == nil then
            local bTargetVisible = SnaplineESP.IsPlayerVisible(PC, Character)
            if isAI then
                colorKey = SnaplineESP.BotLineColorId or 6
            else
                colorKey = bTargetVisible and (SnaplineESP.LineVisColorId or 2) or (SnaplineESP.LineHidColorId or 1)
            end
        end
        if LineData._cachedColorKey ~= colorKey then
            LineData._cachedColorKey = colorKey
            local lineColor = SnaplineESP.LineCol(colorKey, 0.9)
            if lineColor then pcall(_snapSetBrush, Widget, lineColor) end
        end

        local toX = CanvasPos.X + (SnaplineESP.SnapLineHeadOffsetX or 0)
        local toY = CanvasPos.Y + (SnaplineESP.SnapLineHeadOffsetY or 0)

        local dx = toX - fromX
        local dy = toY - fromY
        local length = math.sqrt(dx * dx + dy * dy)
        local thickness = SnaplineESP.SnapLineThickness or 1

        local angle_rad = (math.atan2 and math.atan2(dy, dx)) or math.atan(dy, dx)
        local angle = angle_rad * 57.29577951308232

        local posX = fromX
        local posY = fromY - thickness / 2.0
        -- [SDWxOWNER] Match the reference exactly: write position, size AND angle every tick to keep them in sync.
        if not LineData._CachedPosVec then
            LineData._CachedPosVec = FVector2D and FVector2D(posX, posY) or {X=posX, Y=posY}
            LineData._CachedSizeVec = FVector2D and FVector2D(length, thickness) or {X=length, Y=thickness}
            pcall(_snapSetZOrder, Slot, 1)
        else
            LineData._CachedPosVec.X = posX; LineData._CachedPosVec.Y = posY
            LineData._CachedSizeVec.X = length; LineData._CachedSizeVec.Y = thickness
        end
        -- [SDWxOWNER-PERF] Write only changed slot properties (line origin = cached top-centre).
        local lx, ly, ll, la = LineData._lastX, LineData._lastY, LineData._lastLen, LineData._lastAng
        local posChanged = (lx == nil) or math.abs(posX - lx) > 0.1 or math.abs(posY - ly) > 0.1
        local sizeChanged = (ll == nil) or math.abs(length - ll) > 0.1
        local angChanged = (la == nil) or math.abs(angle - la) > 0.1
        if posChanged or sizeChanged or angChanged then
            LineData._lastX, LineData._lastY, LineData._lastLen, LineData._lastAng = posX, posY, length, angle
            pcall(_snapApplyGeom, Slot, Widget, LineData._CachedPosVec, LineData._CachedSizeVec, angle, posChanged, sizeChanged, angChanged)
        end
    end

    function SnaplineESP.RemoveSnapLine(KeyStr)
        local LineData = SnaplineESP.SnapLineWidgets[KeyStr]
        if LineData and LineData.Widget and slua.isValid(LineData.Widget) then
            pcall(_snapSetCollapsed, LineData.Widget)
            local pool = SnaplineESP._WidgetPool
            if not pool then pool = {}; SnaplineESP._WidgetPool = pool end
            table.insert(pool, LineData)
            SnaplineESP.SnapLineWidgets[KeyStr] = nil
        end
    end

    function SnaplineESP.ClearAllSnapLines()
        -- [SDWxOWNER-LINE FIX] Sweep BOTH the live lines AND the recycle pool. The pool
        -- used to be dropped (SnaplineESP._WidgetPool = {}) WITHOUT detaching its widgets,
        -- so any pooled Border that the engine had re-shown stayed on screen forever as an
        -- unreachable "stuck" line. Now every widget we ever created is collapsed and
        -- removed from its parent, on EVERY map.
        for KeyStr, LineData in pairs(SnaplineESP.SnapLineWidgets or {}) do
            if LineData and LineData.Widget then
                pcall(_snapCollapseAndRemove, LineData.Widget)
            end
        end
        for i = 1, #(SnaplineESP._WidgetPool or {}) do
            local pooled = SnaplineESP._WidgetPool[i]
            if pooled and pooled.Widget then
                pcall(_snapCollapseAndRemove, pooled.Widget)
            end
        end
        SnaplineESP.SnapLineWidgets = {}
        SnaplineESP._WidgetPool = {}
    end
    SnaplineESP.Clear = SnaplineESP.ClearAllSnapLines

    -- [SDWxOWNER-LINE FIX] Hard, map-independent clear used by every ESP-toggle-OFF path.
    -- It removes ALL widgets (live + pooled) from the canvas, drops the canvas handle and
    -- forces a full re-init on the next enable, so no stale line can survive a toggle on
    -- ANY map (Training Ground, Erangel, ...). It does NOT touch unrelated state.
    function SnaplineESP.HardClear()
        pcall(SnaplineESP.ClearAllSnapLines)
        SnaplineESP.SnapLineWidgets = {}
        SnaplineESP._WidgetPool = {}
        SnaplineESP.ESPCanvas = nil
        SnaplineESP._InitGen = -1
        SnaplineESP._DrawCount = 0
        SnaplineESP._DrawPC = nil
        SnaplineESP._DrawList = nil
        SnaplineESP._FastActive = nil
        SnaplineESP._lastTransformTime = 0
        SnaplineESP._lastStartPosTime = 0
        SnaplineESP._CachedFromX = 0
        SnaplineESP._CachedFromY = 0
    end

    -- [SDWxOWNER] Match the SDWxOWNER ESP.
    local _headLocScratch = { X = 0, Y = 0, Z = 0 }
    local _headPawn = nil
    local _headOffset = 75
    local function _headResolveOffset()
        local pawn = _headPawn
        -- [SDWxOWNER-KNOCK-CRASH FIX] Guard the crouch/prone probe: on the knock frame the pawn
        -- can be mid-teardown; reading bIsCrouched / IsProne() then is unsafe. Default offset 75
        -- is kept when the probe is skipped.
        if not pawn or not SafeIsValid(pawn) then return end
        if pawn.bIsCrouched then _headOffset = 50
        elseif pawn.IsProne and pawn:IsProne() then _headOffset = 25 end
    end
    function SnaplineESP.GetHeadLoc(pawn, pLoc)
        if not pawn or not pLoc then return pLoc end
        -- [SDWxOWNER-FIX] Line must NOT float above the head.
        local off = pawn._sdwHeadOff
        local now = os.clock()
        if off == nil or (now - (pawn._sdwHeadOffT or 0)) > 0.25 then
            _headOffset = 75
            _headPawn = pawn
            pcall(_headResolveOffset)
            off = _headOffset
            pawn._sdwHeadOff = off
            pawn._sdwHeadOffT = now
        end
        _headLocScratch.X = pLoc.X; _headLocScratch.Y = pLoc.Y; _headLocScratch.Z = pLoc.Z + off
        return _headLocScratch
    end

    local _SnaplineSeen = {}
    -- [SDWxOWNER-OPT] Hoisted per-enemy location fetch for the 10 Hz snapline SCAN tick.
    _OPT.snapChar = nil
    _OPT.snapLoc = nil
    function _OPT.snapFetchLoc() _OPT.snapLoc = _OPT.snapChar:K2_GetActorLocation() end

    -- [SDWxOWNER-PERF] Hoisted scan probes (closure-free pcall targets for the 10 Hz scan).
    local _scanPawn = nil
    local _scanLoc = nil
    local function _scanGetLoc() _scanLoc = _scanPawn:K2_GetActorLocation() end
    local _scanTeam = nil
    local function _scanGetTeam() _scanTeam = _scanPawn.TeamID or (_scanPawn.GetTeamID and _scanPawn:GetTeamID()) end
    local _scanUID = nil
    local function _scanGetUID() if _scanPawn.GetUniqueID then _scanUID = _scanPawn:GetUniqueID() end end

    local function Tick_SnaplineESP()
        if not (_G.SDWConfig and _G.SDWConfig.SnaplineESPEnabled) then
            SnaplineESP.ClearAllSnapLines()
            return
        end
        -- [SDWxOWNER-FULLMATCH FIX] Scan heartbeat.
        SnaplineESP._LastScanTime = os.clock()
        -- [SDWxOWNER-RUSH-FPS] New projection frame: the camera basis is sampled once here
        -- and reused by every enemy projection in this scan.
        SnaplineESP.BeginProjectionFrame()
        -- [SDWxOWNER-PERF T3] Refill the per-scan raycast budget. Caps native LineTraceSingle
        -- LOS probes at 4 per scan tick (the cheap LineOfSightTo probe is unbudgeted).
        SnaplineESP._TraceBudget = 4

        local LC = _G.SDWConfig
        if LC then
            if LC.Esp9_LineThick then
                -- [SDWxOWNER] Snap the line thickness to the ONLY allowed values: 0.8 / 1 / 2.
                -- Any stale/legacy value (e.g. the old 1.5 default) is clamped so the line
                -- can never render thicker than 2.
                local _lt = tonumber(LC.Esp9_LineThick) or 1
                if _lt <= 0.9 then _lt = 0.8 elseif _lt <= 1.5 then _lt = 1 else _lt = 2 end
                LC.Esp9_LineThick = _lt
                SnaplineESP.SnapLineThickness = _lt
            end
            -- [FIX] Line colours are FIXED (the colour buttons were removed from
            -- the menu): visible enemy = GREEN, enemy behind wall = RED, bot = CYAN.
            SnaplineESP.LineVisColorId = 2
            SnaplineESP.LineHidColorId = 1
            SnaplineESP.BotLineColorId = 6
            SnaplineESP.SnapLineOriginY = tonumber(LC.Esp9_LineOriginY) or SnaplineESP.SnapLineOriginY
        end

        local pc, localPawn = SnaplineESP.GetMyControllerAndPlayer()
        if not pc or not slua.isValid(pc) or not localPawn or not slua.isValid(localPawn) then return end

        local myPos = nil
        _scanPawn = localPawn; _scanLoc = nil
        pcall(_scanGetLoc)
        myPos = _scanLoc
        if not myPos then return end

        local myTeamId = nil
        _scanPawn = localPawn; _scanTeam = nil
        pcall(_scanGetTeam)
        myTeamId = _scanTeam

        if not SnaplineESP.InitESPCanvas() then
            -- [SDWxOWNER-FULLMATCH FIX] Canvas gone (in-game UI rebuild / map transition).
            SnaplineESP._DrawCount = 0
            SnaplineESP._DrawPC = nil
            return
        end
        SnaplineESP.UpdateCanvasTransform(pc)

        local allPawns = SnaplineESP.GetAllPawns()
        if not allPawns or #allPawns == 0 then return end

        local fromX, fromY = SnaplineESP.GetSnapLineStartPos(pc)

        local _dl = SnaplineESP._DrawList
        if not _dl then _dl = {}; SnaplineESP._DrawList = _dl end
        SnaplineESP._DrawCount = 0
        SnaplineESP._FromX = fromX
        SnaplineESP._FromY = fromY
        SnaplineESP._DrawPC = pc

        for k in pairs(_SnaplineSeen) do _SnaplineSeen[k] = nil end

        -- [SDWxOWNER-PERF] Hoist the fast-tick liveness probe OUT of the per-enemy loop.
        -- SnaplineESP._FastActive cannot change mid-scan, so one clock read replaces N
        -- (up to ~60 enemies) os.clock() calls on every 10 Hz scan tick. Behaviour is
        -- identical: this only gates the self-healing fallback draw.
        local _fastLive = (SnaplineESP._FastActive and (os.clock() - SnaplineESP._FastActive) < 0.25) and true or false

        for _, pawn in ipairs(allPawns) do
            if not pawn or not slua.isValid(pawn) or pawn == localPawn then goto continue end
            -- [SDWxOWNER-FULLMATCH FIX] Robust enemy filter: skip only when we can prove
            -- teammate/dead (old filter dropped bots with PlayerKey 0/nil).
            local pTeam = pawn.TeamID or (type(pawn.GetTeamID) == "function" and pawn:GetTeamID())
            if myTeamId and myTeamId > 0 and pTeam and pTeam > 0 and pTeam == myTeamId then goto continue end
            local hs = pawn.HealthStatus
            if hs == 2 or hs == 3 then goto continue end
            if pawn.bIsDead or pawn.bDead then goto continue end

            local pKey = pawn.PlayerKey
            local isAI = ResolveIsAI(pKey, pawn)
            -- [SDWxOWNER-DOUBLELINE FIX] Stable per-enemy key: resolve once and cache it
            -- on the pawn (the old recomputed key changed -> duplicate lines + leak).
            local key = pawn._sdwLineKey
            if not key then
                if pKey and pKey ~= 0 then
                    key = "P" .. tostring(pKey)
                else
                    local uid = nil
                    _scanPawn = pawn; _scanUID = nil
                    pcall(_scanGetUID)
                    uid = _scanUID
                    if uid ~= nil and uid ~= 0 then
                        key = "U" .. tostring(uid)
                    else
                        key = "O" .. tostring(pawn)
                    end
                end
                pawn._sdwLineKey = key
            end

            local pLoc = nil
            -- [SDWxOWNER-OPT] Hoisted fetch (no per-enemy closure alloc).
            _OPT.snapChar = pawn
            _OPT.snapLoc = nil
            pcall(_OPT.snapFetchLoc)
            pLoc = _OPT.snapLoc
            if not pLoc then goto continue end

            local dx = pLoc.X - myPos.X
            local dy = pLoc.Y - myPos.Y
            local dz = pLoc.Z - myPos.Z
            local distSq = dx * dx + dy * dy + dz * dz
            if distSq <= 0 or distSq > 1600000000 then goto continue end

            -- [SDWxOWNER] Snapline must end ON the head (was floating above it).
            local headLoc = SnaplineESP.GetHeadLoc(pawn, pLoc)
            _tempHeadLoc.X = headLoc.X; _tempHeadLoc.Y = headLoc.Y; _tempHeadLoc.Z = headLoc.Z

            -- [SDWxOWNER-FULLMATCH FIX] `key` was already computed above (with a bot-safe
            -- fallback to the pawn itself when PlayerKey is 0/nil).

            _SnaplineSeen[key] = true
            local _vis = SnaplineESP.IsPlayerVisible(pc, pawn)
            local _ck
            if isAI then
                _ck = SnaplineESP.BotLineColorId or 6
            else
                _ck = _vis and (SnaplineESP.LineVisColorId or 2) or (SnaplineESP.LineHidColorId or 1)
            end
            -- [SDWxOWNER-PERF] Queue this enemy for the fast (~20Hz) draw tick.
            local _n = (SnaplineESP._DrawCount or 0) + 1
            local _e = _dl[_n]
            if not _e then _e = {}; _dl[_n] = _e end
            -- [SDWxOWNER-PERF] If the slot now holds a different pawn, drop the cached position to force a redraw.
            if _e.char ~= pawn then _e.lx = nil end
            _e.key = key; _e.char = pawn; _e.pc = pc; _e.isAI = isAI; _e.ck = _ck
            -- [SDWxOWNER-PERF 1.5x] Distance tier for the fast tick's draw divider: >=120 m.
            _e.far = (distSq > 144000000)
            SnaplineESP._DrawCount = _n
            -- [SDWxOWNER-PERF] Draw here ONLY as a self-healing / first-frame fallback.
            if not _fastLive then
                local bOnScreen, CanvasPos = SnaplineESP.ProjectWorldToCanvasLocal(pc, _tempHeadLoc)
                SnaplineESP.UpdateSnapLine(key, CanvasPos, bOnScreen, fromX, fromY, pawn, pc, isAI, _ck)
            end
            ::continue::
        end

        -- [SDWxOWNER-FULLMATCH FIX] Grace period: hide a line only after it has been unseen > 0.5s.
        local _collapseNow = os.clock()
        local _stale = nil
        for key, LineData in pairs(SnaplineESP.SnapLineWidgets) do
            if _SnaplineSeen[key] then
                if LineData then LineData._lastSeen = _collapseNow end
            elseif LineData and (not LineData._lastSeen or (_collapseNow - LineData._lastSeen) > 0.5) then
                -- [SDWxOWNER-LEAK FIX] Fully remove (hide + recycle + drop key), not just
                -- collapse; collect first, mutate after the pairs() loop.
                _stale = _stale or {}
                _stale[#_stale + 1] = key
            end
        end
        if _stale then
            for i = 1, #_stale do pcall(SnaplineESP.RemoveSnapLine, _stale[i]) end
        end
        -- [SDWxOWNER-RUSH-FPS] Quiet screen -> build one spare line widget per scan tick.
        if (SnaplineESP._DrawCount or 0) <= 2 then pcall(SnaplineESP.PrewarmLines, 10) end
    end

    -- [SDWxOWNER-PERF] Hoisted per-pawn location fetch for the fast draw tick (runs 20x
    -- per second per enemy) -> no closure allocation inside the hottest loop.
    local _fastChar, _fastLoc = nil, nil
    local function _fastFetchLoc() _fastLoc = _fastChar:K2_GetActorLocation() end
    -- [SDWxOWNER-PERF 1.5x] Camera-motion gate.
    SnaplineESP._fastCamYaw, SnaplineESP._fastCamPitch = nil, nil
    SnaplineESP._fastCamX, SnaplineESP._fastCamY, SnaplineESP._fastCamZ = nil, nil, nil
    SnaplineESP._fastFrame = 0
    -- [SDWxOWNER-PERF] Hoisted camera probes for the fast draw tick (closure-free).
    local _fcmPC = nil
    local _fcmRot, _fcmLoc = nil, nil
    local function _fcmGetRot() _fcmRot = _fcmPC:GetControlRotation() end
    local function _fcmGetLoc() _fcmLoc = _fcmPC:K2_GetActorLocation() end
    function SnaplineESP._fastCamMoved(pc)
        local rot, loc = nil, nil
        _fcmPC = pc; _fcmRot = nil; _fcmLoc = nil
        pcall(_fcmGetRot)
        pcall(_fcmGetLoc)
        rot, loc = _fcmRot, _fcmLoc
        local yaw = (rot and rot.Yaw) or 0
        local pitch = (rot and rot.Pitch) or 0
        local x = (loc and loc.X) or 0
        local y = (loc and loc.Y) or 0
        local z = (loc and loc.Z) or 0
        local moved = true
        if SnaplineESP._fastCamYaw ~= nil then
            moved = (math.abs(yaw - SnaplineESP._fastCamYaw) > 0.05)
                 or (math.abs(pitch - SnaplineESP._fastCamPitch) > 0.05)
                 or (math.abs(x - SnaplineESP._fastCamX) > 2.0)
                 or (math.abs(y - SnaplineESP._fastCamY) > 2.0)
                 or (math.abs(z - SnaplineESP._fastCamZ) > 2.0)
        end
        SnaplineESP._fastCamYaw, SnaplineESP._fastCamPitch = yaw, pitch
        SnaplineESP._fastCamX, SnaplineESP._fastCamY, SnaplineESP._fastCamZ = x, y, z
        return moved
    end
    local function Tick_SnaplineESP_Fast()
        -- [SDWxOWNER-PERF] Fast (~20Hz) draw: re-project only the pawns cached by the 10Hz scan.
        if not (_G.SDWConfig and _G.SDWConfig.SnaplineESPEnabled) then return end
        -- [SDWxOWNER-FULLMATCH FIX] Fast-tick heartbeat + self-heal.
        local _nowFast = os.clock()
        SnaplineESP._LastFastTime = _nowFast
        if (_nowFast - (SnaplineESP._LastScanTime or 0)) > 0.5 then
            pcall(Tick_SnaplineESP)
        end
        local _dl = SnaplineESP._DrawList
        local n = SnaplineESP._DrawCount or 0
        if not _dl or n == 0 then return end
        local pc = SnaplineESP._DrawPC
        if not pc or not slua.isValid(pc) then return end
        local fromX = SnaplineESP._FromX or 0
        local fromY = SnaplineESP._FromY or 0
        -- [SDWxOWNER-PERF] Mark the fast draw live so the 10Hz scan can skip its redundant update.
        -- [SDWxOWNER-PERF] Reuse the single os.clock() read sampled at the top of this tick
        -- (was a second os.clock() call every 20 Hz beat).
        SnaplineESP._FastActive = _nowFast
        -- [SDWxOWNER-PERF 1.5x] One cheap camera probe per tick (2 native calls total,
        -- NOT per enemy) drives the skip logic below.
        SnaplineESP._fastFrame = (SnaplineESP._fastFrame or 0) + 1
        local camMoved = SnaplineESP._fastCamMoved(pc)
        local parity = SnaplineESP._fastFrame % 2
        for i = 1, n do
            local e = _dl[i]
            -- [SDWxOWNER-FULLMATCH FIX] Cached enemy died/left between scans.
            if e and e.char and not slua.isValid(e.char) then
                if e.key then SnaplineESP.RemoveSnapLine(e.key) end
                e.char = nil
            end
            -- [SDWxOWNER-RUSH-CRASH FIX #2] Also drop an enemy that DIED between scans. The old
            -- check only tested slua.isValid(), but a pawn killed mid-rush stays "valid" for a few
            -- frames while its skeletal mesh is torn down; GetHeadLoc then reads its crouch/prone
            -- state and the projection touches a freed mesh -> native use-after-free crash. The
            -- 10 Hz scan already skips dead pawns, so this closes the gap between scans.
            if e and e.char and slua.isValid(e.char) then
                local _ehs = e.char.HealthStatus
                if _ehs == 2 or _ehs == 3 or e.char.bIsDead == true or e.char.bDead == true then
                    if e.key then SnaplineESP.RemoveSnapLine(e.key) end
                    e.char = nil
                end
            end
            if e and e.char and slua.isValid(e.char) then
                _fastChar = e.char; _fastLoc = nil
                pcall(_fastFetchLoc)
                local loc = _fastLoc
                if loc then
                    -- [SDWxOWNER-PERF 1.5x] Did this enemy move since the last fast tick?
                    -- (cheap world-space compare; ~2 units = 2 cm = invisible)
                    local moved = true
                    local lx, ly, lz = e.lx, e.ly, e.lz
                    if lx ~= nil then
                        local ddx, ddy, ddz = loc.X - lx, loc.Y - ly, loc.Z - lz
                        moved = (ddx * ddx + ddy * ddy + ddz * ddz) > 4.0
                    end
                    e.lx, e.ly, e.lz = loc.X, loc.Y, loc.Z
                    -- [SDWxOWNER-PERF 1.5x] Decide whether this enemy needs a redraw: * camera static.
                    local drawIt
                    if not camMoved then
                        drawIt = moved
                    elseif e.far then
                        drawIt = (i % 2) == parity
                    else
                        drawIt = true
                    end
                    if drawIt then
                        local headLoc = SnaplineESP.GetHeadLoc(e.char, loc)
                        _tempHeadLoc.X = headLoc.X; _tempHeadLoc.Y = headLoc.Y; _tempHeadLoc.Z = headLoc.Z
                        local bOnScreen, CanvasPos = SnaplineESP.ProjectWorldToCanvasLocal(pc, _tempHeadLoc)
                        SnaplineESP.UpdateSnapLine(e.key, CanvasPos, bOnScreen, fromX, fromY, e.char, pc, e.isAI, e.ck)
                    end
                end
            end
        end
    end
    -- [SDWxOWNER-PERSIST FIX] Single, owner-independent snapline driver on
    -- common.time_ticker (the old dual owner-backed drivers dropped at ~1 min
    -- when the PC was invalidated and briefly drew duplicate lines).
    _G.SDW_Snapline = _G.SDW_Snapline or {}
    local SNAP = _G.SDW_Snapline
    SNAP.gen = SNAP.gen or -1
    SNAP.running = SNAP.running or false
    SNAP.chain = SNAP.chain or 0
    SNAP.n = SNAP.n or 0


    local function SDW_StopSnapline()
        -- Bump the chain token so any already-scheduled tick becomes a no-op and cannot resurrect a second chain.
        SNAP.running = false
        SNAP.chain = (SNAP.chain or 0) + 1
    end
    _G.SDW_StopSnapline = SDW_StopSnapline

    local function SDW_SnapDriverTick()
        if not SNAP.running then return end
        local myChain = SNAP.chain
        -- A driver left over from a PREVIOUS match stops itself; the next match's
        -- SDW_EnsureSnapline starts a fresh one.
        if SNAP.gen ~= (_G._SDW_MatchGen or 0) then SNAP.running = false; return end
        -- [SDWxOWNER-WEAPONICON] The driver also runs when the Weapon ICON ESP is on
        -- (even if the snapline itself is off) so the icon reuses this 10 Hz beat.
        if not (_G.LOGIN_OK and _G.SDWConfig and (_G.SDWConfig.SnaplineESPEnabled or _G.SDWConfig.WeaponIconESPEnabled or _G.SDWConfig.SDWBoxESPEnabled)) then
            SNAP.running = false
            return
        end
        SNAP.n = SNAP.n + 1
        -- [SDWxOWNER-LAGFIX] Closure-free calls.
        pcall(SnaplineESP.InitESPCanvas)
        -- [SDWxOWNER-LAGFIX new.lua-style] SINGLE-RATE driver: 10 Hz scan + 10 Hz draw
        -- (was 10 Hz scan + 20 Hz fast draw). This HALVES the per-second projection +
        -- widget work of the ESP line -> the same low-lag cadence new.lua uses, while
        -- keeping EVERY ESP-line feature (visibility colour, widget pooling, off-screen
        -- grace window, per-scan raycast budget). The scan is the roster refresh and the
        -- fast tick is the projection/draw; both now beat at 10 Hz.
        pcall(Tick_SnaplineESP)
        pcall(Tick_SnaplineESP_Fast)
        -- [SDWxOWNER-WEAPONICON] Weapon ICON ESP piggybacks on this 10 Hz driver (no new timer).
        pcall(_OPT.Tick_WeaponIconESP)
        -- [SDWxOWNER-SDWBOX] SDWxOWNER Box ESP piggybacks on the same 10 Hz driver (no new timer).
        if _G.SDW_BoxESP then pcall(_G.SDW_BoxESP.Tick) end
        -- [SDWxOWNER-BOXSMOOTH] Keep the per-frame fast driver alive (restarts it after a match).
        if _G.SDW_EnsureBoxFast then pcall(_G.SDW_EnsureBoxFast) end
        -- Reschedule on the global ticker (survives owner invalidation). The chain
        -- token check guarantees exactly ONE live chain even across a stop/restart.
        -- [SDWxOWNER-SMOOTH] Use the cached ticker accessor (no require() per beat).
        local t = _G.SDW_GetTicker and _G.SDW_GetTicker()
        if t and SNAP.running and SNAP.chain == myChain then
            t.AddTimerOnce(0.1, SDW_SnapDriverTick)
        end
    end

    function _G.SDW_EnsureSnapline()
        if not _G.LOGIN_OK then return end
        -- [SDWxOWNER-WEAPONICON] Keep the driver alive for the Weapon ICON ESP too.
        if not (_G.SDWConfig and (_G.SDWConfig.SnaplineESPEnabled or _G.SDWConfig.WeaponIconESPEnabled or _G.SDWConfig.SDWBoxESPEnabled)) then
            SDW_StopSnapline()
            return
        end
        local gen = _G._SDW_MatchGen or 0
        if SNAP.gen ~= gen then
            -- New match: drop the old driver + all old lines, then start clean.
            SDW_StopSnapline()
            pcall(function() if SnaplineESP.ResetForMatch then SnaplineESP.ResetForMatch() end end)
            SNAP.gen = gen
            SNAP.n = 0
        end
        if SNAP.running then
            -- Already driving this match: just keep the canvas live and return.
            pcall(function() SnaplineESP.InitESPCanvas() end)
            return
        end
        -- (Re)start the single driver.
        SNAP.running = true
        SNAP.chain = (SNAP.chain or 0) + 1
        pcall(SDW_SnapDriverTick)
    end

    -- [SDWxOWNER-BOXSMOOTH] Per-frame driver for the SDWxOWNER Box ESP. The box geometry is
    -- re-projected EVERY FRAME (native-ESP smoothness) instead of only on the 10 Hz snapline
    -- beat, so the box stays LOCKED on the enemy while the camera / gyro moves (no drift).
    -- Self-sustaining on the global ticker; stops itself the moment the box is switched off.
    -- Wrapped in a do-block so its locals do NOT count against __SDW_ModMain's 200-local budget.
    do
    _G.SDW_BoxFast = _G.SDW_BoxFast or {}
    local BOXFAST = _G.SDW_BoxFast
    BOXFAST.running = BOXFAST.running or false
    BOXFAST.chain   = BOXFAST.chain or 0
    BOXFAST.gen     = BOXFAST.gen or -1

    local function SDW_BoxFastStop()
        BOXFAST.running = false
        BOXFAST.chain = (BOXFAST.chain or 0) + 1
    end
    _G.SDW_StopBoxFast = SDW_BoxFastStop

    local function SDW_BoxFastTick()
        if not BOXFAST.running then return end
        local myChain = BOXFAST.chain
        -- A driver left over from a PREVIOUS match stops itself.
        if BOXFAST.gen ~= (_G._SDW_MatchGen or 0) then BOXFAST.running = false; return end
        -- Stop the instant the box is switched off (or the key locks).
        if not (_G.LOGIN_OK and _G.SDWConfig and _G.SDWConfig.SDWBoxESPEnabled) then
            BOXFAST.running = false
            return
        end
        if _G.SDW_BoxESP and _G.SDW_BoxESP.FastTick then pcall(_G.SDW_BoxESP.FastTick) end
        -- Reschedule on the global ticker (~60 Hz, i.e. the frame rate).
        local t = _G.SDW_GetTicker and _G.SDW_GetTicker()
        if t and BOXFAST.running and BOXFAST.chain == myChain then
            t.AddTimerOnce(0.016, SDW_BoxFastTick)
        end
    end

    -- [SDWxOWNER-ESPMODE] ONE-CLICK "ENABLE ALL ESP" for the SDWxOWNER Box (V2).
    -- Turns the master + every part ON (or all OFF) and refreshes live boxes instantly.
    function _G.SDW_SetAllBoxParts(v)
        local c = _G.SDWConfig
        if not c then return end
        v = (v ~= false)
        c.SDWBoxESPEnabled = v
        c.SDWBox_Frame  = v
        c.SDWBox_Health = v
        c.SDWBox_Name   = v
        c.SDWBox_Dist   = v
        c.SDWBox_Weapon = v
        c.SDWBox_Flag   = v
        c.SDWBox_State  = v
        if v then
            -- [SDWxOWNER-ESPMODE] NEVER mix with the old V1 Box ESP.
            if c.BoxESPEnabled then
                c.BoxESPEnabled = false
                if _G.SDW_DisableFeature then pcall(_G.SDW_DisableFeature, "box") end
            end
            if not _G.VisualsStarted and _G.StartVisuals then pcall(_G.StartVisuals) end
            if _G.SDW_EnsureBoxFast then pcall(_G.SDW_EnsureBoxFast) end
            if _G.SDW_EnsureSnapline then pcall(_G.SDW_EnsureSnapline) end
        else
            if _G.SDW_DisableFeature then pcall(_G.SDW_DisableFeature, "sdwbox") end
            if _G.SDW_StopBoxFast then pcall(_G.SDW_StopBoxFast) end
        end
        if _G.SDW_BoxESP and _G.SDW_BoxESP.RefreshParts then pcall(_G.SDW_BoxESP.RefreshParts) end
        if _G.SaveSDWConfig then pcall(_G.SaveSDWConfig) end
    end

    -- [SDWxOWNER-ESPMODE] Mode switch: V1 (old Box ESP) <-> V2 (SDWxOWNER Box). Selecting one
    -- ALWAYS turns the other off, so the two boxes can never be drawn on top of each other.
    function _G.SDW_SetBoxMode(mode)
        local c = _G.SDWConfig
        if not c then return end
        if mode == "v2" then
            c.SDWBoxESPEnabled = true
            if c.BoxESPEnabled then
                c.BoxESPEnabled = false
                if _G.SDW_DisableFeature then pcall(_G.SDW_DisableFeature, "box") end
            end
            if not _G.VisualsStarted and _G.StartVisuals then pcall(_G.StartVisuals) end
            if _G.SDW_EnsureBoxFast then pcall(_G.SDW_EnsureBoxFast) end
            if _G.SDW_EnsureSnapline then pcall(_G.SDW_EnsureSnapline) end
        elseif mode == "v1" then
            c.BoxESPEnabled = true
            if c.SDWBoxESPEnabled then
                c.SDWBoxESPEnabled = false
                if _G.SDW_DisableFeature then pcall(_G.SDW_DisableFeature, "sdwbox") end
                if _G.SDW_StopBoxFast then pcall(_G.SDW_StopBoxFast) end
            end
            if not _G.VisualsStarted and _G.StartVisuals then pcall(_G.StartVisuals) end
        end
        if _G.SDW_BoxESP and _G.SDW_BoxESP.RefreshParts then pcall(_G.SDW_BoxESP.RefreshParts) end
    end

    function _G.SDW_EnsureBoxFast()
        if not _G.LOGIN_OK then return end
        if not (_G.SDWConfig and _G.SDWConfig.SDWBoxESPEnabled) then
            SDW_BoxFastStop()
            return
        end
        local gen = _G._SDW_MatchGen or 0
        if BOXFAST.gen ~= gen then
            SDW_BoxFastStop()
            BOXFAST.gen = gen
        end
        if BOXFAST.running then return end
        BOXFAST.running = true
        BOXFAST.chain = (BOXFAST.chain or 0) + 1
        pcall(SDW_BoxFastTick)
    end
    end


    do
        local SpinEngine = {
            Angle   = 0,
            Weight  = 0,
            _Char   = nil,
            _Weapon = nil,
            _BaseWeaponYaw = 0,
            _BaseMeshYaw = nil,
            _Applied = false,
            _T0 = nil,
            -- [SDWxOWNER-PERF FIX] weak-keyed so recycled/destroyed characters are GC'd
            -- instead of leaking forever (this table used to grow all session).
            _Hooked = setmetatable({}, { __mode = "k" }),
            -- [SDWxOWNER-SPIN FIX] Cached clock source.
            _World = nil,
            _WorldTimeFn = nil,
            -- [SDWxOWNER-SPIN FIX] Idempotency guard shared by the ReceiveTick hook and the 0.008s timer.
            _LastApplyT = -1,
            -- [SDWxOWNER-SPIN FIX] Timestamp of the last per-frame ReceiveTick apply.
            _LastHookT = nil,
            -- [SDWxOWNER-SPIN FIX] Reusable scratch (no per-frame table allocation).
            _Pos = { x = 0, y = 0, t = 0, has = false },
            _LastMoveCheck = 0,
            _Moving = false,
            -- [SDWxOWNER-SPIN SMOOTH] Monotonic spin clock. It accumulates the REAL frame
            -- delta (clamped) so the spin angle is a continuous, monotonic function of
            -- time. Unlike a raw (now - T0) difference, it can never jump backwards when
            -- the underlying world/CPU clock is re-resolved or reset, and it does NOT
            -- advance across a blocked frame -> the spin resumes with zero angle jump.
            _Clock      = 0,
            _LastRealT  = nil,
            _FrameDt    = 0,
            -- [SDWxOWNER-SPIN SMOOTH] The single pre-allocated FRotator reused for EVERY
            -- native write (mesh + weapon). Allocating a fresh FRotator(0,yaw,0) per frame
            -- was the main source of the periodic Lua GC spike -> the 3-second stutter.
            _Rot        = nil,
            _RotOK      = true,
            -- [SDWxOWNER-SPIN SMOOTH] The mesh pointer the current base yaw was captured
            -- from. When the engine rebuilds the mesh (skin/avatar swap) the pointer
            -- changes and we re-acquire the base yaw on the NEW mesh instead of writing
            -- to a stale (freed) one, or freezing the spin.
            _Mesh       = nil,
        }
        _G.SpinEngine = SpinEngine

        local DEFAULT_MESH_YAW = -90


        -- [SDWxOWNER-PERF] Hoisted world-time accessor probe (closure-free; was a pcall closure).
        local _nowWorld, _nowFn = nil, nil
        local function _nowReadFn() _nowFn = _nowWorld.GetTimeSeconds end
        -- [SDWxOWNER-SPIN FIX] Cheap monotonic clock.
        local function NowSeconds()
            local w = SpinEngine._World
            if not w then
                local ok, ww = pcall(slua.getWorld)
                if ok and ww then w = ww; SpinEngine._World = ww end
            end
            if w then
                local f = SpinEngine._WorldTimeFn
                if not f then
                    _nowWorld = w; _nowFn = nil
                    local okf = pcall(_nowReadFn)
                    if okf and type(_nowFn) == "function" then f = _nowFn; SpinEngine._WorldTimeFn = _nowFn end
                end
                if f then
                    local okt, t = pcall(f, w)
                    if okt and type(t) == "number" then return t end
                    -- stale world -> force a re-resolve on the next call
                    SpinEngine._World = nil
                    SpinEngine._WorldTimeFn = nil
                end
            end
            return os.clock()
        end

        -- [SDWxOWNER-SPIN SMOOTH] Resolve the FRotator constructor once (global, or via
        -- import on builds that expose it only through the module system).
        local _FRotatorCtor = nil
        local function _resolveRotCtor()
            if _FRotatorCtor then return _FRotatorCtor end
            -- Accept BOTH a plain function AND a callable table (some slua builds expose
            -- FRotator as a __call table). We only require it to be non-nil, so the proven
            -- `FRotator(0, yaw, 0)` construction can NEVER be skipped (which would make the
            -- spin a silent no-op again).
            local ctor = FRotator
            if ctor == nil then
                local ok, r = pcall(import, "Rotator")
                if ok then ctor = r end
            end
            if ctor ~= nil then _FRotatorCtor = ctor end
            return _FRotatorCtor
        end

        -- [SDWxOWNER-SPIN SMOOTH] Lazily create the ONE reusable FRotator. Every native
        -- write mutates this single object's Yaw instead of allocating a fresh rotator,
        -- which removes the per-frame garbage that triggered the periodic GC stutter.
        local function _ensureRot()
            if SpinEngine._Rot then return SpinEngine._Rot end
            local ctor = _resolveRotCtor()
            if not ctor then SpinEngine._RotOK = false; return nil end
            local ok, r = pcall(ctor, 0, 0, 0)
            if not ok or not r then SpinEngine._RotOK = false; return nil end
            SpinEngine._Rot = r
            return r
        end

        -- [SDWxOWNER-SPIN SMOOTH] Sample the real clock ONCE per frame (blocked or not).
        -- The (clamped) frame delta is stored in _FrameDt and drained into the monotonic
        -- _Clock only by SpinApply, i.e. only on a frame that actually writes. A blocked
        -- frame therefore advances neither _Clock nor the angle, and the resume step is a
        -- normal single-frame delta -> the rotation is perfectly continuous (no snap).
        local function SampleSpinClock()
            local real = NowSeconds()
            local last = SpinEngine._LastRealT
            SpinEngine._LastRealT = real
            if last == nil then SpinEngine._FrameDt = 0; return real end
            local dt = real - last
            if dt < 0 then dt = 0 elseif dt > 0.05 then dt = 0.05 end
            SpinEngine._FrameDt = dt
            return real
        end

        -- [SDWxOWNER-SPIN SMOOTH] One native rotation write, reusing the pre-allocated
        -- FRotator. Falls back to inline construction only if the binding rejects the
        -- field write, so behaviour is never worse than the original. Fully allocation-
        -- free: the field write is a HOISTED function (no per-frame closure) and the
        -- pcall is only paid once, until the field write is proven to work.
        local function _setRotYaw(r, yaw) r.Yaw = yaw end
        local _rotVerified = false
        local function _setYaw(obj, method, yaw)
            -- [SDWxOWNER-SPIN FIX] Lazily create the reusable rotator on FIRST use.
            -- (Regression fix: the previous version read SpinEngine._Rot directly but
            --  never called _ensureRot(), so _Rot stayed nil and this whole function
            --  silently did NOTHING -> the character spin stopped rotating entirely.)
            local r = SpinEngine._Rot
            if r == nil and SpinEngine._RotOK then
                r = _ensureRot()
            end
            if r and SpinEngine._RotOK then
                if _rotVerified then
                    _setRotYaw(r, yaw)
                    obj[method](obj, r, false, nil, false)
                    return
                end
                -- One-time proof that the field write actually STICKS: write a SENTINEL
                -- value and read it back (a sentinel avoids a false pass when yaw==0).
                -- If the binding silently ignores the write we must NOT trust the
                -- reusable rotator -> fall through to the proven fallback.
                if pcall(_setRotYaw, r, 1.2345) and math.abs((tonumber(r.Yaw) or 0) - 1.2345) < 0.01 then
                    _rotVerified = true
                    _setRotYaw(r, yaw)
                    obj[method](obj, r, false, nil, false)
                    return
                end
                SpinEngine._RotOK = false   -- field write unsupported -> never retry
            end
            -- [SDWxOWNER-SPIN FIX] Proven original path: construct a fresh rotator.
            -- Guarantees the spin ALWAYS applies, exactly like the pre-optimisation code.
            -- NOTE: we do NOT gate on type()=="function" -- FRotator may be a callable table.
            local ctor = _resolveRotCtor()
            if ctor == nil then ctor = FRotator end
            if ctor ~= nil then
                local okc, rot = pcall(ctor, 0, yaw, 0)
                if okc and rot ~= nil then
                    obj[method](obj, rot, false, nil, false)
                end
            end
        end

        local function SetMeshYaw(ch, yaw)
            -- [SDWxOWNER-CRASH FIX] Validate the mesh pointer (a mid-match rebuild leaves a stale pointer = UAF).
            if ch and slua.isValid(ch) then
                local mesh = ch.Mesh
                if mesh and slua.isValid(mesh) and mesh.K2_SetRelativeRotation then
                    _setYaw(mesh, "K2_SetRelativeRotation", yaw)
                end
            end
        end

        local function SetWeaponYaw(w, yaw)
            if not (w and slua.isValid(w)) then return end
            if w.K2_SetActorRelativeRotation then
                _setYaw(w, "K2_SetActorRelativeRotation", yaw)
            else
                -- [SDWxOWNER-CRASH FIX] Validate the weapon mesh pointer before writing.
                local m = w.Mesh
                if m and slua.isValid(m) and m.K2_SetRelativeRotation then
                    _setYaw(m, "K2_SetRelativeRotation", yaw)
                end
            end
        end

        -- [SDWxOWNER-SPIN FIX] Hoisted probe helpers (the movement check used to allocate every frame).
        local _mvCh = nil
        local _mvSpd = 0
        local function _probeSpeed()
            local ch = _mvCh
            if ch and type(ch.GetVelocity) == "function" then
                local v = ch:GetVelocity()
                if v then
                    local x = tonumber(v.X) or 0
                    local y = tonumber(v.Y) or 0
                    _mvSpd = math.sqrt(x * x + y * y)
                    return
                end
            end
            local v = ch and ch.Velocity
            if v then
                local x = tonumber(v.X) or 0
                local y = tonumber(v.Y) or 0
                _mvSpd = math.sqrt(x * x + y * y)
            end
        end

        local _locCh = nil
        local _locX, _locY, _locOk = 0, 0, false
        local function _probeLoc()
            local ch = _locCh
            if ch and type(ch.K2_GetActorLocation) == "function" then
                local p = ch:K2_GetActorLocation()
                if p then _locX = tonumber(p.X) or 0; _locY = tonumber(p.Y) or 0; _locOk = true; return end
            end
            local p = ch and ch.ActorLocation
            if p then _locX = tonumber(p.X) or 0; _locY = tonumber(p.Y) or 0; _locOk = true end
        end

        -- [SDWxOWNER-SPIN FIX] Hoisted weapon applier (was a per-frame closure).
        local _wpnCh = nil
        local _wpnApplied = 0
        local function _applyWeapon()
            local ch = _wpnCh
            local w = nil
            if ch and type(ch.GetCurrentWeapon) == "function" then w = ch:GetCurrentWeapon() end
            if w and slua.isValid(w) then
                if w ~= SpinEngine._Weapon then
                    SpinEngine._Weapon = w
                    local baseYaw = 0
                    local rr = w.RelativeRotation
                    if rr and rr.Yaw then baseYaw = rr.Yaw end
                    SpinEngine._BaseWeaponYaw = baseYaw
                end
                SetWeaponYaw(w, (SpinEngine._BaseWeaponYaw or 0) - _wpnApplied)
            end
        end

        -- [SDWxOWNER-PERF PHASE2] Hoisted vehicle probe. SpinApply runs EVERY engine frame
        -- (ReceiveTick hook), and the old inline pcall(function() ... end) allocated a fresh
        -- closure per frame -> constant GC pressure. Now zero-allocation.
        local _spinVehCh = nil
        local _spinInVeh = false
        local function _probeVeh() _spinInVeh = slua.isValid(_spinVehCh:GetCurrentVehicle()) end

        -- [SDWxOWNER-SPIN SMOOTH] Swap / pickup window handling (the "3-second freeze" fix).
        -- ROOT CAUSE: the bag/helmet "SkinFix" re-assert fires EVERY 3s (see the 3.0s skin
        -- loop) and unconditionally rebuilds the character avatar, opening a 0.4s
        -- _SDW_SkinSwapUntil window each cycle -> the spin used to freeze for that whole
        -- window. Weapon / vehicle / pet / dead-box swaps also open the window but never
        -- touch the CHARACTER mesh.
        -- FIX: do not freeze the spin for the whole window. Only skip the frame when the
        -- character mesh is actually UNSAFE (missing / invalid = the real UAF condition).
        -- The mesh pointer is re-validated immediately before every native write, so a
        -- freed mesh can never be written to. The window is still honoured as the trigger.
        local function _swapBlocked(ch, nowC)
            local win  = _G._SDW_SkinSwapUntil
            -- [SDWxOWNER-PERF] Reuse the caller's frame-clock sample when supplied (the
            -- per-frame spin hook and SpinTick already sampled it), so the steady state pays
            -- ONE os.clock() per frame instead of two. Falls back to os.clock() when absent.
            nowC = nowC or os.clock()
            if not (win and nowC < win) then return false end
            local m = ch and ch.Mesh
            return not (m and slua.isValid(m))
        end

        -- [SDWxOWNER-PERF] Hoisted mesh-transform restore probe (closure-free).
        local _restoreCh = nil
        local function _restoreMeshXform()
            if type(_restoreCh.ResetMeshRelativeLocationAndRotation) == "function" then
                _restoreCh:ResetMeshRelativeLocationAndRotation()
            end
        end
        -- [SDWxOWNER-PERF] Hoisted base-yaw readers (closure-free). Used on pawn change and
        -- on a mesh rebuild; the old code allocated a closure on each such event.
        local _yawCh, _yawVal = nil, nil
        local function _readMeshYawCh()
            local rr = _yawCh.Mesh and _yawCh.Mesh.RelativeRotation
            if rr and rr.Yaw then _yawVal = rr.Yaw end
        end
        local _yawMesh, _yawMeshVal = nil, nil
        local function _readMeshYawMesh()
            local rr = _yawMesh.RelativeRotation
            if rr and rr.Yaw then _yawMeshVal = rr.Yaw end
        end

        local function SpinRestore()
            local ch = SpinEngine._Char
            if ch and slua.isValid(ch) then
                _restoreCh = ch
                pcall(_restoreMeshXform)
                pcall(SetMeshYaw, ch, DEFAULT_MESH_YAW)
                local w = SpinEngine._Weapon
                if w and slua.isValid(w) then pcall(SetWeaponYaw, w, SpinEngine._BaseWeaponYaw or 0) end
            end
            SpinEngine._Char = nil
            SpinEngine._Weapon = nil
            SpinEngine._BaseWeaponYaw = 0
            SpinEngine._BaseMeshYaw = nil
            SpinEngine.Angle = 0
            SpinEngine.Weight = 0
            SpinEngine._Applied = false
            SpinEngine._T0 = nil
            SpinEngine._LastApplyT = -1
            SpinEngine._LastHookT = nil
            SpinEngine._Moving = false
            SpinEngine._Mesh = nil
            SpinEngine._Pos.has = false
            -- [SDWxOWNER-SPIN SMOOTH] Re-base the clock sampler so a later re-enable does
            -- not see a stale (long) delta. _Clock itself is preserved for continuity.
            SpinEngine._LastRealT = nil
            SpinEngine._FrameDt = 0
        end
        SpinEngine.Restore = SpinRestore

        local function SpinResetForMatch()
            SpinEngine._Char = nil
            SpinEngine._Weapon = nil
            SpinEngine._BaseWeaponYaw = 0
            SpinEngine._BaseMeshYaw = nil
            SpinEngine.Angle = 0
            SpinEngine.Weight = 0
            SpinEngine._Applied = false
            SpinEngine._T0 = nil
            SpinEngine._LastApplyT = -1
            SpinEngine._LastHookT = nil
            SpinEngine._Moving = false
            SpinEngine._Mesh = nil
            SpinEngine._Pos.has = false
            -- [SDWxOWNER-SPIN SMOOTH] Fresh monotonic clock for the new match.
            SpinEngine._Clock = 0
            SpinEngine._LastRealT = nil
            SpinEngine._FrameDt = 0
            -- [SDWxOWNER-PERF FIX] Do NOT clear _Hooked here.
        end
        SpinEngine.ResetForMatch = SpinResetForMatch

        local function GetSpeed2D(ch)
            _mvCh = ch; _mvSpd = 0
            pcall(_probeSpeed)
            return _mvSpd
        end

        local function SpinApply(dt)
            -- [SDWxOWNER-LOCK] No spin without a valid, unlocked key. The spin hook runs
            -- every engine frame, so THIS gate is what turns the spin OFF the instant a
            -- key is invalid / expired / banned -- even mid-match.
            if not (_G.SDW_IsAuthorized and _G.SDW_IsAuthorized()) then
                if SpinEngine._Applied then SpinRestore() end
                return
            end
            local LC = _G.SDWConfig
            if not (LC and LC.CharSpinEnabled) then
                if SpinEngine._Applied then SpinRestore() end
                return
            end
            -- [SDWxOWNER-PLANE-CRASH-FIX] Never spin while the local pawn is in the drop
            -- plane / aircraft / vehicle / freefall: the engine owns the mesh transform
            -- there and our relative-rotation write fights the attachment -> native crash.
            if _G.SDW_LocalPawnUnsafe and _G.SDW_LocalPawnUnsafe() then
                if SpinEngine._Applied then SpinRestore() end
                return
            end
            local speed = tonumber(LC.CharSpinSpeed) or 360

            local ch = SpinEngine._Char
            if not (ch and slua.isValid(ch)) then
                local pc, localPawn = SnaplineESP.GetMyControllerAndPlayer()
                if not (localPawn and slua.isValid(localPawn)) then
                    if SpinEngine._Applied then SpinRestore() end
                    return
                end
                ch = localPawn
                if ch ~= SpinEngine._Char then
                    if SpinEngine._Applied then SpinRestore() end
                    SpinEngine._Char = ch
                    SpinEngine._Weapon = nil
                    SpinEngine._BaseWeaponYaw = 0
                    SpinEngine.Weight = 0
                    -- [SDWxOWNER-SPIN SMOOTH] Do NOT reset the monotonic clock on a pawn
                    -- change: the angle keeps advancing, so the rotation never snaps to 0.
                    local baseYaw = DEFAULT_MESH_YAW
                    _yawCh = ch; _yawVal = nil
                    pcall(_readMeshYawCh)
                    if _yawVal then baseYaw = _yawVal end
                    SpinEngine._BaseMeshYaw = baseYaw
                    SpinEngine._Mesh = ch.Mesh
                    if SpinEngine.InstallTickHook then pcall(SpinEngine.InstallTickHook, ch) end
                end
            end

            -- [SDWxOWNER-CRASH FIX] Never spin the mesh in a vehicle (vehicle drives the transform -> crash).
            if ch and slua.isValid(ch) then
                _spinVehCh = ch
                _spinInVeh = false
                pcall(_probeVeh)
                if _spinInVeh then if SpinEngine._Applied then SpinRestore() end; return end
            end

            -- [SDWxOWNER-SPIN SMOOTH] Graceful mesh-rebuild handling. If the engine swapped
            -- the skeletal mesh (skin/avatar rebuild) we re-capture the base yaw on the NEW
            -- mesh and keep spinning. This never freezes the spin and never writes to the
            -- freed old mesh (UAF), so the rotation stays smooth across a rebuild.
            do
                local m = ch and ch.Mesh
                if m ~= SpinEngine._Mesh then
                    if m and slua.isValid(m) then
                        local baseYaw = DEFAULT_MESH_YAW
                        _yawMesh = m; _yawMeshVal = nil
                        pcall(_readMeshYawMesh)
                        if _yawMeshVal then baseYaw = _yawMeshVal end
                        SpinEngine._BaseMeshYaw = baseYaw
                        SpinEngine._Mesh = m
                    else
                        SpinEngine._Mesh = nil
                    end
                end
            end

            -- [SDWxOWNER-SPIN SMOOTH] Drain the sampled frame time into the monotonic clock.
            -- Only reached on a frame we are actually going to write, so a blocked frame
            -- resumes with a normal single-frame step -> no angle jump.
            local frameDt = SpinEngine._FrameDt or 0
            SpinEngine._Clock = SpinEngine._Clock + frameDt
            SpinEngine._FrameDt = 0
            local now = SpinEngine._Clock
            if not SpinEngine._T0 then SpinEngine._T0 = now end

            -- [SDWxOWNER-SPIN FIX] One native write per frame.
            local _dt = now - (SpinEngine._LastApplyT or -1)
            if _dt >= 0 and _dt < 0.0005 then return end
            SpinEngine._LastApplyT = now

            SpinEngine.Angle = ((now - SpinEngine._T0) * speed) % 360

            -- [SDWxOWNER-SPIN SMOOTH FIX] Smooth spin weight instead of a hard 0/1 flip.
            -- The old code snapped the mesh between the base yaw and base+Angle the instant
            -- the player started/stopped moving (only when "Spin While Moving" is OFF), which
            -- looked like the rotation SNAPPED. We now ramp the weight toward its target so
            -- the mesh glides in and out of the spin (~0.12s blend). When "Spin While Moving"
            -- is ON (default) the target is always 1, so behaviour is unchanged apart from a
            -- one-off smooth fade-in on the very first frame.
            local targetW = 1
            if not LC.CharSpinWhileMoving then
                local moving = SpinEngine._Moving
                -- [SDWxOWNER-SPIN FIX] Movement does not need a per-frame probe; sample
                -- it at ~30 Hz (cheap) instead of every frame.
                if (now - (SpinEngine._LastMoveCheck or 0)) >= 0.033 then
                    SpinEngine._LastMoveCheck = now
                    local spd = GetSpeed2D(ch)
                    if spd > 40 then
                        moving = true
                    else
                        _locCh = ch; _locOk = false
                        pcall(_probeLoc)
                        if _locOk then
                            local pp = SpinEngine._Pos
                            if pp.has then
                                local dtp = now - pp.t
                                if dtp >= 0.08 then
                                    local dx, dy = _locX - pp.x, _locY - pp.y
                                    local dist = math.sqrt(dx * dx + dy * dy)
                                    if (dist / dtp) > 40 then moving = true end
                                    pp.x, pp.y, pp.t, pp.has = _locX, _locY, now, true
                                end
                            else
                                pp.x, pp.y, pp.t, pp.has = _locX, _locY, now, true
                            end
                        end
                    end
                    SpinEngine._Moving = moving
                end
                if moving then targetW = 0 end
            end

            -- Ramp the weight toward its target (rate 8/s => full blend in ~0.12s).
            local w = SpinEngine.Weight or 0
            local dw = targetW - w
            if dw ~= 0 then
                local step = 8.0 * frameDt
                if step <= 0 then step = 0.05 end   -- guarantee progress on a 0-dt frame
                if step >= math.abs(dw) then
                    w = targetW
                else
                    w = w + (dw > 0 and step or -step)
                end
            end
            SpinEngine.Weight = w

            -- Fully blended out (moving): restore once, then idle with NO per-frame writes.
            if targetW == 0 and w <= 0.0005 then
                if SpinEngine._Applied then
                    pcall(SetMeshYaw, ch, SpinEngine._BaseMeshYaw or DEFAULT_MESH_YAW)
                    local wpn = SpinEngine._Weapon
                    if wpn and slua.isValid(wpn) then pcall(SetWeaponYaw, wpn, SpinEngine._BaseWeaponYaw or 0) end
                    SpinEngine._Applied = false
                end
                return
            end

            local applied = SpinEngine.Angle * w

            pcall(SetMeshYaw, ch, (SpinEngine._BaseMeshYaw or DEFAULT_MESH_YAW) + applied)

            _wpnCh = ch
            _wpnApplied = applied
            pcall(_applyWeapon)

            SpinEngine._Applied = true
        end

        local function SpinTick()
            -- [SDWxOWNER-PERF] Fast-out FIRST: this timer beats 125x/second. When spin is OFF
            -- and nothing is currently applied there is nothing to do (no restore, no hook
            -- check), so return before any clock read / validity probe. Behaviour is identical:
            -- every branch below would ultimately have returned without acting anyway.
            if not (_G.SDWConfig and _G.SDWConfig.CharSpinEnabled) and not SpinEngine._Applied then return end

            -- [SDWxOWNER-SPIN SMOOTH FIX] Decide hook liveness BEFORE sampling the frame clock.
            -- ROOT CAUSE of the periodic spin stutter: this 0.2s fallback timer used to call
            -- SampleSpinClock() unconditionally, which OVERWRITES SpinEngine._FrameDt with the
            -- delta since the last per-frame hook sample. It then bailed (hook alive) WITHOUT
            -- draining that delta, so the slice of frame time it captured was silently LOST and
            -- the monotonic _Clock (and therefore the angle) lurched every 0.2s. We now read the
            -- RAW clock (NowSeconds does NOT touch _FrameDt) for the staleness test and only
            -- sample/drive on the fallback path, so the per-frame hook stays the SOLE sampler.
            local hookAlive = SpinEngine._LastHookT and (NowSeconds() - SpinEngine._LastHookT) <= 0.03

            -- [SDWxOWNER-CRASH FIX] Never spin a dead/dying/knocked pawn's mesh: the mesh is
            -- mid-teardown / ragdoll transition there. Restore first so it is not left rotated.
            -- Runs on EVERY beat (hook alive or not) so a dead pawn is always un-rotated.
            do
                local _c = SpinEngine._Char
                if _c and slua.isValid(_c) then
                    local _hs = _c.HealthStatus
                    if _c.bIsDying == true or _c.bIsGroggy == true or _c.bIsGrogggy == true or _hs == 1 or _hs == 2 then
                        if SpinEngine._Applied then SpinRestore() end
                        return
                    end
                end
            end

            local ch = SpinEngine._Char
            if ch and slua.isValid(ch) then
                -- [SDWxOWNER-SPIN FIX] Verify our ReceiveTick wrapper is still installed.
                local rt = ch.ReceiveTick
                if SpinEngine._Hooked[ch] and not (type(rt) == "function" and rt._SDW_SPIN_WRAP) then
                    SpinEngine._Hooked[ch] = nil
                end
                if not SpinEngine._Hooked[ch] and SpinEngine.InstallTickHook then
                    pcall(SpinEngine.InstallTickHook, ch)
                end
            end

            -- [SDWxOWNER-SPIN SMOOTH FIX] Hook is the PRIMARY driver: bail BEFORE sampling so we
            -- never steal an undrained frame delta from it (the stutter fix above). Behaviour is
            -- unchanged when the hook is dead: we fall through and drive the spin ourselves.
            if hookAlive then return end

            -- Fallback path ONLY (hook lost/stale): this beat owns the clock.
            local now = SampleSpinClock()
            -- [SDWxOWNER-SPIN SMOOTH] Swap/pickup windows block only when the character
            -- mesh is actually unsafe (see _swapBlocked) -> no periodic 3s freeze.
            if _swapBlocked(SpinEngine._Char, now) then return end
            SpinApply(0.008)
        end

        SpinEngine.InstallTickHook = function(ch)
            if not (ch and slua.isValid(ch)) then return end
            if SpinEngine._Hooked[ch] then return end
            local orig = ch.ReceiveTick
            if type(orig) ~= "function" then return end
            -- [SDWxOWNER-PERF FIX] Never wrap our OWN wrapper again (that is what made
            -- the spin run N times per frame and cause the growing "stuck" lag).
            if orig._SDW_SPIN_WRAP then SpinEngine._Hooked[ch] = true; return end
            SpinEngine._Hooked[ch] = true
            pcall(function()
                local wrapper = function(self, d)
                    pcall(orig, self, d)
                    if not (_G.SDWConfig and _G.SDWConfig.CharSpinEnabled) then return end
                    -- [SDWxOWNER-LOCK] Per-frame auth gate: never drive the spin without a
                    -- valid, unlocked key.
                    if not (_G.SDW_IsAuthorized and _G.SDW_IsAuthorized()) then return end
                    -- [SDWxOWNER-SPIN SMOOTH] Sample the frame clock EVERY frame (even a
                    -- blocked one) so the spin resumes with a normal single-frame step.
                    -- [SDWxOWNER-PERF] Reuse the SAME sample for the hook timestamp below
                    -- (was a second NowSeconds() native call every frame).
                    local _spinNow = SampleSpinClock()
                    -- [SDWxOWNER-SPIN SMOOTH] Swap/pickup windows block only when the
                    -- character mesh is actually unsafe (see _swapBlocked). This removes
                    -- the periodic 3s freeze while still never writing to a freed mesh.
                    if _swapBlocked(self, _spinNow) then return end
                    -- [SDWxOWNER-SPIN FIX] The hook is the PRIMARY driver.
                    SpinEngine._LastHookT = _spinNow
                    pcall(SpinApply, d)
                end
                wrapper._SDW_SPIN_WRAP = true
                ch.ReceiveTick = wrapper
            end)
        end

        _G.SDW_SpinTick = SpinTick
        _G.SDW_SpinApply = SpinApply
        _G.SDW_SpinRestore = SpinRestore
        _G.SDW_SpinResetForMatch = SpinResetForMatch
    end

    -- ================================================================
    -- [SDWxOWNER] EXTRA FEATURES — Character Size
    -- Scales the local player's body mesh (3P + 1P).
    -- FULLY REVERSIBLE: the ORIGINAL relative scale of every mesh is
    -- cached once (weak-keyed) and restored the instant the feature is
    -- switched OFF, so the model always snaps back to its normal size.
    -- LAG-FREE: one 0.2s (5 Hz) timer with cheap, validated native writes and
    -- no per-frame allocation. CRASH-SAFE: honours the skin-swap + pickup
    -- windows, skips dead/knocked pawns, validates every native pointer.
    -- ================================================================
    do
        local _FV = FVector or _G.FVector or import("Vector")
        local _origScale = setmetatable({}, { __mode = "k" })   -- mesh -> {x,y,z}
        local _charCur = { mesh = nil, m1p = nil, mult = nil }

        -- Read (and cache) a mesh's ORIGINAL relative scale, once.
        local function _readOrig(mesh)
            if not (mesh and slua.isValid(mesh)) then return nil end
            local o = _origScale[mesh]
            if o then return o end
            local rs = nil
            pcall(function() rs = mesh.RelativeScale3D end)
            if not rs then pcall(function() rs = mesh.RelativeScale end) end
            if not rs then return nil end
            o = { x = tonumber(rs.X) or 1, y = tonumber(rs.Y) or 1, z = tonumber(rs.Z) or 1 }
            _origScale[mesh] = o
            return o
        end

        -- Write original*mult onto a mesh (validated).
        local function _writeScale(mesh, mult)
            if not (mesh and slua.isValid(mesh)) then return end
            local o = _readOrig(mesh)
            if not o or not _FV then return end
            pcall(function()
                if mesh.SetRelativeScale3D then
                    mesh:SetRelativeScale3D(_FV(o.x * mult, o.y * mult, o.z * mult))
                elseif mesh.SetActorScale3D then
                    mesh:SetActorScale3D(_FV(o.x * mult, o.y * mult, o.z * mult))
                end
            end)
        end

        -- [SDWxOWNER-PERF] Hoisted probes for the 0.2s size driver. The old inline
        -- pcall(function() ... end) bodies allocated a fresh closure on every tick; these
        -- named probes are created once and driven through scratch locals (zero alloc).
        local _scCh = nil
        local function _scGetChar() _scCh = GameplayData.GetPlayerCharacter() end
        local _scSafetyCh = nil
        local function _scGetSafetyChar()
            local pc = GameplayData.GetPlayerController()
            if pc and slua.isValid(pc) and pc.GetPlayerCharacterSafety then _scSafetyCh = pc:GetPlayerCharacterSafety() end
        end
        local _scMeshPawn, _scMesh3, _scMesh1 = nil, nil, nil
        local function _scGetMesh3() _scMesh3 = _scMeshPawn.Mesh end
        local function _scGetMesh1() _scMesh1 = _scMeshPawn.Mesh1P end

        local function _localChar()
            local ch = nil
            _scCh = nil
            pcall(_scGetChar)
            ch = _scCh
            if not (ch and slua.isValid(ch)) then
                _scSafetyCh = nil
                pcall(_scGetSafetyChar)
                ch = _scSafetyCh
            end
            if ch and slua.isValid(ch) then return ch end
            return nil
        end

        -- [SDWxOWNER-CRASH FIX] Never scale a dead/knocked pawn's mesh (mid-teardown).
        local function _isDown(ch)
            if not (ch and slua.isValid(ch)) then return true end
            local hs = ch.HealthStatus
            return (ch.bIsDying == true or ch.bIsGroggy == true or ch.bIsGrogggy == true or hs == 1 or hs == 2)
        end

        local function _applyChar()
            local C = _G.SDWConfig
            local mult = (C and C.CharSizeEnabled) and ((tonumber(C.CharSizePercent) or 100) / 100) or nil
            if not mult or mult == 1 then
                -- OFF (or 100%): restore the cached originals, then forget.
                if _charCur.mesh and slua.isValid(_charCur.mesh) then pcall(_writeScale, _charCur.mesh, 1) end
                if _charCur.m1p and slua.isValid(_charCur.m1p) then pcall(_writeScale, _charCur.m1p, 1) end
                _charCur.mesh, _charCur.m1p, _charCur.mult = nil, nil, nil
                return
            end
            -- [SDWxOWNER-PLANE-CRASH FIX] Only the APPLY path is gated: while the local
            -- pawn is in the drop plane / aircraft / vehicle / freefall the mesh is
            -- engine-owned, so scaling it fights the engine and can fault. The OFF-restore
            -- branch above still runs so disabling the feature always restores cleanly.
            if _G.SDW_LocalPawnUnsafe and _G.SDW_LocalPawnUnsafe() then return end
            local ch = _localChar()
            if not ch or _isDown(ch) then return end
            local m3, m1 = nil, nil
            _scMeshPawn = ch; _scMesh3 = nil; _scMesh1 = nil
            pcall(_scGetMesh3)
            pcall(_scGetMesh1)
            m3, m1 = _scMesh3, _scMesh1
            -- Mesh changed (new pawn / skin rebuild): restore the old one first.
            if _charCur.mesh and _charCur.mesh ~= m3 and slua.isValid(_charCur.mesh) then pcall(_writeScale, _charCur.mesh, 1) end
            if _charCur.m1p and _charCur.m1p ~= m1 and slua.isValid(_charCur.m1p) then pcall(_writeScale, _charCur.m1p, 1) end
            if m3 then pcall(_writeScale, m3, mult) end
            if m1 then pcall(_writeScale, m1, mult) end
            _charCur.mesh, _charCur.m1p, _charCur.mult = m3, m1, mult
        end

        local function _tick()
            local C = _G.SDWConfig
            if not C then return end
            -- [SDWxOWNER-CRASH FIX] Never touch a mesh while it is being rebuilt.
            if _G._SDW_SkinSwapUntil and os.clock() < _G._SDW_SkinSwapUntil then return end
            pcall(_applyChar)
        end

        _G.SDW_SizeTick = _tick
        _G.SDW_ApplyCharSize = _applyChar
    end

    do
        local BOMB_ACTIVE_OFFSET = { X = 0, Y = 0, Z = 25 }
        local BOMB_GROUND_OFFSET = { X = 0, Y = 0, Z = 15 }
        -- [SDWxOWNER-OFF-FIX] Expose the label offsets so the feature-disable cleanup can
        -- overwrite (erase) the lingering Bomb labels from outside this block.
        _G.SDW_BOMB_ACTIVE_OFFSET = BOMB_ACTIVE_OFFSET
        _G.SDW_BOMB_GROUND_OFFSET = BOMB_GROUND_OFFSET

        local C_BOMB_FRAG = { R = 255, G = 40, B = 40, A = 255 }
        local C_BOMB_MOLOTOV = { R = 255, G = 130, B = 0, A = 255 }
        local C_BOMB_SMOKE = { R = 0, G = 230, B = 255, A = 255 }

        -- [SDWxOWNER-PERF T3] Shared closure-free local-player/PC/HUD probes (used by Bomb ESP).
        function _OPT.bombGetPlayer()
            _OPT.bombPlayer = GameplayData.GetPlayerCharacter()
            _OPT.bombPC = GameplayData.GetPlayerController()
        end
        function _OPT.bombGetPCFromHUD()
            local pc = _OPT.bombPC or slua_GameFrontendHUD:GetPlayerController()
            _OPT.bombPC = pc
            local pl = _OPT.bombPlayer
            if pc and pc.GetPlayerCharacter then pl = pl or pc:GetPlayerCharacter() end
            _OPT.bombPlayer = pl
        end
        function _OPT.bombGetHUD() local pc = _OPT.bombPC; _OPT.bombHud = pc:GetHUD() end

        -- [SDWxOWNER-PERF T3] ZERO-ALLOCATION Bomb ESP. The old tick allocated two
        -- { actor=, typ= } tables per bomb AND ran string.lower(actor:GetName()) plus up to
        -- 7 pattern finds on EVERY scanned actor EVERY tick (hundreds of actors -> the single
        -- biggest GC/CPU spike in the mod). Now: entry tables are pooled and mutated in place,
        -- and each actor's classification is resolved ONCE and cached in a weak-keyed table
        -- (auto-released when the actor dies). Every pcall body is hoisted/closure-free.
        local _BOMB_ACTIVE_POOL = {}
        local _BOMB_GROUND_POOL = {}
        local _BOMB_TYP_CACHE = setmetatable({}, { __mode = "k" })
        local _BOMB_THROWN_CACHE = setmetatable({}, { __mode = "k" })
        local _BOMB_NAMES = { [1] = "FRAG GRENADE", [2] = "SMOKE GRENADE", [3] = "MOLOTOV" }
        local _BOMB_COLORS = { [1] = C_BOMB_FRAG, [2] = C_BOMB_SMOKE, [3] = C_BOMB_MOLOTOV }

        function _OPT.bombResolveClass()
            local c = import(_OPT.bombClsName)
            if c and _G._CACHED_BOMB_CLS == nil then _G._CACHED_BOMB_CLS = c end
        end
        function _OPT.bombMakeArray() _OPT.bombArr = slua.Array(UEnums.EPropertyClass.Object, _OPT.bombCls) end
        function _OPT.bombGetTime() _OPT.bombGameTime = _OPT.bombGS.GetTimeSeconds(_OPT.bombGI) end
        function _OPT.bombGetActors() _OPT.bombActors = _OPT.bombGS.GetAllActorsOfClass(_OPT.bombGI, _OPT.bombCls, _OPT.bombArr) end
        function _OPT.bombGetName()
            local a = _OPT.bombActor
            _OPT.bombName = string.lower(type(a.GetName) == "function" and a:GetName() or tostring(a))
        end
        function _OPT.bombDistTo() _OPT.bombDist = _OPT.bombPlayer:GetDistanceTo(_OPT.bombActor) / 100 end
        function _OPT.bombExplodeLeft()
            local b = _OPT.bombActor
            if b.ExplosionTime then _OPT.bombLeft = b.ExplosionTime - _OPT.bombTime
            elseif b.ExplodeTime then _OPT.bombLeft = b.ExplodeTime - _OPT.bombTime end
        end
        function _OPT.bombAddLabel()
            _OPT.bombHud:AddDebugText(_OPT.bombText, _OPT.bombActor, _OPT.bombDuration, _OPT.bombOffset, _OPT.bombOffset, _OPT.bombCol, false, false, true, nil, _OPT.bombScale, true)
        end
        -- Hoisted draw pass (was a per-tick closure). Reads its inputs from _OPT.
        function _OPT.bombDraw(list, maxDist, isActive)
            local offset = isActive and BOMB_ACTIVE_OFFSET or BOMB_GROUND_OFFSET
            local duration = 3.5   -- [SDWxOWNER-BLINK FIX] must exceed the 3.0s tick so the label never expires before the next redraw
            local player = _OPT.bombPlayer
            local hud = _OPT.bombHud
            local gameTime = _OPT.bombGameTime
            local bNames = _BOMB_NAMES
            local bColors = _BOMB_COLORS
            for _, e in ipairs(list or {}) do
                local b = e.actor
                if b and SafeIsValid(b) and not b.bHidden then
                    _OPT.bombPlayer = player; _OPT.bombActor = b; _OPT.bombDist = -1
                    pcall(_OPT.bombDistTo)
                    local dist = _OPT.bombDist or -1
                    if dist >= 0 and dist <= maxDist then
                        local bName = bNames[e.typ] or "BOMB"
                        local _bdm = math.floor(dist)
                        local _btc = _BOMB_TXT[e.typ]
                        if not _btc then _btc = {}; _BOMB_TXT[e.typ] = _btc end
                        local text = _btc[_bdm]
                        if not text then text = bName .. " [" .. _bdm .. "m]"; _btc[_bdm] = text end
                        if isActive and gameTime then
                            _OPT.bombActor = b; _OPT.bombTime = gameTime; _OPT.bombLeft = -1
                            pcall(_OPT.bombExplodeLeft)
                            local left = _OPT.bombLeft or -1
                            if left > 0 and left < 100 then
                                local _bt = math.floor(left * 10 + 0.5)
                                local _ts = _BOMB_TIME_TXT[_bt]
                                if not _ts then _ts = string.format("%.1f", left); _BOMB_TIME_TXT[_bt] = _ts end
                                text = text .. " (" .. _ts .. "s)"
                            end
                        end
                        local col = bColors[e.typ] or C_BOMB_FRAG
                        local scale = math.max(0.65, 1.15 - (dist / maxDist))
                        _OPT.bombHud = hud; _OPT.bombText = text; _OPT.bombActor = b
                        _OPT.bombDuration = duration; _OPT.bombOffset = offset
                        _OPT.bombCol = col; _OPT.bombScale = scale
                        pcall(_OPT.bombAddLabel)
                    end
                end
            end
        end

        -- [ZEROLAG] Bomb label memo: base "Name [12m]" per (typ, metre) + the "(3.4s)" tenth
        -- string per tenth. Removes the per-bomb string.format + concatenation churn.
        local _BOMB_TXT = {}
        local _BOMB_TIME_TXT = {}
        _G.Tick_SDW_BombESP = function()
            local C = _G.SDWConfig
            if _G.SDW_FXCheck then pcall(_G.SDW_FXCheck, "bomb", (C and C.BombESPEnabled) and true or false) end
            if not C or C.BombESPEnabled == false then return end
            local player = nil
            local pc = nil
            -- [SDWxOWNER-PERF T3] Shared closure-free local-player/PC/HUD probes.
            pcall(_OPT.bombGetPlayer)
            player = _OPT.bombPlayer; pc = _OPT.bombPC
            if not player or not pc then
                if slua_GameFrontendHUD then
                    _OPT.bombPlayer = player; _OPT.bombPC = pc
                    pcall(_OPT.bombGetPCFromHUD)
                    player = _OPT.bombPlayer; pc = _OPT.bombPC
                end
            end
            if not player or not pc then return end
            local hud = pc.MyHUD
            if not hud and pc.GetHUD then _OPT.bombPC = pc; pcall(_OPT.bombGetHUD); hud = _OPT.bombHud end
            if not hud then return end

            local gs = _ci_GameplayStatics
            if not gs then return end

            if _G._CACHED_BOMB_CLS == nil then
                -- [SDWxOWNER-PERF] NEVER fall back to the broad "Actor" class.
                local clsCandidates = {
                    "GrenadeActorBase", "STExtraGrenadeActor", "GrenadeActor",
                    "ThrowableProjectile", "Projectile", "STProjectileActor",
                }
                for _, cName in ipairs(clsCandidates) do
                    _OPT.bombClsName = cName
                    pcall(_OPT.bombResolveClass)
                    if _G._CACHED_BOMB_CLS then break end
                end
            end
            local cls = _G._CACHED_BOMB_CLS
            if not cls then return end
            _OPT.bombCls = cls
            _OPT.bombArr = nil
            pcall(_OPT.bombMakeArray)
            local arr = _OPT.bombArr
            local ui_util = _cached_ui_util
            if not ui_util then
                local ok; ok, ui_util = pcall(require, "client.common.ui_util")
                if ok then _cached_ui_util = ui_util end
            end
            local gi = ui_util and ui_util.GetGameInstance and ui_util.GetGameInstance()
            _OPT.bombGameTime = nil
            if gi and gs then
                _OPT.bombGI = gi; _OPT.bombGS = gs
                pcall(_OPT.bombGetTime)
            end
            local active = _G.SDW_BombActive
            if not active then active = {}; _G.SDW_BombActive = active end
            local ground = _G.SDW_BombGround
            if not ground then ground = {}; _G.SDW_BombGround = ground end
            for i = #active, 1, -1 do active[i] = nil end
            for i = #ground, 1, -1 do ground[i] = nil end
            local aCount, gCount = 0, 0

            if gi and gs and arr then
                _OPT.bombGI = gi; _OPT.bombGS = gs; _OPT.bombCls = cls; _OPT.bombArr = arr
                _OPT.bombActors = nil
                pcall(_OPT.bombGetActors)
                local actors = _OPT.bombActors
                if actors then
                    -- [SDWxOWNER-PERF] Hard cap the Lua-side iteration.
                    local _bombScanBudget = 400
                    local _bombScanned = 0
                    for _, actor in pairs(actors) do
                        _bombScanned = _bombScanned + 1
                        if _bombScanned > _bombScanBudget then break end
                        if actor and SafeIsValid(actor) and not actor.bHidden and not actor.bTearOff then
                            local typ = _BOMB_TYP_CACHE[actor]
                            if typ == nil then
                                -- [SDWxOWNER-PERF T3] Resolve the classification ONCE per actor.
                                _OPT.bombActor = actor; _OPT.bombName = ""
                                pcall(_OPT.bombGetName)
                                local name = _OPT.bombName or ""
                                typ = 0
                                if name:find("smoke") then typ = 2
                                elseif name:find("burn") or name:find("molotov") or name:find("fire") then typ = 3
                                elseif name:find("grenade") or name:find("frag") then typ = 1 end
                                _BOMB_TYP_CACHE[actor] = typ
                                _BOMB_THROWN_CACHE[actor] = (name:find("projectile") or name:find("thrown") or name:find("active")) and true or false
                            end

                            if typ > 0 then
                                if _BOMB_THROWN_CACHE[actor] then
                                    aCount = aCount + 1
                                    local e = _BOMB_ACTIVE_POOL[aCount]
                                    if not e then e = { actor = nil, typ = 0 }; _BOMB_ACTIVE_POOL[aCount] = e end
                                    e.actor = actor; e.typ = typ
                                    active[aCount] = e
                                else
                                    gCount = gCount + 1
                                    local e = _BOMB_GROUND_POOL[gCount]
                                    if not e then e = { actor = nil, typ = 0 }; _BOMB_GROUND_POOL[gCount] = e end
                                    e.actor = actor; e.typ = typ
                                    ground[gCount] = e
                                end
                            end
                        end
                    end
                end
            end
            _G.SDW_BombActive = active
            _G.SDW_BombGround = ground

            -- [SDWxOWNER-PERF T3] Keep the player/hud on _OPT for the hoisted draw pass.
            _OPT.bombPlayer = player; _OPT.bombHud = hud
            _OPT.bombDraw(_G.SDW_BombGround, 50, false)
            _OPT.bombDraw(_G.SDW_BombActive, 50, true)
        end
    end

    local _FrameCache = { frame = -1, pawn = nil, pos = nil, hud = nil, pc = nil, team = 0 }
    -- [SDWxOWNER-PERF] Hoisted refresh closures stored on the cache table (no new top-level locals).
    _FrameCache._s = { pawn = nil, pos = nil, hud = nil, pc = nil }
    _FrameCache._getChar = function() local s = _FrameCache._s; s.pawn = GameplayData.GetPlayerCharacter() end
    _FrameCache._getPCFromHUD = function() local s = _FrameCache._s; s.pc = slua_GameFrontendHUD:GetPlayerController(); if s.pc and s.pc.GetPlayerCharacter then s.pawn = s.pc:GetPlayerCharacter() end end
    _FrameCache._getPos = function() local s = _FrameCache._s; s.pos = s.pawn.K2_GetActorLocation and s.pawn:K2_GetActorLocation() end
    _FrameCache._getHudFromPawn = function() local s = _FrameCache._s; s.hud = s.pawn.MyHUD or (s.pc and s.pc.MyHUD) end
    _FrameCache._getPC = function() local s = _FrameCache._s; s.pc = GameplayData.GetPlayerController() end
    _FrameCache._getHudFromPC = function() local s = _FrameCache._s; s.hud = s.pc.MyHUD or (s.pc.GetHUD and s.pc:GetHUD()) end
    local function GetFrameCache()
        local f = os.clock()
        -- [SDWxOWNER-PERF 1.5x] TTL raised 0.05s -> 0.2s.
        if _FrameCache.frame < 0 or (f - (_FrameCache.time or 0)) > 0.2 then
            _FrameCache.time = f
            _FrameCache.frame = _FrameCache.frame + 1
            local s = _FrameCache._s
            local pawn, pos, hud, pc = nil, nil, nil, nil
            s.pawn, s.pos, s.hud, s.pc = nil, nil, nil, nil
            pcall(_FrameCache._getChar); pawn = s.pawn
            if not pawn and slua_GameFrontendHUD then
                pcall(_FrameCache._getPCFromHUD); pawn = s.pawn; pc = s.pc
            end
            if pawn then
                s.pawn = pawn; s.pc = pc
                pcall(_FrameCache._getPos); pos = s.pos
                pcall(_FrameCache._getHudFromPawn); hud = s.hud
            else
                pawn = _FrameCache.pawn
                pos = _FrameCache.pos
                hud = _FrameCache.hud
                pc = _FrameCache.pc
            end
            if not pc then s.pc = nil; pcall(_FrameCache._getPC); pc = s.pc end
            if not hud and pc then s.pc = pc; pcall(_FrameCache._getHudFromPC); hud = s.hud end
            _FrameCache.pawn = pawn
            _FrameCache.pos = pos
            _FrameCache.hud = hud
            _FrameCache.pc = pc
            -- [SDWxOWNER-ALLMAPS] Resolve MY team exactly like the snapline does (TeamID
            -- property, else the GetTeamID() method). On TDM/FFA/rooms the property is often
            -- nil while GetTeamID() still works -> without this the counters could not tell a
            -- teammate from an enemy and would over-count. Classic is unchanged (TeamID set).
            local _ft = pawn and pawn.TeamID
            if _ft == nil and pawn then
                local _gt = pawn.GetTeamID
                if type(_gt) == "function" then
                    local okT, tv = pcall(_gt, pawn)
                    if okT and type(tv) == "number" then _ft = tv end
                end
            end
            _FrameCache.team = _ft or 0
        end
        return _FrameCache.pawn, _FrameCache.pos, _FrameCache.hud, _FrameCache.pc, _FrameCache.team
    end

    -- [ZEROLAG] Distance-text memo tables. The health-bar pass builds "12m" / "BOT  12m" for
    -- EVERY enemy on EVERY 0.5 s tick; memoising by the integer metre count (bounded 0..400)
    -- makes the steady state allocate ZERO strings on this path (biggest per-tick GC source here).
    local _HB_TXT = {}
    local _HB_BOT_TXT = {}

    -- ======================================================================
    -- [SDWxOWNER-WEAPONESP]  Weapon ESP  (Show Enemy Weapon)
    -- ----------------------------------------------------------------------
    -- Ported from the v2 ESP tab's "Show Weapon Icon" feature, but implemented
    -- as a TEXT label rather than a texture-brush icon. The reference icon path
    -- needs CDataTable + UIUtil.GetItemBigIcon + SetBrushResourceFromPathSync +
    -- a brush widget PER ENEMY, which is exactly the kind of per-enemy widget
    -- churn that causes hot-drop lag / heat / crashes. This port instead APPENDS
    -- the enemy's weapon name to the SAME AddDebugText label the "Distance+ Bot
    -- Tag" pass already draws, so it adds ZERO new widgets, ZERO new timers and
    -- ZERO new native render calls -- the steady-state per-tick cost is one
    -- cached table lookup per enemy.
    --
    -- All state lives on the shared _OPT scratch table so this adds ZERO locals
    -- to the enclosing __SDW_ModMain scope (which sits at its 200-local ceiling).
    -- ======================================================================
    _OPT.WepNameById = _OPT.WepNameById or {}                                    -- [weaponID] = name (resolved once, forever)
    _OPT.WepPawnName = _OPT.WepPawnName or setmetatable({}, { __mode = "k" })    -- [pawn] = name      (weak key -> auto-collected)
    _OPT.WepPawnTime = _OPT.WepPawnTime or setmetatable({}, { __mode = "k" })    -- [pawn] = os.clock()(weak key -> auto-collected)
    _OPT.WepTxt      = _OPT.WepTxt      or {}                                    -- [distM][name] = "12m M416"
    _OPT.WepBotTxt   = _OPT.WepBotTxt   or {}                                    -- [distM][name] = "BOT  12m M416"
    _OPT.WepOnlyTxt  = _OPT.WepOnlyTxt  or {}                                    -- [name] = "M416" (weapon-only mode)
    _OPT.WepFallback = _OPT.WepFallback or "Weapon"

    -- Resolve the enemy's equipped-weapon NAME. The name is a fixed property of the
    -- weapon DEFINE id, so it is resolved ONCE per id and memoised forever (a tiny,
    -- bounded table). Every native probe is pcall-guarded; failure degrades to "Weapon".
    function _OPT.ResolveWeaponName(pawn)
        -- [SDWxOWNER-KNOCK-CRASH FIX] A knocked pawn DROPS its weapon; GetCurrentWeapon can
        -- briefly hand back a pending-kill weapon actor whose components are already freed.
        -- Probing GetWeaponID / GetWeaponName on it is a native use-after-free. Never read the
        -- weapon of a knocked / groggy / dying pawn - fall back to the generic label instead.
        if not pawn or not SafeIsValid(pawn) then return _OPT.WepFallback end
        local _hs = pawn.HealthStatus
        if _hs == 1 or _hs == 2 or _hs == 3 or pawn.bIsDead == true or pawn.bDead == true
            or pawn.bIsGroggy == true or pawn.bIsGrogggy == true or pawn.bIsKnocked == true
            or pawn.bIsDying == true then return _OPT.WepFallback end
        local weapon = nil
        local okW, w = SafeMethodCall(pawn, "GetCurrentWeapon")
        if okW and w then weapon = w end
        if not weapon then
            local okP, p = pcall(function() return pawn.CurrentWeapon end)
            if okP then weapon = p end
        end
        if not SafeIsValid(weapon) then return _OPT.WepFallback end
        local wID = 0
        local okID, id = SafeMethodCall(weapon, "GetWeaponID")
        if okID and id then wID = tonumber(id) or 0 end
        if wID ~= 0 then
            local hit = _OPT.WepNameById[wID]
            if hit then return hit end
        end
        local nm = nil
        local okN, n = SafeMethodCall(weapon, "GetWeaponName")
        if okN and type(n) == "string" and n ~= "" then nm = n end
        if not nm then
            local okN2, n2 = SafeMethodCall(weapon, "GetItemName")
            if okN2 and type(n2) == "string" and n2 ~= "" then nm = n2 end
        end
        if not nm then nm = _OPT.WepFallback end
        if wID ~= 0 then _OPT.WepNameById[wID] = nm end
        return nm
    end

    -- Per-pawn weapon-name cache (1.5 s TTL) so the live weapon userdata is read at most
    -- once every ~2 ticks per enemy instead of on every tick. Weak keys -> dead pawns are
    -- collected automatically (no use-after-free risk, no manual prune needed).
    function _OPT.GetWeaponNameCached(pawn, now)
        -- [SDWxOWNER-KNOCK-CRASH FIX v2] NO FEATURE LOSS. We must not PROBE the weapon of a
        -- knocked pawn (dropped / pending-kill actor), but the player already SAW the weapon name
        -- before the knock - so we keep showing that last known name instead of "Weapon".
        local _hsK = pawn and pawn.HealthStatus
        if _hsK == 1 or _hsK == 2 or _hsK == 3
            or (pawn and (pawn.bIsGroggy == true or pawn.bIsGrogggy == true
                or pawn.bIsKnocked == true or pawn.bIsDying == true)) then
            local cached = _OPT.WepPawnName[pawn]
            if cached and cached ~= "" then return cached end
            return _OPT.WepFallback
        end
        local nm = _OPT.WepPawnName[pawn]
        local t  = _OPT.WepPawnTime[pawn]
        if nm and t and (now - t) < 1.5 then return nm end
        nm = _OPT.ResolveWeaponName(pawn)
        _OPT.WepPawnName[pawn] = nm
        _OPT.WepPawnTime[pawn] = now
        return nm
    end

    -- ======================================================================
    -- [SDWxOWNER-WEAPONICON]  Weapon Icon ESP  ("Show Weapon Icon" - 2.lua v2 tab)
    -- ----------------------------------------------------------------------
    -- Shows the enemy's equipped weapon ICON as a small image above their head.
    -- This is the ICON variant of the v2-tab feature (2.lua Esp9_Weapon), built
    -- to be HOT-DROP SAFE (no lag / no crash / no heat):
    --   * ONE pooled Image widget per enemy (reused, never churned).
    --   * WeaponID -> icon TEXTURE resolved + loaded ONCE per id, cached forever
    --     (bounded table; ~the number of weapon defs in the game).
    --   * NEW texture loads BUDGETED to 1 per tick -> a brand-new weapon can
    --     never cause a load spike on a hot drop.
    --   * Per-pawn weapon-id read cached 1.5 s (no per-tick native weapon reads).
    --   * Brush re-applied ONLY when the widget's weapon id actually changes.
    --   * Position written ONLY when it moves (like the snapline).
    --   * Weak-keyed pawn tables -> dead pawns auto-collected (no leak).
    --   * Every native call pcall-guarded; failure => icon hidden, never a crash.
    --   * All state on _OPT (ZERO new locals in __SDW_ModMain).
    --   * Reuses the existing SnaplineESP canvas + projection; NO new timer.
    -- ======================================================================
    _OPT.WIconTexById  = _OPT.WIconTexById  or {}                                  -- [wID] = texture | false
    _OPT.WIconPathById = _OPT.WIconPathById or {}                                  -- [wID] = path | false
    _OPT.WIconPawnID   = _OPT.WIconPawnID   or setmetatable({}, { __mode = "k" })  -- [pawn] = wID
    _OPT.WIconPawnT    = _OPT.WIconPawnT    or setmetatable({}, { __mode = "k" })  -- [pawn] = os.clock()
    _OPT.WIconEnt      = _OPT.WIconEnt      or setmetatable({}, { __mode = "k" })  -- [pawn] = entry
    _OPT.WIconPool     = _OPT.WIconPool     or {}                                  -- recycled widget entries
    _OPT.WIconSeen     = _OPT.WIconSeen     or {}                                  -- per-tick seen set
    _OPT.WIconGen      = _OPT.WIconGen      or -1
    _OPT.WIconLoads    = 0
    _OPT.WIconLoc      = _OPT.WIconLoc      or (FVector and FVector(0, 0, 0) or { X = 0, Y = 0, Z = 0 })
    _OPT.WIconCGame    = _OPT.WIconCGame    or nil

    -- Resolve the enemy's equipped-weapon DEFINE id (0 = unknown). Cached 1.5 s / pawn.
    function _OPT.WIconPawnWeaponID(pawn, now)
        -- [SDWxOWNER-KNOCK-CRASH FIX] Same dropped-weapon hazard as ResolveWeaponName: a knocked
        -- pawn's weapon actor may be pending-kill. Hide the icon (id 0) instead of probing it.
        if not pawn or not SafeIsValid(pawn) then return 0 end
        local _hs = pawn.HealthStatus
        if _hs == 1 or _hs == 2 or _hs == 3 or pawn.bIsDead == true or pawn.bDead == true
            or pawn.bIsGroggy == true or pawn.bIsGrogggy == true or pawn.bIsKnocked == true
            or pawn.bIsDying == true then
            -- [SDWxOWNER-KNOCK-CRASH FIX v2] NO FEATURE LOSS: keep the LAST KNOWN weapon icon
            -- visible (it was already resolved before the knock) instead of hiding it.
            local cachedID = _OPT.WIconPawnID[pawn]
            if cachedID and cachedID ~= 0 then return cachedID end
            _OPT.WIconPawnID[pawn] = 0; _OPT.WIconPawnT[pawn] = now
            return 0
        end
        local id = _OPT.WIconPawnID[pawn]
        local t  = _OPT.WIconPawnT[pawn]
        if id ~= nil and t and (now - t) < 1.5 then return id end
        id = 0
        local weapon = nil
        local okW, w = SafeMethodCall(pawn, "GetCurrentWeapon")
        if okW and w then weapon = w end
        if not weapon then
            local okP, p = pcall(function() return pawn.CurrentWeapon end)
            if okP then weapon = p end
        end
        if SafeIsValid(weapon) then
            local okID, wid = SafeMethodCall(weapon, "GetWeaponID")
            if okID and wid then id = tonumber(wid) or 0 end
            if id == 0 then
                local okI2, wid2 = SafeMethodCall(weapon, "GetItemID")
                if okI2 and wid2 then id = tonumber(wid2) or 0 end
            end
        end
        _OPT.WIconPawnID[pawn] = id
        _OPT.WIconPawnT[pawn] = now
        return id
    end

    -- Resolve the icon PATH for a weapon id (once per id, memoised). Returns path | nil.
    function _OPT.WIconResolvePath(wID)
        local cached = _OPT.WIconPathById[wID]
        if cached ~= nil then return cached or nil end
        local path = nil
        pcall(function()
            local CT = _G.CDataTable or CDataTable
            if CT and CT.GetTableData then
                local rec = CT.GetTableData("Item", wID)
                if rec and rec.KillWhiteIcon and rec.KillWhiteIcon ~= "" then path = rec.KillWhiteIcon end
            end
        end)
        if not path then
            pcall(function()
                local UIUtil = require("client.common.ui_util")
                if UIUtil and UIUtil.GetItemBigIcon then
                    local p = UIUtil.GetItemBigIcon(wID)
                    if p and p ~= "" then path = p end
                end
            end)
        end
        _OPT.WIconPathById[wID] = path or false
        return path
    end

    -- Get the icon TEXTURE for a weapon id. Loads ONCE per id (budgeted 1/tick). Returns texture | nil.
    -- [SDWxOWNER-ZEROLAG] Now ASYNC-FIRST: returns (nil, path) so the caller can hand the path to
    -- SetBrushFromPathAsync and let the engine stream it. That removes the last synchronous disk
    -- load from the hot path -- during a hot drop 6-8 enemies can carry 6-8 DIFFERENT weapons, so
    -- the old 1-sync-load-per-tick budget still meant a burst of blocking texture loads exactly
    -- when the device is already busy. The synchronous branch is kept as a FALLBACK and is only
    -- used if the async brush call is unavailable/failed (WIconAsyncOK == false) -> icons keep
    -- working on every engine build.
    function _OPT.WIconGetTexture(wID)
        local cached = _OPT.WIconTexById[wID]
        if cached ~= nil then return cached or nil end
        local path = _OPT.WIconResolvePath(wID)
        if not path then _OPT.WIconTexById[wID] = false; return nil end
        if _OPT.WIconAsyncOK ~= false then return nil, path end
        if (_OPT.WIconLoads or 0) >= 1 then return nil, path end
        _OPT.WIconLoads = (_OPT.WIconLoads or 0) + 1
        local tex = nil
        pcall(function() tex = slua.loadObject(path) end)
        if not tex then pcall(function() tex = import(path) end) end
        _OPT.WIconTexById[wID] = tex or false
        return tex, path
    end

    -- Create (or recycle) an Image widget for one enemy. Returns entry | nil.
    function _OPT.WIconNewWidget(canvas)
        local pool = _OPT.WIconPool
        local entry = nil
        for i = #pool, 1, -1 do
            local e = pool[i]
            table.remove(pool, i)
            if e and e.Widget and slua.isValid(e.Widget) then entry = e; break end
        end
        if entry then return entry end
        -- [SDWxOWNER-RUSH-FPS] Cap NEW icon widgets per tick (see the box-ESP pre-warm note).
        -- Building one Image per enemy in a single tick during a rush is a smaller version of the
        -- same UMG-creation spike; 2 per tick keeps it smooth with no visible delay.
        if (_OPT.WIconCreated or 0) >= 2 then return nil end
        _OPT.WIconCreated = (_OPT.WIconCreated or 0) + 1
        local cg = _OPT.WIconCGame
        if not cg then cg = rawget(_G, "CGame") or import("CGame"); _OPT.WIconCGame = cg end
        if not (cg and cg.NewObjectFromPath) then return nil end
        local img = nil
        pcall(function() img = cg:NewObjectFromPath("/Script/UMG.Image", canvas) end)
        if not img or not slua.isValid(img) then return nil end
        local slot = nil
        pcall(function() slot = canvas:AddChildToCanvas(img) end)
        if not slot then pcall(function() img:RemoveFromParent() end); return nil end
        pcall(function() slot:SetAutoSize(false); slot:SetZOrder(5) end)
        pcall(function() img:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end)
        return { Widget = img, Slot = slot, wID = -1, x = nil, y = nil }
    end

    -- Recycle every live entry (hide + pool). Used on toggle-off / map change.
    function _OPT.WIconClearAll()
        local ent = _OPT.WIconEnt
        if ent then
            for pawn, e in pairs(ent) do
                ent[pawn] = nil
                if e and e.Widget and slua.isValid(e.Widget) then
                    pcall(function() e.Widget:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end)
                    e.wID = -1
                    table.insert(_OPT.WIconPool, e)
                end
            end
        end
        local pool = _OPT.WIconPool
        for i = #pool, 1, -1 do
            local e = pool[i]
            if not (e and e.Widget and slua.isValid(e.Widget)) then table.remove(pool, i) end
        end
    end

    -- [SDWxOWNER-RUSH-FPS] Hoisted widget writers for the weapon ICON ESP. The old inline
    -- `pcall(function() ... end)` bodies allocated 1-4 fresh closures per icon per tick
    -- (10 Hz x N enemies) -> steady GC churn during a rush. These take their arguments
    -- directly, so the tick is allocation-free. Wrapped in a do-block so the scratch locals
    -- do NOT count against __SDW_ModMain's 200-local LuaJIT budget.
    do
    local _wiWhite = FLinearColor and FLinearColor(1, 1, 1, 1) or nil
    local _wiPosV  = FVector2D and FVector2D(0, 0) or { X = 0, Y = 0 }
    local _wiSizeV = FVector2D and FVector2D(0, 0) or { X = 0, Y = 0 }
    local function _wiApplyBrush(entry, tex) entry.Widget:SetBrushFromTexture(tex, false) end
    local function _wiApplyBrushPath(entry, path) entry.Widget:SetBrushFromPathAsync(path, false) end
    local function _wiSetWhite(entry) if _wiWhite then entry.Widget:SetColorAndOpacity(_wiWhite) end end
    local function _wiSetOpacity(entry) entry.Widget:SetRenderOpacity(1.0) end
    local function _wiShow(entry) entry.Widget:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible) end
    local function _wiHide(entry) entry.Widget:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end
    local function _wiPlace(entry, x, y, w, h)
        _wiPosV.X = x; _wiPosV.Y = y
        _wiSizeV.X = w; _wiSizeV.Y = h
        entry.Slot:SetPosition(_wiPosV)
        entry.Slot:SetSize(_wiSizeV)
    end
    function _OPT.WIconApplyStyle(entry, tex)
        pcall(_wiApplyBrush, entry, tex)
        pcall(_wiSetWhite, entry)
        pcall(_wiSetOpacity, entry)
        pcall(_wiShow, entry)
    end
    -- [SDWxOWNER-ZEROLAG] Async brush variant. Same visual result, but the texture is streamed
    -- by the engine instead of being loaded from disk ON THE GAME THREAD. If the engine build
    -- does not expose SetBrushFromPathAsync (or the call throws) we return false and the caller
    -- falls back to the old synchronous texture path, so the icon can NEVER stop working.
    function _OPT.WIconApplyStyleAsync(entry, path)
        local ok = pcall(_wiApplyBrushPath, entry, path)
        if ok then _OPT.WIconAsyncOK = true else _OPT.WIconAsyncOK = false; return false end
        pcall(_wiSetWhite, entry)
        pcall(_wiSetOpacity, entry)
        pcall(_wiShow, entry)
        return true
    end
    function _OPT.WIconPlace(entry, x, y, w, h) pcall(_wiPlace, entry, x, y, w, h) end
    function _OPT.WIconHide(entry) pcall(_wiHide, entry) end
    end

    -- Main tick (~10 Hz). Reuses the snapline canvas + projection; adds no new timer.
    function _OPT.Tick_WeaponIconESP()
        local on = (_G.SDWConfig and _G.SDWConfig.WeaponIconESPEnabled) and true or false
        if _G.SDW_FXCheck then pcall(_G.SDW_FXCheck, "weaponicon", on) end
        if not on then return end
        -- [SDWxOWNER-RUSH-FPS] reset the per-tick NEW-widget counter (see WIconNewWidget)
        _OPT.WIconCreated = 0

        -- Match-generation guard: a new match => drop all cached widgets + textures.
        local gen = _G._SDW_MatchGen or 0
        if _OPT.WIconGen ~= gen then
            _OPT.WIconClearAll()
            _OPT.WIconTexById = {}
            _OPT.WIconPathById = {}
            _OPT.WIconGen = gen
        end

        _OPT.WIconLoads = 0

        if not SnaplineESP.InitESPCanvas() then return end
        local canvas = SnaplineESP.ESPCanvas
        if not canvas or not slua.isValid(canvas) then return end
        local pc, localPawn = SnaplineESP.GetMyControllerAndPlayer()
        if not pc or not slua.isValid(pc) or not localPawn or not slua.isValid(localPawn) then return end
        SnaplineESP.UpdateCanvasTransform(pc)

        local allPawns = SnaplineESP.GetAllPawns()
        if not allPawns or #allPawns == 0 then return end

        -- [SDWxOWNER-RUSH-FPS] One camera-basis sample for every icon projection this tick.
        SnaplineESP.BeginProjectionFrame()

        local now = os.clock()
        _OPT.snapChar = localPawn; _OPT.snapLoc = nil
        pcall(_OPT.snapFetchLoc)
        local myTeamId = localPawn.TeamID or (type(localPawn.GetTeamID) == "function" and localPawn:GetTeamID())

        local seen = _OPT.WIconSeen
        for k in pairs(seen) do seen[k] = nil end

        local sz = (_G.SDWConfig and _G.SDWConfig.WeaponIconSize) or 50
        local iw = 52 * (0.6 + (sz / 100) * 0.8)
        local ih = iw * 0.5

        for _, pawn in ipairs(allPawns) do
            if pawn and slua.isValid(pawn) and pawn ~= localPawn then
                local pTeam = pawn.TeamID or (type(pawn.GetTeamID) == "function" and pawn:GetTeamID())
                if not (myTeamId and myTeamId > 0 and pTeam and pTeam > 0 and pTeam == myTeamId) then
                    local hs = pawn.HealthStatus
                    if not (hs == 2 or hs == 3) and not (pawn.bIsDead or pawn.bDead) then
                        local wID = _OPT.WIconPawnWeaponID(pawn, now)
                        if wID and wID ~= 0 then
                            -- [SDWxOWNER-ZEROLAG] async-first: (texture) or (nil, path)
                            local tex, ipath = _OPT.WIconGetTexture(wID)
                            if tex or ipath then
                                local pLoc = nil
                                _OPT.snapChar = pawn; _OPT.snapLoc = nil
                                pcall(_OPT.snapFetchLoc)
                                pLoc = _OPT.snapLoc
                                if pLoc then
                                    local headLoc = SnaplineESP.GetHeadLoc(pawn, pLoc)
                                    local L = _OPT.WIconLoc
                                    L.X = headLoc.X; L.Y = headLoc.Y; L.Z = headLoc.Z + 10
                                    local bOK, CanvasPos = SnaplineESP.ProjectWorldToCanvasLocalChecked(pc, L)
                                    if bOK and CanvasPos then
                                        local entry = _OPT.WIconEnt[pawn]
                                        if not entry then
                                            entry = _OPT.WIconNewWidget(canvas)
                                            if entry then _OPT.WIconEnt[pawn] = entry end
                                        end
                                        if entry then
                                            seen[pawn] = true
                                            if entry.wID ~= wID then
                                                entry.wID = wID
                                                local applied = false
                                                if tex then
                                                    _OPT.WIconApplyStyle(entry, tex)
                                                    applied = true
                                                end
                                                if not applied and ipath then
                                                    applied = _OPT.WIconApplyStyleAsync(entry, ipath)
                                                    if not applied then
                                                        -- async brush unavailable -> drop the cached
                                                        -- path and let the sync fallback load it.
                                                        _OPT.WIconTexById[wID] = nil
                                                        entry.wID = -1
                                                    end
                                                end
                                            end
                                            local x = CanvasPos.X - iw * 0.5
                                            local y = CanvasPos.Y - ih - 6
                                            if entry.x == nil or math.abs(entry.x - x) > 0.5 or math.abs(entry.y - y) > 0.5 then
                                                entry.x = x; entry.y = y
                                                _OPT.WIconPlace(entry, x, y, iw, ih)
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end

        -- Recycle entries whose pawn is no longer visible.
        for pawn, entry in pairs(_OPT.WIconEnt) do
            if not seen[pawn] then
                _OPT.WIconEnt[pawn] = nil
                if entry and entry.Widget and slua.isValid(entry.Widget) then
                    _OPT.WIconHide(entry)
                    entry.wID = -1
                    table.insert(_OPT.WIconPool, entry)
                end
            end
        end
    end

    -- ==========================================================================
    -- [SDWxOWNER] SDWxOWNER Box ESP  -  corner-bracket design
    -- --------------------------------------------------------------------------
    -- Design ported from the reference ESP: corner brackets + a left health bar
    -- + weapon / name / distance / state labels + a nation flag. The POSITIONING
    -- uses the SDWxOWNER FROZEN engine so the boxes NEVER jitter / drift:
    --     * slot geometry is written ONLY when it changes by more than 0.1 px
    --     * corner brackets refresh ONLY when the box changes by more than 0.6 px
    --     * [SDWxOWNER-NOVIB] the health bar + every label are anchored to the size the
    --       OUTLINE actually applied (read back after _corners) -> the whole assembly
    --       (outline + health bar + labels) is ONE rigid unit: no relative vibration.
    --     * a 0.30 s off-screen grace window (a 1-frame miss never blinks a box)
    --     * per-enemy widget pooling + stable keys (no ghosts, no leaks)
    --     * cached head offsets (no per-frame native socket reads)
    --     * a match-generation guard (a new match drops every old box)
    -- Reuses the proven SnaplineESP canvas / transform / projection / roster /
    -- LOS helpers and the shared 10 Hz driver. Adds NO new timer.
    -- Branding: SDWxOWNER
    --
    -- NOTE: wrapped in a builder function so the module's ~20 helpers do NOT
    -- count against __SDW_ModMain's 200-local LuaJIT budget (only 1 local here).
    -- ==========================================================================
    do
    local function _SDW_BuildBoxESP()
        local B = {}
        _G.SDW_BoxESP = B

        B.gen           = -1
        B.canvas        = nil
        B.boxes         = {}          -- key -> boxData (live)
        B.pool          = {}          -- recycled boxData
        B.seen          = {}          -- per-tick seen-key set
        B.camYaw, B.camPitch = nil, nil
        B.camX, B.camY, B.camZ = nil, nil, nil
        B.count         = 0

        -- design constants (reference ESP)
        B.cornerThickness   = 1.0
        B.cornerLengthRatio = 0.28
        B.healthBarWidth    = 2.0
        B.maxDistSq         = 900000000      -- 30000 u = 300 m
        B.flagLoadBudget    = 1              -- new nation textures loaded per tick
        -- [SDWxOWNER-RUSH-FPS] Rush-safety limits for the BOX ESP widget pool.
        -- ROOT CAUSE of the "2-3 squads rush -> FPS 20-30 -> crash" report: every box is
        -- 16 UMG widgets (1 CanvasPanel + 8 corner Borders + 2 Images + 4 TextBlocks + 1 flag
        -- Image) and each one costs a native NewObjectFromPath + AddChildToCanvas (which
        -- invalidates Slate layout for the WHOLE canvas). The pool started EMPTY, so the
        -- instant 8-10 enemies rushed into range the 10 Hz scan built ALL of them in ONE tick:
        -- ~160 UMG objects + ~160 canvas insertions + ~1,300 Lua closures in a single frame.
        -- That single-frame spike is the FPS 60 -> 20-30 drop, and on a phone the UMG object
        -- storm + Slate re-layout is what then OOMs / crashes.
        -- Fix (NO feature change, NO added delay): the pool is PRE-WARMED while nothing is on
        -- screen (1 box per scan tick, i.e. 100 ms apart) and creation is hard-capped per tick,
        -- so a rush never allocates widgets. Every enemy still gets its box - the pre-warmed
        -- pool already holds them.
        B.maxBoxes          = 40             -- absolute ceiling (memory guard)
        B.warmTarget        = 18             -- boxes kept ready in the pool
        B.createPerTick     = 2              -- max NEW boxes built in one scan tick
        B.liveBoxes         = 0              -- boxes currently owned (live + pooled)
        B.createdThisTick   = 0              -- NEW boxes built in the current scan tick

        local FC = FLinearColor
        B.healthColor   = FC and FC(0.0, 1.0, 0.0, 1.0)    or { R = 0.0, G = 1.0, B = 0.0, A = 1.0 }
        B.healthBgColor = FC and FC(0.0, 0.0, 0.0, 0.85)   or { R = 0.0, G = 0.0, B = 0.0, A = 0.85 }
        B.cornerColor   = FC and FC(1.0, 1.0, 1.0, 1.0)    or { R = 1.0, G = 1.0, B = 1.0, A = 1.0 }
        B.textWeapon    = FC and FC(1.0, 0.95, 0.0, 1.0)   or { R = 1.0, G = 0.95, B = 0.0, A = 1.0 }
        B.textName      = FC and FC(0.18, 0.62, 1.0, 1.0)  or { R = 0.18, G = 0.62, B = 1.0, A = 1.0 }
        B.textDist      = FC and FC(1.0, 1.0, 1.0, 1.0)    or { R = 1.0, G = 1.0, B = 1.0, A = 1.0 }
        B.textOpen      = FC and FC(0.0, 1.0, 0.05, 1.0)   or { R = 0.0, G = 1.0, B = 0.05, A = 1.0 }
        B.textCover     = FC and FC(1.0, 0.15, 0.15, 1.0)  or { R = 1.0, G = 0.15, B = 0.15, A = 1.0 }

        local FSlateColor = import("SlateColor") or import("/Script/SlateCore.SlateColor") or _G.FSlateColor
        local _SELFHIT   = UEnums and UEnums.ESlateVisibility and UEnums.ESlateVisibility.SelfHitTestInvisible
        local _COLLAPSED = UEnums and UEnums.ESlateVisibility and UEnums.ESlateVisibility.Collapsed

        B.flagTexByNation  = {}
        B.flagPathByNation = {}

        local function _newObj(path, parent)
            local cg = rawget(_G, "CGame") or CGame or import("CGame")
            if not (cg and cg.NewObjectFromPath) then return nil end
            local o = nil
            pcall(function() o = cg:NewObjectFromPath(path, parent) end)
            if o and slua.isValid(o) then return o end
            return nil
        end

        -- A 1x1 white texture so the health-bar Images always render (a bare UImage
        -- with no brush resource draws nothing). Loaded ONCE, then cached.
        B._whiteTex = nil
        local function _whiteTexture()
            if B._whiteTex ~= nil then return B._whiteTex or nil end
            local t = nil
            pcall(function() t = slua.loadObject("/Engine/EngineResources/WhiteSquareTexture.WhiteSquareTexture") end)
            if not t then pcall(function() t = slua.loadObject("/Engine/EngineResources/White.White") end) end
            if not t then pcall(function() t = slua.loadObject("/Engine/EngineResources/DefaultTexture.DefaultTexture") end) end
            B._whiteTex = t or false
            return t
        end

        local function _newBorder(parent)
            local b = _newObj("/Script/UMG.Border", parent)
            if not b then return nil end
            pcall(function() b:SetBrushColor(B.cornerColor) end)
            pcall(function() b:SetWidgetVisibility(_SELFHIT) end)
            local s = nil
            pcall(function() s = parent:AddChildToCanvas(b) end)
            if not s then pcall(function() b:RemoveFromParent() end); return nil end
            pcall(function() s:SetAutoSize(false) end)
            return { widget = b, slot = s }
        end

        local function _newText(parent, color, fontSize, alignY)
            local t = _newObj("/Script/UMG.TextBlock", parent)
            if not t then return nil, nil end
            pcall(function() t:SetText("") end)
            pcall(function() t:SetJustification(1) end)
            pcall(function() t:SetAutoWrapText(false) end)
            local sz = math.floor(fontSize or 10)
            pcall(function()
                if t.Font then
                    local f = t.Font
                    f.Size = sz
                    if f.OutlineSettings then
                        f.OutlineSettings.OutlineSize = 1
                        f.OutlineSettings.OutlineColor = FC and FC(0, 0, 0, 1) or { R = 0, G = 0, B = 0, A = 1 }
                    end
                    t.Font = f
                end
            end)
            pcall(function() if t.SetFontSize then t:SetFontSize(sz) end end)
            pcall(function()
                if FSlateColor then t:SetColorAndOpacity(FSlateColor(color)) else t:SetColorAndOpacity(color) end
            end)
            pcall(function() t:SetWidgetVisibility(_SELFHIT) end)
            local s = nil
            pcall(function() s = parent:AddChildToCanvas(t) end)
            if not s then pcall(function() t:RemoveFromParent() end); return nil, nil end
            pcall(function() s:SetAutoSize(true); s:SetZOrder(1000); s:SetAlignment(FVector2D(0.5, alignY or 0.0)) end)
            return t, s
        end

        -- [SDWxOWNER-ZEROLAG-2] Forward declaration: _createBox (below) probes the engine's
        -- SetOffsets support on a real slot, so the probe must be visible before it is defined.
        local _probeOffsets

        local function _createBox(parent)
            local container = _newObj("/Script/UMG.CanvasPanel", parent)
            if not container then return nil end
            local cslot = nil
            pcall(function() cslot = parent:AddChildToCanvas(container) end)
            if not cslot then pcall(function() container:RemoveFromParent() end); return nil end
            pcall(function() cslot:SetAutoSize(false); cslot:SetZOrder(995); cslot:SetAlignment(FVector2D(0.5, 0.5)) end)
            -- [SDWxOWNER-ZEROLAG-2] One-time capability probe on a REAL canvas slot: if the engine
            -- build round-trips SetOffsets we switch every geometry write to the single-call path.
            pcall(_probeOffsets, cslot)

            local C = {
                TLH = _newBorder(container), TLV = _newBorder(container),
                TRH = _newBorder(container), TRV = _newBorder(container),
                BLH = _newBorder(container), BLV = _newBorder(container),
                BRH = _newBorder(container), BRV = _newBorder(container),
            }

            local wt = _whiteTexture()
            local bg, bgSlot = _newObj("/Script/UMG.Image", parent), nil
            if bg then
                if wt then pcall(function() bg:SetBrushFromTexture(wt, false) end) end
                pcall(function() bg:SetColorAndOpacity(B.healthBgColor) end)
                pcall(function() bg:SetWidgetVisibility(_SELFHIT) end)
                pcall(function() bgSlot = parent:AddChildToCanvas(bg) end)
                if bgSlot then pcall(function() bgSlot:SetAutoSize(false); bgSlot:SetZOrder(998); bgSlot:SetAlignment(FVector2D(0.5, 1.0)) end) end
            end
            local hp, hpSlot = _newObj("/Script/UMG.Image", parent), nil
            if hp then
                if wt then pcall(function() hp:SetBrushFromTexture(wt, false) end) end
                pcall(function() hp:SetColorAndOpacity(B.healthColor) end)
                pcall(function() hp:SetWidgetVisibility(_SELFHIT) end)
                pcall(function() hpSlot = parent:AddChildToCanvas(hp) end)
                if hpSlot then pcall(function() hpSlot:SetAutoSize(false); hpSlot:SetZOrder(999); hpSlot:SetAlignment(FVector2D(0.5, 1.0)) end) end
            end

            local weapon, weaponSlot = _newText(parent, B.textWeapon, 10, 1.0)
            local name, nameSlot     = _newText(parent, B.textName, 10, 0.0)
            local dist, distSlot     = _newText(parent, B.textDist, 10, 0.0)
            local state, stateSlot   = _newText(parent, B.textOpen, 10, 0.0)

            local flag, flagSlot = _newObj("/Script/UMG.Image", parent), nil
            if flag then
                pcall(function() flag:SetWidgetVisibility(_SELFHIT) end)
                pcall(function() flagSlot = parent:AddChildToCanvas(flag) end)
                if flagSlot then pcall(function() flagSlot:SetAutoSize(false); flagSlot:SetSize(FVector2D(14, 16)); flagSlot:SetZOrder(1000); flagSlot:SetAlignment(FVector2D(0.5, 1.0)) end) end
            end

            return {
                container = container, cslot = cslot, C = C,
                bg = bg, bgSlot = bgSlot, hp = hp, hpSlot = hpSlot,
                weapon = weapon, weaponSlot = weaponSlot,
                name = name, nameSlot = nameSlot,
                dist = dist, distSlot = distSlot,
                state = state, stateSlot = stateSlot,
                flag = flag, flagSlot = flagSlot,
                lastW = 0, lastH = 0,
                lastCX = nil, lastCY = nil,
                lastHpX = nil, lastHpY = nil, lastHpH = nil, lastHpFill = nil,
                lastWepY = nil, lastFlagY = nil, lastNameY = nil, lastDistY = nil, lastStateY = nil,
                cWeapon = "", cName = "", cDist = "", cState = "", cNation = nil,
                lastOnScreen = 0, visState = 1,
            }
        end

        -- [SDWxOWNER-BOXPERF] Closure-free slot writers for the hot per-frame path.
        -- The old code wrapped EVERY widget write in `pcall(function() ... end)`, which
        -- allocated a brand-new closure (and its upvalues) for EVERY widget of EVERY box on
        -- EVERY frame -> constant GC churn = the "lag". These hoisted functions take their
        -- arguments directly, so the per-frame path allocates NOTHING (same pcalls, no garbage).
        -- [SDWxOWNER-RUSH-FPS] Reusable scratch vectors. The old writers built a brand-new
        -- FVector2D userdata for EVERY widget write (position + size), i.e. up to ~20 fresh
        -- GC objects per box per frame -> ~12,000/s during a 10-enemy rush. SetPosition /
        -- SetSize copy the value, so one scratch pair can be mutated and reused safely.
        local _boxPosV  = FVector2D and FVector2D(0, 0) or { X = 0, Y = 0 }
        local _boxSizeV = FVector2D and FVector2D(0, 0) or { X = 0, Y = 0 }
        -- [SDWxOWNER-ZEROLAG-2] ONE-CALL geometry writes.
        -- UCanvasPanelSlot::SetPosition writes Offsets.Left/Top and SetSize writes
        -- Offsets.Right/Bottom, so SetPosition(p) + SetSize(s) is EXACTLY
        -- SetOffsets(FMargin(p.x, p.y, p.x + s.x, p.y + s.y)) -- one native call instead of two,
        -- and (critically) ONE Slate layout invalidation instead of two. With 8 corner brackets +
        -- the container + the health bar that is 21 native calls -> 12 per box per frame, i.e. the
        -- layout thrash that makes a 40-50 player hot drop crawl is cut by ~43%. The FMargin is a
        -- single reusable scratch struct (mutated in place, like the FVector2D pair) so this adds
        -- ZERO garbage. A one-time runtime probe (see _probeOffsets) verifies the engine build
        -- really round-trips SetOffsets before it is used; if anything is off we transparently
        -- keep the old two-call path, so the box can never break.
        local _boxMarginV = nil
        local _boxUseOffsets = false
        local _boxOffMode = 0        -- 0 = off, 1 = Right/Bottom are EDGES, 2 = Right/Bottom are W/H
        -- [SDWxOWNER-FLICKERFIX] DEFAULT OFF. SetPosition + SetSize is the exact path the box was
        -- tuned against; SetOffsets is only a micro-optimisation, and a wrong convention guess
        -- shows up as a visible jump / flicker. Correctness first: keep the two-call path.
        -- (Flip to true only if you want to A/B test the single-call path in-game.)
        local _BOX_OFFSETS_ENABLED = false
        function _probeOffsets(slot)
            if _boxUseOffsets then return true end
            if not _BOX_OFFSETS_ENABLED then return false end
            if not (slot and slot.SetOffsets and slot.GetPosition and slot.GetSize) then return false end
            local m = nil
            local okM, mm = pcall(Margin, 11, 13, 51, 33)   -- x=11 y=13 w=40 h=20
            if okM then m = mm end
            if not m then return false end
            local okSet = pcall(function() slot:SetOffsets(m) end)
            if not okSet then return false end
            local p = nil
            local s = nil
            pcall(function() p = slot:GetPosition() end)
            pcall(function() s = slot:GetSize() end)
            if not (p and s) then return false end
            if math.abs(p.X - 11) > 0.5 or math.abs(p.Y - 13) > 0.5 then return false end
            -- [SDWxOWNER-FLICKERFIX] Detect the FMargin convention instead of assuming one.
            -- UE4/UMG GetSize() returns (Offsets.Right, Offsets.Bottom) and in the canvas-slot
            -- layout those two are the WIDTH/HEIGHT, not the right/bottom edges. Some builds
            -- however treat them as edges. Probe both and remember which one this build uses.
            if math.abs(s.X - 40) <= 0.5 and math.abs(s.Y - 20) <= 0.5 then
                _boxOffMode = 1     -- Right/Bottom are edges  -> Right = x + w
            elseif math.abs(s.X - 51) <= 0.5 and math.abs(s.Y - 33) <= 0.5 then
                _boxOffMode = 2     -- Right/Bottom are W/H    -> Right = w
            else
                return false        -- unknown semantics: stay on the safe two-call path
            end
            -- Mutation must stick on the scratch struct (struct marshalled by value).
            local okMut = pcall(function() m.Left = 1; m.Top = 2; m.Right = 3; m.Bottom = 4 end)
            if not (okMut and m.Left == 1 and m.Right == 3) then return false end
            _boxMarginV = m
            _boxUseOffsets = true
            return true
        end
        local function _boxSetPos(slot, x, y)
            _boxPosV.X = x; _boxPosV.Y = y; slot:SetPosition(_boxPosV)
        end
        local function _boxSetPosSize(slot, x, y, w, h)
            if _boxUseOffsets then
                local m = _boxMarginV
                m.Left = x; m.Top = y
                if _boxOffMode == 1 then
                    m.Right = x + w; m.Bottom = y + h
                else
                    m.Right = w; m.Bottom = h
                end
                slot:SetOffsets(m)
                return
            end
            _boxPosV.X = x; _boxPosV.Y = y; slot:SetPosition(_boxPosV)
            _boxSizeV.X = w; _boxSizeV.Y = h; slot:SetSize(_boxSizeV)
        end
        -- [SDWxOWNER-FLICKERFIX] SIZE-ONLY writer. This is CRITICAL and must never be replaced
        -- by _boxSetPosSize: the box CONTAINER's position is owned by _placeBox (it writes
        -- cx/cy with _boxSetPos only when the box actually moved >0.25 px). SetOffsets writes
        -- Left/Top as well, so using _boxSetPosSize(container, 0, 0, w, h) RESET the container
        -- to the top-left corner on every frame in which the size changed -> the box visibly
        -- jumped / flickered. SetSize writes ONLY Offsets.Right/Bottom, leaving the position
        -- untouched, which is exactly what the original code did. One native call, same as before.
        local function _boxSetSize(slot, w, h)
            _boxSizeV.X = w; _boxSizeV.Y = h; slot:SetSize(_boxSizeV)
        end
        local function _boxSetBar(bgSlot, hpSlot, hbW, barH, hpFill, hbX, botEdge)
            -- [SDWxOWNER-ZEROLAG-2] 4 native calls -> 2 (one SetOffsets per widget).
            _boxSetPosSize(bgSlot, hbX, botEdge, hbW, barH)
            _boxSetPosSize(hpSlot, hbX, botEdge, hbW, hpFill)
        end
        -- [SDWxOWNER-ZEROLAG] ONE-call corner writer. The 8 corner brackets + the container used
        -- to cost NINE separate pcall() invocations per box per frame (9 x ~10 enemies x ~62 fps
        -- = ~5,600 pcall dispatches/second just for corners). They are now applied inside a single
        -- hoisted function driven by ONE pcall -> same writes, same order, same result, ~9x fewer
        -- pcall dispatches on the hot path. Zero allocation (scratch vectors reused).
        local function _boxCornersApply(box, w, h, cLen, t)
            -- [SDWxOWNER-ZEROLAG-2] Every write now goes through _boxSetPosSize, which is ONE
            -- native SetOffsets call (instead of SetPosition + SetSize) when the engine build
            -- supports it -> 9 native calls instead of 17, and 9 layout invalidations instead
            -- of 17. Visually byte-for-byte identical (same x/y/w/h values).
            -- [SDWxOWNER-FLICKERFIX] Container: SIZE ONLY. Its position belongs to _placeBox;
            -- writing it here (as SetOffsets would) snapped the box to the top-left corner on
            -- every size change = the reported flicker.
            _boxSetSize(box.cslot, w, h)
            local C = box.C
            local TLH, TLV = C.TLH, C.TLV
            local TRH, TRV = C.TRH, C.TRV
            local BLH, BLV = C.BLH, C.BLV
            local BRH, BRV = C.BRH, C.BRV
            if TLH and TLH.slot then _boxSetPosSize(TLH.slot, 0, 0, cLen, t) end
            if TLV and TLV.slot then _boxSetPosSize(TLV.slot, 0, 0, t, cLen) end
            if TRH and TRH.slot then _boxSetPosSize(TRH.slot, w - cLen, 0, cLen, t) end
            if TRV and TRV.slot then _boxSetPosSize(TRV.slot, w - t, 0, t, cLen) end
            if BLH and BLH.slot then _boxSetPosSize(BLH.slot, 0, h - t, cLen, t) end
            if BLV and BLV.slot then _boxSetPosSize(BLV.slot, 0, h - cLen, t, cLen) end
            if BRH and BRH.slot then _boxSetPosSize(BRH.slot, w - cLen, h - t, cLen, t) end
            if BRV and BRV.slot then _boxSetPosSize(BRV.slot, w - t, h - cLen, t, cLen) end
        end
        -- [SDWxOWNER-ZEROLAG] ONE-call label anchor writer (weapon / flag / name / distance /
        -- state). Was FIVE pcall() dispatches per box per frame -> now one. `doX` flags keep the
        -- exact same dead-band behaviour: a label is only moved when its own anchor changed (or
        -- the whole box moved), so nothing is written that the old code would not have written.
        local function _boxAnchorLabels(box, aCX, wepY, flagY, nameY, distY, stateY,
                                        doWep, doFlag, doName, doDist, doState)
            local s
            if doWep and box.weaponSlot then s = box.weaponSlot; _boxPosV.X = aCX; _boxPosV.Y = wepY; s:SetPosition(_boxPosV) end
            if doFlag and box.flagSlot then s = box.flagSlot; _boxPosV.X = aCX; _boxPosV.Y = flagY; s:SetPosition(_boxPosV) end
            if doName and box.nameSlot then s = box.nameSlot; _boxPosV.X = aCX; _boxPosV.Y = nameY; s:SetPosition(_boxPosV) end
            if doDist and box.distSlot then s = box.distSlot; _boxPosV.X = aCX; _boxPosV.Y = distY; s:SetPosition(_boxPosV) end
            if doState and box.stateSlot then s = box.stateSlot; _boxPosV.X = aCX; _boxPosV.Y = stateY; s:SetPosition(_boxPosV) end
        end
        -- [SDWxOWNER-BOXPERF] Closure-free writers for the 10 Hz scan path (label text, the
        -- state label's colour, and the per-pawn world location). The old code wrapped each of
        -- these in `pcall(function() ... end)`, allocating a fresh closure for EVERY enemy on
        -- EVERY scan -> needless GC churn. These take their arguments directly -> zero garbage.
        local function _boxSetText(tb, s) tb:SetText(s) end
        local function _boxSetStateColor(tb, col)
            if FSlateColor then tb:SetColorAndOpacity(FSlateColor(col)) else tb:SetColorAndOpacity(col) end
        end
        local function _boxGetLoc(pawn) return pawn:K2_GetActorLocation() end

        local function _corners(box, w, h)
            -- [SDWxOWNER-NOVIB] Dead-band lowered 1.5 px -> 0.6 px so the SHARED size (which the
            -- health bar + every label now read back) stays visually continuous. Only writes the
            -- 8 tiny corner widgets, and only when the size actually changed -> negligible cost.
            if math.abs(w - box.lastW) < 0.6 and math.abs(h - box.lastH) < 0.6 then return end
            box.lastW, box.lastH = w, h
            local t = B.cornerThickness
            local cLen = math.max(7, math.min(w, h) * B.cornerLengthRatio)
            local C = box.C
            -- [SDWxOWNER-ZEROLAG] All 9 corner/container writes now go through ONE hoisted
            -- function under ONE pcall (was 9 separate pcall dispatches per box per frame).
            pcall(_boxCornersApply, box, w, h, cLen, t)
        end

        -- [SDWxOWNER-RUSH-FPS] Hoisted single-widget visibility writer. The old _setVis wrapped
        -- EACH of the 8 widgets in its own `pcall(function() ... end)` -> 8 fresh closures (and
        -- their upvalues) allocated on EVERY show/hide, i.e. on every enemy entering/leaving
        -- range during a rush. This takes its arguments directly -> zero allocation.
        local function _visOne(w, vis)
            if w then w:SetWidgetVisibility(vis) end
        end

        -- [SDWxOWNER-BOXPARTS] Per-part visibility. Every SDWxOWNER Box element now has its
        -- OWN toggle (Frame / Health / Name / Distance / Weapon / Flag / State). Defaults are
        -- true, so nothing changes visually until the user turns a part off. One extra table
        -- read per part per show/hide only (NOT per frame) -> zero hot-path cost.
        local function _partOn(key)
            local c = _G.SDWConfig
            if not c then return true end
            return c[key] ~= false
        end
        local function _setVis(box, vis)
            local show = (vis ~= _COLLAPSED)
            local onHealth = show and _partOn("SDWBox_Health")
            pcall(_visOne, box.container, vis)
            pcall(_visOne, box.bg,     onHealth and _SELFHIT or _COLLAPSED)
            pcall(_visOne, box.hp,     onHealth and _SELFHIT or _COLLAPSED)
            pcall(_visOne, box.weapon, (show and _partOn("SDWBox_Weapon")) and _SELFHIT or _COLLAPSED)
            pcall(_visOne, box.flag,   (show and _partOn("SDWBox_Flag"))   and _SELFHIT or _COLLAPSED)
            pcall(_visOne, box.name,   (show and _partOn("SDWBox_Name"))   and _SELFHIT or _COLLAPSED)
            pcall(_visOne, box.dist,   (show and _partOn("SDWBox_Dist"))   and _SELFHIT or _COLLAPSED)
            pcall(_visOne, box.state,  (show and _partOn("SDWBox_State"))  and _SELFHIT or _COLLAPSED)
            if box.C then
                local fv = (show and _partOn("SDWBox_Frame")) and _SELFHIT or _COLLAPSED
                for _, c in pairs(box.C) do
                    if c and c.widget then pcall(_visOne, c.widget, fv) end
                end
            end
        end
        B.ApplyVis = _setVis
        -- Live re-apply (called from the menu when a part toggle is flipped) - no rebuild needed.
        function B.RefreshParts()
            for _, box in pairs(B.boxes) do
                if box and box.visState == 1 then pcall(_setVis, box, _SELFHIT) end
            end
        end

        local function _show(box)
            if box.visState == 1 then return end
            box.visState = 1
            box.lastW, box.lastH = 0, 0
            box.lastCX, box.lastCY = nil, nil
            box.lastHpX, box.lastHpY, box.lastHpH, box.lastHpFill = nil, nil, nil, nil
            box.lastWepY, box.lastFlagY, box.lastNameY, box.lastDistY, box.lastStateY = nil, nil, nil, nil, nil
            _setVis(box, _SELFHIT)
        end

        local function _hide(box)
            if box.visState == 0 then return end
            box.visState = 0
            _setVis(box, _COLLAPSED)
        end

        local function _killWidget(w)
            if w and slua.isValid(w) then
                pcall(function() w:SetWidgetVisibility(_COLLAPSED) end)
                pcall(function() if w.RemoveFromParent then w:RemoveFromParent() end end)
            end
        end

        local function _destroyBox(box)
            if not box then return end
            B.liveBoxes = math.max(0, (B.liveBoxes or 0) - 1)
            _killWidget(box.container)
            if box.C then
                for _, c in pairs(box.C) do if c then _killWidget(c.widget) end end
            end
            _killWidget(box.bg); _killWidget(box.hp); _killWidget(box.weapon); _killWidget(box.flag)
            _killWidget(box.name); _killWidget(box.dist); _killWidget(box.state)
        end

        local function _recycle(box)
            if not box then return end
            _setVis(box, _COLLAPSED)
            box.visState = 0
            box.lastCX, box.lastCY = nil, nil
            box.lastW, box.lastH = 0, 0
            box.lastHpX, box.lastHpY, box.lastHpH, box.lastHpFill = nil, nil, nil, nil
            box.lastWepY, box.lastFlagY, box.lastNameY, box.lastDistY, box.lastStateY = nil, nil, nil, nil, nil
            box.cWeapon, box.cName, box.cDist, box.cState, box.cNation = "", "", "", "", nil
            B.pool[#B.pool + 1] = box
        end

        local function _obtain(parent)
            local pool = B.pool
            for i = #pool, 1, -1 do
                local box = pool[i]
                table.remove(pool, i)
                if box and box.container and slua.isValid(box.container) then return box end
            end
            -- [SDWxOWNER-RUSH-FPS] Pool exhausted. Build at most B.createPerTick NEW boxes in this
            -- scan tick and never exceed B.maxBoxes. Building 10 boxes (160 UMG widgets) in one
            -- frame was the rush freeze/crash; a pre-warmed pool means this branch is normally
            -- never reached, and if it is, the ramp is smooth (<=2 boxes / 100 ms) instead of a
            -- single-frame spike. NO feature loss: the box still appears, at worst one tick later.
            if (B.createdThisTick or 0) >= B.createPerTick then return nil end
            if (B.liveBoxes or 0) >= B.maxBoxes then return nil end
            B.createdThisTick = (B.createdThisTick or 0) + 1
            B.liveBoxes = (B.liveBoxes or 0) + 1
            return _createBox(parent)
        end

        -- [SDWxOWNER-RUSH-FPS] Idle pre-warm: build ONE pooled box per scan tick while the screen
        -- is (nearly) empty, so a rush never has to allocate UMG widgets. Runs only when <=2
        -- enemies are on screen, so it can never compete with live boxes for frame time. A pooled
        -- box is created fully collapsed -> it costs nothing to keep around.
        local function _prewarm()
            if #B.pool >= B.warmTarget then return end
            if (B.liveBoxes or 0) >= B.maxBoxes then return end
            if not (B.canvas and slua.isValid(B.canvas)) then return end
            local box = _createBox(B.canvas)
            if not box then return end
            B.liveBoxes = (B.liveBoxes or 0) + 1
            _setVis(box, _COLLAPSED)
            box.visState = 0
            B.pool[#B.pool + 1] = box
        end

        function B.ClearAll()
            for _, box in pairs(B.boxes) do
                _destroyBox(box)
            end
            B.boxes = {}
            for i = #B.pool, 1, -1 do
                _destroyBox(B.pool[i])
                B.pool[i] = nil
            end
            B.pool = {}
            for k in pairs(B.seen) do B.seen[k] = nil end
            B.count = 0
            B.liveBoxes = 0
            B.createdThisTick = 0
        end

        function B.HardClear()
            B.ClearAll()
            B.canvas = nil
            B.gen = -1
            B.camYaw, B.camPitch = nil, nil
            B.camX, B.camY, B.camZ = nil, nil, nil
            B.flagTexByNation = {}
            B.flagPathByNation = {}
            B._whiteTex = nil
        end

        local _botLoc = nil

        local function _setFlag(box, pawn, budget)
            -- [SDWxOWNER-RUSH-CRASH FIX] `pawn.PlayerState` is a live UObject pointer. On a
            -- pawn that just died / left, the PlayerState can already be freed while the pawn
            -- itself still passes slua.isValid() -> reading `.Nation` off it is a native
            -- use-after-free (Lua pcall CANNOT catch that: it is a segfault, not a Lua error).
            -- One validity probe here is free because this whole function early-returns the
            -- moment the nation string is unchanged (i.e. it only runs on a real change).
            local ps = pawn.PlayerState
            if ps ~= nil and not slua.isValid(ps) then ps = nil end
            local nation = (ps and ps.Nation) or pawn.Nation or ""
            nation = tostring(nation or "")
            if nation == "" or nation == "nil" or nation == "0" then nation = "G1" end
            if box.cNation == nation then return end
            box.cNation = nation
            if not (box.flag and slua.isValid(box.flag)) then return end
            local tex = B.flagTexByNation[nation]
            if tex == nil then
                local path = B.flagPathByNation[nation]
                if path == nil then
                    local CT = _G.CDataTable or CDataTable
                    local cfg = (CT and CT.GetTableData) and CT.GetTableData("RegionConfig", nation)
                    if not cfg or not cfg.res_path or cfg.res_path == "" then
                        cfg = (CT and CT.GetTableData) and CT.GetTableData("RegionConfig", "G1")
                    end
                    path = (cfg and cfg.res_path) or "/Game/UMG/Texture/Atlas/NationalflagUI/Frames/T_icon_flag_iland_png.T_icon_flag_iland_png"
                    B.flagPathByNation[nation] = path
                end
                if budget[1] > 0 then
                    budget[1] = budget[1] - 1
                    local t = nil
                    pcall(function() t = slua.loadObject(path) end)
                    if not t then pcall(function() t = import(path) end) end
                    tex = t or false
                    B.flagTexByNation[nation] = tex
                end
            end
            if tex then
                pcall(function() box.flag:SetBrushFromTexture(tex, false) end)
                pcall(function() box.flag:SetColorAndOpacity(FC and FC(1, 1, 1, 1) or { R = 1, G = 1, B = 1, A = 1 }) end)
            else
                -- [SDWxOWNER-RUSH-FPS] NEVER call SetBrushResourceFromPathSync here. That API
                -- loads the texture from disk ON THE GAME THREAD (100-300 ms per new nation).
                -- During a rush 5+ new nations appear at once -> several multi-hundred-ms
                -- hitches back to back -> the FPS 20-30 drop that precedes the crash. Async only:
                -- the flag pops in a frame or two later, visually identical to before.
                pcall(function()
                    if box.flag.SetBrushFromPathAsync then
                        box.flag:SetBrushFromPathAsync(B.flagPathByNation[nation], false)
                    end
                end)
            end
        end

        -- [SDWxOWNER-BOXSMOOTH] Project + place ONE box's geometry: the container position,
        -- the corner brackets, the left health bar and EVERY label anchor (weapon / flag /
        -- name / distance / state). Called by BOTH the 10 Hz scan AND the per-frame fast tick
        -- (B.FastTick) so the box tracks the enemy at the FRAME RATE -> it stays locked on the
        -- enemy while the camera / gyro moves (no drift, no jitter), exactly like the game's
        -- native ESP box. The heavy work (roster, LOS raycast, weapon / flag / name text) is
        -- NOT here: it stays in the 10 Hz scan, so the per-frame path is cheap.
        -- [SDWxOWNER-BOXSMOOTH] Hoisted per-pawn location fetch for the per-frame fast tick
        -- (runs up to ~60x/s per enemy) -> no closure allocation inside the hot path.
        local _placePawn, _placeLoc = nil, nil
        local function _placeFetchLoc() _placeLoc = _placePawn:K2_GetActorLocation() end
        local function _placeBox(box, pawn, pc, now, pLoc)
            if not pLoc then
                _placePawn = pawn; _placeLoc = nil
                pcall(_placeFetchLoc)
                pLoc = _placeLoc
            end
            if not pLoc then return false end
            local headLoc = SnaplineESP.GetHeadLoc(pawn, pLoc)
            local hOff = pawn._sdwHeadOff or 75
            local botOff, wRatio
            if hOff <= 30 then botOff, wRatio = -22, 1.1
            elseif hOff <= 60 then botOff, wRatio = -68, 0.7
            else botOff, wRatio = -90, 0.55 end

            local bT, cpT = SnaplineESP.ProjectWorldToCanvasLocalChecked(pc, headLoc)
            local topX, topY = cpT.X, cpT.Y
            if not _botLoc then _botLoc = FVector and FVector(0, 0, 0) or { X = 0, Y = 0, Z = 0 } end
            _botLoc.X, _botLoc.Y, _botLoc.Z = pLoc.X, pLoc.Y, pLoc.Z + botOff
            local bB, cpB = SnaplineESP.ProjectWorldToCanvasLocalChecked(pc, _botLoc)
            local botX, botY = cpB.X, cpB.Y

            if not (bT and bB) then
                -- off-screen: grace window (a 1-frame miss must not blink)
                if (now - (box.lastOnScreen or 0)) > 0.3 then _hide(box) end
                return false
            end

            box.lastOnScreen = now
            local boxH = math.max(28, math.abs(botY - topY))
            local boxW = math.max(15, boxH * wRatio)
            local cx = (topX + botX) * 0.5
            local cy = (topY + botY) * 0.5
            -- [SDWxOWNER-NOVIB] topEdge / botEdge are NO LONGER derived from the raw boxH here.
            -- The health bar + every label are anchored to the APPLIED size/centre read back
            -- AFTER _corners() below (aTop / aBot / aCX), so the whole assembly is rigid.

            _show(box)

            -- [SDWxOWNER-HPFIX] One shared "did the box move?" flag (container X/Y moved by
            -- > 0.25 px). Reused below so the health bar AND every label re-anchor in the SAME
            -- frame the box moves -> the whole assembly stays locked (no drift on gyro/camera).
            local boxMoved = (box.lastCX == nil) or math.abs(cx - box.lastCX) > 0.25 or math.abs(cy - box.lastCY) > 0.25
            if boxMoved then
                box.lastCX, box.lastCY = cx, cy
                pcall(_boxSetPos, box.cslot, cx, cy)
            end
            -- [SDWxOWNER-NOVIB] Update the OUTLINE first, then read back the size it ACTUALLY
            -- applied (box.lastW / box.lastH) and the centre it ACTUALLY applied (box.lastCX /
            -- box.lastCY). The health bar and EVERY label are anchored to THOSE values -> the
            -- outline, health bar and labels move as ONE rigid unit (no relative slide = no
            -- "halka vibration"), exactly like the native ESP box. box.lastW/H and box.lastCX/CY
            -- always hold the last APPLIED values because _corners() / the container write only
            -- store what they actually wrote (they never store a rejected / dead-banded value).
            _corners(box, boxW, boxH)
            local aCX  = box.lastCX or cx
            local aCY  = box.lastCY or cy
            local aW   = box.lastW
            local aH   = box.lastH
            local aTop = aCY - aH * 0.5
            local aBot = aCY + aH * 0.5

            -- health bar (left edge of the box)
            -- [SDWxOWNER-HPFIX] The GREEN fill must be re-anchored whenever the box MOVES
            -- (camera / gyro rotation changes hbX + botEdge), not only when the fill HEIGHT
            -- changes. The old code gated the fill's POSITION on hpFill (which depends on the
            -- enemy DISTANCE), so on rotation the black background tracked the box while the
            -- green fill was left behind at its old screen spot -> the health bar "drifted"
            -- (not fixed at one position). Now the background AND the fill are placed together
            -- in ONE pcall, gated by boxMoved (same per-frame cost as before, one fewer pcall).
            local hbW = B.healthBarWidth
            local hbX = aCX - aW * 0.5 - 2.5 - hbW * 0.5
            -- [SDWxOWNER-ZEROLAG-2] HEALTH READ CACHE (0.1 s per box). `pawn.Health` /
            -- `pawn.HealthMax` are TWO native property reads per box per frame (~6,000/s at 50
            -- enemies x 62 fps) purely to recompute a bar height that only changes when the enemy
            -- is actually damaged. Reading them at the 10 Hz scan rate instead is visually
            -- identical (a health bar 100 ms late is imperceptible) and removes those reads from
            -- the per-frame path. The bar POSITION still tracks the box every frame (it is driven
            -- by aBot / aH), so nothing lags on screen -- only the fill HEIGHT is refreshed 10x/s.
            local hpPct = box.hpPct
            if hpPct == nil or (now - (box.hpT or 0)) > 0.1 then
                local health = tonumber(pawn.Health) or 100
                local healthMax = tonumber(pawn.HealthMax) or tonumber(pawn.MaxHealth) or 100
                if healthMax <= 0 then healthMax = 100 end
                hpPct = math.max(0, math.min(1, health / healthMax))
                box.hpPct = hpPct
                box.hpT = now
            end            local hpFill = aH * hpPct
            if boxMoved or box.lastHpX == nil or math.abs(aBot - box.lastHpY) > 0.25 or math.abs(aH - box.lastHpH) > 0.25 or box.lastHpFill == nil or math.abs(hpFill - box.lastHpFill) > 0.5 then
                box.lastHpX, box.lastHpY, box.lastHpH, box.lastHpFill = hbX, aBot, aH, hpFill
                pcall(_boxSetBar, box.bgSlot, box.hpSlot, hbW, aH, hpFill, hbX, aBot)
            end

            -- label anchors: weapon + flag above the box; name / distance / state below it
            -- [SDWxOWNER-HPFIX] Re-anchor when the box MOVED (boxMoved) as well as when the
            -- label's own Y changed -> the labels stay locked to the box on camera / gyro
            -- rotation (before they were gated on Y only, which can stay constant during a
            -- pure yaw -> the labels slid horizontally). Same writes on a moving frame, so the
            -- per-frame cost is unchanged.
            local wepY = aTop - 3.5
            local flagY = aTop - 22.0
            local nameY = aBot + 4.0
            local distY = aBot + 20.5
            local stateY = aBot + 37.0
            local doWep = boxMoved or box.lastWepY == nil or math.abs(wepY - box.lastWepY) > 0.25
            local doFlag = boxMoved or box.lastFlagY == nil or math.abs(flagY - box.lastFlagY) > 0.25
            local doName = boxMoved or box.lastNameY == nil or math.abs(nameY - box.lastNameY) > 0.25
            local doDist = boxMoved or box.lastDistY == nil or math.abs(distY - box.lastDistY) > 0.25
            local doState = boxMoved or box.lastStateY == nil or math.abs(stateY - box.lastStateY) > 0.25
            if doWep or doFlag or doName or doDist or doState then
                if doWep then box.lastWepY = wepY end
                if doFlag then box.lastFlagY = flagY end
                if doName then box.lastNameY = nameY end
                if doDist then box.lastDistY = distY end
                if doState then box.lastStateY = stateY end
                -- [SDWxOWNER-ZEROLAG] ONE pcall for all five label anchors (was five).
                pcall(_boxAnchorLabels, box, aCX, wepY, flagY, nameY, distY, stateY,
                      doWep, doFlag, doName, doDist, doState)
            end
            return true
        end

        function B.Tick()
            local on = (_G.SDWConfig and _G.SDWConfig.SDWBoxESPEnabled) and true or false
            if _G.SDW_FXCheck then pcall(_G.SDW_FXCheck, "sdwbox", on) end
            if not on then return end

            local gen = _G._SDW_MatchGen or 0
            if B.gen ~= gen then
                B.ClearAll()
                B.gen = gen
            end

            -- Refill the shared LOS raycast budget so the Cover/Open state stays accurate
            -- even when the snapline (which normally refills it) is switched OFF.
            SnaplineESP._TraceBudget = 4

            if not SnaplineESP.InitESPCanvas() then return end
            local canvas = SnaplineESP.ESPCanvas
            if not canvas or not slua.isValid(canvas) then return end
            B.canvas = canvas
            -- [SDWxOWNER-RUSH-FPS] Reset the per-tick NEW-box counter (see _obtain).
            B.createdThisTick = 0

            local pc, localPawn = SnaplineESP.GetMyControllerAndPlayer()
            if not pc or not slua.isValid(pc) or not localPawn or not slua.isValid(localPawn) then return end
            B.pc = pc
            SnaplineESP.UpdateCanvasTransform(pc)

            local allPawns = SnaplineESP.GetAllPawns()
            if not allPawns or #allPawns == 0 then return end

            -- [SDWxOWNER-RUSH-FPS] One camera-basis sample for the whole scan.
            SnaplineESP.BeginProjectionFrame()

            local myTeamId = localPawn.TeamID or (type(localPawn.GetTeamID) == "function" and localPawn:GetTeamID())
            local okMyLoc, myLocV = pcall(_boxGetLoc, localPawn)
            local myLoc = okMyLoc and myLocV or nil

            local now = os.clock()
            local seen = B.seen
            for k in pairs(seen) do seen[k] = nil end

            local budget = { B.flagLoadBudget }
            local cnt = 0

            for _, pawn in ipairs(allPawns) do
                if pawn and slua.isValid(pawn) and pawn ~= localPawn then
                    local pTeam = pawn.TeamID or (type(pawn.GetTeamID) == "function" and pawn:GetTeamID())
                    if not (myTeamId and myTeamId > 0 and pTeam and pTeam > 0 and pTeam == myTeamId) then
                        local hs = pawn.HealthStatus
                        if not (hs == 2 or hs == 3) and not (pawn.bIsDead or pawn.bDead) then
                            local okLoc, locV = pcall(_boxGetLoc, pawn)
                            local pLoc = okLoc and locV or nil
                            if pLoc then
                                local distSq = 0
                                if myLoc then
                                    local dx, dy, dz = pLoc.X - myLoc.X, pLoc.Y - myLoc.Y, pLoc.Z - myLoc.Z
                                    distSq = dx * dx + dy * dy + dz * dz
                                end
                                if distSq <= B.maxDistSq then
                                    local key = pawn._sdwBoxKey
                                    if not key then
                                        local pk = pawn.PlayerKey
                                        if pk and pk ~= 0 then
                                            key = "P" .. tostring(pk)
                                        else
                                            local uid = nil
                                            pcall(function() if pawn.GetUniqueID then uid = pawn:GetUniqueID() end end)
                                            if uid ~= nil and uid ~= 0 then key = "U" .. tostring(uid) else key = "O" .. tostring(pawn) end
                                        end
                                        pawn._sdwBoxKey = key
                                    end
                                    seen[key] = true
                                    cnt = cnt + 1

                                    local box = B.boxes[key]
                                    if not box then
                                        box = _obtain(canvas)
                                        if box then B.boxes[key] = box end
                                    end
                                    if box then
                                        box.pawn = pawn
                                        -- [SDWxOWNER-ZEROLAG-2] Cache the full liveness verdict at
                                        -- the 10 Hz scan so the ~62 Hz fast tick does NOT have to
                                        -- re-read 5 native properties per box per frame
                                        -- (HealthStatus / bIsDead / bDead / bIsBeingDestroyed /
                                        -- bPendingKill = ~15,000 native reads/sec at 50 enemies).
                                        -- The fast tick still re-checks slua.isValid + HealthStatus
                                        -- every frame, so a pawn that dies between scans is caught
                                        -- immediately and can never be projected while tearing down.
                                        box.live = not (hs == 2 or hs == 3 or pawn.bIsDead == true
                                                        or pawn.bDead == true or pawn.bIsBeingDestroyed == true
                                                        or pawn.bPendingKill == true)
                                        if _placeBox(box, pawn, pc, now, pLoc) then
                                            -- weapon name (above the box)
                                            local wep = nil
                                            if _OPT.GetWeaponNameCached then wep = _OPT.GetWeaponNameCached(pawn, now) end
                                            if not wep or wep == "" then wep = "Fist" end
                                            if box.cWeapon ~= wep then
                                                box.cWeapon = wep
                                                pcall(_boxSetText, box.weapon, wep)
                                            end

                                            -- nation flag (above the box, under the weapon name)
                                            _setFlag(box, pawn, budget)

                                            -- name (below the box)
                                            local nm = nil
                                            if ResolveIsAI and ResolveIsAI(pawn.PlayerKey, pawn) then
                                                nm = "Bot"
                                            else
                                                nm = GetEnemyName and GetEnemyName(pawn) or "Player"
                                            end
                                            if not nm or nm == "" then nm = "Player" end
                                            if box.cName ~= nm then
                                                box.cName = nm
                                                pcall(_boxSetText, box.name, nm)
                                            end

                                            -- distance (below the name)
                                            local distStr = "?"
                                            if myLoc then
                                                local ddx, ddy, ddz = pLoc.X - myLoc.X, pLoc.Y - myLoc.Y, pLoc.Z - myLoc.Z
                                                local dm = math.floor(math.sqrt(ddx * ddx + ddy * ddy + ddz * ddz) / 100.0)
                                                distStr = tostring(dm) .. "m"
                                            end
                                            if box.cDist ~= distStr then
                                                box.cDist = distStr
                                                pcall(_boxSetText, box.dist, distStr)
                                            end

                                            -- state (below the distance): Open / Cover / Knocked
                                            local isVis = SnaplineESP.IsPlayerVisible(pc, pawn)
                                            local stateStr, stateCol = "Open", B.textOpen
                                            if hs == 1 or pawn.bIsKnocked then
                                                stateStr, stateCol = "Knocked", B.textCover
                                            elseif not isVis then
                                                stateStr, stateCol = "Cover", B.textCover
                                            end
                                            if box.cState ~= stateStr then
                                                box.cState = stateStr
                                                pcall(_boxSetText, box.state, stateStr)
                                                pcall(_boxSetStateColor, box.state, stateCol)
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end

            -- recycle boxes for enemies that left / died / went out of range
            for key, box in pairs(B.boxes) do
                if not seen[key] then
                    B.boxes[key] = nil
                    _recycle(box)
                end
            end

            B.count = cnt
            -- [SDWxOWNER-RUSH-FPS] Top the pool up while the screen is quiet (<=2 enemies). This
            -- moves the whole widget-creation cost of a rush OUT of the rush, so 2-3 squads can
            -- appear at once with ZERO allocation spike -> no FPS drop, no crash.
            if cnt <= 2 then _prewarm() end
        end

        -- [SDWxOWNER-BOXSMOOTH] Per-frame fast tick: re-project + re-place every LIVE box so it
        -- tracks the enemy at the FRAME RATE (native-ESP smoothness). The heavy work (roster,
        -- LOS raycast, weapon / flag / name text) stays in the 10 Hz scan (B.Tick); this path
        -- only moves geometry, so it is cheap. Driven by SDW_BoxFastTick (a self-sustaining
        -- ~60 Hz driver) so the box stays LOCKED on the enemy while the camera / gyro moves.
        function B.FastTick()
            if not (_G.SDWConfig and _G.SDWConfig.SDWBoxESPEnabled) then return end
            local canvas = B.canvas
            if not canvas or not slua.isValid(canvas) then return end
            local pc = B.pc
            if not pc or not slua.isValid(pc) then return end
            if not SnaplineESP.ESPCanvas or not slua.isValid(SnaplineESP.ESPCanvas) then return end
            -- [SDWxOWNER-RUSH-FPS] One camera-basis sample per FRAME. Every box (head + feet)
            -- reuses it, instead of each projection re-reading the camera + viewport natively.
            SnaplineESP.BeginProjectionFrame()
            SnaplineESP.UpdateCanvasTransform(pc)
            local now = os.clock()
            for _, box in pairs(B.boxes) do
                local pawn = box.pawn
                if pawn and box.live ~= false and box.visState == 1 and slua.isValid(pawn) then
                    -- [SDWxOWNER-RUSH-CRASH FIX] Re-check liveness between the 10 Hz scans.
                    -- A pawn killed mid-rush stays slua.isValid() for a few frames while its
                    -- mesh is torn down; projecting it then reads a freed component -> native
                    -- use-after-free crash. Skip it here; the scan recycles the box.
                    -- [SDWxOWNER-ZEROLAG-2] Only the CHEAP death signal is re-read per frame
                    -- (HealthStatus, 1 native read). The teardown flags (bIsDead / bDead /
                    -- bIsBeingDestroyed / bPendingKill) are cached by the 10 Hz scan in box.live,
                    -- which removes ~4 native property reads per box per frame. A pawn that dies
                    -- between two scans is still caught here by HealthStatus (it flips to 2/3 on
                    -- death, BEFORE any mesh teardown), so the crash protection is unchanged.
                    local _hs = pawn.HealthStatus
                    if not (_hs == 2 or _hs == 3) then
                        _placeBox(box, pawn, pc, now, nil)
                    else
                        box.live = false
                    end
                end
            end
        end

        return B
    end
    _SDW_BuildBoxESP()
    end

    local function Tick_HealthBarESP()
        local _hbOn = (_G.SDWConfig and _G.SDWConfig.HealthBarESPEnabled) and true or false
        local _wepOn = (_G.SDWConfig and _G.SDWConfig.WeaponESPEnabled) and true or false
        if _G.SDW_FXCheck then
            pcall(_G.SDW_FXCheck, "healthbar", _hbOn)
            pcall(_G.SDW_FXCheck, "weaponesp", _wepOn)
        end
        if not _hbOn and not _wepOn then return end
        local localPawn, myPos, hud, pc, myTeamId = GetFrameCache()
        if not localPawn or not hud then return end
        local okPawns, allPawns = GetCachedPlayerPawns()
        if not okPawns or not allPawns then return end

        local sliderEnemy = _G.SDWConfig.TextSizeEnemyUI or 50
        local eScale = 0.83 + (sliderEnemy / 100.0) * 0.14
        local now = os.clock()
        -- [ZEROLAG] Count enemies/bots in THIS pass so the 3 s Counter tick can reuse them.
        local hbEnemies, hbBots = 0, 0

        for _, pawn in pairs(allPawns) do
            if not SafeIsValid(pawn) or pawn == localPawn then goto continue end
            -- [SDWxOWNER-ALLMAPS] Robust enemy filter (IDENTICAL to the snapline/wallhack one):
            -- skip ONLY a proven teammate or a dead pawn. A nil/0 team (rooms / TDM / FFA /
            -- custom maps) counts as an enemy, so every counter works on EVERY map. The old
            -- filter required pawn.TeamID to be truthy -> on TDM/FFA/rooms it dropped EVERY
            -- pawn (count 0). It also dropped bots whose PlayerKey is 0/nil.
            local pTeam = pawn.TeamID or (type(pawn.GetTeamID) == "function" and pawn:GetTeamID())
            if myTeamId and myTeamId > 0 and pTeam and pTeam > 0 and pTeam == myTeamId then goto continue end
            local hs = pawn.HealthStatus
            if hs == 2 or hs == 3 then goto continue end
            if pawn.bIsDead or pawn.bDead then goto continue end

            local pKey = pawn.PlayerKey
            local isAI = ResolveIsAI(pKey, pawn)

            local okPP, pPos = SafeMethodCall(pawn, "K2_GetActorLocation")
            local distSq = 0
            if okPP and pPos and myPos then
                local dx = pPos.X - myPos.X
                local dy = pPos.Y - myPos.Y
                local dz = pPos.Z - myPos.Z
                distSq = dx * dx + dy * dy + dz * dz
            end
            local isWithin400m = (distSq > 0 and distSq <= 1600000000)
            if not isWithin400m then goto continue end

            local maxHP = tonumber(pawn.HealthMax or pawn.MaxHealth) or 100
            local currentHP = tonumber(pawn.Health) or 0
            if maxHP <= 0 then maxHP = 100 end
            local hpPercent = currentHP / maxHP
            if hpPercent < 0 then hpPercent = 0 elseif hpPercent > 1 then hpPercent = 1 end
            local hpPct = math.floor(hpPercent * 100)
            local distM = math.floor(math.sqrt(distSq) / 100)
            if isAI then hbBots = hbBots + 1 else hbEnemies = hbEnemies + 1 end

            local textColor
            local espText
            -- [FIX] Combat Info shows ONLY the distance (+ "BOT" tag for bots) with a FIXED colour.
            -- [ZEROLAG] Memoised per metre count -> zero string allocation in the steady state.
            if isAI then
                textColor = GetColorTable(_G.SDWConfig.ColorBotText or 1)
            else
                textColor = GetColorTable(_G.SDWConfig.ColorEnemyText or 0)
            end

            if _wepOn then
                -- [SDWxOWNER-WEAPONESP] Append the enemy's weapon name to the SAME label.
                -- Nested memo tables ([distM][name]) keep the steady state allocation-free.
                local wname = _OPT.GetWeaponNameCached(pawn, now)
                if _hbOn then
                    local wtab = isAI and _OPT.WepBotTxt or _OPT.WepTxt
                    local dtab = wtab[distM]
                    if not dtab then dtab = {}; wtab[distM] = dtab end
                    espText = dtab[wname]
                    if not espText then
                        if isAI then espText = "BOT  " .. distM .. "m  " .. wname
                        else espText = distM .. "m  " .. wname end
                        dtab[wname] = espText
                    end
                else
                    espText = _OPT.WepOnlyTxt[wname]
                    if not espText then espText = wname; _OPT.WepOnlyTxt[wname] = espText end
                end
            elseif isAI then
                espText = _HB_BOT_TXT[distM]
                if not espText then espText = "BOT  " .. distM .. "m"; _HB_BOT_TXT[distM] = espText end
            else
                espText = _HB_TXT[distM]
                if not espText then espText = distM .. "m"; _HB_TXT[distM] = espText end
            end

            -- [FIX] ANTI-BLINK: long label lifetime (4.0s) + fast tick (0.5s).
            SafeMethodCall(hud, "AddDebugText", espText, pawn, 4.0, TEXT_OFFSET, TEXT_OFFSET, textColor, false, false, true, nil, eScale, true)
            ::continue::
        end
        -- [ZEROLAG] Publish the counts + a fresh timestamp. The Counter tick's roster filter is
        -- byte-for-byte identical to this one (same team/health/400 m test), so it can consume
        -- these instead of re-scanning every pawn. Falls back to its own scan when this is stale.
        _G._SDW_HB_EnemyCount = hbEnemies
        _G._SDW_HB_BotCount = hbBots
        _G._SDW_HB_ScanT = now
    end

    -- [SDWxOWNER] Mini Map ESP removed on request (Distance ESP already covers it).

    -- ===== BEGIN SDWxOWNER V3 iOS Counter module (SDWxOWNER VIP iOS Counter Framework) =====
    do

    -- =====================================================================
    -- [SDWxOWNER] V3 iOS CAPSULE COUNTER  --  SDWxOWNER VIP iOS Counter Framework
    -- ---------------------------------------------------------------------
    -- The V3 capsule counter is authored for the SDWxOWNER framework's "ESP" namespace.
    -- It is hosted on the SDWxOWNER framework: a small, crash-safe `ESP`
    -- compatibility shim wraps 1.lua's standard LinearColor / Vector2D /
    -- slua.isValid and the SnaplineESP canvas, so the original drawing code runs
    -- unchanged. The only behavioural re-bind is the on/off flag, which now reads
    -- _G.SDWConfig.EnemyCounterIOS (the old legacy config key is gone).
    -- =====================================================================
    local _V3LinearColor = _ci_LinearColor or import("LinearColor") or _G.FLinearColor
    local _V3Vector2D    = import("Vector2D") or _G.FVector2D
    local _V3SlateColor  = import("SlateColor") or _G.FSlateColor

    -- [SDWxOWNER-PERF] Hoisted validity probe. pcall(fn, arg) does NOT allocate a closure,
    -- unlike the old pcall(function() ... end) which created a fresh one on EVERY call.
    -- ESPValid is invoked from the per-frame V3 place/show path, so this is a genuine
    -- zero-garbage win. Behaviour is byte-for-byte identical (never throws on dead userdata).
    local function _espIsValid(w) return slua.isValid(w) end
    local function ESPValid(w)
        if not w then return false end
        local ok, v = pcall(_espIsValid, w)
        return ok and v == true
    end

    -- Vector2D constructor (plain-table fallback if the class is unavailable).
    local function ESPV2(x, y)
        if _V3Vector2D then
            local ok, v = pcall(_V3Vector2D, x, y)
            if ok and v then return v end
        end
        return { X = x, Y = y }
    end

    -- Round to nearest integer (the V3 code snaps to the device-pixel grid).
    local function RND(v)
        v = tonumber(v) or 0
        return math.floor(v + 0.5)
    end

    -- [SDWxOWNER-PERF] Hoisted Slate visibility writers (shared by the V3 show/hide paths).
    -- Zero-allocation: the native call is a plain function reference, not a closure, so
    -- pcall(_wSetVis, w, vis) creates NO garbage on the hot per-frame path.
    local function _wSetVis(w, vis) w:SetWidgetVisibility(vis) end
    local function _wSetCollapsed(w) w:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end
    local function _wSetSelfHit(w) w:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible) end

    -- Visibility setter used by ESP.V3ShowLayer (kept for backward compatibility).
    local H = { vis = function(w, vis)
        if not w then return end
        pcall(_wSetVis, w, vis)
    end }

    -- CGame accessor (owns NewObjectFromPath). Resolved lazily + defensively.
    local _V3CGame = rawget(_G, "CGame") or import("CGame")
    local CGame
    if _V3CGame and _V3CGame.NewObjectFromPath then
        CGame = _V3CGame
    else
        CGame = {
            NewObjectFromPath = function(_, path, parent)
                local cg = rawget(_G, "CGame") or import("CGame")
                if cg and cg.NewObjectFromPath then
                    local ok, w = pcall(function() return cg:NewObjectFromPath(path, parent) end)
                    if ok then return w end
                end
                local cls = nil
                pcall(function() cls = slua.loadClass(path) end)
                if cls then
                    local ok, w = pcall(cls, parent)
                    if ok then return w end
                end
                return nil
            end
        }
    end

    -- The ESP namespace: a table that is ALSO callable -> ESP(r,g,b,a) = LinearColor.
    local ESP = setmetatable({}, {
        __call = function(_, r, g, b, a)
            if _V3LinearColor then
                local ok, c = pcall(_V3LinearColor, r, g, b, a)
                if ok and c then return c end
            end
            return { R = r, G = g, B = b, A = a }
        end
    })

    -- ---- shim primitives expected by the V3 drawing code ----
    ESP.WCheckEvery     = 0.5
    ESP.TILE_DESIGN_PPU = 1.6875
    ESP._now            = 0
    ESP._vep            = 0
    ESP.Ribbon          = nil          -- no V2 ribbon in this framework
    ESP.RibbonHide      = function() end
    ESP.WMHide          = function() end

    ESP.GetCanvas = function()
        local S = _G.SnaplineESP
        if S and S.InitESPCanvas then
            local ok = false
            pcall(function() ok = S.InitESPCanvas() end)
            if ok and S.ESPCanvas and ESPValid(S.ESPCanvas) then return S.ESPCanvas end
        end
        return nil
    end

    ESP.GetPPU = function()
        local S = _G.SnaplineESP
        local sx = S and S._CanvasScaleX
        if sx and sx > 0 then return 1.0 / sx end
        return 1.0
    end

    ESP.Now = function() return os.clock() end

    ESP.WOk = function(d)
        if not d then return false end
        return ESPValid(d.Widget or d)
    end

    -- [SDWxOWNER-PERF] Hoisted widget mutators (closure-free pcall targets).
    local function _wRemoveFromParent(w) w:RemoveFromParent() end
    local function _tbSetColorSlate(tb, color) tb:SetColorAndOpacity(_V3SlateColor(color)) end
    local function _tbSetColorPlain(tb, color) tb:SetColorAndOpacity(color) end

    ESP.Destroy = function(d)
        if not d then return end
        local w = d.Widget or d
        if w and ESPValid(w) and w.RemoveFromParent then pcall(_wRemoveFromParent, w) end
    end

    ESP.Hide = function(d)
        if not d then return end
        local w = d.Widget or d
        if w and ESPValid(w) then pcall(_wSetCollapsed, w) end
    end

    ESP.SetTextColor = function(tb, color)
        if not tb or not color then return end
        if _V3SlateColor then pcall(_tbSetColorSlate, tb, color)
        else pcall(_tbSetColorPlain, tb, color) end
    end

