ESP.V3_LAYER_ORDER = { "bar", "soldier", "robot", "shield", "warn", "title" }
ESP.V3_REF_H       = 34.78      -- bar height (canvas units) at which 1 data unit = 1 device pixel @1080p
ESP.V3_W_DP        = 305      -- capsule width (data units)
ESP.V3_H_DP        = 59      -- capsule height (data units)
ESP.V3_TITLE_BLOCK = 44      -- title block height above the capsule (data units)
ESP.V3_DIG_L       = { 109.1, 34.7 }   -- left (player) digit visual centre
ESP.V3_DIG_R       = { 196, 34.7 }   -- right (bot) digit visual centre

-- V3 CONFIG
ESP.V3_H           = 34.78   -- bar ki height (canvas units). 34.78 = reference screenshot ke barabar 1:1 (305 x 59 px @1080p). Bada/chhota karna ho to sirf yeh number badlo (poora design scale hota hai)
ESP.V3_TOPY        = 47      -- title ka top, screen top se Y (compass ke neeche) -- V2 (TILE_TOPY) jaisa
ESP.V3_DETAIL      = 1.0     -- 1.0 = poori detail (~1200 widgets). Phone par lag aaye to 0.8 / 0.65 / 0.5 karo: sabse kam zaroori rects hat jate hain, picture phir bhi saaf rehti hai
ESP.V3_BUILD_STEP  = 40      -- ek Update mein max itne widgets bante hain (staged build => game mein hitch nahi)
ESP.V3_HOLD        = 0.3     -- enemy 0 hone par warning itni der (sec) ruki rehti hai: count bar-bar 0<->1 ho to 400 widgets bar-bar swap na hon (lag nahi). 0 = turant
ESP.V3_DIG_H_DP    = 24.6    -- digit ki height (data units = px @1080p, V3_H = V3_REF_H par): reference mein "0" / "4" bar ki ~42% height

-- Digit colours: sRGB (reference screenshot se measure). fill = andar ka rang, edge = gehra kinara/outline.
--   value 0  -> HARA (reference ka "0"),   value 1+ -> PEELA (reference ka "4")
ESP.V3_DIG_GREEN   = { fill = { 118, 228, 84 }, edge = { 40, 98, 38 } }
ESP.V3_DIG_YELLOW  = { fill = { 232, 226, 80 }, edge = { 96, 82, 26 } }

-- sRGB (0..255) -> LINEAR (0..1).  ESP linear leta hai.
function ESP.V3S2L(v)
  v = v / 255.0
  if v <= 0.04045 then return v / 12.92 end
  return ((v + 0.055) / 1.055) ^ 2.4
end

function ESP.V3Col(rgb, a)
  return ESP(ESP.V3S2L(rgb[1]), ESP.V3S2L(rgb[2]), ESP.V3S2L(rgb[3]), a or 1.0)
end

-- Digit colour objects (ek baar bante hain)
function ESP.V3DigitCols()
  local c = ESP._v3dc
  if not c then
    c = {
      { fill = ESP.V3Col(ESP.V3_DIG_GREEN.fill),  edge = ESP.V3Col(ESP.V3_DIG_GREEN.edge) },    -- [1] hara
      { fill = ESP.V3Col(ESP.V3_DIG_YELLOW.fill), edge = ESP.V3Col(ESP.V3_DIG_YELLOW.edge) },   -- [2] peela
    }
    ESP._v3dc = c
  end
  return c
end

-- 1 data unit (= 1 device pixel @1080p jab V3_H == ESP.V3_REF_H) kitne canvas units ka hai.
function ESP.V3Cell()
  return ((ESP.V3_H or 33) / (ESP.V3_REF_H or 33)) / (ESP.TILE_DESIGN_PPU or 1.6875)
end

-- Digit font size: HUD font mein digit height ~= 0.986 * size (V2 ka measure).
function ESP.V3FontSize()
  return math.max(6, math.floor((ESP.V3_DIG_H_DP or 15.6) * ESP.V3Cell() / 0.986 + 0.5))
end

-- Pura widget (title + bar) ka neeche wala Y -- snap lines yahin se shuru hoti hain
function ESP.V3BottomY()
  return (ESP.V3_TOPY or 47) + ((ESP.V3_TITLE_BLOCK or 25) + (ESP.V3_H_DP or 37)) * ESP.V3Cell()
end

-- [SDWxOWNER-PERF] Hoisted font appliers (closure-free pcall targets). The old version
-- allocated two pcall(function() ... end) closures per digit-font apply.
local function _v3SetOutlineColor(o, edge) o.OutlineColor = edge end
local function _v3ApplyFont(w, size, edge)
  local f = w.Font
  if not f then return end
  f.Size = size
  local o = f.OutlineSettings
  if o then
    o.OutlineSize = 1
    pcall(_v3SetOutlineColor, o, edge)
    f.OutlineSettings = o
  end
  w:SetFont(f)
end
local function _v3ApplyShadow(w, edge)
  if w.SetShadowOffset then w:SetShadowOffset(ESPV2(0.6, 0.6)) end
  if w.SetShadowColorAndOpacity then w:SetShadowColorAndOpacity(edge) end
end

-- Digit font: size + gehra outline/shadow (reference ke digits ka kinara). Struct copy -> modify -> wapas assign.
function ESP.V3SetFont(w, size, edge)
  if not ESPValid(w) then return end
  pcall(_v3ApplyFont, w, size, edge)
  pcall(_v3ApplyShadow, w, edge)
end

-- Ek digit ko hara (1) ya peela (2) karta hai
function ESP.V3ApplyDigit(tb, kind, fs)
  local dc = ESP.V3DigitCols()[kind] or ESP.V3DigitCols()[1]
  ESP.SetTextColor(tb, dc.fill)
  ESP.V3SetFont(tb, fs, dc.edge)
end

-- Ribbon V3 state
ESP.RibbonV3 = nil

function ESP.RibbonV3Ok(rb)
  local now = ESP._now or 0
  local dt = now - (rb.vt or -1e9)
  if rb.ve == ESP._vep and dt >= 0 and dt < ESP.WCheckEvery then return rb.vok end
  local ok = ESPValid(rb.TxtL) and ESPValid(rb.TxtR)
  rb.ve, rb.vt, rb.vok = ESP._vep, now, ok
  return ok
end

function ESP.RibbonV3Destroy()
  -- [SDWxOWNER-CRASH FIX] Read/clear the GLOBAL mirror too, so a capsule built by the previous
  -- module load is still torn down (ESP is a local table -> ESP.RibbonV3 was lost on reload).
  local rb = ESP.RibbonV3 or _G._SDW_V3_RB
  ESP.RibbonV3 = nil
  _G._SDW_V3_RB = nil
  if not rb then return end
  if rb.Layers then
    for _, ly in pairs(rb.Layers) do
      for _, p in ipairs(ly.parts) do
        if p.ln then ESP.Destroy(p.ln) end
      end
    end
  end
  for _, k in ipairs({ "TxtL", "TxtR" }) do
    if rb[k] then ESP.Destroy({ Widget = rb[k] }) end
  end
end

-- Ek layer ke saare rects chhupao
function ESP.V3HideLayer(ly)
  if not ly or not ly.shown then return end
  ly.shown = false
  local parts = ly.parts
  for i = 1, #parts do
    local ln = parts[i].ln
    -- [SDWxOWNER-PERF] Mark the part hidden so the NEXT V3ShowLayer pass re-asserts its
    -- visibility exactly once. The old code left ln.hidden == false while the Slate
    -- visibility was Collapsed, so the show path skipped the widget and the layer could
    -- never come back (e.g. the warn triangle after the shield). Marking hidden=true here
    -- is what makes the show/hide swap correct AND avoids redundant Slate layout passes.
    if ln.hidden ~= true then
      ln.hidden = true
      pcall(_wSetCollapsed, ln.Widget)
    end
  end
end

-- Naya rect widget (Border): shuru se Collapsed, koi rotation nahi (ESP.NewLine jaisa, bas pivot/flash ke bina).
-- [SDWxOWNER-PERF] All native calls go through HOISTED functions -> no per-widget closure alloc.
local function _v3NewBorder(canvas) return CGame:NewObjectFromPath("/Script/UMG.Border", canvas) end
local function _v3InitBorder(border, color)
  border:SetBrushColor(color)
  border:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed)
end
local function _v3AddChild(canvas, w) return canvas:AddChildToCanvas(w) end
local function _v3SetupSlot(slot, z) slot:SetAutoSize(false) slot:SetZOrder(z) end

function ESP.V3NewRect(color, z)
  local canvas = ESP.GetCanvas()
  if not ESPValid(canvas) then return nil end
  local border = nil
  local okB, b = pcall(_v3NewBorder, canvas)
  if okB then border = b end
  if not ESPValid(border) then return nil end
  pcall(_v3InitBorder, border, color)
  local slot = nil
  local okS, s = pcall(_v3AddChild, canvas, border)
  if okS then slot = s end
  if not slot then
    pcall(_wRemoveFromParent, border)
    return nil
  end
  pcall(_v3SetupSlot, slot, z or 30)
  return { Widget = border, Slot = slot, hidden = true }
end

-- Rect (canvas units) ko DEVICE PIXEL grid par snap karke rakhta hai (sirf position + size, visibility nahi).
-- ESP.DrawRectF jaisa, farq: rect kabhi 0 pixel nahi hota (kam se kam 1 px) -- 1-dp wale cells (stars, title ki patli
-- lines) kabhi gayab nahi hote. Cache integer pixel coords par hai: wahi coords dobara aaye to engine ko kuch nahi jata.
-- [SDWxOWNER-PERF] Hoisted slot writer (closure-free). The old inline pcall(function()
-- ... end) allocated a fresh closure for EVERY rect of EVERY layer on EVERY re-place pass.
local function _v3SlotPlace(slot, ax, ay, sx, sy)
  slot:SetPosition(ESPV2(ax, ay))
  slot:SetSize(ESPV2(sx, sy))
end

function ESP.V3Place(d, x1, y1, x2, y2, ppu)
  if not d or not d.Slot or not ESP.WOk(d) then return false end
  local a = math.floor(x1 * ppu + 0.5)
  local b = math.floor(y1 * ppu + 0.5)
  local c = math.floor(x2 * ppu + 0.5)
  local e = math.floor(y2 * ppu + 0.5)
  if c <= a then c = a + 1 end
  if e <= b then e = b + 1 end
  if d.fx1 == a and d.fy1 == b and d.fx2 == c and d.fy2 == e then return true end
  local ok = pcall(_v3SlotPlace, d.Slot, a / ppu, b / ppu, (c - a) / ppu, (e - b) / ppu)
  if ok then d.fx1, d.fy1, d.fx2, d.fy2 = a, b, c, e end
  return ok
end

-- Ek layer ke saare rects ko jagah do (dp coords -> canvas units) + dikhao.
-- Sirf tab dobara chalta hai jab position / scale / ppu badli ho ya layer chhupa tha.
function ESP.V3ShowLayer(ly, X, Y, cell, ppu)
  if not ly then return end
  -- [SDWxOWNER-PERF] Epsilon float compare (was exact ==). The capsule origin is snapped to
  -- the device-pixel grid every frame, so sub-0.1-unit float jitter must NOT trigger a full
  -- 1500-widget re-place pass. This hysteresis removes the constant re-layout stutter while
  -- keeping the picture pixel-identical (0.1 canvas units is far below one device pixel).
  if ly.shown and ly.gp == ppu
     and math.abs(ly.gx - X) < 0.1 and math.abs(ly.gy - Y) < 0.1
     and math.abs(ly.gc - cell) < 0.0001 then return end
  ly.shown = true
  ly.gx, ly.gy, ly.gc, ly.gp = X, Y, cell, ppu
  local vis = UEnums.ESlateVisibility.SelfHitTestInvisible
  local parts = ly.parts
  for i = 1, #parts do
    local p = parts[i]
    local ln = p.ln
    if ESP.V3Place(ln, X + p.x1 * cell, Y + p.y1 * cell, X + p.x2 * cell, Y + p.y2 * cell, ppu) and ln.hidden ~= false then
      pcall(_wSetVis, ln.Widget, vis)
      ln.hidden = false
    end
  end
end

function ESP.V3HideText(rb)
  rb.txtShown = false
  -- [SDWxOWNER-PERF] No ipairs({...}) table alloc, no per-widget closure: two direct calls.
  local wl, wr = rb.TxtL, rb.TxtR
  if ESPValid(wl) then pcall(_wSetCollapsed, wl) end
  if ESPValid(wr) then pcall(_wSetCollapsed, wr) end
end

function ESP.RibbonV3Hide()
  local rb = ESP.RibbonV3
  if not rb or rb.hidden then return end
  rb.hidden = true
  if rb.Layers then
    for _, ly in pairs(rb.Layers) do ESP.V3HideLayer(ly) end
  end
  ESP.V3HideText(rb)
end

-- [SDWxOWNER-PERF] Hoisted quality map. V3DetailVal() is called ~20x/second by the V3 driver
-- (and on every capsule (re)build). The old inline `{ [1]=1.0, ... }` allocated a FRESH table on
-- every single call -> steady garbage. A module-level constant removes that allocation entirely.
local _V3_QUALITY_MAP = { [1] = 1.0, [2] = 0.8, [3] = 0.65, [4] = 0.5 }
-- ESP.V3_DETAIL ko 0.3 .. 1.0 mein rakhta hai
function ESP.V3DetailVal()
  -- [SDWxOWNER] Quality is driven by _G.SDWConfig.V3CounterQuality (1=High 2=Medium 3=Low 4=Ultra).
  local d
  local q = tonumber(_G.SDWConfig and _G.SDWConfig.V3CounterQuality)
  if q then
    d = _V3_QUALITY_MAP[q] or 0.8
  else
    d = tonumber(ESP.V3_DETAIL) or 1.0
  end
  if d > 1.0 then d = 1.0 elseif d < 0.3 then d = 0.3 end
  return d
end

-- [SDWxOWNER] Colour themes for the V3 capsule. The background art is re-tinted by rotating
-- the hue of the "bar" palette, so the holographic look is preserved while the whole counter
-- shifts to the chosen colour family. White / grey pixels (low saturation) are left untouched.
ESP.V3_THEMES = {
  { name = "Pink",   hue = 315 },
  { name = "Yellow", hue = 52  },
  { name = "Cyan",   hue = 185 },
  { name = "Red",    hue = 0   },
  { name = "Green",  hue = 120 },
  { name = "Blue",   hue = 220 },
  { name = "Orange", hue = 28  },
  { name = "Purple", hue = 280 },
}

function ESP.V3ColorVal()
  local i = tonumber(_G.SDWConfig and _G.SDWConfig.V3CounterColor) or 1
  if i < 1 or i > #ESP.V3_THEMES then i = 1 end
  return i
end

-- Rotate the hue of an RGB colour so the (magenta) source art becomes the theme colour.
function ESP.V3ThemeRGB(r, g, b)
  local delta = (ESP.V3_THEMES[ESP.V3ColorVal()].hue or 315) - 315
  if delta == 0 then return r, g, b end
  local mx = math.max(r, g, b); local mn = math.min(r, g, b); local d = mx - mn
  local h, s, v = 0, 0, mx
  if mx > 0 then s = d / mx end
  if d > 0 then
    if mx == r then h = (g - b) / d
    elseif mx == g then h = 2 + (b - r) / d
    else h = 4 + (r - g) / d end
    h = h * 60
    if h < 0 then h = h + 360 end
  end
  h = (h + delta) % 360
  if s > 0.04 then s = math.min(1.0, s * 1.5) end   -- boost saturation so the theme colour pops
  local c = v * s
  local x = c * (1 - math.abs(((h / 60) % 2) - 1))
  local m = v - c
  local rr, gg, bb = 0, 0, 0
  local seg = math.floor(h / 60) % 6
  if seg == 0 then rr, gg, bb = c, x, 0
  elseif seg == 1 then rr, gg, bb = x, c, 0
  elseif seg == 2 then rr, gg, bb = 0, c, x
  elseif seg == 3 then rr, gg, bb = 0, x, c
  elseif seg == 4 then rr, gg, bb = x, 0, c
  else rr, gg, bb = c, 0, x end
  return rr + m, gg + m, bb + m
end

-- [SDWxOWNER] SDWxOWNER wordmark (title text) colour choices. Index 1 = the ORIGINAL gold.
ESP.V3_TITLE_COLORS = {
  { name = "Gold",  rgb = { 0.7605, 0.5776, 0.2747 } },   -- original title colour (default)
  { name = "White", rgb = { 0.9600, 0.9600, 0.9600 } },
  { name = "Cyan",  rgb = { 0.2500, 0.8500, 1.0000 } },
  { name = "Pink",  rgb = { 1.0000, 0.4500, 0.8500 } },
}
function ESP.V3TitleVal()
  local i = tonumber(_G.SDWConfig and _G.SDWConfig.V3TitleColor) or 1
  if i < 1 or i > #ESP.V3_TITLE_COLORS then i = 1 end
  return i
end
function ESP.V3TitleRGB()
  local c = ESP.V3_TITLE_COLORS[ESP.V3TitleVal()].rgb
  return c[1], c[2], c[3]
end

-- [SDWxOWNER-PERF] Hoisted TextBlock builders (closure-free pcall targets).
local function _v3NewTextBlock(canvas) return CGame:NewObjectFromPath("/Script/UMG.TextBlock", canvas) end
local function _v3InitTextBlock(tb, canvas)
  tb:SetText("0")
  tb:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed)
  if tb.SetJustification then tb:SetJustification(1) end  -- center
  local slot = canvas:AddChildToCanvas(tb)
  if slot then
    slot:SetAutoSize(true)
    slot:SetAlignment(ESPV2(0.5, 0.5))
    slot:SetZOrder(1500)
  end
  return slot
end

-- Do digit TextBlocks (players / bots).  Rects ESP.V3Build mein staged bante hain.
function ESP.RibbonV3Create()
  local canvas = ESP.GetCanvas()
  if not ESPValid(canvas) then return nil end
  -- [SDWxOWNER-DOUBLE-FIX] HARD GUARD against an orphaned capsule. RibbonV3Create used to
  -- overwrite ESP.RibbonV3 / _G._SDW_V3_RB without tearing the PREVIOUS capsule down, so any
  -- call path that reached it while a live capsule still existed left ~1500 Border widgets
  -- (bar + stars + soldier + robot + gold "SDWxOWNER" title + shield + warn) parented to the
  -- canvas forever. The next capsule was then drawn ON TOP of them -> the gold title and the
  -- whole capsule looked DOUBLED. Destroying first makes "exactly one capsule" a hard
  -- invariant, not something that depends on every caller remembering to destroy.
  local _oldRB = ESP.RibbonV3 or _G._SDW_V3_RB
  if _oldRB then pcall(ESP.RibbonV3Destroy) end

  local fs = ESP.V3FontSize()
  local dc = ESP.V3DigitCols()
  local function mkTxt()
    local tb, slot = nil, nil
    local okT, t = pcall(_v3NewTextBlock, canvas)
    if okT then tb = t end
    if not ESPValid(tb) then return nil, nil end
    local okI, s = pcall(_v3InitTextBlock, tb, canvas)
    if okI then slot = s end
    ESP.V3ApplyDigit(tb, 1, fs)
    return tb, slot
  end

  local rb = { Layers = {}, parts = 0, hidden = true, ready = false, bi = 1, bj = 1, detail = ESP.V3DetailVal() }
  rb.TxtL, rb.SlotL = mkTxt()    -- players (left)
  rb.TxtR, rb.SlotR = mkTxt()    -- bots (right)
  if not (rb.SlotL and rb.SlotR) then
    if rb.TxtL then ESP.Destroy({ Widget = rb.TxtL }) end
    if rb.TxtR then ESP.Destroy({ Widget = rb.TxtR }) end
    return nil
  end
  ESP.RibbonV3 = rb
  -- [SDWxOWNER-CRASH FIX] Mirror to the GLOBAL so the reference survives the per-match module
  -- re-load (ESP is a local table, recreated each load -> the old capsule used to be orphaned).
  _G._SDW_V3_RB = rb
  return rb
end

-- Staged build: har call mein max ESP.V3_BUILD_STEP rects (Border widgets) bante hain, sab Collapsed, aur apni
-- final jagah par rakhe jate hain (X, Y = capsule ka top-left). ready = true hone par hi kuch dikhta hai
-- (adhura bar kabhi nahi dikhta) aur tab sirf visibility badalni hoti hai.
function ESP.V3Build(rb, X, Y, cell, ppu)
  local data, order = ESP.V3_LAYERS, ESP.V3_LAYER_ORDER
  local budget = ESP.V3_BUILD_STEP or 60
  while budget > 0 do
    local name = order[rb.bi]
    if not name then
      rb.ready = true
      return
    end
    local layer = data[name]
    local ly = rb.Layers[name]
    if not ly then
      local cols = {}
      local _themed = (name == "bar")   -- only the background capsule takes the colour theme
      local _isTitle = (name == "title") -- the SDWxOWNER wordmark takes the title colour
      local tr, tg, tb
      if _isTitle and ESP.V3TitleRGB then tr, tg, tb = ESP.V3TitleRGB() end
      for i, e in ipairs(layer.pal) do
        local cr, cg, cb = e[1], e[2], e[3]
        if _themed and ESP.V3ThemeRGB then cr, cg, cb = ESP.V3ThemeRGB(cr, cg, cb) end
        if _isTitle and tr then cr, cg, cb = tr, tg, tb end
        cols[i] = ESP(cr, cg, cb, e[4])
      end
      ly = { parts = {}, cols = cols, shown = false }
      rb.Layers[name] = ly
    end
    local r = layer.r
    -- greedy fit: list ka har prefix ek poori (thodi moti) picture hai => detail < 1 par bas aakhir ke rects chhod do
    local nrect = math.floor(#r / 6)
    if (rb.detail or 1) < 1 and name ~= "title" then nrect = math.max(1, math.floor(nrect * rb.detail + 0.5)) end
    local j = rb.bj
    while j <= nrect and budget > 0 do
      local o = (j - 1) * 6
      -- [SDWxOWNER-FIX] Guard the palette lookup: some art uses 0-based
      -- colour indices, but `cols` is 1-based -> cols[0] is nil and the
      -- Border would silently keep its default WHITE brush. Never let that
      -- happen again: fall back to the next / first palette entry.
      local _ci = r[o + 5]
      local _col = ly.cols[_ci] or ly.cols[_ci + 1] or ly.cols[1]
      local ln = ESP.V3NewRect(_col, layer.z + r[o + 6])
      if not ln then
        rb.bj = j          -- canvas abhi taiyaar nahi: agle Update mein wahin se aage
        return
      end
      local p = { ln = ln, x1 = r[o + 1], y1 = r[o + 2], x2 = r[o + 3], y2 = r[o + 4] }
      ly.parts[#ly.parts + 1] = p
      ESP.V3Place(ln, X + p.x1 * cell, Y + p.y1 * cell, X + p.x2 * cell, Y + p.y2 * cell, ppu)
      j = j + 1
      budget = budget - 1
    end
    rb.bj = j
    if j > nrect then
      rb.bi = rb.bi + 1
      rb.bj = 1
    end
  end
end

-- [SDWxOWNER-PERF] Hoisted digit writers (closure-free pcall targets).
local function _v3SetSlotPos(slot, x, y) slot:SetPosition(ESPV2(x, y)) end
local function _v3SetTextNum(tb, n) tb:SetText(tostring(n)) end

-- Digits: sirf warning (enemy) state mein. 0 = hara, 1+ = peela. Position/size/text/colour sirf badalne par.
function ESP.V3UpdateDigits(rb, alert, nP, nB, X, Y, cell)
  if not alert then
    if rb.txtShown then ESP.V3HideText(rb) end
    return
  end
  local fs = ESP.V3FontSize()
  if rb.dgx ~= X or rb.dgy ~= Y or rb.dgc ~= cell or rb.dgf ~= fs then
    rb.dgx, rb.dgy, rb.dgc = X, Y, cell
    local dl, dr = ESP.V3_DIG_L, ESP.V3_DIG_R
    -- digit ka visual center reference ke anchor par; HUD font ka digit widget-center se 0.115*size upar baithta hai
    local off = fs * 0.115
    pcall(_v3SetSlotPos, rb.SlotL, X + dl[1] * cell, Y + dl[2] * cell + off)
    pcall(_v3SetSlotPos, rb.SlotR, X + dr[1] * cell, Y + dr[2] * cell + off)
  end
  local kl = (nP > 0) and 2 or 1
  local kr = (nB > 0) and 2 or 1
  if rb.kl ~= kl or rb.dgf ~= fs then
    rb.kl = kl
    ESP.V3ApplyDigit(rb.TxtL, kl, fs)
  end
  if rb.kr ~= kr or rb.dgf ~= fs then
    rb.kr = kr
    ESP.V3ApplyDigit(rb.TxtR, kr, fs)
  end
  rb.dgf = fs
  if rb.LastP ~= nP then
    rb.LastP = nP
    pcall(_v3SetTextNum, rb.TxtL, nP)
  end
  if rb.LastB ~= nB then
    rb.LastB = nB
    pcall(_v3SetTextNum, rb.TxtR, nB)
  end
  if not rb.txtShown then
    rb.txtShown = true
    -- [SDWxOWNER-PERF] No ipairs({...}) alloc, no per-widget closure.
    local wl, wr = rb.TxtL, rb.TxtR
    if ESPValid(wl) then pcall(_wSetSelfHit, wl) end
    if ESPValid(wr) then pcall(_wSetSelfHit, wr) end
  end
end

-- cx = screen center X.  players+bots > 0 => warning triangle + digits, warna green shield (digits nahi)
function ESP.UpdateRibbonV3(nPlayers, nBots, cx)
  -- [SDWxOWNER-CRASH FIX] Restore the capsule reference from the GLOBAL (reload-safe). Validate it
  -- first: if the widgets died (map change) drop the stale ref so a fresh capsule is built. This is
  -- what stops the iOS "SDWxOWNER" gold capsule from DOUBLING on match 2 (old capsule was orphaned
  -- and a new one was stacked on top of it because ESP.RibbonV3 reset to nil on every re-load).
  local _prevRB = _G._SDW_V3_RB
  if _prevRB and not (ESPValid(_prevRB.TxtL) and ESPValid(_prevRB.TxtR)) then _prevRB = nil end
  _G._SDW_V3_RB = _prevRB
  ESP.RibbonV3 = _prevRB
  local rb = ESP.RibbonV3
  if not (_G.SDWConfig and _G.SDWConfig.EnemyCounterIOS) then
    if rb then ESP.RibbonV3Hide() end
    return
  end
  -- V3 ON => V2 aur uska watermark band
  if ESP.Ribbon then ESP.RibbonHide() end
  ESP.WMHide()

  local _v3col = ESP.V3ColorVal and ESP.V3ColorVal() or 1
  local _v3tc  = ESP.V3TitleVal and ESP.V3TitleVal() or 1
  if not rb or not ESP.RibbonV3Ok(rb) or rb.detail ~= ESP.V3DetailVal() or rb.v3col ~= _v3col or rb.v3tc ~= _v3tc then
    -- [SDWxOWNER-PERF] Creation-retry backoff (borrowed from new.lua's _CounterLastAttempt
    -- pattern). If the capsule is not built YET (canvas / HUD still coming up during match
    -- load), do NOT re-attempt the (relatively costly) widget creation on every 15 Hz beat --
    -- throttle to one attempt per 0.5 s. This removes the load-time rebuild storm while the
    -- HUD canvas is still being created. When `rb` already exists (theme / quality change, or
    -- a stale-widget refresh) the throttle is bypassed, so user-initiated changes still apply
    -- instantly and NO feature is affected.
    local _now = ESP._now or ESP.Now()
    if not rb and ESP._v3CreateT and (_now - ESP._v3CreateT) < 0.5 then return end
    if rb then ESP.RibbonV3Destroy() end
    ESP._v3CreateT = _now
    rb = ESP.RibbonV3Create()
    if not rb then return end
    rb.v3col = _v3col
    rb.v3tc  = _v3tc
  end
  nPlayers = math.floor((tonumber(nPlayers) or 0) + 0.5)
  nBots    = math.floor((tonumber(nBots) or 0) + 0.5)
  local alert = (nPlayers + nBots) > 0
  -- release hold: alert -> safe swap 400 widgets ki visibility badalta hai; count flicker kare to bar-bar na ho
  do
    local hold = tonumber(ESP.V3_HOLD) or 0
    if hold > 0 then
      local now = ESP._now or ESP.Now()
      if alert then
        rb.holdUntil = now + hold
      elseif rb.holdUntil then
        local left = rb.holdUntil - now
        if left > 0 and left <= hold + 0.05 then
          alert = true                      -- hold abhi chal raha hai
        else
          rb.holdUntil = nil                -- khatam (ya clock peeche gaya => purana hold chhod do, alert atakta nahi)
        end
      end
    end
  end

  local cell = ESP.V3Cell()
  local ppu  = ESP.GetPPU()
  cx = RND(cx)
  -- origin ko pehle device pixel par snap: phir har dp-cell ki edge poore pixel par girti hai (half-pixel rounding ka jhanjhat nahi)
  local X = math.floor((cx - ESP.V3_W_DP * cell * 0.5) * ppu + 0.5) / ppu                        -- capsule ka left edge
  local Y = math.floor(((ESP.V3_TOPY or 47) + ESP.V3_TITLE_BLOCK * cell) * ppu + 0.5) / ppu      -- capsule ka top (title uske upar)

  if not rb.ready then
    ESP.V3Build(rb, X, Y, cell, ppu)
    if not rb.ready then return end
  end

  -- [SDWxOWNER-PERF FIX #4] V3 COUNTER DIRTY-CACHE FAST PATH. If the capsule is already built
  -- and visible and NOTHING that affects the rendered picture changed since the last frame --
  -- alert state, player/bot counts, capsule origin (with a sub-pixel epsilon so the snapped-grid
  -- jitter can never defeat it) and the cell/ppu scale -- skip the ENTIRE 1500+ widget layer pass
  -- (bar / stars / soldier / robot / title / shield / warn) plus the digit pass. A stationary
  -- count with a still camera now costs ~0 work per beat instead of walking every layer's part
  -- list. The gate only ever engages on a fully-built, visible capsule, so the first paint and
  -- every state change still run the full path. `_lastX`/`_lastY` are seeded by the full pass
  -- below, so they are non-nil the first time the gate can possibly engage.
  if rb.ready and not rb.hidden
     and rb._lastAlert == alert
     and rb.LastP == nPlayers and rb.LastB == nBots
     and rb._lastX and math.abs(rb._lastX - X) < 0.1
     and rb._lastY and math.abs(rb._lastY - Y) < 0.1
     and rb.dCell == cell and rb.dPpu == ppu then
    rb.bottomY = Y + ESP.V3_H_DP * cell
    return
  end
  rb._lastAlert, rb._lastX, rb._lastY = alert, X, Y
  rb.dCell, rb.dPpu = cell, ppu
  rb.hidden = false

  local L = rb.Layers
  ESP.V3ShowLayer(L.bar,     X, Y, cell, ppu)
  ESP.V3ShowLayer(L.stars,   X, Y, cell, ppu)
  ESP.V3ShowLayer(L.soldier, X, Y, cell, ppu)
  ESP.V3ShowLayer(L.robot,   X, Y, cell, ppu)
  ESP.V3ShowLayer(L.title,   X, Y, cell, ppu)
  if alert then
    ESP.V3HideLayer(L.shield)
    ESP.V3ShowLayer(L.warn, X, Y, cell, ppu)
  else
    ESP.V3HideLayer(L.warn)
    ESP.V3ShowLayer(L.shield, X, Y, cell, ppu)
  end
  ESP.V3UpdateDigits(rb, alert, nPlayers, nBots, X, Y, cell)
  -- [SDWxOWNER-PERF FIX #4] Record the rendered counts as the fast-path's "last painted" values.
  -- V3UpdateDigits already mirrors these while alert is on; setting them here (AFTER the digit
  -- pass, so its SetText gating still compares against the previous frame's value) keeps them
  -- correct in the no-enemy (shield) state too, which is what lets the fast path engage there.
  rb.LastP, rb.LastB = nPlayers, nBots

  rb.bottomY = Y + ESP.V3_H_DP * cell        -- snap lines yahin se neeche shuru hoti hain (UpdateCounter)
end
-- <<< V3 END

    -- =====================================================================
    -- [SDWxOWNER] V3 counter runtime: exposure + ~20 Hz self-sustaining driver
    -- =====================================================================
    -- Expose the counter to the rest of the framework (menus / cleanup / driver).
    _G.SDW_V3Counter = {
        Update  = ESP.UpdateRibbonV3,
        Destroy = ESP.RibbonV3Destroy,
        Hide    = ESP.RibbonV3Hide,
    }

    -- Screen-centre X for the capsule, in canvas-local units:
    -- viewportWidth * 0.5 (screen px) mapped onto the canvas the capsule lives on.
    -- [SDWxOWNER-PERF] Hoisted probes for SDW_V3CenterX (called ~20 Hz by the V3 driver).
    -- The old inline pcall(function() ... end) bodies allocated three closures per beat;
    -- these named probes are created once and driven through scratch locals (zero alloc).
    -- Wrapped in a nested do-block with a forward-declared function so the helper slots are
    -- released afterwards and do not count against LuaJIT's 200-local limit.
    local SDW_V3CenterX
    do
    local _v3cxPC, _v3cxVW = nil, 0
    -- [SDWxOWNER-PERF] Reusable scratch vectors. The old code allocated a fresh ESPV2(0,0)
    -- inside _v3cxViewportProbe AND a fresh ESPV2(_v3cxPix,0) inside _v3cxCanvasProbe on
    -- EVERY 20 Hz beat -> constant garbage. These are created once and mutated in place.
    local _v3cxVS = ESPV2(0, 0)
    local _v3cxIn = ESPV2(0, 0)
    local function _v3cxViewportProbe()
        local pc = _v3cxPC
        if pc and pc.GetViewportSize then
            local vs = _v3cxVS
            vs.X = 0; vs.Y = 0
            pc:GetViewportSize(vs)
            if vs and vs.X and vs.X > 200 then _v3cxVW = vs.X end
        end
    end
    local function _v3cxWLLProbe()
        local WLL = _ci_WLL
        if WLL and WLL.GetViewportSize then
            local vs = WLL.GetViewportSize(_v3cxPC)
            if vs and vs.X and vs.X > 200 then _v3cxVW = vs.X end
        end
    end
    local _v3cxPix, _v3cxOut = 0, 0
    local function _v3cxCanvasProbe()
        local S = _G.SnaplineESP
        if S and S.ScreenPixelToCanvasLocal then
            local inp = _v3cxIn
            inp.X = _v3cxPix; inp.Y = 0
            local cp = S.ScreenPixelToCanvasLocal(_v3cxPC, inp)
            if cp and cp.X then _v3cxOut = cp.X end
        end
    end
    -- [SDWxOWNER-PERF] The viewport WIDTH only changes on a resolution / orientation change, so
    -- probing it (a native GetViewportSize call) on every 20 Hz beat was pure redundant work.
    -- Cache the resolved width for 0.5 s. The canvas-local X itself is STILL recomputed every
    -- call (pure arithmetic, no native) so it always tracks the 1 s canvas-transform refresh and
    -- the capsule stays exactly centred. Behaviour is identical; only the native probe is skipped.
    local _v3cxVWT, _v3cxVWC = -1e9, 1920
    SDW_V3CenterX = function(pc)
        _v3cxPC = pc
        local now = os.clock()
        local vw
        if _v3cxVWT >= 0 and (now - _v3cxVWT) < 0.5 then
            vw = _v3cxVWC
        else
            _v3cxVW = 0
            pcall(_v3cxViewportProbe)
            vw = _v3cxVW
            if vw <= 200 then
                _v3cxVW = 0
                pcall(_v3cxWLLProbe)
                vw = _v3cxVW
            end
            if vw <= 200 then vw = 1920 end
            _v3cxVWT = now
            _v3cxVWC = vw
        end
        local cxPix = vw * 0.5
        _v3cxPix = cxPix; _v3cxOut = cxPix
        pcall(_v3cxCanvasProbe)
        return _v3cxOut
    end
    end
    _G.SDW_V3CenterX = SDW_V3CenterX

    -- ~20 Hz self-sustaining driver (mirrors SDW_EnsureSnapline): the staged widget
    -- build never stalls the game, and the chain dies cleanly on match change / OFF.
    _G.SDW_V3 = _G.SDW_V3 or {}
    local V3 = _G.SDW_V3
    V3.gen = V3.gen or -1
    V3.running = V3.running or false
    V3.chain = V3.chain or 0
    V3.n = V3.n or 0

    local function SDW_StopV3Counter()
        V3.running = false
        V3.chain = (V3.chain or 0) + 1
        if _G.SDW_V3Counter and _G.SDW_V3Counter.Destroy then pcall(_G.SDW_V3Counter.Destroy) end
    end
    _G.SDW_StopV3Counter = SDW_StopV3Counter

    -- [SDWxOWNER-PERF] Hoisted V3 driver body. The old inline pcall(function() ... end)
    -- allocated a fresh closure on every 0.05s (20 Hz) driver beat; this named function is
    -- created once, so the steady-state driver allocates nothing extra. Behaviour identical.
    local function _v3DriverBody()
        local S = _G.SnaplineESP
        if S and S.InitESPCanvas then pcall(S.InitESPCanvas) end
        local _, _, _, pc = GetFrameCache()
        if not pc then return end
        if S and S.UpdateCanvasTransform then pcall(S.UpdateCanvasTransform, pc) end
        local cx = SDW_V3CenterX(pc)
        if _G.SDW_V3Counter then
            ESP._now = os.clock()
            ESP._vep = _G._SDW_MatchGen or 0
            _G.SDW_V3Counter.Update(_G._Counter_Players or 0, _G._Counter_Bots or 0, cx)
        end
    end
    local function SDW_V3DriverTick()
        if not V3.running then return end
        local myChain = V3.chain
        -- A driver left over from a PREVIOUS match stops itself (and drops its widgets).
        if V3.gen ~= (_G._SDW_MatchGen or 0) then
            V3.running = false
            if _G.SDW_V3Counter and _G.SDW_V3Counter.Destroy then pcall(_G.SDW_V3Counter.Destroy) end
            return
        end
        if not (_G.LOGIN_OK and _G.SDWConfig and _G.SDWConfig.EnemyCounterIOS) then
            V3.running = false
            if _G.SDW_V3Counter and _G.SDW_V3Counter.Destroy then pcall(_G.SDW_V3Counter.Destroy) end
            return
        end
        V3.n = V3.n + 1
        pcall(_v3DriverBody)
        -- Reschedule on the global ticker (survives owner invalidation). The chain
        -- token guarantees exactly ONE live chain even across a stop/restart.
        local t = _G.SDW_GetTicker and _G.SDW_GetTicker()
        if t and V3.running and V3.chain == myChain then
            -- [SDWxOWNER-PERF] Counter capsule driver relaxed 0.05s (20 Hz) -> 0.066s (15 Hz).
            -- The enemy-count capsule is a HUD readout; 15 Hz is visually identical and trims
            -- the steady-state callback load. The canvas transform keeps its own 1 s cache, so
            -- nothing else changes.
            t.AddTimerOnce(0.066, SDW_V3DriverTick)
        end
    end

    function _G.SDW_EnsureV3Counter()
        if not _G.LOGIN_OK then return end
        if not (_G.SDWConfig and _G.SDWConfig.EnemyCounterIOS) then
            SDW_StopV3Counter()
            return
        end
        local gen = _G._SDW_MatchGen or 0
        if V3.gen ~= gen then
            -- New match: drop the old driver + all old widgets, then start clean.
            SDW_StopV3Counter()
            V3.gen = gen
            V3.n = 0
        end
        if V3.running then
            pcall(function() local S = _G.SnaplineESP; if S and S.InitESPCanvas then S.InitESPCanvas() end end)
            return
        end
        V3.running = true
        V3.chain = (V3.chain or 0) + 1
        pcall(SDW_V3DriverTick)
    end

    -- =====================================================================
    -- [SDWxOWNER] V4 "HD Image" Enemy Counter  (SDWxOWNER VIP Image Counter)
    -- ---------------------------------------------------------------------
    -- Faithful, THEMEABLE vector reproduction of the in-game reference banner:
    -- a vivid red banner with a centre divider and "B:" / "E:" readouts.
    --   * Drawn with a couple of canvas Borders (a flat fill + a centre
    --     divider) plus two TextBlocks -> razor-sharp at EVERY resolution and
    --     essentially free: the widgets are built ONCE and only re-placed when
    --     origin / size / colour / counts change.
    --   * COLOUR OPTIONS : 11 vivid themes (Red = default) -> EnemyCounterHDColor
    --   * SIZE INCREASER : percent, 40..260 (default 125)  -> EnemyCounterHDSize
    --   * MOVE           : left/right + up/down offsets     -> EnemyCounterHDPosX / PosY
    --   * Sits at the SAME spot as the iOS counter and is mutually exclusive
    --     with the other three counters.
    -- [SDWxOWNER-PERF] Wrapped in an immediately-invoked function so the V4 module gets its
    -- OWN 200-local budget and adds ZERO locals to the enclosing __SDW_ModMain scope (which is
    -- already close to Lua's limit). All the module's locals become upvalues of the exposed
    -- globals, so behaviour is unchanged.
    -- =====================================================================
    (function()
    -- ---- geometry (normalised to the banner) ----
    local CAP_ASPECT = 3.94       -- banner width : height (measured from the in-game reference: 193 x 49 px)
    local CAP_WFRAC  = 0.080      -- default banner width as a fraction of the screen width
    local TX_L, TX_R = 0.256, 0.744   -- text centre X (fraction of banner width)
    local TX_Y       = 0.500          -- text centre Y (fraction of banner height)
    local TXT_HFRAC  = 0.56           -- text height (fraction of banner height)
    local DIV_WFRAC  = 0.018          -- centre-divider width (fraction of banner width)
    local NBANDS     = 1              -- single flat fill (matches the in-game banner; was a 16-band gradient)

    -- ---- colour themes (sRGB base colour).  Index 1 (Red) is the default and
    -- matches the vivid red of the reference / game screenshot.
    -- Optional per-theme fields:  txtL/txtR = text colour override (left/right),
    -- noLetters = hide the "B:" / "E:" prefixes (numbers only),
    -- div = divider colour override, light = light background (divider goes grey).
    local THEMES = {
      { r=205, g=20,  b=25  },   -- 1  Red    (default; measured from the in-game banner)
      { r=0,   g=215, b=60  },   -- 2  Green
      { r=45,  g=115, b=242 },   -- 3  Blue
      { r=28,  g=205, b=215 },   -- 4  Cyan
      { r=236, g=236, b=236,     -- 5  White  (ORIGINAL working look: light banner, B side = cyan, E side = red, no letters)
        txtL={28,205,215}, txtR={205,20,25}, noLetters=true, div={168,168,172}, light=true },
    }

    -- [SDWxOWNER-PERF] Hoisted closure-free pcall targets.
    local function _v4SetBrush(w, col) w:SetBrushColor(col) end
    local function _v4SetText(tb, s) tb:SetText(s) end
    local function _v4SetPos(slot, x, y) slot:SetPosition(ESPV2(x, y)) end
    -- [SDWxOWNER] V4 readout FONT. The reference "B:" / "E:" glyphs are a heavy sans
    -- (Roboto), the same face as the v5 banner. Pin the engine Roboto face and pick the
    -- weight from the menu.  1 = Regular   2 = Medium   3 = Bold (default).
    local _V4_TYPEFACE = { [1] = "Regular", [2] = "Medium", [3] = "Bold" }
    local function _v4GetFontAsset()
      local f = _G._SDW_V4_FontAsset
      if f ~= nil then return f end
      f = false
      pcall(function() f = slua.loadObject("/Engine/EngineFonts/Roboto.Roboto") end)
      if not f then pcall(function() f = slua.loadObject("/Engine/EngineFonts/Roboto") end) end
      _G._SDW_V4_FontAsset = f or false
      return f or nil
    end
    -- PLAIN text: NO outline / stroke and NO shadow (user request: "normal only white
    -- text, ss jaisa" -- no black outline around B/E).  Now also pins the Roboto face so
    -- the glyphs match the reference screenshot (same treatment as the v5 readouts).
    local function _v4ApplyFontPlain(w, size, weight)
      local f = w.Font
      if not f then return end
      f.Size = size
      local rf = _v4GetFontAsset()
      if rf then
        pcall(function() f.FontObject = rf end)
        pcall(function() f.TypefaceFontName = _V4_TYPEFACE[weight] or "Bold" end)
      end
      local o = f.OutlineSettings
      if o then
        o.OutlineSize = 0
        f.OutlineSettings = o
      end
      w:SetFont(f)
    end
    local function _v4NoShadow(w)
      if w.SetShadowOffset then w:SetShadowOffset(ESPV2(0, 0)) end
    end

    local function V4Col(r, g, b, a)
      return ESP(ESP.V3S2L(r), ESP.V3S2L(g), ESP.V3S2L(b), a or 1.0)
    end

    -- gradient shade for band i (0..NBANDS-1): bright in the middle, a touch
    -- darker at the very top / bottom edge (mirrors the reference art's depth).
    local function V4Shade(i)
      local t = (i + 0.5) / NBANDS
      return 0.905 + 0.095 * math.sin(math.pi * t)
    end

    -- ---- widget teardown ----
    local function V4DestroyRb(rb)
      if not rb then return end
      local bands, divs = rb.bands, rb.divs
      if bands then for i = 1, #bands do if bands[i].ln then ESP.Destroy(bands[i].ln) end end end
      if divs  then for i = 1, #divs  do if divs[i].ln  then ESP.Destroy(divs[i].ln)  end end end
      if rb.txtL then ESP.Destroy({ Widget = rb.txtL }) end
      if rb.txtR then ESP.Destroy({ Widget = rb.txtR }) end
    end
    local function V4Destroy()
      local rb = _G._SDW_V4_RB
      _G._SDW_V4_RB = nil
      V4DestroyRb(rb)
    end
    _G.SDW_V4Destroy = V4Destroy

    -- ---- build (once) ----
    local function V4MakeText(canvas)
      local tb = nil
      local okT, t = pcall(function() return CGame:NewObjectFromPath("/Script/UMG.TextBlock", canvas) end)
      if okT then tb = t end
      if not ESPValid(tb) then return nil, nil end
      local slot = nil
      pcall(function()
        tb:SetText("0")
        tb:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed)
        if tb.SetJustification then tb:SetJustification(1) end
        slot = canvas:AddChildToCanvas(tb)
        if slot then
          slot:SetAutoSize(true)
          slot:SetAlignment(ESPV2(0.5, 0.5))
          slot:SetZOrder(1500)
        end
      end)
      return tb, slot
    end

    local function V4Create()
      local canvas = ESP.GetCanvas()
      if not ESPValid(canvas) then return nil end
      local rb = { bands = {}, divs = {}, hidden = true, ready = false, theme = 0 }
      for i = 1, NBANDS do
        local ln = ESP.V3NewRect(V4Col(216, 20, 24, 1.0), 1000)
        if not ln then V4DestroyRb(rb); return nil end
        rb.bands[i] = { ln = ln, i = i }
      end
      local dv = ESP.V3NewRect(V4Col(121, 3, 4, 1.0), 1100)
      if not dv then V4DestroyRb(rb); return nil end
      rb.divs[1] = { ln = dv }
      rb.txtL, rb.slotL = V4MakeText(canvas)
      rb.txtR, rb.slotR = V4MakeText(canvas)
      if not (rb.slotL and rb.slotR) then V4DestroyRb(rb); return nil end
      rb.ready = true
      return rb
    end

    -- ---- recolour every band + the divider for the chosen theme (rare) ----
    local function V4ApplyTheme(rb, ti)
      local th = THEMES[ti] or THEMES[1]
      local bands = rb.bands
      for i = 1, #bands do
        local ln = bands[i].ln
        local sh = V4Shade(i - 1)
        local r = th.r * sh; if r > 255 then r = 255 end
        local g = th.g * sh; if g > 255 then g = 255 end
        local b = th.b * sh; if b > 255 then b = 255 end
        if ESPValid(ln.Widget) then pcall(_v4SetBrush, ln.Widget, V4Col(r, g, b, 1.0)) end
      end
      -- divider: the SAME hue, strongly darkened & desaturated -> a crisp DARK-RED
      -- slot (reference / screenshot ~RGB(122,0,0)), never grey.  Light themes
      -- (e.g. White) use their own grey divider so it reads correctly on white.
      local dcol
      if th.div then
        dcol = V4Col(th.div[1], th.div[2], th.div[3], 1.0)
      else
        dcol = V4Col(th.r * 0.60, th.g * 0.06, th.b * 0.12, 1.0)
      end
      local divs = rb.divs
      for i = 1, #divs do
        if ESPValid(divs[i].ln.Widget) then pcall(_v4SetBrush, divs[i].ln.Widget, dcol) end
      end
      rb.theme = ti
    end

    -- ---- hide (collapse every widget, keep them for a fast re-show) ----
    local function V4Hide()
      local rb = _G._SDW_V4_RB
      if not rb or rb.hidden then return end
      rb.hidden = true
      local bands, divs = rb.bands, rb.divs
      for i = 1, #bands do pcall(_wSetCollapsed, bands[i].ln.Widget) end
      for i = 1, #divs  do pcall(_wSetCollapsed, divs[i].ln.Widget)  end
      if ESPValid(rb.txtL) then pcall(_wSetCollapsed, rb.txtL) end
      if ESPValid(rb.txtR) then pcall(_wSetCollapsed, rb.txtR) end
    end

    -- ---- per-frame place + text ----
    local function V4Update(nEnemy, nBot, cx)
      local rb = _G._SDW_V4_RB
      if rb and not (ESPValid(rb.txtL) and ESPValid(rb.txtR)) then rb = nil; _G._SDW_V4_RB = nil end
      local cfg = _G.SDWConfig
      if not (cfg and cfg.EnemyCounterHD) then
        if rb then V4Hide() end
        return
      end
      if not rb or not rb.ready then
        -- creation-retry backoff (canvas / HUD may still be coming up)
        local now = ESP._now or ESP.Now()
        if ESP._v4CreateT and (now - ESP._v4CreateT) < 0.5 then return end
        ESP._v4CreateT = now
        if rb then V4Destroy() end
        rb = V4Create()
        if not rb then return end
        _G._SDW_V4_RB = rb
      end
      nEnemy = math.floor((tonumber(nEnemy) or 0) + 0.5)
      nBot   = math.floor((tonumber(nBot)   or 0) + 0.5)
      local cell = ESP.V3Cell()
      local ppu  = ESP.GetPPU()
      cx = RND(cx)

      -- ---- user controls ----
      local ti = math.floor((tonumber(cfg.EnemyCounterHDColor) or 1) + 0.5)
      if ti < 1 then ti = 1 elseif ti > #THEMES then ti = #THEMES end
      -- [SDWxOWNER-LOCK] v4 counter size + position are LOCKED to their defaults on
      -- request (the +/- controls were removed from BOTH menus). Size 125% -> sc 1.25,
      -- PosX 0, PosY -53. Changing these config values no longer has any effect.
      local sc = 1.25
      local posX = 0
      local posY = -53

      -- capsule size in DATA UNITS (1 data unit = 1 px @1080p; 1920 = 1080p width)
      local W = CAP_WFRAC * 1920 * sc
      local H = W / CAP_ASPECT

      -- origin: the SAME spot as the iOS counter's capsule, plus the move offsets
      local X = math.floor((cx - W * cell * 0.5 + posX * cell) * ppu + 0.5) / ppu
      local Y = math.floor(((ESP.V3_TOPY or 47) + (ESP.V3_TITLE_BLOCK or 44) * cell + posY * cell) * ppu + 0.5) / ppu

      -- dirty-cache fast path: nothing visible changed -> do nothing at all.
      if not rb.hidden and rb.lx and math.abs(rb.lx - X) < 0.1 and math.abs(rb.ly - Y) < 0.1
         and rb.lc == cell and rb.lp == ppu and rb.lE == nEnemy and rb.lB == nBot
         and rb.lw == W and rb.lh == H and rb.theme == ti then
        return
      end
      if rb.theme ~= ti then V4ApplyTheme(rb, ti) end
      rb.lx, rb.ly, rb.lc, rb.lp = X, Y, cell, ppu
      rb.lw, rb.lh = W, H
      rb.lE, rb.lB = nEnemy, nBot
      rb.hidden = false
      local vis = UEnums.ESlateVisibility.SelfHitTestInvisible
      local bands, divs = rb.bands, rb.divs
      local Wc, Hc = W * cell, H * cell
      local bandH = Hc / NBANDS
      for i = 1, #bands do
        local t = bands[i]
        local y0 = Y + (t.i - 1) * bandH
        local y1 = Y + t.i * bandH
        if ESP.V3Place(t.ln, X, y0, X + Wc, y1, ppu) then
          pcall(_wSetVis, t.ln.Widget, vis)
        end
      end
      local dx0 = X + (0.5 - DIV_WFRAC * 0.5) * Wc
      local dx1 = X + (0.5 + DIV_WFRAC * 0.5) * Wc
      for i = 1, #divs do
        local t = divs[i]
        if ESP.V3Place(t.ln, dx0, Y, dx1, Y + Hc, ppu) then
          pcall(_wSetVis, t.ln.Widget, vis)
        end
      end
      -- text: "B:" + bots (left) / "E:" + enemies (right).  PLAIN white text --
      -- no black outline / stroke (like the game screenshot).  The White theme
      -- uses coloured text (B side cyan, E side red) and drops the letters.
      local th = THEMES[ti] or THEMES[1]
      local fs = math.max(6, math.floor(H * TXT_HFRAC * cell / 0.986 + 0.5))
      local fillL = ESP(1.0, 1.0, 1.0, 1.0)
      local fillR = ESP(1.0, 1.0, 1.0, 1.0)
      if th.txtL then fillL = V4Col(th.txtL[1], th.txtL[2], th.txtL[3], 1.0) end
      if th.txtR then fillR = V4Col(th.txtR[1], th.txtR[2], th.txtR[3], 1.0) end
      -- [SDWxOWNER-LOCK] v4 readout font LOCKED to Bold (weight 3) on request
      -- ("v4 mai bold lock"). The "Counter Font (v4)" menu control was removed.
      local fw = 3
      if rb.fs ~= fs or rb.tti ~= ti or rb.fw ~= fw then
        rb.fs, rb.tti, rb.fw = fs, ti, fw
        pcall(_v4ApplyFontPlain, rb.txtL, fs, fw)
        pcall(_v4ApplyFontPlain, rb.txtR, fs, fw)
        pcall(_v4NoShadow, rb.txtL)
        pcall(_v4NoShadow, rb.txtR)
        ESP.SetTextColor(rb.txtL, fillL)
        ESP.SetTextColor(rb.txtR, fillR)
      end
      if rb.px ~= X or rb.py ~= Y or rb.pc ~= cell or rb.pw ~= W or rb.ph ~= H then
        rb.px, rb.py, rb.pc, rb.pw, rb.ph = X, Y, cell, W, H
        pcall(_v4SetPos, rb.slotL, X + TX_L * Wc, Y + TX_Y * Hc)
        pcall(_v4SetPos, rb.slotR, X + TX_R * Wc, Y + TX_Y * Hc)
      end
      local sL, sR
      if th.noLetters then
        sL = tostring(nBot)
        sR = tostring(nEnemy)
      else
        sL = "B:" .. nBot
        sR = "E:" .. nEnemy
      end
      if rb.sL ~= sL then rb.sL = sL; pcall(_v4SetText, rb.txtL, sL) end
      if rb.sR ~= sR then rb.sR = sR; pcall(_v4SetText, rb.txtR, sR) end
      if ESPValid(rb.txtL) then pcall(_wSetSelfHit, rb.txtL) end
      if ESPValid(rb.txtR) then pcall(_wSetSelfHit, rb.txtR) end
    end

    -- ---- exposure + ~15 Hz self-sustaining driver (same pattern as V3) ----
    _G.SDW_V4Counter = { Update = V4Update, Destroy = V4Destroy, Hide = V4Hide }

    _G.SDW_V4 = _G.SDW_V4 or {}
    local V4 = _G.SDW_V4
    V4.gen = V4.gen or -1
    V4.running = V4.running or false
    V4.chain = V4.chain or 0

    local function SDW_StopV4Counter()
      V4.running = false
      V4.chain = (V4.chain or 0) + 1
      V4Destroy()
    end
    _G.SDW_StopV4Counter = SDW_StopV4Counter

    local function _v4DriverBody()
      local S = _G.SnaplineESP
      if S and S.InitESPCanvas then pcall(S.InitESPCanvas) end
      local _, _, _, pc = GetFrameCache()
      if not pc then return end
      if S and S.UpdateCanvasTransform then pcall(S.UpdateCanvasTransform, pc) end
      local cx = _G.SDW_V3CenterX and _G.SDW_V3CenterX(pc) or 0
      ESP._now = os.clock()
      ESP._vep = _G._SDW_MatchGen or 0
      V4Update(_G._Counter_Players or 0, _G._Counter_Bots or 0, cx)
    end

    local function SDW_V4DriverTick()
      if not V4.running then return end
      local myChain = V4.chain
      -- a driver left over from a PREVIOUS match stops itself (and drops its widgets)
      if V4.gen ~= (_G._SDW_MatchGen or 0) then
        V4.running = false
        V4Destroy()
        return
      end
      if not (_G.LOGIN_OK and _G.SDWConfig and _G.SDWConfig.EnemyCounterHD) then
        V4.running = false
        V4Destroy()
        return
      end
      pcall(_v4DriverBody)
      local t = _G.SDW_GetTicker and _G.SDW_GetTicker()
      if t and V4.running and V4.chain == myChain then
        t.AddTimerOnce(0.066, SDW_V4DriverTick)
      end
    end

    function _G.SDW_EnsureV4Counter()
      if not _G.LOGIN_OK then return end
      if not (_G.SDWConfig and _G.SDWConfig.EnemyCounterHD) then
        SDW_StopV4Counter()
        return
      end
      local gen = _G._SDW_MatchGen or 0
      if V4.gen ~= gen then
        -- new match: drop the old driver + all old widgets, then start clean
        SDW_StopV4Counter()
        V4.gen = gen
      end
      if V4.running then
        pcall(function() local S = _G.SnaplineESP; if S and S.InitESPCanvas then S.InitESPCanvas() end end)
        return
      end
      V4.running = true
      V4.chain = (V4.chain or 0) + 1
      pcall(SDW_V4DriverTick)
    end

    end)()
    -- ===== END SDWxOWNER V4 HD Image Counter module =====

    -- =====================================================================
    -- [SDWxOWNER] V5 "Player / Bot" Enemy Counter  (SDWxOWNER VIP v5 Counter)
    -- ---------------------------------------------------------------------
    -- Faithful vector reproduction of the supplied v5 reference banner: a
    -- rounded, glowing crimson capsule with a dark maroon interior that reads
    --     [red dot] Player - <n>        [green dot] Bot - <n>       (white)
    --   * Drawn with canvas Borders ONLY (no textures): a soft glow, the
    --     crimson border and the dark fill are each a rounded rectangle built
    --     from horizontal scanline strips; the two dots are circle strips.
    --     Razor-sharp at EVERY resolution and essentially free: the widgets
    --     are built ONCE and only re-placed when origin / size / colour /
    --     counts change.
    --   * COLOUR OPTIONS : 11 vivid themes (Red = default) -> EnemyCounterV5Color
    --   * SIZE INCREASER : percent, 40..260 (default 125)  -> EnemyCounterV5Size
    --   * MOVE           : left/right + up/down offsets     -> EnemyCounterV5PosX / PosY
    --   * Sits at the SAME spot as the v4 / iOS counter and is mutually
    --     exclusive with the other four counters.
    -- [SDWxOWNER-PERF] Wrapped in an immediately-invoked function so the V5
    -- module gets its OWN 200-local budget and adds ZERO locals to the
    -- enclosing __SDW_ModMain scope.
    -- =====================================================================
    ;(function()
      -- ---- geometry (all in "height units": banner = ASPECT wide x 1 tall,
      --      so circular corners stay circular at any size) ----
      local ASPECT    = 5.40     -- banner width : height (measured from the v5 reference)
      local CAP_WFRAC = 0.118    -- default banner width as a fraction of the screen width
      local CORNER_R  = 0.300    -- corner radius (height units)
      local BORDER_T  = 0.085    -- crimson border thickness (height units)
      local GLOW_T    = 0.065    -- soft outer glow expansion (height units)
      local KSTRIP    = 12       -- scanline strips per rounded corner
      -- [SDWxOWNER-V5-DOTCIRCLE] The dots are now drawn as DEVICE-PIXEL-ALIGNED circles: one
      -- 1-px strip per device pixel row (see V5PlaceLayer). NDOT is therefore the MAX number of
      -- pixel rows a dot can need (i.e. its max diameter in device px). 48 covers every size the
      -- counter offers (40..260%) with room to spare; unused rows are simply collapsed.
      local NDOT      = 48       -- max scanline strips per dot (one per device pixel row)
      local DOT_R     = 0.105    -- dot radius (height units)
      local DOT_LX    = 0.105 * ASPECT   -- left  dot centre X (height units)
      local DOT_RX    = 0.672 * ASPECT   -- right dot centre X (height units)
      local DOT_Y     = 0.500            -- dot centre Y (height units)
      local TXT_LX    = 0.364 * ASPECT   -- left  text centre X (height units)
      local TXT_RX    = 0.838 * ASPECT   -- right text centre X (height units)
      local TXT_Y     = 0.500            -- text centre Y (height units)
      -- [SDWxOWNER-FIX] Text height as a fraction of the banner height.  The heavy
      -- Roboto face (added for the screenshot match) is much WIDER than the old thin
      -- default face, so at 0.44 the two readouts collided in the middle and spilled
      -- out of the capsule.  Measured against the reference banner (text span = 0.43 of
      -- the banner height) and the in-game bug (0.54), the correct ratio is ~0.35, so
      -- "Player - N" / "Bot - N" sit clear of the dots and the edges.  This ratio is
      -- FIXED (the old "Counter Text Size (v5)" menu control was removed on request),
      -- so the readout always renders at this exact size.
      local TXT_HFRAC = 0.350            -- text height (fraction of banner height)

      -- [SDWxOWNER-V5-ADAPT] SINGLE-ENTRY ("Player only" / "Bot only") banner geometry.
      -- When one of the two counts is 0 the counter SHRINKS to a narrow capsule that shows
      -- ONLY the surviving entry -- exactly like the in-game reference:
      --     no bots    ->  [red dot]   Player - N            (narrow)
      --     no players ->  [green dot] Bot - N               (narrow)
      --     both       ->  [red dot] Player - N  [green dot] Bot - N   (full)
      local ASPECT_S  = 3.20     -- single-entry banner width : height
      local DOT_LX_S  = 0.115 * ASPECT_S   -- single-entry dot centre X (height units)
      local TXT_LX_S  = 0.575 * ASPECT_S   -- single-entry text centre X (height units)
      -- [SDWxOWNER-V5-WDOT] Radius of the WHITE centre dot drawn inside the PLAYER dot
      -- (the reference's player marker is a red dot with a bright / white core).
      -- [SDWxOWNER-V5-DOTCIRCLE] 0.045 -> 0.055: at the default counter size a 0.045 core is
      -- only ~4.7 device px, which the pixel grid can only draw as a 4x4 SQUARE. 0.055 lifts it
      -- to ~5.8 px so the pixel-aligned circle renders it as a true round dot (2/4/6/6/4/2 rows).
      -- [SDWxOWNER-V5-DOTCIRCLE-3] 0.055 -> 0.062: at the default counter size a 0.055 core
      -- was only ~2.9 device px radius, which the pixel grid could only draw as a 5x5 SQUARE
      -- (the "player dot is not circular" complaint). 0.062 lifts it to ~3.3 px so the
      -- pixel-aligned circle renders as a true round core (3/5/7/7/7/5/3 rows).
      -- [SDWxOWNER-V5-SCREENSHOT] FINAL: 0.062, i.e. the ORIGINAL value, untouched.
      -- 0.062 / 0.105 = 59% -- exactly the proportion visible in the reference screenshot
      -- (red dot R ~6.5 px, white core R ~3.9 px, ring ~2.7 px at the default counter size).
      -- No minimum-radius clamp and no cap are applied anywhere: the white core, the red dot and
      -- the green dot are all plain R * Hc * ppu, so the ring thickness is identical to the
      -- original build at EVERY counter size. Roundness comes only from the pixel-centre snap.
      local WC_R      = 0.062    -- white centre dot radius (height units) -- ORIGINAL, untouched

      -- ---- colour themes (sRGB).  Index 1 (Red) is the default and matches
      -- the vivid crimson of the v5 reference / game screenshot. ----
      local THEMES = {
        { r=214, g=34,  b=48  },   -- 1  Red    (default; measured from the v5 banner)
        { r=0,   g=215, b=60  },   -- 2  Green
        { r=45,  g=115, b=242 },   -- 3  Blue
        { r=28,  g=205, b=215 },   -- 4  Cyan
        { r=255, g=255, b=255 },   -- 5  White  (proper pure white)
      }

      -- ---- scanline strip generators (height units) ----
      local function _v5RoundStrips(w, h, r, k)
        local s = {}
        if r > h * 0.5 then r = h * 0.5 end
        if r < 0 then r = 0 end
        for i = 0, k - 1 do
          local y0 = r * i / k
          local y1 = r * (i + 1) / k
          local ym = (y0 + y1) * 0.5
          local dy = r - ym
          local ins = r - math.sqrt(math.max(0, r * r - dy * dy))
          s[#s + 1] = { x1 = ins, y1 = y0, x2 = w - ins, y2 = y1 }
        end
        s[#s + 1] = { x1 = 0, y1 = r, x2 = w, y2 = h - r }
        for i = 0, k - 1 do
          local y0 = (h - r) + r * i / k
          local y1 = (h - r) + r * (i + 1) / k
          local ym = (y0 + y1) * 0.5
          local dy = ym - (h - r)
          local ins = r - math.sqrt(math.max(0, r * r - dy * dy))
          s[#s + 1] = { x1 = ins, y1 = y0, x2 = w - ins, y2 = y1 }
        end
        return s
      end

      local function _v5CircleStrips(R, n)
        local s = {}
        for i = 0, n - 1 do
          local y0 = -R + 2 * R * i / n
          local y1 = -R + 2 * R * (i + 1) / n
          local ym = (y0 + y1) * 0.5
          local hw = math.sqrt(math.max(0, R * R - ym * ym))
          s[#s + 1] = { x1 = -hw, y1 = y0, x2 = hw, y2 = y1 }
        end
        return s
      end

      -- ---- precomputed strip sets (built once) ----
      local STR_GLOW1 = _v5RoundStrips(ASPECT + GLOW_T * 2, 1 + GLOW_T * 2, CORNER_R + GLOW_T, KSTRIP)
      local STR_BORD  = _v5RoundStrips(ASPECT, 1, CORNER_R, KSTRIP)
      local STR_FILL  = _v5RoundStrips(ASPECT - BORDER_T * 2, 1 - BORDER_T * 2, math.max(0.02, CORNER_R - BORDER_T), KSTRIP)
      local STR_DOT   = _v5CircleStrips(1.0, NDOT)   -- unit circle, scaled by DOT_R
      -- [SDWxOWNER-V5-ADAPT] single-entry (narrow) banner strips + white centre dot strips
      local STR_GLOW1_S = _v5RoundStrips(ASPECT_S + GLOW_T * 2, 1 + GLOW_T * 2, CORNER_R + GLOW_T, KSTRIP)
      local STR_BORD_S  = _v5RoundStrips(ASPECT_S, 1, CORNER_R, KSTRIP)
      local STR_FILL_S  = _v5RoundStrips(ASPECT_S - BORDER_T * 2, 1 - BORDER_T * 2, math.max(0.02, CORNER_R - BORDER_T), KSTRIP)
      local STR_WDOT    = _v5CircleStrips(1.0, NDOT)   -- unit circle, scaled by WC_R

      -- ---- hoisted closure-free pcall targets ----
      local function _v5SetBrush(w, col) w:SetBrushColor(col) end
      local function _v5SetText(tb, s) tb:SetText(s) end
      local function _v5SetPos(slot, x, y) slot:SetPosition(ESPV2(x, y)) end
      -- [SDWxOWNER] V5 readout FONT. The reference banner's "Player - N" / "Bot - N"
      -- text is a heavy sans (Roboto), not the thin default TextBlock face. We pin the
      -- readouts to the engine Roboto face and pick the weight from the menu.
      --   1 = Regular   2 = Medium   3 = Bold (default, matches the reference)
      local _V5_TYPEFACE = { [1] = "Regular", [2] = "Medium", [3] = "Bold" }
      local function _v5GetFontAsset()
        local f = _G._SDW_V5_FontAsset
        if f ~= nil then return f end
        f = false
        pcall(function() f = slua.loadObject("/Engine/EngineFonts/Roboto.Roboto") end)
        if not f then pcall(function() f = slua.loadObject("/Engine/EngineFonts/Roboto") end) end
        _G._SDW_V5_FontAsset = f or false
        return f or nil
      end

      local function _v5ApplyFontPlain(w, size, weight)
        local f = w.Font
        if not f then return end
        f.Size = size
        local rf = _v5GetFontAsset()
        if rf then
          pcall(function() f.FontObject = rf end)
          pcall(function() f.TypefaceFontName = _V5_TYPEFACE[weight] or "Bold" end)
        end
        local o = f.OutlineSettings
        if o then
          o.OutlineSize = 0
          f.OutlineSettings = o
        end
        w:SetFont(f)
      end
      local function _v5NoShadow(w)
        if w.SetShadowOffset then w:SetShadowOffset(ESPV2(0, 0)) end
      end

      local function V5Col(r, g, b, a)
        return ESP(ESP.V3S2L(r), ESP.V3S2L(g), ESP.V3S2L(b), a or 1.0)
      end

      -- ---- widget teardown ----
      local function V5DestroyRb(rb)
        if not rb then return end
        local layers = rb.layers
        if layers then
          for i = 1, #layers do
            local parts = layers[i].parts
            if parts then for j = 1, #parts do if parts[j].ln then ESP.Destroy(parts[j].ln) end end end
          end
        end
        if rb.txtL then ESP.Destroy({ Widget = rb.txtL }) end
        if rb.txtR then ESP.Destroy({ Widget = rb.txtR }) end
      end
      local function V5Destroy()
        local rb = _G._SDW_V5_RB
        _G._SDW_V5_RB = nil
        V5DestroyRb(rb)
      end
      _G.SDW_V5Destroy = V5Destroy

      -- ---- build (once) ----
      local function V5MakeText(canvas)
        local tb = nil
        local okT, t = pcall(function() return CGame:NewObjectFromPath("/Script/UMG.TextBlock", canvas) end)
        if okT then tb = t end
        if not ESPValid(tb) then return nil, nil end
        local slot = nil
        pcall(function()
          tb:SetText("0")
          tb:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed)
          if tb.SetJustification then tb:SetJustification(1) end
          slot = canvas:AddChildToCanvas(tb)
          if slot then
            slot:SetAutoSize(true)
            slot:SetAlignment(ESPV2(0.5, 0.5))
            slot:SetZOrder(1500)
          end
        end)
        return tb, slot
      end

      local function V5MakeLayer(strips, color, z)
        local parts = {}
        for i = 1, #strips do
          local ln = ESP.V3NewRect(color, z)
          if not ln then
            for j = 1, #parts do ESP.Destroy(parts[j].ln) end
            return nil
          end
          parts[i] = { ln = ln, s = strips[i] }
        end
        return parts
      end

      local function V5Create()
        local canvas = ESP.GetCanvas()
        if not ESPValid(canvas) then return nil end
        local rb = { layers = {}, hidden = true, ready = false, theme = 0 }
        rb.layers[1] = { ox = -GLOW_T,  oy = -GLOW_T,  parts = V5MakeLayer(STR_GLOW1, V5Col(214, 34, 48, 0.20), 995) }
        rb.layers[2] = { ox = 0,        oy = 0,        parts = V5MakeLayer(STR_BORD,  V5Col(214, 34, 48, 1.00), 1000) }
        rb.layers[3] = { ox = BORDER_T, oy = BORDER_T, parts = V5MakeLayer(STR_FILL,  V5Col(48, 16, 18, 0.92),   1005) }
        rb.layers[4] = { cx = DOT_LX, cy = DOT_Y, R = DOT_R, parts = V5MakeLayer(STR_DOT, V5Col(255, 60, 92, 1.0),  1010) }
        rb.layers[5] = { cx = DOT_RX, cy = DOT_Y, R = DOT_R, parts = V5MakeLayer(STR_DOT, V5Col(70, 220, 120, 1.0), 1010) }
        -- [SDWxOWNER-V5-ADAPT] narrow single-entry banner (shown only when one count is 0)
        rb.layers[6] = { ox = -GLOW_T,  oy = -GLOW_T,  parts = V5MakeLayer(STR_GLOW1_S, V5Col(214, 34, 48, 0.20), 995) }
        rb.layers[7] = { ox = 0,        oy = 0,        parts = V5MakeLayer(STR_BORD_S,  V5Col(214, 34, 48, 1.00), 1000) }
        rb.layers[8] = { ox = BORDER_T, oy = BORDER_T, parts = V5MakeLayer(STR_FILL_S,  V5Col(48, 16, 18, 0.92),   1005) }
        -- [SDWxOWNER-V5-WDOT] white centre dot drawn on top of the PLAYER dot
        rb.layers[9] = { cx = DOT_LX, cy = DOT_Y, R = WC_R, parts = V5MakeLayer(STR_WDOT, V5Col(255, 255, 255, 1.0), 1015) }
        for i = 1, #rb.layers do
          if not rb.layers[i].parts then V5DestroyRb(rb); return nil end
        end
        rb.txtL, rb.slotL = V5MakeText(canvas)
        rb.txtR, rb.slotR = V5MakeText(canvas)
        if not (rb.slotL and rb.slotR) then V5DestroyRb(rb); return nil end
        rb.ready = true
        return rb
      end

      -- ---- recolour for the chosen theme (rare) ----
      local function V5ApplyTheme(rb, ti)
        local th = THEMES[ti] or THEMES[1]
        local L = rb.layers
        local cg = V5Col(th.r, th.g, th.b, 0.20)
        local cb = V5Col(th.r, th.g, th.b, 1.00)
        local fr = th.r * 0.20 + 8; if fr > 255 then fr = 255 end
        local fg = th.g * 0.20 + 8; if fg > 255 then fg = 255 end
        local fb = th.b * 0.20 + 8; if fb > 255 then fb = 255 end
        local cf = V5Col(fr, fg, fb, 0.92)
        local function recolor(layer, col)
          local parts = layer.parts
          for i = 1, #parts do
            if ESPValid(parts[i].ln.Widget) then pcall(_v5SetBrush, parts[i].ln.Widget, col) end
          end
        end
        recolor(L[1], cg)
        recolor(L[2], cb)
        recolor(L[3], cf)
        -- [SDWxOWNER-V5-ADAPT] keep the narrow single-entry banner in sync with the theme
        recolor(L[6], cg)
        recolor(L[7], cb)
        recolor(L[8], cf)
        rb.theme = ti
      end

      -- ---- hide (collapse every widget, keep them for a fast re-show) ----
      local function V5Hide()
        local rb = _G._SDW_V5_RB
        if not rb or rb.hidden then return end
        rb.hidden = true
        local L = rb.layers
        for i = 1, #L do
          local parts = L[i].parts
          for j = 1, #parts do pcall(_wSetCollapsed, parts[j].ln.Widget) end
        end
        if ESPValid(rb.txtL) then pcall(_wSetCollapsed, rb.txtL) end
        if ESPValid(rb.txtR) then pcall(_wSetCollapsed, rb.txtR) end
      end

      -- ---- place every strip of one layer ----
      local function V5PlaceLayer(layer, X, Y, Hc, ppu, vis)
        local parts = layer.parts
        local ox, oy = layer.ox or 0, layer.oy or 0
        local cx, cy, R = layer.cx, layer.cy, layer.R
        -- [SDWxOWNER-V5-DOTCIRCLE] DOT layer -> draw a DEVICE-PIXEL-ALIGNED circle: exactly one
        -- 1-px-tall strip per device pixel row, each row's width taken at the row centre. The
        -- old code scaled a fixed 12-strip unit circle and then SNAPPED every strip to the pixel
        -- grid; adjacent strips collapsed onto the same row and the widest one won, so an ~11 px
        -- dot rendered as a blocky star instead of a round dot. Building the rows directly on the
        -- pixel grid gives a true circle at ANY size. The rows are already integer device pixels,
        -- so ESP.V3Place's snap is a no-op -> razor sharp, same widget count, no extra timer.
        if cx then
          local Rpx = R * Hc * ppu                 -- dot radius in device px
          -- [SDWxOWNER-V5-SCREENSHOT] EXACT ORIGINAL GEOMETRY.
          -- Every dot (red, green, white core) is now R * Hc * ppu with NO clamp of any kind,
          -- so the counter renders pixel-for-pixel like the reference screenshot:
          --   red / green dot  R = 0.105 * Hc   (untouched)
          --   white core       R = 0.062 * Hc   (untouched, 59% of the red radius)
          -- Earlier attempts added a minimum radius so the tiny white core would stay round, but
          -- that grew the core and ate the coloured ring ("red outline decrease", "dot size
          -- increase"). The ring is the priority, so all clamps are gone. Roundness at normal
          -- sizes comes from the pixel-centre snap below, which is what the screenshot shows.
          -- [SDWxOWNER-V5-DOTCIRCLE-2] THE REAL FIX for "player dot is not circular".
          -- The centre used to be the raw fractional device-pixel position (X + cx*Hc)*ppu.
          -- Because top = floor(cyd - Rpx + 0.5) and bot = floor(cyd + Rpx + 0.5), a
          -- fractional cyd makes the top and bottom row counts DIFFER by one (e.g. 5 rows up,
          -- 6 rows down) -> the circle is lopsided and reads as a blob / square on device.
          -- Snapping the centre to a PIXEL CENTRE (integer + 0.5) makes top/bot and left/right
          -- perfectly symmetric, so the row widths form a true circle at ANY radius. The 0.5 px
          -- shift is invisible.
          local cxd = math.floor((X + cx * Hc) * ppu) + 0.5   -- dot centre X in device px (pixel-centre snapped)
          local cyd = math.floor((Y + cy * Hc) * ppu) + 0.5   -- dot centre Y in device px (pixel-centre snapped)
          local top = math.floor(cyd - Rpx + 0.5)
          local bot = math.floor(cyd + Rpx + 0.5)
          local n = #parts
          local idx = 0
          for row = top, bot - 1 do
            local yc = (row + 0.5) - cyd
            if yc <= Rpx and yc >= -Rpx then
              local hw = math.sqrt(Rpx * Rpx - yc * yc)
              -- [SDWxOWNER-V5-DOTCIRCLE-3] Skip degenerate rows whose half-width is < 0.5 px.
              -- Without this, a row landing exactly on yc == Rpx produced hw == 0 -> a 1-px
              -- "spike" row at the top/bottom of the dot (the little tail that made the dot
              -- look like a teardrop instead of a circle).
              if hw >= 0.5 then
              local a = math.floor(cxd - hw + 0.5)
              local c = math.floor(cxd + hw + 0.5)
              if c <= a then c = a + 1 end
              idx = idx + 1
              if idx > n then break end
              local p = parts[idx]
              -- [SDWxOWNER-V5-DOTCIRCLE] place + ALWAYS (re)show the row. V3Place only WRITES
              -- when the pixel position changed, so gating the show on its return value could
              -- leave a row collapsed after a hide/show cycle; SetWidgetVisibility is a cheap
              -- early-out when the value is unchanged, so calling it every frame is free.
              ESP.V3Place(p.ln, a / ppu, row / ppu, c / ppu, (row + 1) / ppu, ppu)
              pcall(_wSetVis, p.ln.Widget, vis)
              end
            end
          end
          -- [SDWxOWNER-V5-DOTCIRCLE] Collapse ONLY the tail rows the current dot does not use,
          -- and only when the visible-row count actually changed. The dot radius is constant for
          -- a given resolution/size, so in the steady state this loop does nothing -> zero
          -- redundant UMG calls on the hot path.
          if layer.lastIdx ~= idx then
            for i = idx + 1, n do pcall(_wSetCollapsed, parts[i].ln.Widget) end
            layer.lastIdx = idx
          end
          return
        end
        for i = 1, #parts do
          local p = parts[i]
          local s = p.s
          local x1, y1, x2, y2
          x1 = X + (ox + s.x1) * Hc
          y1 = Y + (oy + s.y1) * Hc
          x2 = X + (ox + s.x2) * Hc
          y2 = Y + (oy + s.y2) * Hc
          if ESP.V3Place(p.ln, x1, y1, x2, y2, ppu) then
            pcall(_wSetVis, p.ln.Widget, vis)
          end
        end
      end

      -- [SDWxOWNER-V5-ADAPT] place a layer when it is needed, otherwise collapse it.
      -- (module-level so the hot path stays closure-free / garbage-free)
      local function V5Layer(layer, on, X, Y, Hc, ppu, vis)
        if on then
          V5PlaceLayer(layer, X, Y, Hc, ppu, vis)
        else
          local parts = layer.parts
          for i = 1, #parts do pcall(_wSetCollapsed, parts[i].ln.Widget) end
        end
      end

      -- ---- per-frame place + text ----
      local function V5Update(nEnemy, nBot, cx)
        local rb = _G._SDW_V5_RB
        if rb and not (ESPValid(rb.txtL) and ESPValid(rb.txtR)) then rb = nil; _G._SDW_V5_RB = nil end
        local cfg = _G.SDWConfig
        if not (cfg and cfg.EnemyCounterV5) then
          if rb then V5Hide() end
          return
        end
        if not rb or not rb.ready then
          local now = ESP._now or ESP.Now()
          if ESP._v5CreateT and (now - ESP._v5CreateT) < 0.5 then return end
          ESP._v5CreateT = now
          if rb then V5Destroy() end
          rb = V5Create()
          if not rb then return end
          _G._SDW_V5_RB = rb
        end
        nEnemy = math.floor((tonumber(nEnemy) or 0) + 0.5)
        nBot   = math.floor((tonumber(nBot)   or 0) + 0.5)
        local cell = ESP.V3Cell()
        local ppu  = ESP.GetPPU()
        cx = RND(cx)

        -- ---- user controls ----
        local ti = math.floor((tonumber(cfg.EnemyCounterV5Color) or 1) + 0.5)
        if ti < 1 then ti = 1 elseif ti > #THEMES then ti = #THEMES end
        local sz = tonumber(cfg.EnemyCounterV5Size) or 125
        if sz < 40 then sz = 40 elseif sz > 260 then sz = 260 end
        local sc = sz / 100
        local posX = tonumber(cfg.EnemyCounterV5PosX) or 0
        local posY = tonumber(cfg.EnemyCounterV5PosY) or -53

        -- [SDWxOWNER-V5-ADAPT] pick the layout:
        --   mode 1 = BOTH entries  (full capsule)
        --   mode 2 = PLAYER only   (narrow capsule)  <- when there are no bots
        --   mode 3 = BOT only      (narrow capsule)  <- when there are no players
        local mode
        if nEnemy > 0 and nBot > 0 then mode = 1
        elseif nEnemy > 0 then mode = 2
        elseif nBot > 0 then mode = 3
        else mode = 2 end            -- nothing on the field -> keep the player slot

        -- banner size in DATA UNITS (1 data unit = 1 px @1080p; 1920 = 1080p width).
        -- The HEIGHT is constant; only the WIDTH changes between the full and narrow layouts.
        local H = (CAP_WFRAC * 1920 * sc) / ASPECT
        local W = (mode == 1) and (ASPECT * H) or (ASPECT_S * H)

        -- origin: the SAME spot as the v4 / iOS counter's capsule, plus the move offsets
        local X = math.floor((cx - W * cell * 0.5 + posX * cell) * ppu + 0.5) / ppu
        local Y = math.floor(((ESP.V3_TOPY or 47) + (ESP.V3_TITLE_BLOCK or 44) * cell + posY * cell) * ppu + 0.5) / ppu

        -- dirty-cache fast path: nothing visible changed -> do nothing at all.
        if not rb.hidden and rb.lx and math.abs(rb.lx - X) < 0.1 and math.abs(rb.ly - Y) < 0.1
           and rb.lc == cell and rb.lp == ppu and rb.lE == nEnemy and rb.lB == nBot
           and rb.lw == W and rb.lh == H and rb.theme == ti and rb.lm == mode then
          return
        end
        if rb.theme ~= ti then V5ApplyTheme(rb, ti) end
        rb.lx, rb.ly, rb.lc, rb.lp = X, Y, cell, ppu
        rb.lw, rb.lh = W, H
        rb.lE, rb.lB = nEnemy, nBot
        rb.lm = mode
        rb.hidden = false
        local vis = UEnums.ESlateVisibility.SelfHitTestInvisible
        local Hc = H * cell
        local L = rb.layers

        -- [SDWxOWNER-V5-ADAPT] move the dots to the current layout's slots
        if mode == 1 then
          L[4].cx = DOT_LX;  L[5].cx = DOT_RX;  L[9].cx = DOT_LX
        else
          L[4].cx = DOT_LX_S; L[5].cx = DOT_LX_S; L[9].cx = DOT_LX_S
        end

        -- [SDWxOWNER-V5-ADAPT] show ONLY the layers the current layout needs
        local showFull   = (mode == 1)
        local showNarrow = (mode ~= 1)
        local showRed    = (mode == 1) or (mode == 2)
        local showGreen  = (mode == 1) or (mode == 3)
        local showWDot   = (mode == 1) or (mode == 2)
        V5Layer(L[1], showFull,   X, Y, Hc, ppu, vis)
        V5Layer(L[2], showFull,   X, Y, Hc, ppu, vis)
        V5Layer(L[3], showFull,   X, Y, Hc, ppu, vis)
        V5Layer(L[6], showNarrow, X, Y, Hc, ppu, vis)
        V5Layer(L[7], showNarrow, X, Y, Hc, ppu, vis)
        V5Layer(L[8], showNarrow, X, Y, Hc, ppu, vis)
        V5Layer(L[4], showRed,    X, Y, Hc, ppu, vis)
        V5Layer(L[5], showGreen,  X, Y, Hc, ppu, vis)
        V5Layer(L[9], showWDot,   X, Y, Hc, ppu, vis)

        -- text: "Player - <enemies>" (left) / "Bot - <bots>" (right).  PLAIN white
        -- text -- no black outline / stroke (like the v5 game screenshot).
        -- [SDWxOWNER-LOCK] v5 counter text size is LOCKED to the tuned default (95%).
        -- The "Counter Text Size (v5)" menu controls were removed on request
        -- ("koi change na kr paye"), so the readout ALWAYS uses this exact size.
        local tsz = 95
        local fs = math.max(6, math.floor(H * TXT_HFRAC * (tsz / 100) * cell / 0.986 + 0.5))
        -- [SDWxOWNER-LOCK] v5 readout font LOCKED to Regular (weight 1) on request
        -- ("Font regular lock"). The "Counter Font (v5)" menu control was removed.
        local fw = 1
        if rb.fs ~= fs or rb.fw ~= fw then
          rb.fs = fs
          rb.fw = fw
          pcall(_v5ApplyFontPlain, rb.txtL, fs, fw)
          pcall(_v5ApplyFontPlain, rb.txtR, fs, fw)
          pcall(_v5NoShadow, rb.txtL)
          pcall(_v5NoShadow, rb.txtR)
          local white = ESP(1.0, 1.0, 1.0, 1.0)
          ESP.SetTextColor(rb.txtL, white)
          ESP.SetTextColor(rb.txtR, white)
        end
        -- [SDWxOWNER-V5-ADAPT] text slots follow the layout (single entry is centred)
        local txL = (mode == 1) and TXT_LX or TXT_LX_S
        local txR = (mode == 1) and TXT_RX or TXT_LX_S
        if rb.px ~= X or rb.py ~= Y or rb.pc ~= cell or rb.pw ~= W or rb.ph ~= H or rb.pm ~= mode then
          rb.px, rb.py, rb.pc, rb.pw, rb.ph, rb.pm = X, Y, cell, W, H, mode
          pcall(_v5SetPos, rb.slotL, X + txL * Hc, Y + TXT_Y * Hc)
          pcall(_v5SetPos, rb.slotR, X + txR * Hc, Y + TXT_Y * Hc)
        end
        local sL = "Player - " .. nEnemy
        local sR = "Bot - " .. nBot
        if rb.sL ~= sL then rb.sL = sL; pcall(_v5SetText, rb.txtL, sL) end
        if rb.sR ~= sR then rb.sR = sR; pcall(_v5SetText, rb.txtR, sR) end
        -- [SDWxOWNER-V5-ADAPT] only the relevant readout is visible
        if ESPValid(rb.txtL) then
          if mode == 3 then pcall(_wSetCollapsed, rb.txtL) else pcall(_wSetSelfHit, rb.txtL) end
        end
        if ESPValid(rb.txtR) then
          if mode == 2 then pcall(_wSetCollapsed, rb.txtR) else pcall(_wSetSelfHit, rb.txtR) end
        end
      end

      -- ---- exposure + ~15 Hz self-sustaining driver (same pattern as V4) ----
      _G.SDW_V5Counter = { Update = V5Update, Destroy = V5Destroy, Hide = V5Hide }

      _G.SDW_V5 = _G.SDW_V5 or {}
      local V5 = _G.SDW_V5
      V5.gen = V5.gen or -1
      V5.running = V5.running or false
      V5.chain = V5.chain or 0

      local function SDW_StopV5Counter()
        V5.running = false
        V5.chain = (V5.chain or 0) + 1
        V5Destroy()
      end
      _G.SDW_StopV5Counter = SDW_StopV5Counter

      local function _v5DriverBody()
        local S = _G.SnaplineESP
        if S and S.InitESPCanvas then pcall(S.InitESPCanvas) end
        local _, _, _, pc = GetFrameCache()
        if not pc then return end
        if S and S.UpdateCanvasTransform then pcall(S.UpdateCanvasTransform, pc) end
        local cx = _G.SDW_V3CenterX and _G.SDW_V3CenterX(pc) or 0
        ESP._now = os.clock()
        ESP._vep = _G._SDW_MatchGen or 0
        V5Update(_G._Counter_Players or 0, _G._Counter_Bots or 0, cx)
      end

      local function SDW_V5DriverTick()
        if not V5.running then return end
        local myChain = V5.chain
        -- a driver left over from a PREVIOUS match stops itself (and drops its widgets)
        if V5.gen ~= (_G._SDW_MatchGen or 0) then
          V5.running = false
          V5Destroy()
          return
        end
        if not (_G.LOGIN_OK and _G.SDWConfig and _G.SDWConfig.EnemyCounterV5) then
          V5.running = false
          V5Destroy()
          return
        end
        pcall(_v5DriverBody)
        local t = _G.SDW_GetTicker and _G.SDW_GetTicker()
        if t and V5.running and V5.chain == myChain then
          t.AddTimerOnce(0.066, SDW_V5DriverTick)
        end
      end

      function _G.SDW_EnsureV5Counter()
        if not _G.LOGIN_OK then return end
        if not (_G.SDWConfig and _G.SDWConfig.EnemyCounterV5) then
          SDW_StopV5Counter()
          return
        end
        local gen = _G._SDW_MatchGen or 0
        if V5.gen ~= gen then
          -- new match: drop the old driver + all old widgets, then start clean
          SDW_StopV5Counter()
          V5.gen = gen
        end
        if V5.running then
          pcall(function() local S = _G.SnaplineESP; if S and S.InitESPCanvas then S.InitESPCanvas() end end)
          return
        end
        V5.running = true
        V5.chain = (V5.chain or 0) + 1
        pcall(SDW_V5DriverTick)
      end

    end)()
    -- ===== END SDWxOWNER V5 "Player / Bot" Enemy Counter module =====
    end
    -- ===== END SDWxOWNER V3 iOS Counter module =====

    local function Tick_CounterESP()
        local _cfg = _G.SDWConfig
        -- [SDWxOWNER] All FOUR counters feed off this single scan.
        local _anyCounter = _cfg and (_cfg.EnemyCounterEnabled or _cfg.EnemyCounterHUD or _cfg.EnemyCounterIOS or _cfg.EnemyCounterHD or _cfg.EnemyCounterV5)
        if _G.SDW_FXCheck then pcall(_G.SDW_FXCheck, "counter", _anyCounter and true or false) end
        if not _anyCounter then return end
        local localPawn, myPos, hud, pc, myTeamId = GetFrameCache()
        if not localPawn then return end
        local okPawns, allPawns = GetCachedPlayerPawns()
        if not okPawns or not allPawns then return end

        local enemyCount = 0
        local botCount = 0

        -- [ZEROLAG] Reuse the roster counts the 0.5 s HealthBar pass just computed. Its filter is
        -- identical (same team / health / 400 m test), so the values match exactly. Only when that
        -- pass is OFF or stale (>1.5 s) do we fall back to the full re-scan below.
        local _hbT = _G._SDW_HB_ScanT
        local _hbFresh = _hbT and _G._SDW_HB_EnemyCount ~= nil and (os.clock() - _hbT) < 1.5
        if _hbFresh then
            enemyCount = _G._SDW_HB_EnemyCount
            botCount = _G._SDW_HB_BotCount or 0
        else
        for _, pawn in pairs(allPawns) do
            if not SafeIsValid(pawn) or pawn == localPawn then goto continue end
            -- [SDWxOWNER-ALLMAPS] Robust enemy filter (IDENTICAL to the snapline/wallhack one):
            -- skip ONLY a proven teammate or a dead pawn. A nil/0 team (rooms / TDM / FFA /
            -- custom maps) counts as an enemy, so every counter works on EVERY map. The old
            -- filter required pawn.TeamID to be truthy -> on TDM/FFA/rooms it dropped EVERY
            -- pawn (count 0). It also dropped bots whose PlayerKey is 0/nil.
            local pTeam = pawn.TeamID or (type(pawn.GetTeamID) == "function" and pawn:GetTeamID())
            if myTeamId and myTeamId > 0 and pTeam and pTeam > 0 and pTeam == myTeamId then goto continue end
            local hs = pawn.HealthStatus
            if hs == 2 or hs == 3 then goto continue end
            if pawn.bIsDead or pawn.bDead then goto continue end

            local pKey = pawn.PlayerKey
            local isAI = ResolveIsAI(pKey, pawn)

            local okPP, pPos = SafeMethodCall(pawn, "K2_GetActorLocation")
            local distSq = 0
            if okPP and pPos and myPos then
                local dx = pPos.X - myPos.X
                local dy = pPos.Y - myPos.Y
                local dz = pPos.Z - myPos.Z
                distSq = dx * dx + dy * dy + dz * dz
            end
            if distSq > 0 and distSq <= 1600000000 then
                if isAI then botCount = botCount + 1 else enemyCount = enemyCount + 1 end
            end
            ::continue::
        end
        end

        _G._Counter_Players = enemyCount
        _G._Counter_Bots = botCount
        if _cfg.EnemyCounterEnabled then
            if _G.SDW_Counter then pcall(_G.SDW_Counter) end
        elseif _G.SDW_Counter_Clear then
            pcall(_G.SDW_Counter_Clear)
        end
        -- [SDWxOWNER] New text-only HUD bot counter (independent ON/OFF toggle).
        if _cfg.EnemyCounterHUD then
            GK_UpdateWidget(enemyCount, botCount)
        elseif _G.GK_DestroyWidget then
            pcall(_G.GK_DestroyWidget)
        end
        -- [SDWxOWNER] V3 iOS Capsule Counter (SDWxOWNER VIP iOS Counter Framework).
        -- Counts come straight from THIS scan (enemyCount / botCount); the capsule is
        -- repainted by the ~20 Hz SDW_V3 driver so the staged build stays smooth.
        if _cfg.EnemyCounterIOS then
            if _G.SDW_EnsureV3Counter then pcall(_G.SDW_EnsureV3Counter) end
        elseif _G.SDW_StopV3Counter then
            pcall(_G.SDW_StopV3Counter)
        end
        -- [SDWxOWNER] V4 "HD Image" Counter (faithful reproduction of the supplied reference art).
        -- Counts come straight from THIS scan (enemyCount / botCount); the capsule is repainted
        -- by the ~15 Hz SDW_V4 driver so the staged build stays smooth.
        if _cfg.EnemyCounterHD then
            if _G.SDW_EnsureV4Counter then pcall(_G.SDW_EnsureV4Counter) end
        elseif _G.SDW_StopV4Counter then
            pcall(_G.SDW_StopV4Counter)
        end
        -- [SDWxOWNER] V5 "Player / Bot" Counter (faithful reproduction of the v5 reference banner).
        -- Counts come straight from THIS scan (enemyCount / botCount); the banner is repainted
        -- by the ~15 Hz SDW_V5 driver so the staged build stays smooth.
        if _cfg.EnemyCounterV5 then
            if _G.SDW_EnsureV5Counter then pcall(_G.SDW_EnsureV5Counter) end
        elseif _G.SDW_StopV5Counter then
            pcall(_G.SDW_StopV5Counter)
        end
    end

    _G._SDW_WhiteTex = _G._SDW_WhiteTex or false
    _G._SDW_SimpleFont = _G._SDW_SimpleFont or false

    local function _SDW_GetWhiteTex()
        if _G._SDW_WhiteTex ~= false then return _G._SDW_WhiteTex end
        local t = nil
        pcall(function() t = slua.loadObject("/Engine/EngineResources/WhiteSquareTexture.WhiteSquareTexture") end)
        if not t then pcall(function() t = slua.loadObject("/Engine/EngineResources/White.White") end) end
        _G._SDW_WhiteTex = t
        return t
    end

    local function _SDW_GetSimpleFont()
        if _G._SDW_SimpleFont ~= false then return _G._SDW_SimpleFont end
        local f = nil
        pcall(function() f = slua.loadObject("/Engine/EngineFonts/Roboto.Roboto") end)
        _G._SDW_SimpleFont = f
        return f
    end

    local function _SDW_MakeCounterBox(txt, r, g, b, xPos, yPos, w, h)
        yPos = yPos or 34
        w = w or 92
        h = h or 34
        local nw = nil
        pcall(function()
            local BTN_BP = "/Game/UMG/UI_BP/Common/BaseComponent/CommonBaseComponent_TextButton_UIBP.CommonBaseComponent_TextButton_UIBP"
            nw = slua.loadUI(BTN_BP)
        end)
        if not nw or not slua.isValid(nw) then return nil end

        pcall(function()
            require("game_frontend_hud").AddToContainer(UIContainers.Top, nw, 10500)
        end)

        local kids = {}
        pcall(function()
            local function walk(w, d)
                if not w or not slua.isValid(w) or d > 8 then return end
                kids[#kids + 1] = w
                pcall(function()
                    local n = w:GetChildrenCount()
                    if n and n > 0 then
                        for i = 0, n - 1 do walk(w:GetChildAt(i), d + 1) end
                    end
                end)
            end
            local tree = nw.WidgetTree
            if tree and slua.isValid(tree) and tree.RootWidget then
                walk(tree.RootWidget, 0)
            end
            walk(nw, 0)
        end)

        pcall(function()
            local direct = {
                "Image_Bg","Img_Bg","Image_Background","BgImage","Background",
                "Image_Normal","Img_Normal","Image_Btn","Image_Base","Image_BG",
                "Image_1","Image_2","Image_3","Image_4","Image_5","Image_6",
                "Img_1","Img_2","Img_3","Img_4",
                "Image_Light","Image_Glow","Image_Shine","Image_Highlight",
                "Image_Corner","Image_Corner_LT","Image_Corner_RT",
                "Image_Corner_LB","Image_Corner_RB","Image_Border",
                "Image_Frame","Image_Line","Image_Dot","Image_Point",
                "Image_Deco","Image_Decorate","Image_Mask","Image_Shadow",
                "Image_Select","Image_Selected","Image_Hover","Image_Press",
                "Image_Angle","Image_Arrow","Image_Icon","Img_Icon"
            }
            for _, n in ipairs(direct) do
                local el = nw[n]
                if el and slua.isValid(el) then kids[#kids + 1] = el end
            end
        end)

        local whiteTex = _SDW_GetWhiteTex()
        pcall(function()
            local white = FLinearColor(1, 1, 1, 0)   -- [SDWxOWNER] transparent bg -> text-only counter (no yellow box)
            local bgDone = false
            local firstImg = nil
            for _, el in ipairs(kids) do
                local nm = ""
                pcall(function() nm = tostring(el:GetName() or "") end)
                local low = nm:lower()
                local isImg = low:find("image") or low:find("img")
                if isImg then
                    if not firstImg then firstImg = el end
                    local isBg = low:find("bg") or low:find("background")
                              or low:find("normal") or low:find("btn")
                              or low:find("base") or low:find("panel")
                    if isBg then
                        if whiteTex then
                            pcall(function() el:SetBrushFromTexture(whiteTex, false) end)
                            pcall(function() el:SetBrushFromTexture(whiteTex) end)
                        end
                        pcall(function() el:SetColorAndOpacity(white) end)
                        pcall(function() el:SetBrushColor(white) end)
                        pcall(function() el:SetOpacity(1.0) end)
                        pcall(function() el:SetRenderOpacity(1.0) end)
                        bgDone = true
                    else
                        pcall(function() el:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end)
                        pcall(function() el:SetVisibility(UEnums.ESlateVisibility.Collapsed) end)
                        pcall(function() el:SetRenderOpacity(0) end)
                        pcall(function() el:SetColorAndOpacity(FLinearColor(0,0,0,0)) end)
                    end
                end
            end
            if not bgDone and firstImg then
                if whiteTex then
                    pcall(function() firstImg:SetBrushFromTexture(whiteTex, false) end)
                    pcall(function() firstImg:SetBrushFromTexture(whiteTex) end)
                end
                pcall(function() firstImg:SetColorAndOpacity(white) end)
                pcall(function() firstImg:SetBrushColor(white) end)
                pcall(function() firstImg:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible) end)
            end
        end)

        pcall(function() nw:SetColorAndOpacity(FLinearColor(r, g, b, 0.80)) end)

        pcall(function()
            local tb = nw.RichText_Content
            if not tb or not slua.isValid(tb) then return end
            tb:SetText(txt)
            local cr = (r > 0.01) and (1.0 / r) or 1.0
            local cg = (g > 0.01) and (1.0 / g) or 1.0
            local cb = (b > 0.01) and (1.0 / b) or 1.0
            pcall(function() tb:SetColorAndOpacity(FSlateColor(FLinearColor(cr, cg, cb, 1.0 / 0.80))) end)
            pcall(function() tb:SetShadowColorAndOpacity(FLinearColor(0, 0, 0, 0)) end)
            pcall(function() tb:SetShadowOffset(FVector2D(0, 0)) end)
            pcall(function()
                local fi = tb.Font
                if not fi then return end
                local simpleFont = _SDW_GetSimpleFont()
                if simpleFont then
                    pcall(function() fi.FontObject = simpleFont end)
                    pcall(function() fi.TypefaceFontName = "Regular" end)
                else
                    pcall(function() fi.TypefaceFontName = "Regular" end)
                end
                fi.Size = 16
                pcall(function()
                    if fi.OutlineSettings then
                        fi.OutlineSettings.OutlineSize = 0
                        pcall(function() fi.OutlineSettings.OutlineColor = FLinearColor(0,0,0,0) end)
                        pcall(function() fi.OutlineSettings.bApplyOutlineToDropShadows = false end)
                    end
                end)
                pcall(function() fi.LetterSpacing = 0 end)
                tb:SetFont(fi)
            end)
        end)

        pcall(function()
            local WLL = import("WidgetLayoutLibrary")
            local slot = WLL.SlotAsCanvasSlot(nw)
            if slot then
                slot:SetAnchors(FAnchors(0.5, 0, 0.5, 0))
                slot:SetAlignment(FVector2D(0.5, 0))
                slot:SetPosition(FVector2D(xPos, yPos))
                slot:SetSize(FVector2D(w, h))
            end
        end)

        pcall(function() nw:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible) end)
        return nw
    end

    _G.SDW_Counter = function()
        pcall(function()
            local bots    = _G._Counter_Bots    or 0
            local players = _G._Counter_Players or 0

            local realTxt = string.format("REAL %d", players)
            local botTxt  = string.format("BOT %d", bots)
            local stamp   = realTxt .. "|" .. botTxt

            local wT = _G._SDWCounterWidgetTitle
            local wR = _G._SDWCounterWidgetReal
            local wB = _G._SDWCounterWidgetBot
            local aliveT, aliveR, aliveB = false, false, false
            pcall(function() aliveT = (wT ~= nil) and slua.isValid(wT) end)
            pcall(function() aliveR = (wR ~= nil) and slua.isValid(wR) end)
            pcall(function() aliveB = (wB ~= nil) and slua.isValid(wB) end)

            if not (aliveR and aliveB) then
                pcall(function() if wT and slua.isValid(wT) then wT:RemoveFromParent() end end)
                pcall(function() if wR and slua.isValid(wR) then wR:RemoveFromParent() end end)
                pcall(function() if wB and slua.isValid(wB) then wB:RemoveFromParent() end end)

                _G._SDWCounterWidgetTitle = nil
                _G._SDWCounterWidgetReal  = _SDW_MakeCounterBox(realTxt, 0.95, 0.10, 0.10, -48, 34, 92, 34)
                _G._SDWCounterWidgetBot   = _SDW_MakeCounterBox(botTxt,  0.10, 0.80, 0.16,  48, 34, 92, 34)
                _G._SDWCounterLastText    = stamp
            elseif stamp ~= _G._SDWCounterLastText then
                _G._SDWCounterLastText = stamp
                pcall(function() if wR.RichText_Content then wR.RichText_Content:SetText(realTxt) end end)
                pcall(function() if wB.RichText_Content then wB.RichText_Content:SetText(botTxt) end end)
            end
        end)
    end

    _G.SDW_Counter_Clear = function()
        pcall(function()
            local wT = _G._SDWCounterWidgetTitle
            local wR = _G._SDWCounterWidgetReal
            local wB = _G._SDWCounterWidgetBot
            if wT and slua.isValid(wT) then wT:RemoveFromParent() end
            if wR and slua.isValid(wR) then wR:RemoveFromParent() end
            if wB and slua.isValid(wB) then wB:RemoveFromParent() end
            _G._SDWCounterWidgetTitle = nil
            _G._SDWCounterWidgetReal  = nil
            _G._SDWCounterWidgetBot   = nil
            _G._SDWCounterLastText    = nil
        end)
    end


    -- [SDWxOWNER-COUNTER] Mutually-exclusive control for ALL THREE counters:
    --   "old" = Classic Counter, "hud" = HUD Bot Counter, "ios" = SDWxOWNER iOS Counter.
    -- Turning ON any one ALWAYS turns the other two OFF and destroys their widgets, so
    -- exactly ONE counter is ever live and no orphan widgets are left behind.
    _G.SDW_SetCounterMode = function(mode)
        local cfg = _G.SDWConfig
        if not cfg then return end
        -- 1) Switch EVERY counter OFF and wipe its widgets first.
        cfg.EnemyCounterEnabled = false
        cfg.EnemyCounterHUD = false
        cfg.EnemyCounterIOS = false
        cfg.EnemyCounterHD = false
        cfg.EnemyCounterV5 = false
        if _G.SDW_Counter_Clear then pcall(_G.SDW_Counter_Clear) end
        if _G.GK_DestroyWidget then pcall(_G.GK_DestroyWidget) end
        if _G.SDW_StopV3Counter then pcall(_G.SDW_StopV3Counter)
        elseif _G.SDW_V3Counter and _G.SDW_V3Counter.Destroy then pcall(_G.SDW_V3Counter.Destroy) end
        if _G.SDW_StopV4Counter then pcall(_G.SDW_StopV4Counter)
        elseif _G.SDW_V4Counter and _G.SDW_V4Counter.Destroy then pcall(_G.SDW_V4Counter.Destroy) end
        if _G.SDW_StopV5Counter then pcall(_G.SDW_StopV5Counter)
        elseif _G.SDW_V5Counter and _G.SDW_V5Counter.Destroy then pcall(_G.SDW_V5Counter.Destroy) end
        -- 2) Switch the requested one ON.
        if mode == "old" then
            cfg.EnemyCounterEnabled = true
        elseif mode == "hud" then
            cfg.EnemyCounterHUD = true
        elseif mode == "ios" then
            cfg.EnemyCounterIOS = true
            if _G.SDW_EnsureV3Counter then pcall(_G.SDW_EnsureV3Counter) end
        elseif mode == "hd" then
            cfg.EnemyCounterHD = true
            if _G.SDW_EnsureV4Counter then pcall(_G.SDW_EnsureV4Counter) end
        elseif mode == "v5" then
            cfg.EnemyCounterV5 = true
            if _G.SDW_EnsureV5Counter then pcall(_G.SDW_EnsureV5Counter) end
        end
    end

    -- [SDWxOWNER-COUNTER] Back-compat wrapper (older menu rows / saved callbacks).
    _G.SDW_SetCounterHUD = function(on)
        return _G.SDW_SetCounterMode(on and "hud" or nil)
    end

    local _WallhackTickTime = 0
    -- [SDWxOWNER-OPT] Adopt sdw.lua's 2.5 s wallhack tick. Combined with the per-mesh
    -- hibernation in _OPT.dyeMeshApply (skip native work when a mesh is already wallhacked)
    -- and the bounded mesh budget below, a settled frame costs almost nothing while a newly
    -- spawned / re-skinned enemy is still picked up within one tick.
    local _WallhackInterval = 2.5
    local function Tick_Wallhack()
        local _whOn = (_G.SDWConfig and _G.SDWConfig.WallhackEnabled) and true or false
        if _G.SDW_FXCheck then pcall(_G.SDW_FXCheck, "wallhack", _whOn) end
        if not _whOn then return end
        local now = os.clock()
        if now - _WallhackTickTime < _WallhackInterval then return end
        _WallhackTickTime = now
        DYE_CALLS_THIS_TICK = 0

        local localPawn, myPos, hud, pc, myTeamId = GetFrameCache()
        if not localPawn or not myPos then return end

        local okPawns, allPawns = GetCachedPlayerPawns()
        if not okPawns or not allPawns then return end

        -- [SDWxOWNER-RUSH-CRASH FIX #2] BOUNDED, roster-independent mesh budget. The old
        -- roster-scaled budget (256..640) let a single tick fire thousands of native dye calls
        -- (the FPS-drop-then-crash herd). The budget is now a fixed small mesh count, and the
        -- per-enemy slice below spreads it fairly so no enemy is starved while the tail streams.
        -- [SDWxOWNER-RUSH-FPS] BODY-FIRST bounded budget. Every enemy is guaranteed its 8 visible
        -- body meshes per tick (so the wallhack looks identical, instantly), plus a small headroom
        -- for trailing cosmetic meshes. The REAL spike protection is the 8 ms wall-clock guard in
        -- ApplyColorBodyNew: it always lets an enemy's first 8 (body) meshes through, then stops
        -- once the tick has burned 8 ms, resuming from the saved cursor next tick.
        -- Why this matters: each dyed mesh costs ~17 native setters AND one render-proxy rebuild.
        -- 128+ meshes in one frame = 128+ render-proxy rebuilds in one frame -> the FPS 60 -> 20-30
        -- drop that precedes the crash on phones. This bounds it without any visible delay.
        local _nEnemies = math.max(1, #allPawns or 1)
        DYE_CALL_BUDGET = _OPT.dyeBodyMeshes * _nEnemies + 32
        _OPT.dyeSlice = math.max(_OPT.dyeBodyMeshes + 1, math.floor(DYE_CALL_BUDGET / _nEnemies))
        _OPT.dyeTickStart = os.clock()

        _G.SDWState = _G.SDWState or {}
        _G.SDWState.EnemyMarks = _G.SDWState.EnemyMarks or {}

        -- [SDWxOWNER-RUSH-CRASH FIX #2] AGGRESSIVE up-front prune. EnemyMarks holds a STRONG
        -- reference to every enemy pawn AND its cached skeletal meshes (markData.CachedMeshes).
        -- During a rush many pawns die at once; the engine tears their meshes down, but the mark
        -- (and its mesh refs) used to survive until the END of this tick - long enough for the
        -- dye/undo path to touch a freed mesh (native use-after-free -> hard crash). Pruning
        -- BEFORE the loop, and dropping the cached mesh refs + streaming cursor, releases them
        -- immediately so no torn-down mesh is ever handed to the dye path this tick.
        do
            local marks = _G.SDWState.EnemyMarks
            for k, md in pairs(marks) do
                local e = md and md.enemy
                if not (e and SafeIsValid(e)) then
                    marks[k] = nil
                elseif e.HealthStatus == 2 or e.HealthStatus == 3 or e.bIsDead == true or e.bDead == true
                    or e.bIsBeingDestroyed == true or e.bPendingKill == true or e.bActorIsBeingDestroyed == true then
                    -- Dead / torn-down pawn: release the strong mesh refs now, keep the reusable slot.
                    md.CachedMeshes = nil
                    md.CachedMeshTime = nil
                    md.ColorNewApplied = false
                    md.DyeComplete = false
                    md.DyeCursor = nil
                    md.DyeCursorColorHash = nil
                end
            end
        end

        local maxESP = (_G.SDWConfig and _G.SDWConfig.MaxESP) or 60
        local processed = 0
        for _, pawn in pairs(allPawns) do
            if not SafeIsValid(pawn) or pawn == localPawn then goto continue end

            local pTeam = pawn.TeamID or (type(pawn.GetTeamID) == "function" and pawn:GetTeamID())
            if myTeamId and myTeamId > 0 and pTeam and pTeam > 0 and pTeam == myTeamId then goto continue end

            local hs = pawn.HealthStatus
            -- [SDWxOWNER-KILL-CRASH FIX] hs == 2 = dead: skip it exactly like every other ESP
            -- tick does. The old `hs ~= 2` clause deliberately kept dead pawns dyeable ->
            -- reading a torn-down skeletal mesh (GetAllSkeletalMeshes/SetDrawDyeing) on the
            -- next tick -> native crash right at the kill moment.
            if hs == 2 or hs == 3 then goto continue end
            if pawn.bIsDead or pawn.bDead or (pawn.Health and pawn.Health <= 0) then goto continue end
            -- [SDWxOWNER-RUSH-CRASH v2] TEARDOWN FENCE. A pawn mid-destruction can still report a
            -- live HealthStatus for a frame while its skeletal meshes are already freed. Dyeing
            -- those is the exact native UAF that crashes on a squad-wipe rush. Skipping is free
            -- (no feature loss - the pawn is gone anyway) and removes the last crash window.
            if pawn.bIsBeingDestroyed == true or pawn.bPendingKill == true or pawn.bActorIsBeingDestroyed == true then goto continue end

            local pKey = pawn.PlayerKey
            local eKey = (pKey and pKey ~= 0) and pKey or pawn
            local isAI = ResolveIsAI(pKey, pawn)

            local okPP, pPos = SafeMethodCall(pawn, "K2_GetActorLocation")
            if not (okPP and pPos) then goto continue end

            local dx = pPos.X - myPos.X
            local dy = pPos.Y - myPos.Y
            local dz = pPos.Z - myPos.Z
            local distSq = dx * dx + dy * dy + dz * dz
            local isWithin500m = (distSq > 0 and distSq <= 2500000000)

            _G.SDWState.EnemyMarks[eKey] = _G.SDWState.EnemyMarks[eKey] or { enemy = pawn }
            local markData = _G.SDWState.EnemyMarks[eKey]
            markData.enemy = pawn
            markData.AK_IS_BOT = isAI

            if isWithin500m then
                ApplyColorBodyNew(pawn, markData)
            else
                UndoColorBodyNew(pawn, markData)
            end

            processed = processed + 1
            if processed >= maxESP then break end
            ::continue::
        end

        -- [SDWxOWNER-RUSH-CRASH FIX] Prune marks for pawns that died / were torn down this match.
        -- Without this, EnemyMarks kept a strong reference to every dead pawn (and its meshes) for
        -- the WHOLE match; the next tick then re-read a torn-down mesh -> native UAF crash. This is
        -- the same class of leak that fires hardest when many enemies die at once during a rush.
        do
            local marks = _G.SDWState.EnemyMarks
            for k, md in pairs(marks) do
                local e = md and md.enemy
                if not (e and SafeIsValid(e)) then marks[k] = nil end
            end
        end
        -- [SDWxOWNER-OPT] One-shot force-update flag (sdw.lua pattern): cleared after every
        -- tick so a config change only forces ONE full re-apply, then hibernation resumes.
        _G._WH_ForceUpdate = nil
    end
    -- [ZEROLAG] Vehicle label memo: "Name | 12m" built once per (name, metre) pair.
    local _VEH_TXT = {}
    local function Tick_Vehicles()
        local _vehOn = (_G.SDWConfig and _G.SDWConfig.VehicleESPEnabled) and true or false
        if _G.SDW_FXCheck then pcall(_G.SDW_FXCheck, "vehicle", _vehOn) end
        if not _vehOn then return end
        local localPawn, myPos, hud, pc = GetESPState()
        if not localPawn or not SafeIsValid(hud) or not myPos then return end

        local now = NowSeconds()
        if now - VEH_CACHE_TIME > VEH_CACHE_TTL then
            VEH_CACHE_TIME = now
            local okVeh, vehicles = SafeMethodCall(Game, "GetAllVehicles")
            VEH_CACHE = okVeh and vehicles or {}
        end

        local sliderVeh = _G.SDWConfig.TextSizeVehUI or 50
        local vScale = 0.83 + (sliderVeh / 100.0) * 0.14
        local vCol = GetColorTable(_G.SDWConfig.ColorVehicle or 5)

        for _, veh in pairs(VEH_CACHE) do
            if SafeIsValid(veh) then
                local okVP, vPos = SafeMethodCall(veh, "K2_GetActorLocation")
                if okVP and vPos then
                    local dx = vPos.X - myPos.X
                    local dy = vPos.Y - myPos.Y
                    local dz = vPos.Z - myPos.Z
                    local distSq = dx * dx + dy * dy + dz * dz
                    if distSq <= 1600000000 then
                        local vName = GetVehicleNameAndKey(veh)
                        -- [SDWxOWNER-VEH MASTER] Vehicle ESP is a single global master
                        -- switch: when ON, EVERY vehicle is shown (no per-vehicle keys).
                        if _G.SDWConfig.VehicleESPEnabled then
                            local vDist = math.floor(math.sqrt(distSq) / 100)
                            local _vc = _VEH_TXT[vName]
                            if not _vc then _vc = {}; _VEH_TXT[vName] = _vc end
                            local txt = _vc[vDist]
                            if not txt then txt = vName .. " | " .. vDist .. "m"; _vc[vDist] = txt end
                            SafeMethodCall(hud, "AddDebugText", txt, veh, 4.5, VEH_OFFSET, VEH_OFFSET, vCol, false, false, true, nil, vScale, true)
                        end
                    end
                end
            end
        end
    end

    local _BoxESPCache = setmetatable({}, { __mode = "k" })
    local _BoxActivePawns = {}

    local _BOX_C_WHITE = FLinearColor and FLinearColor(1, 1, 1, 1) or LinearColor(1, 1, 1, 1)
    local _BOX_C_CYAN = FLinearColor and FLinearColor(0, 1, 1, 1) or LinearColor(0, 1, 1, 1)
    local _BOX_C_YELLOW = FLinearColor and FLinearColor(1, 1, 0, 1) or LinearColor(1, 1, 0, 1)
    local _BOX_C_FRAME_RED = FLinearColor and FLinearColor(1, 0, 0, 1) or LinearColor(1, 0, 0, 1)
    local _BOX_OFF_NAME = {X=0, Y=0, Z=-370}

    local _HP_BAR_STRINGS = {}
    for hpPct = 0, 100 do
        local hp = hpPct / 100.0
        local barTotal = 10
        local barFilled = math.floor(hp * barTotal + 0.5)
        local barEmpty = barTotal - barFilled
        _HP_BAR_STRINGS[hpPct] = string.rep("\xe2\x96\x88", barFilled) .. string.rep("\xe2\x96\x91", barEmpty) .. " " .. hpPct .. "%"
    end

    local function SetBoxFrameColor(pawn)
        if not SafeIsValid(pawn) then return end
        pcall(function()
            if pawn.Replay_SetFrameUIColor then pawn:Replay_SetFrameUIColor(_BOX_C_FRAME_RED)
            elseif pawn.SetEnemyFrameColor then pawn:SetEnemyFrameColor(_BOX_C_FRAME_RED)
            elseif pawn.SetFrameColor then pawn:SetFrameColor(_BOX_C_FRAME_RED)
            elseif pawn.SetOutlineColor then pawn:SetOutlineColor(_BOX_C_FRAME_RED) end
        end)
    end


    -- [SDWxOWNER-PERF] Hoisted per-pawn closures for Tick_BoxESP. The old code built 3-4 new
    -- pcall(function() ... end) bodies for EVERY pawn on EVERY 5s tick; these named probes are
    -- created once and driven through scratch locals, so the box pass allocates no closure.
    -- Wrapped in a nested do-block (with a forward-declared Tick_BoxESP) so the helper slots
    -- are released afterwards and do not count against LuaJIT's 200-local limit.
    local Tick_BoxESP
    do
    local _boxPawn = nil
    local function _boxFrameOn()
        local pawn = _boxPawn
        if pawn.Replay_CreateEnemyFrameUI then
            pawn:Replay_CreateEnemyFrameUI(true, true)
        end
        SetBoxFrameColor(pawn)
        if pawn.Replay_SetVisiableOfFrameUI then
            pawn:Replay_SetVisiableOfFrameUI(true)
        end
        if pawn.SetPlayerNameVisible then
            pawn:SetPlayerNameVisible(true)
        end
    end
    local function _boxFrameOff()
        local pawn = _boxPawn
        if SafeIsValid(pawn) and pawn.Replay_SetVisiableOfFrameUI then
            pawn:Replay_SetVisiableOfFrameUI(false)
        end
    end
    local _boxPosePawn, _boxStateText = nil, "Standing"
    local function _boxPoseProbe()
        local pawn = _boxPosePawn
        local pose = pawn.PoseState or (pawn.GetPoseState and pawn:GetPoseState())
        if pose == 0 or pose == "Stand" then _boxStateText = "Standing"
        elseif pose == 1 or pose == "Crouch" then _boxStateText = "Crouching"
        elseif pose == 2 or pose == "Prone" then _boxStateText = "Prone" end
    end
    local _boxLabelPawn, _boxLabelHud, _boxLabelDist = nil, nil, 0
    local function _boxLabelProbe()
        local pawn = _boxLabelPawn
        local hud = _boxLabelHud
        local dist = _boxLabelDist
        local pKey = pawn.PlayerKey
        local isAI = ResolveIsAI(pKey, pawn)
        local dynamicScale = math.max(0.5, 0.8 - (dist / 40000))
        local distM = math.floor(dist / 100)

        local maxHP = pawn.HealthMax or pawn.MaxHealth or 100
        if maxHP <= 0 then maxHP = 100 end
        local rawHp = (pawn.Health or 100) / maxHP
        local hpPct = math.max(0, math.min(100, math.floor(rawHp * 100)))
        local hpText = _HP_BAR_STRINGS[hpPct] or (hpPct .. "%")

        _boxStateText = "Standing"
        _boxPosePawn = pawn
        pcall(_boxPoseProbe)
        local stateText = _boxStateText

        local enemyName = isAI and "BOT" or GetEnemyName(pawn)
        local textColor = isAI and _BOX_C_CYAN or _BOX_C_YELLOW

        local boxCombined = enemyName .. "\n" .. hpText .. "\n[" .. distM .. "m] " .. stateText
        -- [SDWxOWNER-OFF-FIX] bSkipOverwriteCheck=false so the label is overwritten
        -- in place (true stacked labels that lingered after OFF).
        SafeMethodCall(hud, "AddDebugText", boxCombined, pawn, 5.5, _BOX_OFF_NAME, _BOX_OFF_NAME, _BOX_C_WHITE, false, false, true, nil, dynamicScale, true)
    end

    Tick_BoxESP = function()
        local _boxOn = (_G.SDWConfig and _G.SDWConfig.BoxESPEnabled) and true or false
        -- [SDWxOWNER-OFF-FIX] ON -> OFF edge: erase the box labels + hide the frame UI now.
        if _G.SDW_FXCheck then pcall(_G.SDW_FXCheck, "box", _boxOn) end
        if not _boxOn then
            -- [SDWxOWNER] Keep the enemy frame UI hidden when Box ESP is off, so the
            -- Native HP Bar shows ONLY the health bar (no name / frame).
            do
                for pawn, _ in pairs(_BoxESPCache) do
                    _boxPawn = pawn
                    pcall(_boxFrameOff)
                end
            end
            _BoxESPCache = setmetatable({}, { __mode = "k" })
            return
        end

        local localPawn, myPos, hud, pc, myTeamId = GetFrameCache()
        if not localPawn or not myPos then return end

        local okPawns, allPawns = GetCachedPlayerPawns()
        if not okPawns or not allPawns then return end

        for k in pairs(_BoxActivePawns) do _BoxActivePawns[k] = nil end

        for _, pawn in pairs(allPawns) do
            if not SafeIsValid(pawn) or pawn == localPawn then goto continue end
            -- [SDWxOWNER-ALLMAPS] Robust enemy filter (IDENTICAL to the snapline/wallhack one).
            local pTeam = pawn.TeamID or (type(pawn.GetTeamID) == "function" and pawn:GetTeamID())
            if myTeamId and myTeamId > 0 and pTeam and pTeam > 0 and pTeam == myTeamId then goto continue end
            local hs = pawn.HealthStatus
            if hs == 2 or hs == 3 then goto continue end
            if pawn.bIsDead or pawn.bDead then goto continue end

            local okPP, pPos = SafeMethodCall(pawn, "K2_GetActorLocation")
            if not (okPP and pPos) then goto continue end

            local dx = pPos.X - myPos.X
            local dy = pPos.Y - myPos.Y
            local dz = pPos.Z - myPos.Z
            local distSq = dx * dx + dy * dy + dz * dz
            if distSq <= 0 or distSq > 900000000 then goto continue end

            local dist = math.sqrt(distSq)
            _BoxActivePawns[pawn] = true

            _boxPawn = pawn
            pcall(_boxFrameOn)
            _BoxESPCache[pawn] = true

            if hud and dist < 25000 then
                _boxLabelPawn = pawn; _boxLabelHud = hud; _boxLabelDist = dist
                pcall(_boxLabelProbe)
            end

            ::continue::
        end

        for pawn, _ in pairs(_BoxESPCache) do
            if not _BoxActivePawns[pawn] then
                _boxPawn = pawn
                pcall(_boxFrameOff)
                _BoxESPCache[pawn] = nil
            end
        end
    end
    end

    -- [SDWxOWNER] Native Health Bar (game's ScreenMark 1006) -- no custom widgets.
    local _SDW_NativeHPInit = false
    local _SDW_NativeHPApplied = false
    local _SDW_NativeHP_LastApply = 0
    local _SDW_NativeHP_Gen = -1          -- match/map generation the group was built for
    local _SDW_NativeHP_LastInitTry = 0   -- safety-net re-init throttle
    -- [SDWxOWNER-MATCH2-FIX] Deep-copy a config table to replicate ScreenMark group 1006 exactly.
    local function SDW_DeepCopy(v, seen, depth)
        if type(v) ~= "table" then return v end
        depth = depth or 0
        if depth > 8 then return v end
        seen = seen or {}
        if seen[v] then return seen[v] end
        local t = {}
        seen[v] = t
        for k, val in pairs(v) do
            t[SDW_DeepCopy(k, seen, depth + 1)] = SDW_DeepCopy(val, seen, depth + 1)
        end
        return t
    end

    -- [SDWxOWNER-MATCH2-FIX] The ORIGINAL group-1006 table, captured the FIRST time it is seen (before patching).
    if type(_G._SDW_NativeHP_Template) ~= "table" then _G._SDW_NativeHP_Template = nil end

    -- [FIX] The ScreenMark config table for group 1006 (the game's native enemy
    -- HP bar / "TipHitEnemy" widget). Rebuilt every time it is applied.
    local function SDW_NativeHPCfgTable()
        return {
            UIPathName = "/Game/Mod/EvoBase/BluePrints/UIBP/QuickSign/QuickSign_TipHitEnemy_UIBP_New.QuickSign_TipHitEnemy_UIBP_New_C",
            MaxWidgetNum = 99,
            MaxShowDistance = 6000000,
            bBindOutScreen = true,
            bBindBlocked = true,          -- [SDWxOWNER] bind even when occluded -> X-ray
            bIsBindingActor = true,
            BindSocketName = "head",
            bUseLuaWorldSocketName = true,
            WorldPositionOffset = FVector(0, 0, 40),
            bNeedPreLoad = true,
            Priority = 2,
        }
    end

    -- [FIX] Resolve ScreenMarkConfig: global GamePlayTools, then require, then package.loaded.
    local function SDW_ApplyNativeHPConfig()
        local applied = false
        local function patch(smc)
            if type(smc) ~= "table" then return end
            local g = smc[1006]
            -- [SDWxOWNER-MATCH2-FIX] Capture the game's original group-1006 table the first time we see it.
            if type(g) == "table" and next(g) ~= nil
               and not _G._SDW_NativeHP_Template and not _G._SDW_NativeHP_SeededSelf then
                _G._SDW_NativeHP_Template = SDW_DeepCopy(g)
            end
            local tpl = _G._SDW_NativeHP_Template
            if type(g) == "table" then
                -- [SDWxOWNER-MATCH2-FIX] Force the REAL widget path back onto the LIVE group.
                if tpl then
                    for k, v in pairs(tpl) do
                        if type(v) == "string" and (v:find("UIBP", 1, true) or v:sub(-2) == "_C") then
                            if g[k] ~= v then g[k] = v end
                        end
                    end
                end
                g.bBindBlocked = true          -- [SDWxOWNER] bind even when occluded -> X-ray
                g.bBindOutScreen = true
                g.MaxWidgetNum = 99
                g.MaxShowDistance = 6000000
                -- [SDWxOWNER-PORT] Match new.lua's head offset + constant size so the HP bar
                -- sits at the SAME position as new.lua's "Health Bar (Wall Penetrating)".
                g.WorldPositionOffset = FVector(0, 0, 40)
                -- [SDWxOWNER-HEAD-FIX] Pin the mark to the HEAD socket. new.lua ALWAYS forces
                -- BindSocketName="head" + bUseLuaWorldSocketName=true on the LIVE group 1006.
                -- Without this the game's own default socket (torso / "pet" bone) is kept, so in
                -- classic the bar/name rendered at the belly instead of above the head.
                g.BindSocketName = "head"
                g.bUseLuaWorldSocketName = true
                g.bScaleByDistance = false
                _G._SDW_NativeHP_LastWidget = tostring(g.UIPathName or "?")
                _G._SDW_NativeHP_LastPresent = true
                applied = true
            elseif tpl then
                -- [SDWxOWNER-MATCH2-FIX] Group 1006 is NOT present.
                local t = SDW_DeepCopy(tpl)
                t.bBindBlocked = true
                t.bBindOutScreen = true
                t.MaxWidgetNum = 99
                t.MaxShowDistance = 6000000
                t.WorldPositionOffset = FVector(0, 0, 40)
                -- [SDWxOWNER-HEAD-FIX] Same head-socket pin as the live-group branch above.
                t.BindSocketName = "head"
                t.bUseLuaWorldSocketName = true
                t.bScaleByDistance = false
                smc[1006] = t
                _G._SDW_NativeHP_LastWidget = tostring(t.UIPathName or "?")
                _G._SDW_NativeHP_LastPresent = false
                applied = true
            else
                -- [SDWxOWNER-MATCH2-FIX] Group 1006 missing and no template captured yet (first match).
                smc[1006] = SDW_NativeHPCfgTable()
                _G._SDW_NativeHP_SeededSelf = true
                _G._SDW_NativeHP_LastWidget = "SELF-SEED"
                _G._SDW_NativeHP_LastPresent = false
                applied = true
            end
        end
        -- [FIX] Use the file-local GamePlayTools module (the `_G.GamePlayTools` lookup was always nil).
        pcall(function()
            if GamePlayTools and GamePlayTools.GetCurrentConfig then
                patch(GamePlayTools.GetCurrentConfig("ScreenMarkConfig"))
            end
        end)
        pcall(function()
            if _G.GamePlayTools and _G.GamePlayTools.GetCurrentConfig then
                patch(_G.GamePlayTools.GetCurrentConfig("ScreenMarkConfig"))
            end
        end)
        pcall(function()
            local okGP, gameplayTools = pcall(require, "GameLua.Mod.BaseMod.Common.GamePlayTools")
            if okGP and gameplayTools and gameplayTools.GetCurrentConfig then
                patch(gameplayTools.GetCurrentConfig("ScreenMarkConfig"))
            end
        end)
        pcall(function()
            for moduleName, moduleData in pairs(package.loaded) do
                if type(moduleName) == "string" and string.find(moduleName, "ScreenMarkConfig") and type(moduleData) == "table" then
                    patch(moduleData)
                end
            end
        end)
        return applied
    end

    local function SDW_InitNativeHPGroup()
        -- [SDWxOWNER-PORT] Never re-initialises group 1006; it patches the existing config in-place.
        pcall(function() SDW_ApplyNativeHPConfig() end)
        -- [SDWxOWNER-HEAD-FIX] new.lua re-runs OnInitMarkGroupData(1006) right after patching the
        -- ScreenMarkConfig so the LIVE group actually picks up the new BindSocketName/offset.
        -- Without this re-init the group kept the game's default (torso/"pet") socket, which is
        -- why the bar+name showed at the belly in classic. Mirror new.lua exactly.
        pcall(function()
            if InGameMarkTools and InGameMarkTools.ScreenMarkManager and InGameMarkTools.ScreenMarkManager.OnInitMarkGroupData then
                pcall(InGameMarkTools.ScreenMarkManager.OnInitMarkGroupData, InGameMarkTools.ScreenMarkManager, 1006)
            end
        end)
        _SDW_NativeHPInit = true
        _SDW_NativeHPApplied = true
        return true
    end
    -- [FIX] Expose so the native HP group can be (re)initialised on EVERY map.
    _G.SDW_InitNativeHPGroup = SDW_InitNativeHPGroup

    -- [FIX] Reset the init cache on match/map change so the config is re-applied for EVERY map.
    _G.SDW_ResetNativeHPInit = function()
        _SDW_NativeHPInit = false
        _SDW_NativeHPApplied = false
        _SDW_NativeHP_LastApply = 0
        _SDW_NativeHP_Gen = -1
        _SDW_NativeHP_LastInitTry = 0
    end

    local function SDW_RemoveNativeHPBar(pawn)
        if not pawn then return end
        pcall(function()
            if InGameMarkTools and InGameMarkTools.ClientRemoveMapMark and pawn.NativeHPBarMark then
                InGameMarkTools.ClientRemoveMapMark(pawn.NativeHPBarMark)
            end
        end)
        pcall(function()
            if InGameMarkTools and InGameMarkTools.HideMapMark and pawn.NativeHPBarMark then
                InGameMarkTools.HideMapMark(pawn.NativeHPBarMark)
            end
        end)
        pawn.NativeHPBarMark = nil
        pawn.bHasSDWNativeHPBar = false
    end

    -- [FIX] Remove every native HP-bar mark we added (used on match/map change so
    -- stale marks from the previous map cannot linger).
    _G.SDW_ClearNativeHPMarks = function()
        pcall(function()
            local okP, allP = GetCachedPlayerPawns()
            if okP and allP then
                for _, pawn in pairs(allP) do
                    if SafeIsValid(pawn) and pawn.bHasSDWNativeHPBar then SDW_RemoveNativeHPBar(pawn) end
                end
            end
        end)
    end

    -- [SDWxOWNER-PERF] Reusable closures for the native HP-bar tick.
    local _nhpNamePawn = nil
    local function _nhpHideName()
        local pawn = _nhpNamePawn
        if pawn.SetPlayerNameVisible then pawn:SetPlayerNameVisible(false) end
        if pawn.SetNameVisible then pawn:SetNameVisible(false) end
        if pawn.SetShowName then pawn:SetShowName(false) end
    end
    local _nhpMarkPawn = nil
    -- [SDWxOWNER-PERF PHASE2] Reusable scratch set for Tick_NativeHealthBar so the tick no
    -- longer allocates a fresh table every call (~4x/second for the whole match).
    local _nhpSeen = {}
    local function _nhpAddMark()
        local pawn = _nhpMarkPawn
        if InGameMarkTools and InGameMarkTools.ClientAddMapMark then
            local mk = InGameMarkTools.ClientAddMapMark(1006, FVector(0, 0, 0), 0, "", 4, pawn)
            if mk then
                pawn.NativeHPBarMark = mk
                pawn.bHasSDWNativeHPBar = true
            end
        end
    end

    local function Tick_NativeHealthBar()
        local cfg = _G.SDWConfig
        local enabled = cfg and cfg.NativeHealthBarEnabled
        if _G.SDW_FXCheck then pcall(_G.SDW_FXCheck, "nativehp", enabled and true or false) end

        local localPawn, myPos, hud, pc, myTeamId = GetFrameCache()
        local okPawns, allPawns = GetCachedPlayerPawns()

        if not enabled then
            if okPawns and allPawns then
                for _, pawn in pairs(allPawns) do
                    if SafeIsValid(pawn) and pawn.bHasSDWNativeHPBar then SDW_RemoveNativeHPBar(pawn) end
                end
            end
            return
        end

        if not localPawn then return end
        if not okPawns or not allPawns then return end

        -- [FIX] Keep the ScreenMark config alive for the CURRENT map.
        local now = os.clock()

        -- [FIX] Force a re-init whenever the match/map generation changes.
        local gen = _G._SDW_MatchGen or 0
        if gen ~= _SDW_NativeHP_Gen then
            _SDW_NativeHP_Gen = gen
            _SDW_NativeHPInit = false
            _SDW_NativeHP_LastApply = 0     -- [SDWxOWNER-NHP-DIAG] force an immediate re-apply
            _G._SDW_NativeHP_SeededSelf = false   -- [SDWxOWNER-MATCH2-FIX] per-match reset
            for _, p in pairs(allPawns) do
                if SafeIsValid(p) then p.bHasSDWNativeHPBar = false; p.NativeHPBarMark = nil end
            end
        end

        -- [FIX] Safety net: if enemies are present but NO native HP mark is alive,
        -- the group was reset (e.g. map change) -> re-init it (throttled to 4s).
        if (now - _SDW_NativeHP_LastInitTry) > 4.0 then
            _SDW_NativeHP_LastInitTry = now
            local anyMark = false
            for _, p in pairs(allPawns) do
                if SafeIsValid(p) and p.bHasSDWNativeHPBar then anyMark = true; break end
            end
            if not anyMark then
                _SDW_NativeHPInit = false
                for _, p in pairs(allPawns) do
                    if SafeIsValid(p) then p.bHasSDWNativeHPBar = false; p.NativeHPBarMark = nil end
                end
            end
        end

        if (now - _SDW_NativeHP_LastApply) > 1.0 then
            _SDW_NativeHP_LastApply = now
            local okApply = false
            if not _SDW_NativeHPInit then
                okApply = SDW_InitNativeHPGroup()          -- apply config + (re)init the group
            else
                okApply = SDW_ApplyNativeHPConfig()        -- just keep the config fresh
            end
            if not okApply then _G._SDW_NativeHP_LastWidget = "NO-CONFIG" end
        end

        -- [SDWxOWNER-PERF] The temporary [SDWxOWNER-NHP-DIAG] debug line has been removed.

        -- [SDWxOWNER-PERF PHASE2] Reuse the module-level scratch set (cleared in place)
        -- instead of allocating a new table on every tick.
        local seen = _nhpSeen
        for k in pairs(seen) do seen[k] = nil end
        for _, pawn in pairs(allPawns) do
            if SafeIsValid(pawn) and pawn ~= localPawn then
                -- [SDWxOWNER-ALLMAPS] Robust enemy filter (IDENTICAL to the snapline/wallhack one).
                local pTeam = pawn.TeamID or (type(pawn.GetTeamID) == "function" and pawn:GetTeamID())
                local _isMate = (myTeamId and myTeamId > 0 and pTeam and pTeam > 0 and pTeam == myTeamId)
                local hs = pawn.HealthStatus
                if not _isMate and hs ~= 2 and hs ~= 3 and not pawn.bIsDead and not pawn.bDead then
                    seen[pawn] = true
                    -- [SDWxOWNER-PORT] Show ONLY the health bar: hide the enemy NAME.
                    _nhpNamePawn = pawn
                    pcall(_nhpHideName)
                    if not pawn.bHasSDWNativeHPBar then
                        _nhpMarkPawn = pawn
                        pcall(_nhpAddMark)
                    end
                end
            end
        end

        -- remove marks for pawns that are no longer valid enemies (dead / left)
        for _, pawn in pairs(allPawns) do
            if SafeIsValid(pawn) and pawn.bHasSDWNativeHPBar and not seen[pawn] then
                SDW_RemoveNativeHPBar(pawn)
            end
        end
    end

    local function CleanupESP(pc)
        PBC_ENABLED = false
        if pc and type(ClearModTimers) == "function" then ClearModTimers(pc) end
        if TimerManager and type(TimerManager.ClearAllForOwner) == "function" then
            if _G.Game then TimerManager:ClearAllForOwner(_G.Game) end
            if pc then TimerManager:ClearAllForOwner(pc) end
        end
        AI_CACHE = {}; AI_CACHE_SIZE = 0; PBC_RUNNING = false; retryCount = 0; PBC_MATCH_TOKEN = nil; PBC_TICK_FAILURES = 0; if _G.SDW_ResetNativeHPInit then pcall(_G.SDW_ResetNativeHPInit) end; InvalidatePawnCache()
        if _G.SDW_StopSnapline then pcall(_G.SDW_StopSnapline) end
