        if _G.SDW_BoxESP and _G.SDW_BoxESP.HardClear then pcall(_G.SDW_BoxESP.HardClear) end
        VEH_CACHE = {}; VEH_CACHE_TIME = 0; _G.POS_CACHE = {}; if GK_DestroyWidget then GK_DestroyWidget() end
        -- [SDWxOWNER] V3 iOS counter: full teardown on visuals cleanup.
        if _G.SDW_StopV3Counter then pcall(_G.SDW_StopV3Counter)
        elseif _G.SDW_V3Counter and _G.SDW_V3Counter.Destroy then pcall(_G.SDW_V3Counter.Destroy) end
        -- [SDWxOWNER] V4 HD Image counter: full teardown on visuals cleanup.
        if _G.SDW_StopV4Counter then pcall(_G.SDW_StopV4Counter)
        elseif _G.SDW_V4Counter and _G.SDW_V4Counter.Destroy then pcall(_G.SDW_V4Counter.Destroy) end
        -- [SDWxOWNER] V5 "Player / Bot" counter: full teardown on visuals cleanup.
        if _G.SDW_StopV5Counter then pcall(_G.SDW_StopV5Counter)
        elseif _G.SDW_V5Counter and _G.SDW_V5Counter.Destroy then pcall(_G.SDW_V5Counter.Destroy) end
        -- [SDWxOWNER] Remove the native HP-bar marks we added.
        pcall(function()
            local okP, allP = GetCachedPlayerPawns()
            if okP and allP then
                for _, pawn in pairs(allP) do
