    end

    -- [SDWxOWNER-OFF-FIX] Feature disable cleanup. Labels drawn with hud:AddDebugText
    -- stay attached for their whole lifetime, so a feature looked "still running
    -- faintly" after OFF. On ON->OFF we call ClearAllDebugStrings() and overwrite
    -- each label with "" (bSkipOverwriteCheck=false replaces it in place).
    local function _GetHudNow()
        local hud = nil
        pcall(function()
            local pc = nil
            if slua_GameFrontendHUD then pc = slua_GameFrontendHUD:GetPlayerController() end
            if pc then hud = pc.MyHUD or (pc.GetHUD and pc:GetHUD()) end
        end)
        return hud
    end

    local function _FlushHudLabels()
        local done = false
        pcall(function()
            local hud = _GetHudNow()
            if hud and slua.isValid(hud) then
                for _, m in ipairs({ "ClearAllDebugStrings", "ClearDebugStrings", "FlushDebugStrings" }) do
                    if type(hud[m]) == "function" then pcall(function() hud[m](hud) end); done = true end
                end
            end
        end)
        return done
    end

    local _WHITE_LBL = { R = 255, G = 255, B = 255, A = 255 }
    local function _EraseLabel(hud, actor, offset, color, scale)
        if not (hud and actor and SafeIsValid(actor)) then return end
        pcall(function()
            hud:AddDebugText("", actor, 0.01, offset, offset, color or _WHITE_LBL, false, false, true, nil, scale or 1.0, true)
        end)
    end

    local function _EraseLabelsForList(hud, list, offset, color, scale)
        if not (hud and list) then return end
        for _, it in ipairs(list) do
            local actor = it and (it.actor or it)
            _EraseLabel(hud, actor, offset, color, scale)
        end
    end

    local _FX = {}
    _G.SDW_FXCleanup = _FX

    _FX.healthbar = function()
        if _FlushHudLabels() then return end
        local hud = _GetHudNow(); if not hud then return end
        local okP, allP = GetCachedPlayerPawns()
        if okP and allP then
            for _, pawn in pairs(allP) do _EraseLabel(hud, pawn, TEXT_OFFSET, nil, 1.0) end
        end
    end

    -- [SDWxOWNER-WEAPONESP] Weapon ESP shares the "Distance+ Bot Tag" label. When it is
    -- switched OFF we only erase that shared label if the distance label is ALSO off
    -- (otherwise the next healthbar tick simply rewrites it without the weapon name).
    _FX.weaponesp = function()
        if _G.SDWConfig and _G.SDWConfig.HealthBarESPEnabled then return end
        if _FlushHudLabels() then return end
        local hud = _GetHudNow(); if not hud then return end
        local okP, allP = GetCachedPlayerPawns()
        if okP and allP then
            for _, pawn in pairs(allP) do _EraseLabel(hud, pawn, TEXT_OFFSET, nil, 1.0) end
        end
    end

    -- [SDWxOWNER-WEAPONICON] Weapon ICON ESP cleanup: hide + recycle every icon widget
    -- (and drop cached textures on the next match) when the feature is switched OFF.
    _FX.weaponicon = function()
        pcall(_OPT.WIconClearAll)
    end

    -- [SDWxOWNER-SDWBOX] SDWxOWNER Box ESP cleanup: destroy + detach every box widget
    -- (live + pooled) when the feature is switched OFF.
    _FX.sdwbox = function()
        if _G.SDW_BoxESP and _G.SDW_BoxESP.HardClear then pcall(_G.SDW_BoxESP.HardClear) end
    end

    _FX.vehicle = function()
        if _FlushHudLabels() then return end
        local hud = _GetHudNow(); if not hud then return end
        _EraseLabelsForList(hud, VEH_CACHE, VEH_OFFSET, nil, 1.0)
    end

    _FX.bomb = function()
        if _FlushHudLabels() then return end
        local hud = _GetHudNow(); if not hud then return end
        _EraseLabelsForList(hud, _G.SDW_BombActive, _G.SDW_BOMB_ACTIVE_OFFSET or { X = 0, Y = 0, Z = 25 }, nil, 1.0)
        _EraseLabelsForList(hud, _G.SDW_BombGround, _G.SDW_BOMB_GROUND_OFFSET or { X = 0, Y = 0, Z = 15 }, nil, 1.0)
    end

    _FX.box = function()
        -- Hide the native enemy frame UI that Box ESP turned on.
        for pawn, _ in pairs(_BoxESPCache or {}) do
            pcall(function()
                if SafeIsValid(pawn) and pawn.Replay_SetVisiableOfFrameUI then
                    pawn:Replay_SetVisiableOfFrameUI(false)
                end
            end)
        end
        _BoxESPCache = setmetatable({}, { __mode = "k" })
        if _FlushHudLabels() then return end
        local hud = _GetHudNow(); if not hud then return end
        local okP, allP = GetCachedPlayerPawns()
        if okP and allP then
            for _, pawn in pairs(allP) do _EraseLabel(hud, pawn, _BOX_OFF_NAME, nil, 1.0) end
        end
    end

    _FX.wallhack = function()
        if _G.SDWState and _G.SDWState.EnemyMarks then
            for _, md in pairs(_G.SDWState.EnemyMarks) do
                if md and md.enemy then pcall(function() UndoColorBodyNew(md.enemy, md) end) end
            end
            _G.SDWState.EnemyMarks = {}
        end
    end

    _FX.nativehp = function()
        pcall(function()
            local okP, allP = GetCachedPlayerPawns()
            if okP and allP then
                for _, pawn in pairs(allP) do
                    if SafeIsValid(pawn) and pawn.bHasSDWNativeHPBar then SDW_RemoveNativeHPBar(pawn) end
                end
            end
        end)
    end

    _FX.snapline = function()
        -- [SDWxOWNER-LINE FIX] Stop the driver FIRST (so no pending/queued tick can
        -- re-show a line), then hard-clear every widget on every map.
        -- [SDWxOWNER-SDWBOX] BUT if the SDWxOWNER Box ESP (or the Weapon ICON ESP) still
        -- needs the shared 10 Hz driver, keep it alive and only sweep the LINE widgets
        -- (ClearAllSnapLines) instead of HardClear, so the shared canvas handle is not
        -- dropped out from under the box widgets.
        local keepDriver = _G.SDWConfig and (_G.SDWConfig.WeaponIconESPEnabled or _G.SDWConfig.SDWBoxESPEnabled)
        if _G.SDW_StopSnapline and not keepDriver then pcall(_G.SDW_StopSnapline) end
        pcall(function()
            if keepDriver then
                if SnaplineESP.ClearAllSnapLines then SnaplineESP.ClearAllSnapLines() end
            else
                if SnaplineESP.HardClear then SnaplineESP.HardClear()
                elseif SnaplineESP.Clear then SnaplineESP.Clear() end
            end
        end)
    end

    _FX.counter = function()
        if _G.SDW_Counter_Clear then pcall(_G.SDW_Counter_Clear) end
        if GK_DestroyWidget then pcall(GK_DestroyWidget) end
    end

    _G.SDW_DisableFeature = function(name)
        local fn = _FX[name]
        if fn then pcall(fn) end
    end

    -- Edge-detect ON -> OFF for ANY toggle path (menu, config load, another toggle).
    local _FXState = {}
    _G.SDW_FXCheck = function(name, isOn)
        local prev = _FXState[name]
        _FXState[name] = isOn and true or false
        if prev == true and not isOn then
            local fn = _FX[name]
            if fn then pcall(fn) end
        end
    end


    local function StartVisuals(force)
        if not _G.LOGIN_OK then return end
        if _G.VisualsStarted and not force then
            if _G.VisualTimerIds and #_G.VisualTimerIds > 0 then return true end
        end
        pcall(function()
            if _G.VisualTimerIds and TimerManager then
                for _, tid in ipairs(_G.VisualTimerIds) do
                    pcall(function() TimerManager:Clear(tid) end)
                end
            end
            _G.VisualTimerIds = nil
            if TimerManager and type(TimerManager.PurgeDeadTimers) == "function" then
                TimerManager:PurgeDeadTimers()
            end
        end)
        -- [SDWxOWNER-PERSIST FIX] Snapline runs on its own driver (SDW_EnsureSnapline), so
        -- it is intentionally not stopped/registered here.
        _G.VisualsStarted = false
        if GK_DestroyWidget then GK_DestroyWidget() end; VEH_CACHE = {}; VEH_CACHE_TIME = 0; SetupConsole()
        local timerOwner = nil
        if _G.Game and _G.Game.AddGameTimer then timerOwner = _G.Game
        else
            local pc2 = nil; if slua_GameFrontendHUD then local okPc, retPc = SafeMethodCall(slua_GameFrontendHUD, "GetPlayerController"); if okPc then pc2 = retPc end end
            if SafeIsValid(pc2) and pc2.AddGameTimer then timerOwner = pc2 end
        end
        if timerOwner and TimerManager then
            -- [SDWxOWNER-PERF] Hoisted timer callbacks. These were inline closures in the
            -- specs table below. They are only built once per StartVisuals, but hoisting them
            -- to named statics keeps the sub-0.2s drivers (Spin 0.008s, Size 0.2s) closure-free
            -- and leaves the registration block allocation-clean.
            local function _specLoopTick()
                local last = _G._SDW_LastTick or 0
                if (os.time() - last) > 12 then
                    if _G._SDW_FastTick then pcall(_G._SDW_FastTick) end
                end
            end
            -- [ZEROLAG] The TimerManager wrapper already pcall()s every callback, so the inner
            -- pcall() here was a redundant SECOND protected call on every beat. Dropped (crash
            -- safety unchanged: the wrapper still catches any error). Also hoists the global read.
            local function _specSpinTick() local f = _G.SDW_SpinTick; if f then f() end end
            local function _specSizeTick() local f = _G.SDW_SizeTick; if f then f() end end
            local function _specMenuTick() local f = _G.SDW_MenuTick; if f then f() end end
            local specs = {
                -- [SDWxOWNER-PERF FIX] Tick rates re-balanced to match the proven, smooth SDWxOWNER profile.
                -- [SDWxOWNER-LAGFIX v4.7] ESP cadence throttled to new.lua's proven low-lag profile.
                -- Every feature stays registered & active; only the refresh RATE drops, so the
                -- per-second Lua work (pawn scan + AddDebugText/widget writes) falls sharply with
                -- ZERO loss of functionality. HealthBar label lifetime is 4.0s, so a 1.0s tick
                -- still never blinks. (new.lua reference: HealthBar 2.0s, Wallhack 2.5s, Vehicle 10.0s.)
                {"ESP_HealthBar", 1.0, "HealthBar", Tick_HealthBarESP},
                {"ESP_Counter", 3.0, "Counter", Tick_CounterESP},
                {"ESP_Wallhack", 1.5, "Wallhack", Tick_Wallhack},
                {"ESP_Bombs", 3.0, "BombESP", _G.Tick_SDW_BombESP},
                {"ESP_Vehicles", 6.0, "VehicleESP", Tick_Vehicles},
                {"ESP_Box", 5.0, "BoxESP", Tick_BoxESP},
                {"ESP_NativeHP", 0.5, "NativeHealthBar", Tick_NativeHealthBar},
                {"ESP_Loop", 1.0, "UI", _specLoopTick},
                -- [SDWxOWNER-PERSIST FIX] Snapline not registered here (single driver only).
                -- [SDWxOWNER-SPIN FIX] Spin driver runs per-frame (0.008s).
                -- [SDWxOWNER-PERF T3] Spin fallback timer throttled 0.008s (125 Hz) -> 0.2s.
                -- The authoritative driver is the per-frame ReceiveTick hook (see SpinTick);
                -- this timer only re-asserts the spin when that hook is momentarily absent,
                -- so it no longer burns a 125 Hz Lua callback on every match frame.
                {"ESP_Spin", 0.008, "Spin", _specSpinTick},
                -- [SDWxOWNER] EXTRA FEATURES: Character/Gun size driver (0.35s, change-driven).
                {"ESP_Size", 0.35, "Size", _specSizeTick},
                {"ESP_Menu", 1.0, "UI", _specMenuTick},
            }
            local created = {}
            for _, spec in ipairs(specs) do
                local id = TimerManager:Register(timerOwner, spec[1], spec[2], true, spec[3], spec[4])
                if not id then
                    for _, createdId in ipairs(created) do pcall(function() TimerManager:Clear(createdId) end) end
                    _G.VisualTimerIds = nil
                    _G.VisualsStarted = false
                    return false
                end
                created[#created + 1] = id
            end
            _G.VisualTimerIds = created
            _G.VisualsStarted = true
            pcall(function()
                TimerManager:Register(timerOwner, "ESP_Watchdog", 30.0, true, "Diagnostic", function()
                    if not _G.VisualsStarted then return end
                    if not _G.VisualTimerIds then return end
                    local anyAlive = false
                    for _, tid in ipairs(_G.VisualTimerIds) do
                        if TimerManager._byId[tid] then anyAlive = true; break end
                    end
                    if not anyAlive then
                        _G.VisualsStarted = false
                        _G.VisualTimerIds = nil
                    end
                end)
            end)
            pcall(_G.SDW_EnsureSnapline)
            return true
        end
        return false
    end

    local function StopVisuals()
        pcall(function()
            if _G.VisualTimerIds and TimerManager then
                for _, id in ipairs(_G.VisualTimerIds) do pcall(function() TimerManager:Clear(id) end) end
            end
            if _G.SDW_StopSnapline then pcall(_G.SDW_StopSnapline) end
            if SnaplineESP.HardClear then SnaplineESP.HardClear() else SnaplineESP.Clear() end
            if _G.SDW_BoxESP and _G.SDW_BoxESP.HardClear then pcall(_G.SDW_BoxESP.HardClear) end
            _G.VisualTimerIds = nil
            _G.VisualsStarted = false
            if _G.SDWState and _G.SDWState.EnemyMarks then
                for _, md in pairs(_G.SDWState.EnemyMarks) do
                    if md and md.enemy and UndoColorBodyNew then UndoColorBodyNew(md.enemy, md) end
                end
                _G.SDWState.EnemyMarks = {}
            end
        end)
    end

    local function StartPBC()
        if _G._MOD_EXPIRED or _G._SDW_LOCKED then return false end
        if PBC_ENABLED and _G.WH_TIMER_BR then
            pcall(SetupConsole)
            return true
        end
        PBC_ENABLED = true
        pcall(SetupConsole)
        StartVisuals()
        _G.WH_TIMER_BR = true
        return PBC_ENABLED
    end

    local _RETRY_TIMER_ACTIVE = false
    local _RETRY_GENERATION = 0
    local function RetryStart()
        if retryCount >= 30 or _RETRY_TIMER_ACTIVE then return end
        retryCount = retryCount + 1
        local generation = _RETRY_GENERATION
        if StartPBC() then
            _RETRY_TIMER_ACTIVE = false
            return
        end
        if _G.Game and _G.Game.AddGameTimer then
            _RETRY_TIMER_ACTIVE = true
            pcall(_G.Game.AddGameTimer, _G.Game, 5.0, false, function()
                _RETRY_TIMER_ACTIVE = false
                if generation ~= _RETRY_GENERATION then return end
                RetryStart()
            end)
        end
    end


    _G.StartVisuals = StartVisuals
    _G.StopVisuals = StopVisuals
    _G.StartPBC = StartPBC
    _G.CleanupESP = CleanupESP
    _G.SnaplineESP = SnaplineESP
    _G.Tick_SnaplineESP = Tick_SnaplineESP
    _G.Tick_SnaplineESP_Fast = Tick_SnaplineESP_Fast
    _G.Tick_HealthBarESP = Tick_HealthBarESP
    _G.Tick_CounterESP = Tick_CounterESP
    _G.Tick_Wallhack = Tick_Wallhack
    _G.Tick_Vehicles = Tick_Vehicles
    _G.Tick_BoxESP = Tick_BoxESP
    -- [SDWxOWNER-SDWBOX] New corner-bracket Box ESP (design + frozen positioning).
    _G.SDW_BoxESP = _G.SDW_BoxESP
    _G.Tick_SDW_BoxESP = _G.SDW_BoxESP and _G.SDW_BoxESP.Tick
    _G.Tick_NativeHealthBar = Tick_NativeHealthBar
    _G.Tick_SDW_BombESP = _G.Tick_SDW_BombESP
    _G.GK_DestroyWidget = GK_DestroyWidget
    _G.GK_GetOrCreateWidget = GK_GetOrCreateWidget
    _G.GK_UpdateWidget = GK_UpdateWidget
    _G.ApplyColorBodyNew = ApplyColorBodyNew
    _G.UndoColorBodyNew = UndoColorBodyNew
    _G.SetupConsole = SetupConsole
    _G._GK_RETRY_GENERATION = { get = function() return _RETRY_GENERATION end, set = function(v) _RETRY_GENERATION = v end }
    _G._GK_RETRY_TIMER_ACTIVE = { get = function() return _RETRY_TIMER_ACTIVE end, set = function(v) _RETRY_TIMER_ACTIVE = v end }
    _G._GK_retryCount = { get = function() return retryCount end, set = function(v) retryCount = v end }
    _G._GK_AI_CACHE = { reset = function() AI_CACHE = {}; AI_CACHE_SIZE = 0 end }
    _G._GK_VEH_CACHE = { reset = function() VEH_CACHE = {}; VEH_CACHE_TIME = 0 end }
    _G._GK_PBC_MATCH_TOKEN = { set = function(v) PBC_MATCH_TOKEN = v end }
    _G._GK_PBC_TICK_FAILURES = { set = function(v) PBC_TICK_FAILURES = v end }
    _G._GK_PBC_RUNNING = { set = function(v) PBC_RUNNING = v end }
    _G._GK_PBC_ENABLED = { get = function() return PBC_ENABLED end, set = function(v) PBC_ENABLED = v end }
    _G.InvalidatePawnCache = InvalidatePawnCache
    _G.RetryStart = RetryStart
end


