    -- [SDWxOWNER] Runtime named-skin resolver (SDWxOWNER technique): auto-find skins by
    -- name (bag #5 Polar Prism, #6 Corrupted Crown, helmet #3 Masked Psychic).
    _G.SDW_ResolveNamedSkins = function()
        if _G._SDW_NamedResolveDone then return end
        pcall(function()
            local CT = _G.CDataTable or CDataTable
            if not (CT and CT.GetTable) then return end
            local itemTable = CT.GetTable("Item")
            if not itemTable then return end
            -- Readiness: wait until the Item table is actually populated.
            local probes = { 1101004246, 1405628 }
            local hits = 0
            for _, pid in ipairs(probes) do
                if itemTable[pid] or itemTable[tostring(pid)] then hits = hits + 1 end
            end
            if hits < 1 then return end -- not loaded yet -> retry next tick
            _G._SDW_NamedResolveDone = true

            local function nameToString(name)
                if name == nil then return "" end
                if type(name) == "string" then return name end
                if type(name) == "userdata" then
                    local s
                    pcall(function() if name.ToString then s = name:ToString() end end)
                    if type(s) == "string" then return s end
                    pcall(function() if name.ToWString then s = name:ToWString() end end)
                    if type(s) == "string" then return s end
                end
                if type(name) == "table" and name.SourceString then return name.SourceString end
                return tostring(name)
            end
            local function norm(s) return string.lower(nameToString(s)) end
            local function has(s, sub) return string.find(s, sub, 1, true) ~= nil end

            -- [FIX] Bag #5 / #6 and Helmet #3 are now HARDCODED in _G.OutfitSkins
            -- with the exact ids from the 4.5.0 dump (Polar Prism / Corrupted
            -- Crown / Masked Psychic). So this resolver no longer name-scans the
            -- Item table for bag/helmet -- it only resolves the M416 Glacier
            -- weapon skin (the single thing that still needs runtime lookup).
            local glacierBest
            for k, v in pairs(itemTable) do
                local rid = tonumber(k)
                if not rid then rid = tonumber(v.ID or v.Id or v.ItemID) end
                if rid and rid >= 1101004000 and rid < 1101005000 then
                    local nm = norm(v.ItemName or v.Name or v.name)
                    if nm ~= "" and has(nm, "glacier") then
                        if not glacierBest or rid < glacierBest then glacierBest = rid end
                    end
                end
            end
            local cd = _G.SDWState and _G.SDWState.CustomTextData
            if glacierBest and _G.skinIdMappings and _G.skinIdMappings[101004] then
                _G.skinIdMappings[101004][7] = glacierBest
                if cd and tonumber(cd.SkinM416) == 7 and _G.WeaponSkinMap then _G.WeaponSkinMap[101004] = glacierBest end
                _G._SDW_SkinMapSig = nil
            end
        end)
    end

    local function DownloadGameItem(id)
        if not id or id == 0 then return end
        local puffer_manager = package.loaded['client.slua.logic.download.puffer.puffer_manager'] or require('client.slua.logic.download.puffer.puffer_manager')
        local puffer_const = package.loaded['client.slua.logic.download.puffer_const'] or require('client.slua.logic.download.puffer_const')
        if puffer_manager and puffer_const and puffer_manager.GetState and puffer_const.ENUM_DownloadType and puffer_const.ENUM_DownloadState then
            -- [SDWxOWNER-FIX] ENUM_DownloadType.ODPTD does NOT exist. The real enum is
            -- ODPAK/ODPACK/MAP/RES/SHADER/PREFETCH/UGCPAK/UGCPACK, so the old "ODPTD"
            -- lookup was nil and the skin package (which also carries the kill-counter
            -- background texture) was NEVER downloaded -> the kill counter skin never
            -- showed even though the kill counter itself worked. Weapon/outfit skins
            -- live in the ODPAK bundle (same type the working reference uses).
            local dlType = puffer_const.ENUM_DownloadType.ODPAK
            if dlType and puffer_manager.GetState(dlType, {id}) ~= puffer_const.ENUM_DownloadState.Done then
                pcall(puffer_manager.Download, dlType, {id})
            end
        end
    end
    _G.download_item = DownloadGameItem

    _G.get_skin_id = function(weaponID)
        if not weaponID then return nil end
        local targetSkinId = _G.WeaponSkinMap and _G.WeaponSkinMap[weaponID]
        if targetSkinId and targetSkinId > 0 then
            if not _G.skinIdCache2[targetSkinId] then
                if _G.download_item then pcall(_G.download_item, targetSkinId) end
                _G.skinIdCache2[targetSkinId] = true
            end
            return targetSkinId
        end
        return weaponID
    end

    _G.equip_character_avatar = function(Character)
        if not Character or not Valid(Character) or not Character.AvatarComponent2 then return end
        local BackpackUtils = import("BackpackUtils")
        local NetAvatarData = Character.AvatarComponent2.NetAvatarData
        local SlotSyncData = NetAvatarData and NetAvatarData.SlotSyncData
        if not SlotSyncData or not Valid(SlotSyncData) or not BackpackUtils then return end

        local function _SDW_ResolveOutfitMap()
            if _G.ForceRefreshSkinMaps then _G.ForceRefreshSkinMaps() end
            return _G.OutfitMap or {}
        end

        local om = _SDW_ResolveOutfitMap()

        local needsFullApply = false
        if Character._LastAppliedOutfitHash then
            local currentOutfitHash = (om.Suit or 0) + (om.Pants or 0) * 3 + (om.Hair or 0) * 7 + (om.Parachute or 0) * 11
            if Character._LastAppliedOutfitHash ~= currentOutfitHash then
                needsFullApply = true
            else
                local numSlots = SlotSyncData:Num()
                for i = 0, numSlots - 1 do
                    local slotData = SlotSyncData:Get(i)
                    if slotData and slotData.SlotID then
                        local expectedItemId = 0
                        if slotData.SlotID == _G.CustSlotType.ClothesEquipemtSlot then expectedItemId = om.Suit or 0
                        elseif slotData.SlotID == 6 then expectedItemId = om.Pants or 0
                        elseif slotData.SlotID == 7 then expectedItemId = om.Hair or 0
                        elseif slotData.SlotID == _G.CustSlotType.BackpackEquipemtSlot then expectedItemId = om.Bag or 0
                        elseif slotData.SlotID == _G.CustSlotType.HelmetEquipemtSlot then expectedItemId = om.Helmet or 0
                        elseif slotData.SlotID == _G.CustSlotType.ParachuteEquipemtSlot then expectedItemId = om.Parachute or 0
                        end
                        if expectedItemId ~= 0 and slotData.ItemId ~= expectedItemId then
                            needsFullApply = true
                            break
                        end
                    end
                end
            end
        end

        if not Character._OutfitApplied or needsFullApply then
            Character._OutfitApplied = false
            Character._LastAppliedOutfitHash = nil
        end

        -- [SDWxOWNER-PERF] reuse the already-resolved outfit map (avoids a 2nd ForceRefreshSkinMaps per call)
        local isAnyModified = false

        local function EquipAvatar(ApplyDataIdx, mappedSkin, ApplyEquipSlot, isLevelDependent, levelFunc)
            if not mappedSkin or mappedSkin == 0 then return end
            local slotData = SlotSyncData:Get(ApplyDataIdx)
            if slotData and slotData.SlotID == ApplyEquipSlot then
                local applyItemId = mappedSkin
                if isLevelDependent and type(mappedSkin) == "table" then
                    local level = levelFunc and levelFunc(slotData.AdditionalItemID) or 1
                    if level < 1 then level = 1 end
                    if level > 3 then level = 3 end
                    applyItemId = mappedSkin[level] or mappedSkin[1]
                end

                if not applyItemId or applyItemId == 0 then return end

                -- [SkinFix] Bag/Helmet are loot-managed during a match: picking up
                -- a backpack/helmet overwrites the slot and the streamed texture
                -- unloads after ~10s. So for these two slots we RE-ASSERT every
                -- tick -- re-request the asset AND force a mesh rebuild -- even
                -- when the id already matches. Every other slot keeps the original
                -- "write only when changed" behaviour (those already stay applied
                -- full-time).
                local _isBagHelmet = (ApplyEquipSlot == _G.CustSlotType.BackpackEquipemtSlot)
                                  or (ApplyEquipSlot == _G.CustSlotType.HelmetEquipemtSlot)

                if _isBagHelmet then
                    if _G.download_item then pcall(_G.download_item, applyItemId) end
                    slotData.ItemId = applyItemId
                    SlotSyncData:Set(ApplyDataIdx, slotData)
                    isAnyModified = true
                    return
                end

                if not _G.skinIdCache[applyItemId] then
                    if _G.download_item then pcall(_G.download_item, applyItemId) end
                    _G.skinIdCache[applyItemId] = true
                end

                if slotData.ItemId == applyItemId then return end

                slotData.ItemId = applyItemId
                SlotSyncData:Set(ApplyDataIdx, slotData)
                isAnyModified = true
            end
        end

        local slotPresence = {}
        local numSlots = SlotSyncData:Num()
        for i = 0, numSlots - 1 do
            local slotData = SlotSyncData:Get(i)
            if slotData and slotData.SlotID then
                slotPresence[slotData.SlotID] = i
            end
        end

        if not slotPresence[_G.CustSlotType.GlideEquipemtSlot] then
            SlotSyncData:Add({ SlotID = _G.CustSlotType.GlideEquipemtSlot, ItemId = 0 })
            isAnyModified = true
        end

        if om.Suit and om.Suit ~= 0 and not slotPresence[_G.CustSlotType.ClothesEquipemtSlot] then
            SlotSyncData:Add({ SlotID = _G.CustSlotType.ClothesEquipemtSlot, ItemId = 0 })
            isAnyModified = true
        end

        for i = 0, SlotSyncData:Num() - 1 do
            EquipAvatar(i, om.Suit or 0, _G.CustSlotType.ClothesEquipemtSlot, false)
            EquipAvatar(i, om.Pants or 0, 6, false)
            EquipAvatar(i, om.Hair or 0, 7, false)
            EquipAvatar(i, om.Bag, _G.CustSlotType.BackpackEquipemtSlot, true, BackpackUtils.GetEquipmentBagLevel)
            EquipAvatar(i, om.Helmet, _G.CustSlotType.HelmetEquipemtSlot, true, BackpackUtils.GetEquipmentHelmetLevel)
            EquipAvatar(i, om.Parachute or 0, _G.CustSlotType.ParachuteEquipemtSlot, false)
        end

        if isAnyModified and Character.AvatarComponent2.OnRep_BodySlotStateChanged then
            -- [SDWxOWNER-PERF/CRASH FIX] Open a skin/avatar swap window so the per-frame
            -- spin/TPP hooks stay OFF the mesh while it is being rebuilt.
            _G._SDW_SkinSwapUntil = os.clock() + 0.4
            pcall(function() Character.AvatarComponent2:OnRep_BodySlotStateChanged() end)
        end
        Character._OutfitApplied = true
    end

    -- [SkinFix] Fast, self-contained bag/helmet re-assert. The backpack and
    -- helmet slots are loot-managed during a match: picking one up overwrites
    -- the slot (and the streamed texture can unload), so the slider skin is
    -- lost after a few seconds. This re-applies the slider skin on a fast timer
    -- so it always wins. Only Bag + Helmet are touched; every other slot is
    -- left exactly as before.
    local function _SDW_LocalPawn()
        local pawn = nil
        pcall(function()
            if slua_GameFrontendHUD then
                local pc = slua_GameFrontendHUD:GetPlayerController()
                if pc and pc.GetPlayerCharacterSafety then pawn = pc:GetPlayerCharacterSafety() end
            end
        end)
        if not (pawn and slua and slua.isValid(pawn)) then
            local gpd = package.loaded["GameLua.GameCore.Data.GameplayData"]
            if gpd and gpd.GetPlayerCharacter then pcall(function() pawn = gpd.GetPlayerCharacter() end) end
        end
        return pawn
    end

    _G.SDW_ReassertBagHelmet = function(pawn)
        if not (_G.SDWConfig and _G.SDWConfig.ModSkin) then return end
        pawn = pawn or _SDW_LocalPawn()
        if not (pawn and slua and slua.isValid(pawn) and pawn.AvatarComponent2) then return end
        local Net = pawn.AvatarComponent2.NetAvatarData
        local SSD = Net and Net.SlotSyncData
        if not (SSD and slua.isValid(SSD)) then return end
        local om = _G.OutfitMap
        if not om then return end
        local BU = import("BackpackUtils")
        local wrote = false
        local function apply(slotConst, levels, levelFn)
            if not levels or type(levels) ~= "table" then return end
            for i = 0, SSD:Num() - 1 do
                local sd = SSD:Get(i)
                if sd and sd.SlotID == slotConst then
                    local lvl = 1
                    if levelFn then pcall(function() lvl = levelFn(sd.AdditionalItemID) or 1 end) end
                    if lvl < 1 then lvl = 1 elseif lvl > 3 then lvl = 3 end
                    local id = levels[lvl] or levels[1]
                    if id and id ~= 0 then
                        if _G.download_item then pcall(_G.download_item, id) end
                        if sd.ItemId ~= id then
                            sd.ItemId = id
                            SSD:Set(i, sd)
                            wrote = true
                        end
                    end
                    return
                end
            end
        end
        apply(_G.CustSlotType.BackpackEquipemtSlot, om.Bag, BU and BU.GetEquipmentBagLevel)
        apply(_G.CustSlotType.HelmetEquipemtSlot, om.Helmet, BU and BU.GetEquipmentHelmetLevel)
        if wrote then
            _G._SDW_SkinSwapUntil = os.clock() + 0.3
            pcall(function() pawn.AvatarComponent2:OnRep_BodySlotStateChanged() end)
        end
    end

    -- Drive the re-assert on a 0.5s timer so an in-match loot overwrite is
    -- corrected within half a second.
    pcall(function()
        local ok, ticker = pcall(require, "common.time_ticker")
        if ok and ticker and ticker.AddTimerOnce then
            local function _loop()
                if _G.SDW_IsAuthorized and _G.SDW_IsAuthorized() then
                    pcall(_G.SDW_ReassertBagHelmet)
                end
                pcall(function() ticker.AddTimerOnce(0.5, _loop) end)
            end
            ticker.AddTimerOnce(0.5, _loop)
        end
    end)

    _G.ApplyWeaponSkins = function(PlayerCharacter)
        pcall(function()
            if not Valid(PlayerCharacter) then return end
            local WeaponManager = PlayerCharacter:GetWeaponManager()
            if not Valid(WeaponManager) then return end

            if _G.ForceRefreshSkinMaps then _G.ForceRefreshSkinMaps() end

            -- [SDWxOWNER-PICKUP-CRASH-FIX] Count filled attachment slots; on change open a
            -- swap window and skip the weapon so the native rebuild settles (UAF).
            _G._SDW_WeaponSlotCount = _G._SDW_WeaponSlotCount or setmetatable({}, { __mode = "k" })
            local function CountFilledSlots(Weapon)
                local n = 0
                pcall(function()
                    for ai = 0, 5 do
                        local ad = Weapon.synData:Get(ai)
                        if ad and ad.defineID then
                            local v = tonumber(ad.defineID.TypeSpecificID) or 0
                            if v > 0 then n = n + 1 end
                        end
                    end
                end)
                return n
            end

            local function SkinSingleWeapon(Weapon)
                if not Valid(Weapon) or not Valid(Weapon.synData) then return end

                local WeaponID = Weapon:GetWeaponID()
                local SkinID = _G.get_skin_id(WeaponID) or WeaponID
                local isModified = false

                -- [SDWxOWNER-PICKUP-CRASH-FIX] Layout-change guard (pickup / new attach).
                local slotCount = CountFilledSlots(Weapon)
                local prevCount = _G._SDW_WeaponSlotCount[Weapon]
                _G._SDW_WeaponSlotCount[Weapon] = slotCount
                if prevCount ~= nil and prevCount ~= slotCount then
                    _G._SDW_SkinSwapUntil = os.clock() + 1.0
                    return
                end

                local SkinData = Weapon.synData:Get(7)
                -- [SDWxOWNER-PICKUP-CRASH-FIX] Re-validate weapon + synData RIGHT before the
                -- native write (they can be freed between the guard above and here).
                if SkinData and SkinData.defineID and SkinData.defineID.TypeSpecificID ~= SkinID then
                    if Valid(Weapon) and Valid(Weapon.synData) then
                        SkinData.defineID.TypeSpecificID = SkinID
                        Weapon.synData:Set(7, SkinData)
                        if Weapon.SetWeaponAvatarID then pcall(function() Weapon:SetWeaponAvatarID(SkinID) end) end
                        if not _G.skinIdCache[SkinID] then
                            if _G.download_item then _G.download_item(SkinID) end
                            _G.skinIdCache[SkinID] = true
                        end
                        isModified = true
                    end
                end

                if SkinID and SkinID >= 10000000 and _G.VIP_Attachments and _G.VIP_Attachments[SkinID] then
                    for AttachIdx = 0, 5 do
                        -- [SDWxOWNER-PICKUP-CRASH-FIX] Re-validate the weapon + synData for
                        -- EVERY slot (the weapon can be rebuilt mid-loop).
                        if Valid(Weapon) and Valid(Weapon.synData) then
                            local attachData = Weapon.synData:Get(AttachIdx)
                            if attachData then
                                local defineIDRef = slua and slua.IndexReference and slua.IndexReference(attachData, "defineID")
                                if defineIDRef then
                                    local attachmentId = defineIDRef.TypeSpecificID
                                    if attachmentId and attachmentId > 0 then
                                        local mapIndex = _G.BaseAttachToIndex[attachmentId] or _G.VipAttachToIndex[attachmentId]
                                        if mapIndex and _G.VIP_Attachments[SkinID][mapIndex] and _G.VIP_Attachments[SkinID][mapIndex] > 0 then
                                            local targetAttachId = _G.VIP_Attachments[SkinID][mapIndex]
                                            if targetAttachId ~= attachmentId then
                                                -- Re-fetch the slot one last time right before
                                                -- the write so we never write a stale object.
                                                local attachData2 = Weapon.synData:Get(AttachIdx)
                                                if attachData2 and attachData2.defineID then
                                                    attachData2.defineID.TypeSpecificID = targetAttachId
                                                    Weapon.synData:Set(AttachIdx, attachData2)
                                                    if not _G.skinIdCache2[targetAttachId] then
                                                        if _G.download_item then pcall(_G.download_item, targetAttachId) end
                                                        _G.skinIdCache2[targetAttachId] = true
                                                    end
                                                    isModified = true
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end

                if isModified then
                    -- [SDWxOWNER-CRASH FIX] Open a 1.0s swap window so the spin hook stays
                    -- off the mesh during the attachment rebuild.
                    _G._SDW_SkinSwapUntil = os.clock() + 1.0
                    if Valid(Weapon) then
                        if Weapon.DelayHandleAvatarMeshChanged then pcall(function() Weapon:DelayHandleAvatarMeshChanged() end) end
                        if Weapon.OnRep_synData then pcall(function() Weapon:OnRep_synData() end) end
                    end
                end
            end

            for slot = 1, 5 do
                local Weapon = WeaponManager:GetInventoryWeaponByPropSlot(slot)
                SkinSingleWeapon(Weapon)
            end

            local curWeapon = PlayerCharacter.GetCurrentWeapon and PlayerCharacter:GetCurrentWeapon()
            if Valid(curWeapon) then
                SkinSingleWeapon(curWeapon)
            end
        end)
    end

    -- ============================================================================
    -- [SDWxOWNER-ERANGEL-VEH-CRASH-FIX] Vehicle-skin rebuild stabilizer.
    -- ----------------------------------------------------------------------------
    -- ROOT CAUSE (shared by oldupdate.lua and 1.lua): ApplyVehicleSkins() is invoked
    -- SYNCHRONOUSLY from the engine's OnAttachedToVehicle / OnDetachedFromVehicle
    -- callback. The old file registers those handlers directly
    -- (BRPlayerCharacterBase:HandleOnAttachedToVehicle / HandleOnDetachedFromVehicle,
    -- oldupdate.lua lines 4720-4733) and both of them end with
    --   `if _G.ApplyVehicleSkins then pcall(_G.ApplyVehicleSkins, self) end`.
    -- The current file keeps the same call path: the handlers live in the external
    -- injector (see the note at 1.lua line 1549) and call the SAME global.
    --
    -- ApplyVehicleSkins then immediately performs a heavy native avatar rebuild
    -- (VehicleAvatar:ChangeItemAvatar). At that instant the engine is still
    -- re-parenting the pawn and (re)building the vehicle's avatar components, so the
    -- rebuild races the engine's own transition and dereferences a component that is
    -- mid-teardown -> a native use-after-free. pcall CANNOT catch a native crash, so
    -- the whole game dies. The race window widens on slower devices (longer
    -- transition) and fires far more often on Erangel (many more vehicles + enter/exit
    -- events per match) than on Livik -- exactly the reported symptom.
    --
    -- FIX: never rebuild inside the event callback. Queue ONE deferred rebuild per
    -- vehicle and re-validate everything at fire time (pawn alive, still seated in
    -- THIS vehicle, vehicle not pending-kill, avatar still valid + owned by the
    -- vehicle). A per-vehicle throttle stops rapid enter/exit from stacking rebuilds.
    -- If no scheduler is available the rebuild falls back to an immediate, fully
    -- guarded call. Vehicle skins still apply (just ~0.2s later), and all other
    -- features are untouched.
    -- ============================================================================
    _G._SDW_VehSkinPending = _G._SDW_VehSkinPending or setmetatable({}, { __mode = "k" })
    _G._SDW_VehSkinAt      = _G._SDW_VehSkinAt      or setmetatable({}, { __mode = "k" })

    local function _SDW_VehSkinStillStable(pc, veh, av)
        if not (pc and slua and slua.isValid and slua.isValid(pc)) then return false end
        if not (veh and slua.isValid(veh)) then return false end
        if not (av and slua.isValid(av)) then return false end
        -- Vehicle must not be mid-destruction (exploded / despawning).
        if veh.bPendingKill == true or veh.bIsPendingKill == true then return false end
        if type(veh.IsPendingKill) == "function" then
            local okPK, pk = pcall(veh.IsPendingKill, veh)
            if okPK and pk == true then return false end
        end
        -- The pawn must STILL be seated in this exact vehicle (no mid-transition).
        local okCur, cur = pcall(function() return pc:GetCurrentVehicle() end)
        if not okCur or cur ~= veh then return false end
        -- The avatar component must still belong to this vehicle.
        if type(av.GetOwner) == "function" then
            local okOwn, owner = pcall(av.GetOwner, av)
            if okOwn and owner and owner ~= veh then return false end
        end
        return true
    end

    local function _SDW_VehSkinRebuild(pc, veh, av, skinId)
        -- Re-validate EVERYTHING immediately before the native write.
        if not _SDW_VehSkinStillStable(pc, veh, av) then return end
        -- Per-vehicle throttle: never rebuild the same vehicle more than once per 1.5s.
        local now = os.clock()
        local last = _G._SDW_VehSkinAt[veh]
        if last and (now - last) < 1.5 then return end
        _G._SDW_VehSkinAt[veh] = now
        av.curSwitchEffectId = 7303001
        -- Open a skin/avatar swap window so the per-frame spin / aim hooks stay off the mesh.
        _G._SDW_SkinSwapUntil = os.clock() + 0.4
        if av.ChangeItemAvatar then av:ChangeItemAvatar(skinId, true) end
        _G.CurrentEquipVehicleID = skinId
        _G.LastVehicleEntity = veh
    end

    local function _SDW_QueueVehicleSkin(pc, veh, av, skinId)
        if not (veh and slua and slua.isValid and slua.isValid(veh)) then return end
        -- One outstanding deferred rebuild per vehicle. A stale pending entry (a dropped
        -- ticker beat) expires after 1.0s so a vehicle can never get stuck un-skinned.
        local pend = _G._SDW_VehSkinPending[veh]
        if pend and (os.clock() - pend) < 1.0 then return end
        _G._SDW_VehSkinPending[veh] = os.clock()
        local function _fire()
            _G._SDW_VehSkinPending[veh] = nil
            _SDW_VehSkinRebuild(pc, veh, av, skinId)
        end
        local ok, t = pcall(require, "common.time_ticker")
        if ok and t and t.AddTimerOnce then
            t.AddTimerOnce(0.20, function() pcall(_fire) end)
        else
            -- No scheduler: run the fully-guarded rebuild immediately.
            pcall(_fire)
        end
    end
    _G._SDW_QueueVehicleSkin = _SDW_QueueVehicleSkin

    _G.ApplyVehicleSkins = function(PlayerCharacter)
        pcall(function()
            if not Valid(PlayerCharacter) then return end
            local Vehicle = PlayerCharacter:GetCurrentVehicle()
            if not Valid(Vehicle) then
                _G.LastVehicleEntity = nil
                return
            end

            if _G.LastVehicleEntity == Vehicle and _G.CurrentEquipVehicleID ~= nil then
                return
            end

            local VehicleAvatar = Vehicle.VehicleAvatar or Vehicle.VehicleAvatarComponent_BP or (Vehicle.GetAvatarComponent and Vehicle:GetAvatarComponent())
            if not Valid(VehicleAvatar) then return end

            local defId = tostring((VehicleAvatar.GetDefaultAvatarID and VehicleAvatar:GetDefaultAvatarID()) or Vehicle.VehicleID or "")
            local currentId = tostring((Vehicle.GetAvatarId and Vehicle:GetAvatarId()) or "")
            local applySkinId = 0

            for baseMapId, targetSkin in pairs(_G.VehicleSkinMap) do
                if defId:find(tostring(baseMapId)) or currentId:find(tostring(baseMapId)) then
                    applySkinId = targetSkin
                    break
                end
            end

            if applySkinId and applySkinId > 0 then
                _G.skinIdCache = _G.skinIdCache or {}
                if not _G.skinIdCache[applySkinId] then
                    if _G.download_item then pcall(_G.download_item, applySkinId) end
                    _G.skinIdCache[applySkinId] = true
                end

                -- [SDWxOWNER-ERANGEL-VEH-CRASH-FIX] Do NOT rebuild synchronously inside the
                -- engine's attach/detach callback. Queue a deferred, fully-guarded rebuild.
                _SDW_QueueVehicleSkin(PlayerCharacter, Vehicle, VehicleAvatar, applySkinId)
            end
        end)
    end

    _G.HandlePetLogic = function()
        pcall(function()
            local petSkin = _G.OutfitMap and _G.OutfitMap.Pet
            if not petSkin or petSkin == 0 or petSkin == 50000 or petSkin == _G.LastAppliedPet then return end

            _G.skinIdCache = _G.skinIdCache or {}
            if not _G.skinIdCache[petSkin] then
                if _G.download_item then pcall(_G.download_item, petSkin) end
                _G.skinIdCache[petSkin] = true
            end

            local ModuleManager = package.loaded["client.module_framework.ModuleManager"] or require("client.module_framework.ModuleManager")
            if ModuleManager and ModuleManager.CommonModuleConfig then
                local logic_pet = ModuleManager.GetModule(ModuleManager.CommonModuleConfig.logic_pet)
                if logic_pet then
                    -- [SDWxOWNER-CRASH FIX] Equipping a pet rebuilds the attached mesh; open a
                    -- skin/avatar swap window so the per-frame spin/TPP hooks stay off it.
                    _G._SDW_SkinSwapUntil = os.clock() + 0.4
                    if logic_pet.SetCurPetID then logic_pet:SetCurPetID(petSkin) end
                    if logic_pet.EquipPet then logic_pet:EquipPet(petSkin) end
                end
            end
            _G.LastAppliedPet = petSkin
        end)
    end

