    local cached_GameplayStatics = nil
    local cached_PlayerTombBox = nil
    local cached_ActorClass = nil
    _G.NeedCheckDeadBoxTimer = 0

    _G.DeadBox_TemperRequest = function(PlayerController)
        if _G.NeedCheckDeadBoxTimer <= 0 or not Valid(PlayerController) then return end

        local curTime = os.clock()
        -- [SDWxOWNER-PERF FIX] Throttle raised 2.0s -> 5.0s.
        if _G.LastCheckDeadBoxTime and (curTime - _G.LastCheckDeadBoxTime) < 5.0 then return end
        _G.LastCheckDeadBoxTime = curTime
        _G.NeedCheckDeadBoxTimer = _G.NeedCheckDeadBoxTimer - 1

        local PlayerCharacter = PlayerController:GetPlayerCharacterSafety()
        if not Valid(PlayerCharacter) then return end

        if not cached_GameplayStatics then
            cached_GameplayStatics = import("GameplayStatics")
            cached_ActorClass = import("Actor")
            cached_PlayerTombBox = import("PlayerTombBox")
        end

        if not _G.CachedActorArray and cached_ActorClass and slua and slua.Array then
            pcall(function() _G.CachedActorArray = slua.Array(UEnums.EPropertyClass.Object, cached_ActorClass) end)
        end

        local UI_Util = package.loaded["client.common.ui_util"] or require("client.common.ui_util")
        local GameInstance = UI_Util and UI_Util.GetGameInstance and UI_Util.GetGameInstance()
        if not GameInstance or not cached_GameplayStatics or not _G.CachedActorArray then return end

        local deadBoxes = nil
        pcall(function() deadBoxes = cached_GameplayStatics.GetAllActorsOfClass(GameInstance, cached_PlayerTombBox, _G.CachedActorArray) end)
        if not deadBoxes then return end

        for _, deadBoxActor in pairs(deadBoxes) do
            if Valid(deadBoxActor) and not deadBoxActor.bIsTDSkinApplied then
                local damageCauser = deadBoxActor.DamageCauser
                if damageCauser and damageCauser.PlayerKey == PlayerController.PlayerKey then
                    local DeadBoxAvatarComponent = deadBoxActor.DeadBoxAvatarComponent_BP
                    if Valid(DeadBoxAvatarComponent) then
                        local currentBoxSkinId = 0
                        -- [SDWxOWNER-FIX] Restored sdw.lua's known-good dead-box skin resolution.
                        if PlayerCharacter.CurrentVehicle and _G.CurrentEquipVehicleID and _G.CurrentEquipVehicleID ~= 0 then
                            currentBoxSkinId = tonumber(tostring(_G.CurrentEquipVehicleID) .. "1") or 0
                        else
                            local currentWeapon = PlayerCharacter:GetCurrentWeapon()
                            if Valid(currentWeapon) and currentWeapon.synData then
                                local weaponSkinData = currentWeapon.synData:Get(7)
                                if weaponSkinData and weaponSkinData.defineID then
                                    currentBoxSkinId = weaponSkinData.defineID.TypeSpecificID
                                end
                            end
                        end

                        if currentBoxSkinId and currentBoxSkinId ~= 0 then
                            -- [SDWxOWNER-CRASH FIX] The dead-box avatar rebuild touches a shared
                            -- avatar component; open a swap window so per-frame hooks stay off.
                            _G._SDW_SkinSwapUntil = os.clock() + 0.4
                            pcall(function()
                                if DeadBoxAvatarComponent.ResetItemAvatar then DeadBoxAvatarComponent:ResetItemAvatar() end
                                if DeadBoxAvatarComponent.PreChangeItemAvatar then DeadBoxAvatarComponent:PreChangeItemAvatar(currentBoxSkinId) end
                                if DeadBoxAvatarComponent.SyncChangeItemAvatar then DeadBoxAvatarComponent:SyncChangeItemAvatar(currentBoxSkinId) end
                            end)
                            deadBoxActor.bIsTDSkinApplied = true
                        end
                    end
                end
            end
        end
    end

    _G.SDWxOWNER_KillCounts = _G.SDWxOWNER_KillCounts or {}
    local CACHED_LinearColor = import("LinearColor")
    local CACHED_GoldColor = CACHED_LinearColor and CACHED_LinearColor(1.0, 0.8, 0.0, 1.0) or nil

    -- ======================================================================
    -- [SDWxOWNER] Kill-Counter SKIN -- faithful port of the proven working
    -- SDWxOWNER reference implementation.
    --
    -- WHY THE OLD CODE SHOWED THE NUMBER BUT NOT THE SKIN:
    --   * It hardcoded the counter item id 2100004, which is NOT a real
    --     Elimination-Counter item (it is absent from Dump_Skin_4.5.0.txt), so
    --     the game could never resolve a background texture for the counter.
    --   * It overrode LogicKillCounter:GetBaseKillCounterIdByWeaponId /
    --     GetEquipedKillCounterId / GetMyEquipedKillCounterId to always return
    --     2100004, poisoning every lookup the game makes for the counter skin.
    --   * It NEVER injected the game's NATIVE counter data
    --     (ExpandData.KillCounterItemId / KillCounterNum) into the kill damage
    --     record -- that serialized blob is what the counter actually reads to
    --     draw its skin.
    --
    -- THIS VERSION mirrors the working reference exactly:
    --   1. Injects ExpandData.KillCounterItemId = <weapon define id> and
    --      ExpandData.KillCounterNum (+1) on every real kill
    --      (ResultHealthStatus == 2 == FinishedLastBreath) when the gun carries
    --      a MOD skin (skin id > 1000000).
    --   2. Leaves the game's OWN LogicKillCounter resolvers untouched.
    --   3. Explicitly ShowUI / UpdateWeaponID / SetKillCounterItemShowWithNum
    --      with the LIVE weapon id + LIVE skin id -- even when the server
    --      returns nil for the equipped counter (the reference does this).
    --   4. Runs a per-tick driver that re-asserts the counter on weapon/skin
    --      change or right after a kill.
    -- ======================================================================

    -- Live weapon define id (e.g. 101004 = M416).
    _G.SDW_KC_LiveWeaponID = function(weapon)
        local id = 0
        pcall(function()
            if weapon and Valid(weapon) then
                local d = weapon:GetItemDefineID()
                if d and slua.isValid(d) then id = tonumber(d.TypeSpecificID) or 0 end
                if id == 0 and weapon.GetWeaponID then id = tonumber(weapon:GetWeaponID()) or 0 end
            end
        end)
        return id
    end

    -- Live applied skin id (the mod writes the VIP skin id into synData slot 7).
    _G.SDW_KC_LiveSkinID = function(weapon)
        local skinID = 0
        pcall(function()
            if weapon and Valid(weapon) and weapon.synData then
                local ref = slua.IndexReference(weapon.synData:Get(7), "defineID")
                if ref and slua.isValid(ref) then skinID = tonumber(ref.TypeSpecificID) or 0 end
            end
        end)
        return skinID
    end

    -- Skin id to hand to the counter + make sure its package is downloaded.
    _G.SDW_KC_ResolveSkin = function(weapon, weaponID)
        local skinID = _G.SDW_KC_LiveSkinID(weapon)
        if (not skinID or skinID == 0) and _G.get_skin_id then skinID = _G.get_skin_id(weaponID) or 0 end
        if not skinID or skinID == 0 then skinID = weaponID end
        if skinID and skinID > 1000000 and _G.download_item then
            _G._SDW_KC_DlCache = _G._SDW_KC_DlCache or {}
            if not _G._SDW_KC_DlCache[skinID] then
                _G._SDW_KC_DlCache[skinID] = true
                pcall(_G.download_item, skinID)
            end
        end
        return skinID
    end

    -- Per-weapon kill count (keyed by the weapon define id).
    _G.SDW_KC_Count = function(weapon, defineID)
        local c = _G.SDWxOWNER_KillCounts and _G.SDWxOWNER_KillCounts[defineID]
        if c == nil and weapon and weapon.GetWeaponID then
            local wid = weapon:GetWeaponID()
            if wid then c = _G.SDWxOWNER_KillCounts[wid] end
        end
        return c or 0
    end

    -- [SDWxOWNER] Inject the game's NATIVE kill-counter data into a damage
    -- record. This is the piece the old code was missing entirely, and it is
    -- what actually makes the counter background/skin render.
    _G.SDW_KC_InjectExpandData = function(DamageRecordData, DefineID)
        -- LuaStateWrapper is a game-provided global (the slua Lua state). If it is
        -- ever absent, skip silently rather than risk a native error.
        if not LuaStateWrapper then return end
        pcall(function()
            if not (DamageRecordData and DamageRecordData.ExpandDataContent) then return end
            local ExpandData = slua.LuaArchiverDecode(LuaStateWrapper, DamageRecordData.ExpandDataContent) or {}
            ExpandData.KillCounterItemId = DefineID
            ExpandData.KillCounterNum = (ExpandData.KillCounterNum or 0) + 1
            DamageRecordData.ExpandDataContent = slua.LuaArchiverEncode(LuaStateWrapper, ExpandData)
        end)
    end

    -- ======================================================================
    -- [SDWxOWNER] (Re)install every kill-counter hook. Idempotent: each hook
    -- is guarded by its own flag, and the flags are cleared whenever the game
    -- rebuilds the subsystem (new match / module reload) so the hooks are
    -- always live in the current match.
    -- ======================================================================
    _G.ForceEnableKillCounterUI = function()
        pcall(function()
            local KCSub = package.loaded["GameLua.Mod.BaseMod.Client.KillCounter.KillCounterUISubsystem"] or require("GameLua.Mod.BaseMod.Client.KillCounter.KillCounterUISubsystem")
            local MainKC = package.loaded["GameLua.Mod.BaseMod.Client.KillCounter.MainKillCounter"] or require("GameLua.Mod.BaseMod.Client.KillCounter.MainKillCounter")
            local UIManager = package.loaded["client.slua_ui_framework.manager"] or require("client.slua_ui_framework.manager")
            local ModuleManager = package.loaded["client.module_framework.ModuleManager"] or require("client.module_framework.ModuleManager")
            local KillInfo = package.loaded["GameLua.Mod.BaseMod.Client.KillInfoTips.KillInfo"] or require("GameLua.Mod.BaseMod.Client.KillInfoTips.KillInfo")
            local SlotBase = package.loaded["GameLua.Mod.BaseMod.Client.MainControlUI.SwitchWeaponSlotMode2"] or require("GameLua.Mod.BaseMod.Client.MainControlUI.SwitchWeaponSlotMode2")

            -- Re-install hooks if the game rebuilt the subsystem (new match / reload).
            if KCSub and KCSub.__inner_impl then
                if _G._SDW_KC_SubsysRef ~= KCSub.__inner_impl then
                    _G._SDW_KC_SubsysRef = KCSub.__inner_impl
                    _G.KCUISystemHacked2, _G.MainKCHacked, _G.KCLogicHacked2 = nil, nil, nil
                    _G.KillInfoCounterHacked, _G.SlotBaseHacked = nil, nil
                    _G._SDW_KC_LastW, _G._SDW_KC_LastS = nil, nil
                end
            end

            -- ---- KillCounterUISubsystem ----
            if KCSub and KCSub.__inner_impl and not _G.KCUISystemHacked2 then
                local kcImpl = KCSub.__inner_impl
                _G.OurkillCountSystem = kcImpl
                kcImpl.CheckSupportKCUI = function() return (_G.SDWConfig and _G.SDWConfig.ModSkin) and true or false end

                kcImpl.CheckNeedMainKillCounterUI = function(self, Weapon, PlayerID)
                    pcall(function()
                        local uCharacter = slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController() and slua_GameFrontendHUD:GetPlayerController():GetPlayerCharacterSafety()
                        local currweapon = uCharacter and uCharacter:GetCurrentWeapon()
                        if Valid(currweapon) then
                            local DefineID = _G.SDW_KC_LiveWeaponID(currweapon)
                            local SkinID = _G.SDW_KC_ResolveSkin(currweapon, DefineID)
                            self:UpdateMainKillCounterUI(true, DefineID, SkinID)
                        end
                    end)
                end

                local o_UpdateMainKillCounterUI = kcImpl.UpdateMainKillCounterUI
                kcImpl.UpdateMainKillCounterUI = function(self, bShow, WeaponID, AvatarID)
                    -- Hard gate: when the mod-skin system is OFF, never show the counter.
                    if not (_G.SDWConfig and _G.SDWConfig.ModSkin) then
                        if o_UpdateMainKillCounterUI then pcall(o_UpdateMainKillCounterUI, self, false, WeaponID, AvatarID) end
                        pcall(function()
                            local MK = UIManager.GetUI(UIManager.UI_Config_InGame.MainKillCounter)
                            if MK then UIManager.CloseUI(UIManager.UI_Config_InGame.MainKillCounter) end
                        end)
                        return
                    end

                    if o_UpdateMainKillCounterUI then pcall(o_UpdateMainKillCounterUI, self, bShow, WeaponID, AvatarID) end

                    pcall(function()
                        local MainKillCounter = UIManager.GetUI(UIManager.UI_Config_InGame.MainKillCounter)
                        local uCharacter = slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController() and slua_GameFrontendHUD:GetPlayerController():GetPlayerCharacterSafety()
                        local currweapon = uCharacter and uCharacter:GetCurrentWeapon()
                        if not bShow then
                            if MainKillCounter then UIManager.CloseUI(UIManager.UI_Config_InGame.MainKillCounter) end
                            return
                        end
                        if not Valid(currweapon) then return end
                        local DefineID = _G.SDW_KC_LiveWeaponID(currweapon)
                        local currentEquipAvatrid = _G.SDW_KC_ResolveSkin(currweapon, DefineID)
                        local LogicKillCounter = ModuleManager and ModuleManager.GetModule(ModuleManager.CommonModuleConfig.LogicKillCounter)
                        local SupportKillCounter = LogicKillCounter and LogicKillCounter.GetBaseKillCounterIdByWeaponId and LogicKillCounter:GetBaseKillCounterIdByWeaponId(DefineID)
                        local curEquipedKillCounter = LogicKillCounter and LogicKillCounter.GetEquipedKillCounterId and LogicKillCounter:GetEquipedKillCounterId(6114302174, currentEquipAvatrid)
                        -- [SDWxOWNER] Fall back to the weapon's OWN base counter item when
                        -- the server returns nil for the equipped counter (which it does for
                        -- modded skins it cannot recognise). Handing the widget a real counter
                        -- id is what lets it resolve the counter background texture.
                        if not curEquipedKillCounter then curEquipedKillCounter = SupportKillCounter end
                        local isModdedSkin = (currentEquipAvatrid and currentEquipAvatrid > 1000000)
                        -- Close for melee / throwables / unskinned guns; show for modded
                        -- guns even when the server returns nil for the equipped counter or
                        -- the base-counter lookup (the widget derives the skin from the skin
                        -- id we hand it).
                        if not isModdedSkin then
                            if MainKillCounter then UIManager.CloseUI(UIManager.UI_Config_InGame.MainKillCounter) end
                        else
                            if not MainKillCounter then
                                UIManager.ShowUI(UIManager.UI_Config_InGame.MainKillCounter, DefineID, currentEquipAvatrid)
                                MainKillCounter = UIManager.GetUI(UIManager.UI_Config_InGame.MainKillCounter)
                                if MainKillCounter then
                                    MainKillCounter:SetKillCounterItemShowWithNum(curEquipedKillCounter, _G.SDW_KC_Count(currweapon, DefineID), currentEquipAvatrid)
                                end
                            else
                                MainKillCounter:UpdateWeaponID(DefineID, currentEquipAvatrid)
                                MainKillCounter:SetKillCounterItemShowWithNum(curEquipedKillCounter, _G.SDW_KC_Count(currweapon, DefineID), currentEquipAvatrid)
                            end
                        end
                    end)
                end
                _G.KCUISystemHacked2 = true
            end

            -- ---- MainKillCounter.OnRefreshUI ----
            if MainKC and MainKC.__inner_impl and not _G.MainKCHacked then
                local o_OnRefreshUI = MainKC.__inner_impl.OnRefreshUI
                MainKC.__inner_impl.OnRefreshUI = function(self, _, _, UID)
                    local handled = false
                    pcall(function()
                        local LogicKillCounter = ModuleManager and ModuleManager.GetModule(ModuleManager.CommonModuleConfig.LogicKillCounter)
                        local curEquipedKillCounter = LogicKillCounter and LogicKillCounter.GetEquipedKillCounterId and LogicKillCounter:GetEquipedKillCounterId(6114302174, self.WeaponID)
                        local uCharacter = slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController() and slua_GameFrontendHUD:GetPlayerController():GetPlayerCharacterSafety()
                        local currweapon = uCharacter and uCharacter:GetCurrentWeapon()
                        if not Valid(currweapon) then return end
                        local DefineID = _G.SDW_KC_LiveWeaponID(currweapon)
                        if DefineID == 0 then DefineID = self.WeaponID end
                        local SkinID = _G.SDW_KC_ResolveSkin(currweapon, DefineID)
                        -- [SDWxOWNER] Same counter-id fallback as UpdateMainKillCounterUI.
                        if not curEquipedKillCounter then
                            local SupportKillCounter = LogicKillCounter and LogicKillCounter.GetBaseKillCounterIdByWeaponId and LogicKillCounter:GetBaseKillCounterIdByWeaponId(DefineID)
                            curEquipedKillCounter = SupportKillCounter
                        end
                        if self.KillCounterItem and self.KillCounterItem.SetKillCounterItemShowWithNum then
                            self.KillCounterItem:SetKillCounterItemShowWithNum(curEquipedKillCounter, _G.SDW_KC_Count(currweapon, DefineID), SkinID)
                            handled = true
                        end
                    end)
                    if not handled and o_OnRefreshUI then o_OnRefreshUI(self, _, _, UID) end
                end
                _G.MainKCHacked = true
            end

            -- ---- LogicKillCounter support flags (resolvers left untouched) ----
            if ModuleManager and ModuleManager.CommonModuleConfig and not _G.KCLogicHacked2 then
                local LogicKillCounter = ModuleManager.GetModule(ModuleManager.CommonModuleConfig.LogicKillCounter)
                if LogicKillCounter then
                    LogicKillCounter.CheckSupportKC = function() return true end
                    LogicKillCounter.CheckSupportKillCounterAvatar = function() return true end
                    LogicKillCounter.CheckHasWeaponKillCounter = function() return true end
                    LogicKillCounter.GetOneWeaponKillCountInBattle = function(self, uid, weaponId) return _G.SDWxOWNER_KillCounts[weaponId] or 0 end
                    LogicKillCounter.GetWeaponKillCountByUid = function(self, uid, weaponId) return _G.SDWxOWNER_KillCounts[weaponId] or 0 end
                    _G.KCLogicHacked2 = true
                end
            end

            -- ---- KillInfo.FileItem: count kills + inject the native counter data ----
            if KillInfo and KillInfo.__inner_impl and not _G.KillInfoCounterHacked then
                local o_FileItem = KillInfo.__inner_impl.FileItem
                KillInfo.__inner_impl.FileItem = function(self, DamageRecordData)
                    pcall(function()
                        if not DamageRecordData then return end
                        local gpd = package.loaded["GameLua.GameCore.Data.GameplayData"] or require("GameLua.GameCore.Data.GameplayData")
                        local LocalPlayer = gpd and gpd.GetPlayerCharacter and gpd.GetPlayerCharacter()
                        if not (Valid(LocalPlayer) and DamageRecordData.Causer == LocalPlayer:GetPlayerNameSafety()) then return end
                        local currWeapon = LocalPlayer:GetCurrentWeapon()
                        if not Valid(currWeapon) then return end
                        local DefineID = _G.SDW_KC_LiveWeaponID(currWeapon)
                        if DefineID == 0 then return end
                        local SkinID = _G.SDW_KC_ResolveSkin(currWeapon, DefineID)
                        if SkinID then DamageRecordData.CauserWeaponAvatarID = SkinID end
                        if _G.OutfitMap and _G.OutfitMap.Suit and _G.OutfitMap.Suit ~= 0 then DamageRecordData.CauserClothAvatarID = _G.OutfitMap.Suit end
                        if CACHED_GoldColor then DamageRecordData.IsUseColor, DamageRecordData.UseColor = true, CACHED_GoldColor end

                        if DamageRecordData.ResultHealthStatus == 2 then
                            -- [SDWxOWNER] hs==2 == ECharacterHealthStatus.FinishedLastBreath (real kill).
                            -- The COUNT always increments for the live weapon, so the kill
                            -- counter number shows for EVERY gun. The counter SKIN data is
                            -- injected only for modded guns (skin id > 1000000), which are the
                            -- only ones that carry a counter background texture.
                            local _newCount = (_G.SDWxOWNER_KillCounts[DefineID] or 0) + 1
                            _G.SDWxOWNER_KillCounts[DefineID] = _newCount
                            -- Alias under GetWeaponID too (some game paths query by it).
                            local _wid = currWeapon.GetWeaponID and currWeapon:GetWeaponID()
                            if _wid and _wid ~= DefineID then _G.SDWxOWNER_KillCounts[_wid] = _newCount end
                            _G.NeedCheckDeadBoxTimer = 50
                            _G.UpdateMyKillCounter = true
                            if SkinID and SkinID > 1000000 then
                                -- Inject the game's native counter data -> renders the skin.
                                _G.SDW_KC_InjectExpandData(DamageRecordData, DefineID)
                                -- [SDWxOWNER] Belt-and-suspenders: refresh the counter widget
                                -- IMMEDIATELY with the real counter item id + live skin id, so
                                -- the skin shows the instant a kill lands. The 0.5s ticker does
                                -- the same, but this removes any ticker dependency.
                                pcall(function()
                                    local UIMgr = package.loaded["client.slua_ui_framework.manager"] or require("client.slua_ui_framework.manager")
                                    local MK = UIMgr and UIMgr.GetUI(UIMgr.UI_Config_InGame.MainKillCounter)
                                    if MK and MK.SetKillCounterItemShowWithNum then
                                        local LKC = ModuleManager and ModuleManager.GetModule(ModuleManager.CommonModuleConfig.LogicKillCounter)
                                        local baseKC = LKC and LKC.GetBaseKillCounterIdByWeaponId and LKC:GetBaseKillCounterIdByWeaponId(DefineID)
                                        local eqKC = LKC and LKC.GetEquipedKillCounterId and LKC:GetEquipedKillCounterId(6114302174, SkinID)
                                        if MK.UpdateWeaponID then MK:UpdateWeaponID(DefineID, SkinID) end
                                        MK:SetKillCounterItemShowWithNum(eqKC or baseKC, _newCount, SkinID)
                                    end
                                end)
                            end
                        end
                    end)
                    if o_FileItem then return o_FileItem(self, DamageRecordData) end
                end
                _G.KillInfoCounterHacked = true
            end

            -- ---- SwitchWeaponSlotMode2 ----
            if SlotBase and SlotBase.__inner_impl and not _G.SlotBaseHacked then
                SlotBase.__inner_impl.CheckShowKCIcon = function(self)
                    if Valid(self.KillCounterImg) then
                        self.KillCounterImg:SetVisibility(import("ESlateVisibility").SelfHitTestInvisible)
                    end
                end
                _G.SlotBaseHacked = true
            end

            -- ---- Dedicated fast ticker (0.5s) so the counter refreshes promptly after a
            -- kill / weapon change, independent of the 3s skin re-apply loop. Mirrors the
            -- working reference's ticker.AddTimerLoop(0, fn, -1, 0.5). ----
            if not _G._SDW_KC_TickerStarted then
                _G._SDW_KC_TickerStarted = true
                pcall(function()
                    local ticker = package.loaded["common.time_ticker"] or require("common.time_ticker")
                    if ticker and ticker.AddTimerLoop then
                        ticker.AddTimerLoop(0, function() if _G.SDW_KC_Tick then pcall(_G.SDW_KC_Tick) end end, -1, 0.5)
                    end
                end)
            end
        end)
    end

    -- ======================================================================
    -- [SDWxOWNER] Per-tick kill-counter driver (faithful to the reference's
    -- GameAvatarHandlerkillcounter). Re-asserts the counter whenever the
    -- weapon or its skin changes, or right after a kill.
    -- ======================================================================
    _G.SDW_KC_Tick = function()
        pcall(function()
            local UIManager = package.loaded["client.slua_ui_framework.manager"] or require("client.slua_ui_framework.manager")
            if not (_G.SDWConfig and _G.SDWConfig.ModSkin) then
                local MainKillCounter = UIManager and UIManager.GetUI(UIManager.UI_Config_InGame.MainKillCounter)
                if MainKillCounter then UIManager.CloseUI(UIManager.UI_Config_InGame.MainKillCounter) end
                return
            end
            local uCharacter = slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController() and slua_GameFrontendHUD:GetPlayerController():GetPlayerCharacterSafety()
            if not (uCharacter and Valid(uCharacter)) then return end
            local weapon = uCharacter:GetCurrentWeapon()
            if not Valid(weapon) then return end
            local weaponID = _G.SDW_KC_LiveWeaponID(weapon)
            local skinID = _G.SDW_KC_ResolveSkin(weapon, weaponID)
            if _G._SDW_KC_LastW ~= weaponID or _G._SDW_KC_LastS ~= skinID or _G.UpdateMyKillCounter then
                _G._SDW_KC_LastW, _G._SDW_KC_LastS = weaponID, skinID
                _G.UpdateMyKillCounter = false
                if _G.OurkillCountSystem then _G.OurkillCountSystem:UpdateMainKillCounterUI(true, weaponID, skinID) end
            end
        end)
    end

    _G.InitializeSkinModSystem = function()
        pcall(function()
            local LobbyAvatar = package.loaded["client.logic.avatar.LobbyAvatar"] or require("client.logic.avatar.LobbyAvatar")
            if LobbyAvatar and not _G.LobbySkinHooked then
                local originalPutonEquipment = LobbyAvatar.PutonEquipment
                LobbyAvatar.PutonEquipment = function(self, itemID, tAvatarCustom, tExtraData)
                    local attachIndex = _G.BaseAttachToIndex and _G.BaseAttachToIndex[itemID]
                    if attachIndex then
                        local holdingWeaponSkinID = self.GetCurHoldingWeaponSkinID and self:GetCurHoldingWeaponSkinID()
                        if holdingWeaponSkinID and holdingWeaponSkinID >= 10000000 and _G.VIP_Attachments and _G.VIP_Attachments[holdingWeaponSkinID] then
                            local vipAttachID = _G.VIP_Attachments[holdingWeaponSkinID][attachIndex]
                            if vipAttachID and vipAttachID > 0 then
                                if self.HandleDownload then self:HandleDownload(vipAttachID, nil, nil, false) end
                                itemID = vipAttachID
                            end
                        end
                    end
                    if originalPutonEquipment then return originalPutonEquipment(self, itemID, tAvatarCustom, tExtraData) end
                end

                local originalCharEquipWeaponByResId = LobbyAvatar.CharEquipWeaponByResId
                LobbyAvatar.CharEquipWeaponByResId = function(self, resID, isUse, isAsync, SocketName)
                    local retValue = originalCharEquipWeaponByResId and originalCharEquipWeaponByResId(self, resID, isUse, isAsync, SocketName) or nil
                    if isUse and self.GetEquipments then
                        local equipments = self:GetEquipments()
                        if equipments then
                            for _, equip in ipairs(equipments) do
                                if equip and equip.itemID and _G.BaseAttachToIndex and _G.BaseAttachToIndex[equip.itemID] then
                                    self:PutonEquipment(equip.itemID, equip.CustomInfo, {bIsUse = false})
                                end
                            end
                        end
                    end
                    return retValue
                end
                _G.LobbySkinHooked = true
            end
        end)

        pcall(function()
            local Common_Items_UIBP = package.loaded["client.slua.component.item.ItemChildren.Common_Items_UIBP"] or require("client.slua.component.item.ItemChildren.Common_Items_UIBP")
            if Common_Items_UIBP and not _G.IconBaloHacked then
                local originalInitView = Common_Items_UIBP.InitView
                Common_Items_UIBP.InitView = function(self, nItemId, nCount, nValidTime, tExtraData)
                    tExtraData = tExtraData or {}
                    local displayResId = nil

                    if _G.get_skin_id then
                        local skinID = _G.get_skin_id(nItemId)
                        if skinID and skinID ~= nItemId then displayResId = skinID end
                    end

                    local attachIndex = _G.BaseAttachToIndex and _G.BaseAttachToIndex[nItemId]
                    if not displayResId and attachIndex then
                        local gpd = package.loaded["GameLua.GameCore.Data.GameplayData"] or require("GameLua.GameCore.Data.GameplayData")
                        local LocalPlayer = gpd and gpd.GetPlayerCharacter and gpd.GetPlayerCharacter()
                        if Valid(LocalPlayer) then
                            local currentWeapon = LocalPlayer:GetCurrentWeapon()
                            if Valid(currentWeapon) then
                                local weaponID = currentWeapon:GetWeaponID()
                                local finalSkinID = _G.get_skin_id(weaponID) or weaponID
                                if finalSkinID and finalSkinID >= 10000000 and _G.VIP_Attachments and _G.VIP_Attachments[finalSkinID] then
                                    local vipAttachID = _G.VIP_Attachments[finalSkinID][attachIndex]
                                    if vipAttachID and vipAttachID > 0 then displayResId = vipAttachID end
                                end
                            end
                        end
                    end

                    if displayResId then
                        tExtraData.displayResId = displayResId
                        if not _G.skinIdCache2[displayResId] then
                            if _G.download_item then pcall(_G.download_item, displayResId) end
                            _G.skinIdCache2[displayResId] = true
                        end
                    end
                    if originalInitView then return originalInitView(self, nItemId, nCount, nValidTime, tExtraData) end
                end
                _G.IconBaloHacked = true
            end
        end)
    end

    _G.RestoreDefaultSkins = function(localPlayer)
        _G.OutfitMap = {}
        _G.WeaponSkinMap = {}
        _G.VehicleSkinMap = {}
        -- [SDWxOWNER-FIX] maps are now empty -> invalidate the signature fast-path.
        _G._SDW_SkinMapPopulated = false
        -- [SDWxOWNER-PERF/CRASH FIX] Restoring also rebuilds the avatar/weapon meshes,
        -- so open a swap window for the per-frame spin/TPP hooks.
        _G._SDW_SkinSwapUntil = os.clock() + 0.4
        if not Valid(localPlayer) then return end
        pcall(function()
            local WeaponManager = localPlayer:GetWeaponManager()
            if Valid(WeaponManager) then
                for slot = 1, 3 do
                    local Weapon = WeaponManager:GetInventoryWeaponByPropSlot(slot)
                    if Valid(Weapon) and Valid(Weapon.synData) then
                        local WeaponID = Weapon:GetWeaponID()
                        local SkinData = Weapon.synData:Get(7)
                        if SkinData and SkinData.defineID then
                            SkinData.defineID.TypeSpecificID = WeaponID
                            Weapon.synData:Set(7, SkinData)
                            if Weapon.SetWeaponAvatarID then pcall(function() Weapon:SetWeaponAvatarID(WeaponID) end) end
                            if isModified and Weapon.DelayHandleAvatarMeshChanged then pcall(function() Weapon:DelayHandleAvatarMeshChanged() end) end
                        end
                    end
                end
            end
            local Vehicle = localPlayer:GetCurrentVehicle()
            if Valid(Vehicle) then
                local VehicleAvatar = Vehicle.VehicleAvatar or Vehicle.VehicleAvatarComponent_BP or (Vehicle.GetAvatarComponent and Vehicle:GetAvatarComponent())
                if Valid(VehicleAvatar) and type(VehicleAvatar.GetDefaultAvatarID) == "function" then
                    local defId = VehicleAvatar:GetDefaultAvatarID()
                    if VehicleAvatar.ChangeItemAvatar then VehicleAvatar:ChangeItemAvatar(defId, true) end
                end
            end
            if localPlayer.AvatarComponent2 and type(localPlayer.AvatarComponent2.OnRep_BodySlotStateChanged) == "function" then
                localPlayer.AvatarComponent2:OnRep_BodySlotStateChanged()
            end
        end)
    end



    _G.SDW_DisableAllSkins = function()
        pcall(function()
            -- [SDWxOWNER-SETTINGS-FIX] Do NOT wipe the user's skin SELECTIONS here.
            -- The old code reset every Skin* key in CustomTextData to 1 and then SAVED
            -- that, which the user perceives as "toggling the skin off/on resets my
            -- settings" -- and it also makes the skin look broken afterwards (every
            -- item silently reverts to default skin #1). We now keep the selections
            -- and only clear the DERIVED maps + restore the default in-world look, so
            -- re-enabling the skin restores EXACTLY what the user had chosen.
            _G.OutfitMap = {}
            _G.WeaponSkinMap = {}
            _G.VehicleSkinMap = {}
            -- [SDWxOWNER-FIX] maps are now empty -> invalidate the signature fast-path.
            _G._SDW_SkinMapPopulated = false
            local pc = slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController()
            local lp = nil
            if pc and pc.GetPlayerCharacterSafety then pcall(function() lp = pc:GetPlayerCharacterSafety() end) end
            if not Valid(lp) then
                local gpd = package.loaded["GameLua.GameCore.Data.GameplayData"]
                if gpd and gpd.GetPlayerCharacter then pcall(function() lp = gpd.GetPlayerCharacter() end) end
            end
            if Valid(lp) and _G.RestoreDefaultSkins then pcall(_G.RestoreDefaultSkins, lp) end
            if _G.SDWState then _G.SDWState.SkinWasApplied = false end
            _G.TDSkinLoopStarted = false
            _G._LastAppliedOutfitHash = 0
            if _G.SaveModSettings then pcall(_G.SaveModSettings, true) end
        end)
    end

    _G.SDW_SetModSkin = function(v)
        v = v and true or false
        _G.SDWConfig.ModSkin = v
        _G.SDWConfig.SkinOptionOpen = v
        if v then
            pcall(function()
                if _G.AK_Features then
                    for _, f in ipairs(_G.AK_Features) do
                        if f.id == "ALL_SKINS" then f.val = 0 elseif f.id == "MOD_SKIN" then f.val = 1 end
                    end
                end
            end)
            if _G.ForceRefreshSkinMaps then pcall(_G.ForceRefreshSkinMaps) end
        else
            pcall(function()
                if _G.AK_Features then
                    for _, f in ipairs(_G.AK_Features) do
                        if f.id == "ALL_SKINS" then f.val = 0 elseif f.id == "MOD_SKIN" then f.val = 0 end
                    end
                end
            end)
            if _G.SDW_DisableAllSkins then pcall(_G.SDW_DisableAllSkins) end
        end
        if _G.SaveModSettings then pcall(_G.SaveModSettings, true) end
        return true
    end

    _G.DownloadGameItem = DownloadGameItem
end


do
    local ShowExpiryDialog = _G.ShowExpiryDialog or function() end

    local _ENV_LAST_WORLD = nil
    local function ApplyEnvironment()
        -- [SDWxOWNER-LOCK] No environment (no-grass / no-fog) without a valid, unlocked key.
        if not (_G.SDW_IsAuthorized and _G.SDW_IsAuthorized()) then return end
        pcall(function()
            local currentWorld = slua.getWorld()
            local worldChanged = currentWorld ~= _ENV_LAST_WORLD
            if worldChanged then _ENV_LAST_WORLD = currentWorld; _ENV_ONCE_DONE = false end
            local gi = slua_GameFrontendHUD and slua_GameFrontendHUD:GetGameInstance()
            if gi then
                gi:ExecuteCMD("t.MaxFPS", "165")
                gi:ExecuteCMD("r.FrameRateLimit", "165")
                gi:ExecuteCMD("r.VSync", "0")
                if not _ENV_ONCE_DONE then
                    gi:ExecuteCMD("r.Touch.EnableVibration", "0")
                    gi:ExecuteCMD("r.GTSyncType", "2")
                    gi:ExecuteCMD("r.OneFrameThreadLag", "0")
                    gi:ExecuteCMD("r.Streaming.PoolSize", "512")
                    gi:ExecuteCMD("r.EnableLowFPSRender", "0")
                    gi:ExecuteCMD("r.LensFlareQuality", "0")
                    gi:ExecuteCMD("r.DepthOfFieldQuality", "0")
                    gi:ExecuteCMD("r.Shadow.CSM.TransitionScale", "0")
                    gi:ExecuteCMD("r.Tonemapper.Quality", "0")
                    _ENV_ONCE_DONE = true
                end
                local cleanup = _G.SDWConfig.VisualCleanupEnabled == true
                if _ENV_LAST_GRASS_STATE ~= cleanup or worldChanged then
                    if cleanup then
                        gi:ExecuteCMD("grass.DensityScale", "0")
                        gi:ExecuteCMD("grass.DiscardDataOnLoad", "1")
                    else
                        gi:ExecuteCMD("grass.DensityScale", "1")
                        gi:ExecuteCMD("grass.DiscardDataOnLoad", "0")
                    end
                    _ENV_LAST_GRASS_STATE = cleanup
                end
            end
        end)
        if _ENV_LAST_FOG_WORLD ~= _ENV_LAST_WORLD then
            _ENV_LAST_FOG_WORLD = _ENV_LAST_WORLD
            pcall(function()
                local KSL = import("KismetSystemLibrary")
                local w = slua.getWorld()
                if KSL and w then KSL.ExecuteConsoleCommand(w, "r.Fog 1") end
            end)
        end
    end

    _G.ApplyEnvironment = ApplyEnvironment

    -- ============================================================================
    -- [SDWxOWNER-PERF] FPS STABILIZER & POTATO GRAPHICS (ported from new.lua)
    -- Ultra-smooth performance engine:
    --   * GC pacing (native slua.setGCParam) -> removes GC spikes / freezes
    --   * CPU threading + camera frame pacing -> removes micro-stutters
    --   * anti-heating / thermal stabilisation (background telemetry culling)
    --   * decal RT clamp + particle LOD + engine GC pacing -> no combat freezes
    --   * shadow / fog / bloom / DOF / motion-blur / AO / SSR / water-reflection OFF
    --   * Potato Graphics: texture mip-bias (clay buildings, crisp players/weapons)
    -- Everything is pcall-wrapped and only runs on toggle / init / match-start,
    -- so it adds ZERO per-frame cost.
    -- ============================================================================
    do
        -- Robust game-instance getter (mirrors ApplyEnvironment's path + fallbacks).
        local function _perfGetGI()
            local gi = nil
            pcall(function()
                gi = slua_GameFrontendHUD and slua_GameFrontendHUD:GetGameInstance()
            end)
            if gi then return gi end
            pcall(function()
                local ok, gp = pcall(require, "GameLua.GameCore.Data.GameplayData")
                if ok and gp and gp.GetGameInstance then gi = gp.GetGameInstance() end
            end)
            if gi then return gi end
            pcall(function()
                local ok, ui_util = pcall(require, "client.common.ui_util")
                if ok and ui_util and ui_util.GetGameInstance then gi = ui_util.GetGameInstance() end
            end)
            return gi
        end

        -- Executes a console command through BOTH the GameInstance and Kismet (whichever is live).
        local function _perfExec(cmd, arg)
            local gi = _perfGetGI()
            if gi and gi.ExecuteCMD then pcall(gi.ExecuteCMD, gi, cmd, tostring(arg)) end
            pcall(function()
                local KSL = import("KismetSystemLibrary")
                local w = slua.getWorld()
                if KSL and w and KSL.ExecuteConsoleCommand then
                    KSL.ExecuteConsoleCommand(w, cmd .. " " .. tostring(arg))
                end
            end)
        end

        -- ---- TARGET FRAME RATE (FPS) ----
        local function ApplyFPSLimit(targetFps)
            targetFps = tonumber(targetFps) or (_G.SDWConfig and _G.SDWConfig.TargetFPS) or 165
            if _G.SDWConfig then _G.SDWConfig.TargetFPS = targetFps end
            pcall(function()
                local gi = _perfGetGI()
                if gi and gi.ExecuteCMD then
                    local fpsStr = tostring(targetFps)
                    gi:ExecuteCMD("t.MaxFPS", fpsStr)
                    gi:ExecuteCMD("r.FrameRateLimit", fpsStr)
                end
            end)
            if _G.SDWState then _G.SDWState.DirtyConfig = true end
        end
        _G.SDW_ApplyFPSLimit = ApplyFPSLimit

        -- ---- FPS STABILIZER & ANTI-JITTER (ULTRA SMOOTH) ----
        local function ApplyFPSStabilizer(enable)
            local isEnabled = (enable ~= false)
            if enable == nil then
                isEnabled = (_G.SDWConfig and _G.SDWConfig.FPSStabilizerEnabled ~= false)
            end
            if _G.SDWConfig then _G.SDWConfig.FPSStabilizerEnabled = isEnabled end

            pcall(function()
                -- 1. Native C++ slua Garbage Collection pacing (prevents GC spikes / freezes).
                if slua and slua.setGCParam then
                    if isEnabled then
                        -- BattleStepGCTime = 0.5 ms micro-step per frame, interval = 50 ms.
                        slua.setGCParam(5.0E-4, 500, 50)
                    else
                        slua.setGCParam(0.001, 1000, 0)
                    end
                end

                if isEnabled then
                    -- 2. CPU threading & camera frame pacing (eliminates micro-stutters).
                    _perfExec("a.ParallelAnimEvaluation", 1)
                    _perfExec("r.GTSyncType", 1)
                    _perfExec("r.OneFrameThreadLag", 1)
                    _perfExec("r.FinishCurrentFrame", 0)
                    _perfExec("r.EnableWeaponCompTickOptimise", 1)
                    _perfExec("r.EnableWeaponGameStallIssueFix", 1)
                    _perfExec("slate.SuperFrameMiniMapUpdateRate", 3)
                    _perfExec("r.Streaming.PoolSize", 400)
                    _perfExec("r.Streaming.LimitPoolSizeToVRAM", 1)
                    _perfExec("fx.ParticlePerfStats", 0)
                    _perfExec("r.VSync", 0)

                    -- 3. Anti-heating & thermal stabilisation (background telemetry culling).
                    _perfExec("Jank.EnableCollection", 0)
                    _perfExec("Jank.EnableCollectionFromGamePlay", 0)
                    _perfExec("Engine.GSleepSlackTimeThod", 0.0012)
                    _perfExec("Engine.GSleepTimeThod", 0.0012)

                    -- 4. Gunfight & spray anti-lag (decal RT, particle LOD, engine GC pacing).
                    _perfExec("diy.SetDecalBakingRTSize", 256)
                    _perfExec("r.ParticleLodDistanceScale", 1.5)
                    _perfExec("gc.TimeBetweenPurgingPendingKillObjects", 60)

                    -- 5. Remove heavy GPU rendering (zero gameplay loss, big FPS boost).
                    _perfExec("r.ShadowQuality", 0)
                    _perfExec("r.Shadow.CSM.MaxCascades", 0)
                    _perfExec("r.DistanceFieldShadowing", 0)
                    _perfExec("r.Fog", 0)
                    _perfExec("r.AtmosphericFog", 0)
                    _perfExec("r.BloomQuality", 0)
                    _perfExec("r.DepthOfFieldQuality", 0)
                    _perfExec("r.MotionBlurQuality", 0)
                    _perfExec("r.LensFlareQuality", 0)
                    _perfExec("r.AmbientOcclusionLevels", 0)
                    _perfExec("r.EyeAdaptationQuality", 0)
                    _perfExec("r.WaterReflection", 0)
                    _perfExec("r.SSR.Quality", 0)
                else
                    -- Revert to stock defaults.
                    _perfExec("a.ParallelAnimEvaluation", 0)
                    _perfExec("r.GTSyncType", 0)
                    _perfExec("r.Streaming.PoolSize", 0)
                    _perfExec("Jank.EnableCollection", 1)
                    _perfExec("Jank.EnableCollectionFromGamePlay", 1)
                    _perfExec("diy.SetDecalBakingRTSize", 512)
                    _perfExec("r.ParticleLodDistanceScale", 1.0)
                    _perfExec("gc.TimeBetweenPurgingPendingKillObjects", 20)
                    _perfExec("r.ShadowQuality", 1)
                    _perfExec("r.Shadow.CSM.MaxCascades", 1)
                    _perfExec("r.Fog", 1)
                    _perfExec("r.AtmosphericFog", 1)
                    _perfExec("r.BloomQuality", 1)
                    _perfExec("r.DepthOfFieldQuality", 1)
                    _perfExec("r.MotionBlurQuality", 1)
                    _perfExec("r.AmbientOcclusionLevels", 1)
                    _perfExec("r.WaterReflection", 1)
                    _perfExec("r.SSR.Quality", 1)
                end
            end)
            if _G.SDWState then _G.SDWState.DirtyConfig = true end
        end
        _G.SDW_ApplyFPSStabilizer = ApplyFPSStabilizer

        -- ---- POTATO GRAPHICS (clay buildings + crisp players) ----
        local function ApplyPotatoGraphics(enable)
            local isEnabled = (enable == true)
            if _G.SDWConfig then _G.SDWConfig.PotatoGraphicsEnabled = isEnabled end

            pcall(function()
                local ClientObj = _G.Client
                if not ClientObj then local okc, c = pcall(import, "Client"); if okc then ClientObj = c end end
                local TG = _G.TextureGroup
                if not TG then local okt, t = pcall(import, "TextureGroup"); if okt then TG = t end end

                -- Collect all environment / building / terrain / world texture groups.
                local envGroups = {}
                if TG then
                    local groupNames = {
                        "TEXTUREGROUP_World", "TEXTUREGROUP_WorldHD", "TEXTUREGROUP_WorldNormalMap",
                        "TEXTUREGROUP_WorldNormalMapHD", "TEXTUREGROUP_WorldSpecular", "TEXTUREGROUP_WorldSpecularHD",
                        "TEXTUREGROUP_WorldAniso", "TEXTUREGROUP_GamePOI", "TEXTUREGROUP_TerrainAlbedo",
                        "TEXTUREGROUP_Terrain_Weightmap", "TEXTUREGROUP_Terrain_Heightmap", "TEXTUREGROUP_ProcBuilding_Face",
                        "TEXTUREGROUP_ProcBuilding_LightMap", "TEXTUREGROUP_MobileFlattened", "TEXTUREGROUP_MaskedBillboard"
                    }
                    for _, name in ipairs(groupNames) do
                        if TG[name] ~= nil then table.insert(envGroups, TG[name]) end
                    end
                end
                table.insert(envGroups, 42) -- GamePOI in BGMI
                for _, idx in ipairs({10, 5, 28, 16, 14, 1, 2, 23, 34, 4}) do
                    table.insert(envGroups, idx)
                end

                -- Permanent visibility & material restoration (never block windows/doors, never white materials).
                _perfExec("r.StaticMeshLODDistanceScale", 1.0)
                _perfExec("r.DetailMode", 2)
                _perfExec("s.EnableOverrideVerySmoothMaterial", 0)
                _perfExec("r.MaterialQualityLevel", 1)
                _perfExec("r.StaticMeshForceLODMaterialBias", 0)
                _perfExec("r.ForceMipFilterToPoint", 0)
                _perfExec("r.Streaming.UseFixedPoolSize", 0)

                if isEnabled then
                    -- Colorful potato graphics: drop env mips by 2 levels (clay look, natural colors).
                    if ClientObj and ClientObj.SetTextureGroupLODBias then
                        for _, grp in ipairs(envGroups) do
                            pcall(ClientObj.SetTextureGroupLODBias, grp, 2)
                        end
                        -- Keep character & weapon textures fully sharp (0 bias).
                        if TG then
                            if TG.TEXTUREGROUP_Character then pcall(ClientObj.SetTextureGroupLODBias, TG.TEXTUREGROUP_Character, 0) end
                            if TG.TEXTUREGROUP_CharacterHD then pcall(ClientObj.SetTextureGroupLODBias, TG.TEXTUREGROUP_CharacterHD, 0) end
                            if TG.TEXTUREGROUP_Weapon then pcall(ClientObj.SetTextureGroupLODBias, TG.TEXTUREGROUP_Weapon, 0) end
                            if TG.TEXTUREGROUP_WeaponHD then pcall(ClientObj.SetTextureGroupLODBias, TG.TEXTUREGROUP_WeaponHD, 0) end
                        end
                    end
                    _perfExec("r.MipLODBiasFromQuality", 2)
                    _perfExec("r.EnableBiasWhenTexStreamingOff", 1)
                    _perfExec("r.MipLODBiasLowClampSize", 256)
                    _perfExec("r.Streaming.DropMips", 2)
                    _perfExec("r.Streaming.MipBias", 2)
                    _perfExec("r.MipMapLODBias", 2)
                    _perfExec("r.MaxAnisotropy", 0)
                    if _G.SDWConfig and _G.SDWConfig.FPSStabilizerEnabled then
                        _perfExec("r.Streaming.PoolSize", 400)
                    else
                        _perfExec("r.Streaming.PoolSize", 300)
                    end
                    _perfExec("foliage.LODDistanceScale", 0.7)
                    _perfExec("r.SkeletalMeshLODBias", 0)
                    _perfExec("r.SkeletalMeshLODDistanceScale", 1.0)
                else
                    -- Revert to clean standard sharpness.
                    if ClientObj and ClientObj.SetTextureGroupLODBias then
                        for _, grp in ipairs(envGroups) do
                            pcall(ClientObj.SetTextureGroupLODBias, grp, 0)
                        end
                    end
                    _perfExec("r.MipLODBiasFromQuality", 0)
                    _perfExec("r.EnableBiasWhenTexStreamingOff", 0)
                    _perfExec("r.MipLODBiasLowClampSize", 0)
                    _perfExec("r.Streaming.DropMips", 0)
                    _perfExec("r.Streaming.MipBias", 0)
                    _perfExec("r.MipMapLODBias", 0)
                    _perfExec("r.MaxAnisotropy", 1)
                    if _G.SDWConfig and _G.SDWConfig.FPSStabilizerEnabled then
                        _perfExec("r.Streaming.PoolSize", 400)
                    else
                        _perfExec("r.Streaming.PoolSize", 0)
                    end
                    _perfExec("foliage.LODDistanceScale", 1.0)
                    _perfExec("r.SkeletalMeshLODBias", 0)
                    _perfExec("r.SkeletalMeshLODDistanceScale", 1.0)
                end
            end)
            if _G.SDWState then _G.SDWState.DirtyConfig = true end
        end
        _G.SDW_ApplyPotatoGraphics = ApplyPotatoGraphics

        -- ---- AUTO-APPLY on script init (if enabled in saved config) ----
        pcall(function()
            if _G.SDWConfig and _G.SDWConfig.FPSStabilizerEnabled ~= false then
                ApplyFPSStabilizer(true)
            end
            if _G.SDWConfig and _G.SDWConfig.PotatoGraphicsEnabled then
                ApplyPotatoGraphics(true)
            end
        end)
    end

    local function MarkWHTimerBR()
        if _G.WH_TIMER_BR then return end
        _G.WH_TIMER_BR = true
    end

    -- [SDWxOWNER-SMOOTH] Defer a chunk of match-start work to a later frame so the whole
    -- feature-enable sequence no longer runs in ONE frame (which froze the screen ~3s).
    local function SDW_Defer(delay, fn)
        local ok, t = pcall(require, "common.time_ticker")
        if ok and t and t.AddTimerOnce then
            t.AddTimerOnce(delay, function() pcall(fn) end)
        else
            pcall(fn)
        end
    end
    _G.SDW_Defer = SDW_Defer

    local function StartMatchFeatures(pc, pawn)
        if not _G.LOGIN_OK then return end
        _G._SDW_MatchGen = (_G._SDW_MatchGen or 0) + 1
        if rawget(_G, "SnaplineESP") and SnaplineESP.ResetForMatch then
            pcall(function() SnaplineESP.ResetForMatch() end)
        end
        -- [SDWxOWNER-SMOOTH] Cheap state + FPS cap stay synchronous (they must be live
        -- immediately); everything heavy is spread over the next ~0.5s of frames so no
        -- single frame stalls.
        if _G.SDW_EnforceFPS then pcall(_G.SDW_EnforceFPS) end
        if _G.SDW_StartFPSLoop then pcall(_G.SDW_StartFPSLoop) end
        _G.VisualsStarted = false
        _G.WH_TIMER_BR = nil
        -- [SDWxOWNER-SMOOTH] StartVisuals stays SYNCHRONOUS: it registers the ESP timers and
        -- flips _G.VisualsStarted=true, which MainLoop's "visuals healthy" check reads on THIS
        -- same frame. If it were deferred, MainLoop's retry path would call StartVisuals(true)
        -- again on this frame (double run). The genuinely heavy match-start work is deferred below.
        if _G.StartVisuals then pcall(function() _G.StartVisuals(true) end) end

        SDW_Defer(0.00, function() pcall(SetupConsole) end)
        SDW_Defer(0.03, function() if _G.SDW_MenuTick then _G.SDW_MenuTick() end end)
        SDW_Defer(0.06, function()
            if type(ApplyEnvironment) == "function" then
                -- Only skip re-creating the 30 s env/FPS timer if the existing id is still ALIVE (present in ModTimers).
                local _envAlive = false
                local _eid = _G.SDWState.EnvironmentTimerId
                if _eid then
                    local _ml = _G.SDWState.ModTimers
                    if _ml then for _i = 1, #_ml do if _ml[_i] == _eid then _envAlive = true; break end end end
                end
                if not _envAlive then
                    pcall(ApplyEnvironment)
                    _G.SDWState.EnvironmentTimerId = AddModTimer(pc, 30.0, true, ApplyEnvironment)
                else
                    pcall(ApplyEnvironment)
                end
            end
            -- [SDWxOWNER-PERF] Re-assert the FPS Stabilizer on every new match/world so the
            -- graphics/GC tuning survives map reloads (matches new.lua's match-start behaviour).
            pcall(function()
                if _G.SDWConfig and _G.SDWConfig.FPSStabilizerEnabled ~= false and _G.SDW_ApplyFPSStabilizer then
                    _G.SDW_ApplyFPSStabilizer(true)
                end
                if _G.SDWConfig and _G.SDWConfig.PotatoGraphicsEnabled and _G.SDW_ApplyPotatoGraphics then
                    _G.SDW_ApplyPotatoGraphics(true)
                end
            end)
            if _G._MOD_EXPIRED then
                pcall(ShowExpiryDialog)
                AddModTimer(pc, 5.0, true, ShowExpiryDialog)
            end
        end)
        SDW_Defer(0.20, function() if _G.SDW_EnsureSnapline then _G.SDW_EnsureSnapline() end end)
        SDW_Defer(0.30, function() if _G.SDW_MenuTick then _G.SDW_MenuTick() end end)
        SDW_Defer(0.40, function() if _G.SDW_Force165 then _G.SDW_Force165() end end)
        SDW_Defer(0.50, function() if not _G.WH_TIMER_BR then if _G.RetryStart then _G.RetryStart() end end end)
    end

    function _G.InitModMenuTab()
        if _G.ModMenuInitialized then return end
        _G.SDWState.CustomTextData = _G.SDWState.CustomTextData or {
            iPadViewFOV = 110,
            SkinSuit = 1, SkinBag = 1, SkinHelmet = 1,
            SkinM416 = 1, SkinAKM = 1, SkinSCAR = 1, SkinM762 = 1, SkinAUG = 1, SkinUMP = 1,
            SkinUZI = 1, SkinGroza = 1, SkinS12K = 1, SkinDBS = 1, SkinASM = 1, SkinQBZ = 1,
            SkinHoney = 1, SkinM16A4 = 1, SkinACE32 = 1, SkinKar98k = 1, SkinM24 = 1, SkinAWM = 1,
            SkinDacia = 1, SkinUAZ = 1, SkinCoupe = 1, SkinBuggy = 1, SkinMirado = 1
        }
        local LocUtil = _G.LocUtil or package.loaded["client.common.LocUtil"]
        if not LocUtil then pcall(function() LocUtil = require("client.common.LocUtil") end) end
        local FakeTextMap = {
            [999000] = "SDWxOWNER PREMIUM",
            [999001] = "> VISUALS",
            [999002] = "> PERFORMANCE",
        }
        if LocUtil and not LocUtil._IsModMenuHooked then
            for _, fn in ipairs({"GetLocalizeResStr","GetText","GetTextByID","GetLocalText","GetLocalizeStr"}) do
                if LocUtil[fn] then
                    local oldFunc = LocUtil[fn]
                    local localOld = oldFunc
                    LocUtil[fn] = function(id)
                        if FakeTextMap[id] then return FakeTextMap[id] end
                        if type(id) == "string" and not tonumber(id) then return id end
                        if type(localOld) == "function" then return localOld(id) end
                        return ""
                    end
                end
            end
            LocUtil._IsModMenuHooked = true
        end
        local SettingPageDefine = require("client.logic.NewSetting.SettingPageDefine")
        local SettingCatalog = require("client.logic.NewSetting.SettingCatalog")
        local AliasMap = require("client.slua.umg.NewSetting.Item.AliasMap")
        local D = function()
            pcall(function()
                _G._ConfigDirty = true
                if _G.SaveModSettings then _G.SaveModSettings(true) end
            end)
