        end

        local colNames = {"Red","Cyan","Yellow","Green","Purple","White"}
        local colVals = {0,1,2,3,4,5}
        -- [SDWxOWNER] Enemy Counter text colour list: Yellow default, White removed.
        local counterColNames = {"Red","Cyan","Yellow","Green","Purple"}
        local counterColVals = {0,1,2,3,4}

        local StackWallhack = {
            { Key = "GK_Wallhack", UI = AliasMap.Switcher, Text = "Wallhack (New Engine Chams)", ExpandIndex = 0, GetFunc = function() return _G.SDWConfig.WallhackEnabled end, SetFunc = function(c,v) SafeToggle("GK_Wallhack", function() _G.SDWConfig.WallhackEnabled = v; if not v then if _G.SDW_DisableFeature then pcall(_G.SDW_DisableFeature, "wallhack") else for _, data in pairs((_G.SDWState and _G.SDWState.EnemyMarks) or {}) do if data and data.enemy then UndoColorBodyNew(data.enemy, data) end end end else StartVisuals() end end); return D() end },
            { Key = "GK_HDRGlow", UI = AliasMap.Switcher, Text = " + HDR Glow Mode", ExpandHandle = "GK_Wallhack", GetFunc = function() return _G.SDWConfig.HDRGlowEnabled ~= false end, SetFunc = function(c,v) _G.SDWConfig.HDRGlowEnabled = v; local KSL = import("KismetSystemLibrary"); local w = slua.getWorld(); if KSL and w then if v then KSL.ExecuteConsoleCommand(w, "r.BloomQuality 1"); KSL.ExecuteConsoleCommand(w, "r.Mobile.TonemapperFilm 1") else KSL.ExecuteConsoleCommand(w, "r.BloomQuality 0"); KSL.ExecuteConsoleCommand(w, "r.Mobile.TonemapperFilm 0") end end; return D() end },
            { Key = "GK_GlowIntensity", UI = AliasMap.Slider, Text = " + Glow Intensity", ExpandHandle = "GK_Wallhack", MinValue = 10, MaxValue = 100, GetFunc = function() return _G.SDWConfig.GlowIntensity or 60 end, SetFunc = function(c,v) SafeToggle("GK_GlowIntensity", function() _G.SDWConfig.GlowIntensity = tonumber(v) or 60; LINEAR_COLOR_CACHE = {}; if _G.SDWState and _G.SDWState.EnemyMarks then for _, d in pairs(_G.SDWState.EnemyMarks) do d.LastColorNewHash = "" end end end); return D() end },
            { Key = "GK_C_EWH_V", UI = AliasMap.Switcher, Text = " + Enemy Visible Color", ExpandHandle = "GK_Wallhack", SwitcherText = colNames, SwitcherValue = colVals, GetFunc = function() return _G.SDWConfig.ColorEnemyWHVis or 0 end, SetFunc = function(c,v) _G.SDWConfig.ColorEnemyWHVis = v; LINEAR_COLOR_CACHE = {}; if _G.SDWState and _G.SDWState.EnemyMarks then for _, d in pairs(_G.SDWState.EnemyMarks) do d.LastColorNewHash = "" end end; return D() end },
            { Key = "GK_C_EWH_O", UI = AliasMap.Switcher, Text = " + Enemy Invisible Color", ExpandHandle = "GK_Wallhack", SwitcherText = colNames, SwitcherValue = colVals, GetFunc = function() return _G.SDWConfig.ColorEnemyWHOcc or 0 end, SetFunc = function(c,v) _G.SDWConfig.ColorEnemyWHOcc = v; LINEAR_COLOR_CACHE = {}; if _G.SDWState and _G.SDWState.EnemyMarks then for _, d in pairs(_G.SDWState.EnemyMarks) do d.LastColorNewHash = "" end end; return D() end },
            { Key = "GK_C_BWH_V", UI = AliasMap.Switcher, Text = " + Bot Visible Color", ExpandHandle = "GK_Wallhack", SwitcherText = colNames, SwitcherValue = colVals, GetFunc = function() return _G.SDWConfig.ColorBotWHVis or 0 end, SetFunc = function(c,v) _G.SDWConfig.ColorBotWHVis = v; LINEAR_COLOR_CACHE = {}; if _G.SDWState and _G.SDWState.EnemyMarks then for _, d in pairs(_G.SDWState.EnemyMarks) do d.LastColorNewHash = "" end end; return D() end },
            { Key = "GK_C_BWH_O", UI = AliasMap.Switcher, Text = " + Bot Invisible Color", ExpandHandle = "GK_Wallhack", SwitcherText = colNames, SwitcherValue = colVals, GetFunc = function() return _G.SDWConfig.ColorBotWHOcc or 5 end, SetFunc = function(c,v) _G.SDWConfig.ColorBotWHOcc = v; LINEAR_COLOR_CACHE = {}; if _G.SDWState and _G.SDWState.EnemyMarks then for _, d in pairs(_G.SDWState.EnemyMarks) do d.LastColorNewHash = "" end end; return D() end },
        }

                local StackESP_V1 = {
