    local function ShowWelcomeDialog()
        if _G.SDWState.WelcomeShown then return end
        _G.SDWState.WelcomeShown = true
        pcall(function()
            local Msg = GetMsgBox(); if not Msg or not Msg.Show then return end
            local sh = import("ScriptHelperClient")
            if sh and sh.AddOnScreenDebugMessage then sh.AddOnScreenDebugMessage("SECURING ENGINE...", -1, 2.0, {0, 255, 0, 255}, {1.5, 1.5}) end

            Msg.Show(1, "* SDWxOWNER PREMIUM *", table.concat({
                "SYSTEM STATUS:",
                "* Engine Status : Active",
                "* Subscription  : Active",
                "* Build Version : v4.6",
                "",
                "STATUS: Ready. Enjoy!"
            }, "\n"), function()
                pcall(function() require("common.time_ticker").AddTimerOnce(0.5, ShowWelcomePopup) end)
            end, nil, "Continue", "")
        end)
    end

    local _MAINLOOP_RUNNING = false
    local function MainLoop()
        if not _G.LOGIN_OK then return end
        if _MAINLOOP_RUNNING then return end
        _MAINLOOP_RUNNING = true
        local ok, err = pcall(function()
        if _G._MOD_EXPIRED then pcall(ShowExpiryDialog); return end
        if not _G.SDWState.CustomTextData then
            _G.SDWState.CustomTextData = {
                iPadViewFOV = 110,
                SkinSuit = 1, SkinBag = 1, SkinHelmet = 1,
                SkinM416 = 1, SkinAKM = 1, SkinSCAR = 1, SkinM762 = 1, SkinAUG = 1, SkinUMP = 1,
                SkinUZI = 1, SkinGroza = 1, SkinS12K = 1, SkinDBS = 1, SkinASM = 1, SkinQBZ = 1,
                SkinHoney = 1, SkinM16A4 = 1, SkinACE32 = 1, SkinKar98k = 1, SkinM24 = 1, SkinAWM = 1,
                SkinDacia = 1, SkinUAZ = 1, SkinCoupe = 1, SkinBuggy = 1, SkinMirado = 1
            }
        end
        local gpd = _cached_GameplayData
        if not gpd then local ok; ok, gpd = pcall(require, "GameLua.GameCore.Data.GameplayData"); if ok then _cached_GameplayData = gpd else return end end
        local pc = gpd.GetPlayerController(); local localPlayer = nil
        if Valid(pc) then localPlayer = pc:GetPlayerCharacterSafety() end
        if not Valid(localPlayer) then if _G.SDWState.MatchStarted then CleanupMatchState(pc) end; return end
        local pawnKey = nil
        pcall(function() if localPlayer.GetUniqueID then pawnKey = tostring(localPlayer:GetUniqueID()) end end)
        if not pawnKey then pawnKey = tostring(localPlayer) end
        if not _G.SDWState.MatchStarted or (_G._SDW_LastPawnKey and _G._SDW_LastPawnKey ~= pawnKey) then
            _G.SDWState.MatchStarted = true
            _G._SDW_LastPawnKey = pawnKey
            _G._GK_SentThisMatch = nil   -- [SDWxOWNER-FEEDBACK-FIX] new match -> allow the single shot
            _G._SDW_TDMEventFired = nil  -- [SDWxOWNER-TDM-FEEDBACK] new match -> re-arm TDM/Arena detector
            _G._SDW_CreativeEventFired = nil  -- [SDWxOWNER-WOW-FEEDBACK] new match -> re-arm WOW/Creative detector
            pcall(_G.StartMatchFeatures, pc, localPlayer)
        end

        local visualsHealthy = _G.VisualsStarted and _G.VisualTimerIds and #_G.VisualTimerIds > 0
        if visualsHealthy and TimerManager then
            local anyAlive = false
            for _, tid in ipairs(_G.VisualTimerIds) do
                if TimerManager._byId[tid] then anyAlive = true; break end
            end
            visualsHealthy = anyAlive
        end
        if _G.SDWState.MatchStarted and not visualsHealthy then
            local nowRetry = os.time()
            if nowRetry - (_G._SDW_LastVisualRetry or 0) >= 3 then
                _G._SDW_LastVisualRetry = nowRetry
                pcall(function() if _G.StartVisuals then _G.StartVisuals(true) end end)
            end
        end
        if _G.SDW_EnsureSnapline then pcall(_G.SDW_EnsureSnapline) end
        if _G.SDW_EnsureV3Counter then pcall(_G.SDW_EnsureV3Counter) end
        if _G.SDW_EnsureV4Counter then pcall(_G.SDW_EnsureV4Counter) end

        -- [SDWxOWNER-FULLMATCH FIX] Keep the aimbot self-arming chain alive for the WHOLE
        -- match. If it went silent (>3s == 150 missed 0.02s ticks) re-arm it here.
        -- [SDWxOWNER-AIMCHAIN FIX] force=true: the idempotent starter only spawns a chain if
        -- none is live (or the running one is genuinely silent), so this keepalive can NEVER
        -- stack a second chain on a healthy one.
        if _G._SDW_AimAlive ~= false and _G.SDW_EnsureAim then
            local _at = os.clock()
            if (_at - (_G._SDW_AimLastTick or 0)) > 3.0 then
                pcall(_G.SDW_EnsureAim, true)
            end
        end


        if _G._GK_PBC_ENABLED and not _G._GK_PBC_ENABLED.get() then
            pcall(function()
                if _G._GK_retryCount then
                    _G._GK_retryCount.set(math.min(tonumber(_G._GK_retryCount.get()) or 0, 25))
                end
            end)
            pcall(_G.RetryStart or function() end)
        end

        if not _G.SDWState.WelcomeShown then ShowWelcomePopup(); _G.SDWState.WelcomeShown = true end
        -- [SDWxOWNER-SMOOTH] Build the mod menu on a LATER frame (it loads several
        -- modules + hooks the settings UI) so it does not stall the match-start frame.
        if not _G.ModMenuInitialized and not _G._SDW_MenuInitPending and _G.InitModMenuTab then
            _G._SDW_MenuInitPending = true
            local _defer = _G.SDW_Defer or function(_, fn) pcall(fn) end
            _defer(0.60, function()
                _G._SDW_MenuInitPending = false
                pcall(_G.InitModMenuTab)
                pcall(function()
                    if _G.Notify then _G.Notify("SDWxOWNER PREMIUM active! Open Settings -> SDWxOWNER PREMIUM to configure.") end
                end)
            end)
        end
        if not _G._GK_FeedbackStarted then
            _G._GK_FeedbackStarted = true
        end
        if _G._GK_InstallBattleResultHook then
            local _brt = os.time()
            if not _G._SDW_BRHookNextTry or _brt >= _G._SDW_BRHookNextTry then
                _G._SDW_BRHookNextTry = _brt + 5
                pcall(_G._GK_InstallBattleResultHook)
            end
        end
        pcall(function() if Valid(pc) then if pc.HiggsBoson then pc.HiggsBoson.bMHActive = false; pc.HiggsBoson.bCallPreReplication = false end; if pc.HiggsBosonComponent then pc.HiggsBosonComponent.bMHActive = false; pc.HiggsBosonComponent.bCallPreReplication = false end end end)
        pcall(_G.ApplyiPadView or function() end)
        pcall(_G.SDW_EnsureiPadHold or function() end)
        -- [SDWxOWNER] TPP-in-FPP removed.
        if _G.SpinEngine and _G.SpinEngine.ResetForMatch then
            local _spinGen = _G._SDW_MatchGen or 0
            if _G._SDW_SpinGen ~= _spinGen then
                _G._SDW_SpinGen = _spinGen
                pcall(_G.SpinEngine.ResetForMatch)
            end
        end
        pcall(_G.SDW_EnsurePaidWatermark or function() end)
        pcall(_G.SDW_MenuTick or function() end)

        local _skinFullOn  = _G.SDWConfig and _G.SDWConfig.ModSkin
        if _skinFullOn then
            if not _G.TDSkinLoopStarted then
                if _G.InitializeSkinModSystem then _G.InitializeSkinModSystem() end
                if _G.ForceRefreshSkinMaps then _G.ForceRefreshSkinMaps() end
                _G.TDSkinLoopStarted = true
            end

            _G.SDWState.SkinWasApplied = true

            -- [SDWxOWNER] Auto-resolve named bag/helmet skins from the Item table (retries until loaded).
            if _G.SDW_ResolveNamedSkins then pcall(_G.SDW_ResolveNamedSkins) end

            -- [SDWxOWNER-FIX] Simple fixed-interval skin timer (SDWxOWNER): re-apply every skin every 3 seconds.
            local ct = os.clock()
            if not _G.LastSkinUpdateTime or (ct - _G.LastSkinUpdateTime) > 3.0 then
                _G.LastSkinUpdateTime = ct
                pcall(function()
                    local alive = type(localPlayer.IsAlive) == "function" and localPlayer:IsAlive() or true
                    if alive then
                        -- [SDWxOWNER] (Re)install the kill-counter hooks every beat (idempotent:
                        -- each hook is guarded) and re-assert the counter skin for the live gun.
                        if _G.ForceEnableKillCounterUI then pcall(_G.ForceEnableKillCounterUI) end
                        if _G.SDW_KC_Tick then pcall(_G.SDW_KC_Tick) end
                        if _G.equip_character_avatar then pcall(_G.equip_character_avatar, localPlayer) end
                        if _G.ApplyWeaponSkins then pcall(_G.ApplyWeaponSkins, localPlayer) end
                        if _G.ApplyVehicleSkins then pcall(_G.ApplyVehicleSkins, localPlayer) end
                        if _G.HandlePetLogic then pcall(_G.HandlePetLogic) end
                        if _G.DeadBox_TemperRequest and Valid(pc) then pcall(_G.DeadBox_TemperRequest, pc) end
                    end
                end)
            end
        else
            if _G.SDWState and _G.SDWState.SkinWasApplied then
                if _G.RestoreDefaultSkins then _G.RestoreDefaultSkins(localPlayer) end
                _G.SDWState.SkinWasApplied = false
                _G._LastAppliedOutfitHash = 0
            end
            _G.TDSkinLoopStarted = false
        end
        pcall(function()
            local SL = import("KismetSystemLibrary")
            if SL and not _G.FakeHWID_Hooked then
                _G.Original_GetDeviceId = SL.GetDeviceId
                if not _G._HWID_SEEDED then
                    pcall(function() math.randomseed(os.time() + math.floor(os.clock() * 1000)) end)
                    _G._HWID_SEEDED = true
                end
                SL.GetDeviceId = function(...) if _G.SDWConfig.FakeHWID then if not _G.FakeHWID_String then local chars = "0123456789abcdef"; local hwid = ""; for i = 1, 32 do local pos = math.random(1,16); hwid = hwid .. chars:sub(pos, pos) end; _G.FakeHWID_String = hwid end; return _G.FakeHWID_String end; if _G.Original_GetDeviceId then return _G.Original_GetDeviceId(...) end; return "UNKNOWN" end
                _G.FakeHWID_Hooked = true
            end
        end)
        end)
        _MAINLOOP_RUNNING = false
        if not ok then LogError("MainLoop", err) end
    end

    -- [SDWxOWNER-RELOGIN FIX] FastTick is now built FRESH on every SDW_StartLoop so its
    -- generation token always matches the CURRENT LoopToken. Previously the token was
    -- captured ONCE here at load; SDW_RevokeAccess bumps LoopToken to kill the chain, so
    -- after entering a NEW key the loop could never restart (the stale token guard
    -- returned immediately) and EVERY feature had to be toggled by hand -- and skins
    -- only applied after a full game restart. Each StartLoop now bumps the token and
    -- binds a NEW chain to it, so a fresh valid login resumes the whole engine at once.
    local function MakeFastTick(myToken)
        local FastTick
        FastTick = function()
            if myToken ~= _G.SDWState.LoopToken then return end
            _G._SDW_LastTick = os.time()
            -- [SDWxOWNER-PERF] MainLoop already drives SDW_MenuTick + SDW_EnsureSnapline, so we do NOT call them again.
            pcall(MainLoop)
            -- [SDWxOWNER-FPS FIX] Second safety net: re-apply the 165-FPS cap every FastTick (3 s match / 8 s lobby).
            if _G.SDW_EnforceFPS then pcall(_G.SDW_EnforceFPS) end
            if TimerManager and TimerManager.PurgeDeadTimers then
                pcall(TimerManager.PurgeDeadTimers, TimerManager)
            end
            -- [SDWxOWNER-PERF] Periodic incremental GC nudge (matches new.lua's FastTick).
            -- The native setGCParam pacing (FPS Stabilizer) is the PRIMARY mechanism; this is a
            -- cheap belt-and-braces step on the slow keep-alive beat only. Gated on the toggle so
            -- switching the FPS Stabilizer OFF restores stock GC behaviour exactly.
            if _G.SDWConfig and _G.SDWConfig.FPSStabilizerEnabled ~= false then
                pcall(function() collectgarbage("step", 100) end)
            end
            local okTicker, ticker = pcall(require, "common.time_ticker")
            if okTicker and ticker and ticker.AddTimerOnce and not _G._MOD_EXPIRED and myToken == _G.SDWState.LoopToken then
                local nextDelay = (_G.SDWState and _G.SDWState.MatchStarted) and 3.0 or 8.0
                ticker.AddTimerOnce(nextDelay, FastTick)
            end
        end
        return FastTick
    end

    local function ExecuteMasterSequence()
        pcall(function()
            if _G.SetupConsole then _G.SetupConsole() end
            local sh = import("ScriptHelperClient")
            if sh and sh.AddOnScreenDebugMessage then
                sh.AddOnScreenDebugMessage("* SDWxOWNER ENGINE & INGAME PHONE STATS ACTIVE *", -1, 4.0, {0, 255, 0, 255}, {1.5, 1.5})
            end
        end)

        pcall(function()
            pcall(ShowWelcomeDialog)
            local tt = require("common.time_ticker")
            if tt and tt.AddTimerOnce then
                tt.AddTimerOnce(0.4, function()
                    if not _G.SDWState or not _G.SDWState.WelcomeShown then
                        pcall(ShowWelcomeDialog)
                    end
                end)
                tt.AddTimerOnce(1.2, function()
                    if not _G.SDWState or not _G.SDWState.WelcomeShown then
                        pcall(ShowWelcomeDialog)
                    end
                end)
            end
        end)
    end

    function _G.SDW_StartLoop()
        if _G._SDW_LOCKED or not _G.LOGIN_OK then return end
        _G._SDW_LastTick = os.time()
        -- [SDWxOWNER-RELOGIN FIX] Bump the generation and start a FRESH FastTick chain
        -- bound to it, so a re-login after a revoke ALWAYS resumes the engine. The old
        -- chain (if any) is invalidated by the bump and dies on its next beat.
        _G.SDWState.LoopToken = (_G.SDWState.LoopToken or 0) + 1
        local _ft = MakeFastTick(_G.SDWState.LoopToken)
        _G._SDW_FastTick = _ft
        _G.FastTick = _ft
        pcall(_ft)
        -- [SDWxOWNER-FPS FIX] Start the lifecycle-independent FPS enforcement loop.
        if _G.SDW_StartFPSLoop then pcall(_G.SDW_StartFPSLoop) end
        _G._SDW_WatchdogGen = (_G._SDW_WatchdogGen or 0) + 1
        local wgen = _G._SDW_WatchdogGen
        local _wdExpiryCounter = 0
        local function watchdog()
            if wgen ~= _G._SDW_WatchdogGen then return end
            if not _G.LOGIN_OK then return end
            if os.time() - (_G._SDW_LastTick or 0) > 15 then
                if _G._SDW_FastTick then pcall(_G._SDW_FastTick) end
            end
            -- [SDWxOWNER-FPS HARDEN] Watchdog for the 2.0 s FPS re-assert loop.
            -- [SDWxOWNER-PERF FIX #3] Staleness threshold widened 3 -> 8 s to match the slower beat
            -- (a live loop's heartbeat is at most ~2 s old, so 8 s is a safe dead-loop margin).
            pcall(function()
                local last = _G._SDW_FPSLastTick or 0
                if (os.time() - last) > 8 then
                    _G._SDW_FPSLoopRunning = false
                    if _G.SDW_StartFPSLoop then _G.SDW_StartFPSLoop() end
                end
            end)
            -- [FIX] Re-check expiry every ~10s (5 x 2s) so it also triggers mid-session.
            _wdExpiryCounter = _wdExpiryCounter + 1
            if _wdExpiryCounter >= 5 then
                _wdExpiryCounter = 0
                pcall(function() if _G.CheckExpiration then _G.CheckExpiration() end end)
            end
            pcall(function()
                local t = require("timer")
                if t and t.SetGameTimer then t.SetGameTimer(2.0, false, watchdog); return end
                local tt = require("common.time_ticker")
                if tt and tt.AddTimerOnce then tt.AddTimerOnce(2.0, watchdog) end
            end)
        end
        pcall(watchdog)
    end

    function _G.SDW_BootEngine()
        if _G._SDW_LOCKED or not _G.LOGIN_OK then return end
        if not _G._SDW_ENGINE_BOOTED then
            _G._SDW_ENGINE_BOOTED = true
            pcall(ExecuteMasterSequence)
        end
        pcall(_G.SDW_StartLoop)
    end
    if _G.LOGIN_OK then pcall(_G.SDW_BootEngine) end

    if _G._MOD_EXPIRED then pcall(function() require("common.time_ticker").AddTimerOnce(0.5, ShowExpiryDialog) end) end


    _G.CleanupMatchState = CleanupMatchState
    _G.ShowWelcomePopup = ShowWelcomePopup
    _G.ShowWelcomeDialog = ShowWelcomeDialog
    _G.ShowSetupGuidanceDialog = ShowSetupGuidanceDialog
    _G.MainLoop = MainLoop
    -- [SDWxOWNER-RELOGIN FIX] _G.FastTick is (re)bound to the live chain inside
    -- SDW_StartLoop (MakeFastTick), so it is intentionally NOT assigned here.
end


_G.SDWState = _G.SDWState or {}
_G._SDW_AimAlive = true

if not _G.GetEnemyTargetsFromActors then
    -- [SDWxOWNER-PERF] Short-lived pawn list for the aim scan.
    local _AIM_PAWN_CACHE, _AIM_PAWN_TIME = nil, 0
    -- [SDWxOWNER-PERF] Reusable entry pool + hoisted probe closures.
    local _AIM_ENTRY_POOL = {}
    local _AIM_LIST = {}
    local _AIM_GPD = nil
    local _AIM_MAXD = 25000
    local _aimPlayer, _aimActor, _aimDist, _aimKnocked
    local function _aimDistProbe() _aimDist = _aimPlayer:GetDistanceTo(_aimActor) end
    local function _aimKnockProbe()
        -- [SDWxOWNER-KILL-CRASH FIX] hs == 1 = knocked, hs == 2 = dead. Flag BOTH (plus the
        -- bIsDead/bDead flags) so the aim scan never hands a corpse (torn-down mesh) to the
        -- aim tick -> fixes the crash right at the kill moment on every weapon.
        local hs = _aimActor.HealthStatus
        _aimKnocked = (hs == 1) or (hs == 2) or (_aimActor.bIsGroggy == true) or (_aimActor.bIsGrogggy == true) or (_aimActor.bIsDying == true) or (_aimActor.bIsDead == true) or (_aimActor.bDead == true)
    end
    -- [SDWxOWNER-ALLMAPS] Hoisted team probe (no per-actor closure allocation).
    local _aimTeamActor, _aimTeam = nil, nil
    local function _aimTeamProbe()
        local a = _aimTeamActor
        if type(a.GetTeamID) == "function" then _aimTeam = a:GetTeamID()
        else _aimTeam = a.TeamID end
    end
    -- [SDWxOWNER-ALLMAPS] Multi-source pawn gather (Classic / rooms / TDM / FFA / custom
    -- maps). The old code only used Game:GetAllPlayerPawns(), which is empty on several
    -- modes -> the aimbot found NO enemies. We now also pull the GameplayData character
    -- lists and Game:GetAllPawns(), de-duplicated, into a reusable scratch table.
    local _AIM_SRC = {}
    local _AIM_SEEN = {}
    -- [SDWxOWNER-AIM-GC FIX] Hoisted, closure-free pawn gather. The old version built FOUR
    -- pcall(function() ... end) closures on every 0.1 s scan (~40 closures/sec, each one a GC
    -- object). During a 2-3 squad rush the pawn lists are at their largest, so this was pure
    -- garbage pressure right when the device is already at 20-30 fps. Same 4 sources, same
    -- de-dup, same pcall isolation -- just no per-scan allocation.
    local _aimSrcN = 0
    local function _aimSrcPush(c) if c then _aimSrcN = _aimSrcN + 1; _AIM_SRC[_aimSrcN] = c end end
    local function _aimSrcPushList(list)
        if not list then return end
        if type(list.Num) == "function" then
            for i = 0, list:Num() - 1 do _aimSrcPush(list:Get(i)) end
        else
            for _, c in pairs(list) do _aimSrcPush(c) end
        end
    end
    local function _aimGatherSrcA()
        local gpd = _AIM_GPD
        if gpd and gpd.GetAllPlayerCharacters then _aimSrcPushList(gpd.GetAllPlayerCharacters()) end
    end
    local function _aimGatherSrcB()
        local gpd = _AIM_GPD
        if gpd and gpd.GameCharacters then for _, c in pairs(gpd.GameCharacters) do _aimSrcPush(c) end end
    end
    local function _aimGatherSrcC()
        if Game and Game.GetAllPlayerPawns then _aimSrcPushList(Game:GetAllPlayerPawns()) end
    end
    local function _aimGatherSrcD()
        if Game and Game.GetAllPawns then _aimSrcPushList(Game:GetAllPawns()) end
    end
    local function _aimGatherPawns()
        _aimSrcN = 0
        pcall(_aimGatherSrcA)
        pcall(_aimGatherSrcB)
        pcall(_aimGatherSrcC)
        pcall(_aimGatherSrcD)
        for i = _aimSrcN + 1, #_AIM_SRC do _AIM_SRC[i] = nil end
        return _AIM_SRC
    end
    local function _aimCollect()
        local gpd = _AIM_GPD
        if not gpd then
            local ok; ok, gpd = pcall(require, "GameLua.GameCore.Data.GameplayData")
            if ok then _AIM_GPD = gpd; _cached_GameplayData = gpd end
        end
        local player = gpd and gpd.GetPlayerCharacter and gpd.GetPlayerCharacter()
        if not player or not slua.isValid(player) then return end
        local now = os.clock()
        local pawns = _AIM_PAWN_CACHE
        if not pawns or (now - _AIM_PAWN_TIME) > 0.1 then
            pawns = _aimGatherPawns()
            _AIM_PAWN_CACHE = pawns
            _AIM_PAWN_TIME = now
        end
        if not pawns then return end
        local myTeam = player.TeamID or 0
        local list = _AIM_LIST
        local pool = _AIM_ENTRY_POOL
        local seen = _AIM_SEEN
        for k in pairs(seen) do seen[k] = nil end
        local n = 0
        _aimPlayer = player
        for _, actor in pairs(pawns) do
            if actor and slua.isValid(actor) and actor ~= player then
                if not seen[actor] then
                    seen[actor] = true
                    _aimTeamActor = actor; _aimTeam = nil
                    pcall(_aimTeamProbe)
                    local team = _aimTeam
                    -- [SDWxOWNER-ALLMAPS] Only skip a REAL teammate (both teams known and
                    -- equal). A nil / 0 team (rooms / TDM / FFA / custom maps) counts as an
                    -- enemy so the aimbot works on every map.
                    local sameTeam = (myTeam and myTeam ~= 0 and team and team ~= 0 and team == myTeam)
                    if not sameTeam then
                        _aimActor = actor; _aimDist = 0
                        pcall(_aimDistProbe)
                        local dist = _aimDist
                        if dist and dist <= _AIM_MAXD then
                            _aimKnocked = false
                            pcall(_aimKnockProbe)
                            n = n + 1
                            local e = pool[n]
                            if not e then e = {}; pool[n] = e end
                            e.actor = actor; e.distance = dist; e.knocked = _aimKnocked
                            list[n] = e
                        end
                    end
                end
            end
        end
        for i = n + 1, #list do list[i] = nil end
    end
    _G.GetEnemyTargetsFromActors = function(maxDistCm)
        _AIM_MAXD = maxDistCm or 25000
        for i = 1, #_AIM_LIST do _AIM_LIST[i] = nil end
        pcall(_aimCollect)
        return _AIM_LIST
    end
end

-- [SDWxOWNER-SMOOTH] Hoisted per-enemy probes for the 50 Hz aim scan. The old code created
-- 3-4 NEW pcall closures for EVERY enemy on EVERY tick (up to ~500 closures/second in a full
-- lobby) -> constant GC churn -> micro-stutter. These closures are now created ONCE and driven
-- through scratch variables, so the steady-state scan allocates nothing extra. Behaviour is
-- byte-for-byte identical: same calls, same guards, same pcall protection.
local _aimMesh, _aimBoneName, _aimPoint = nil, nil, nil
local function _aimSocketProbe()
    _aimPoint = nil
    local m = _aimMesh
    if not m then return end
    -- [SDWxOWNER-RUSH-FPS] A mesh that is mid-teardown can still pass slua.isValid() for a frame
    -- while its skeleton is already freed -> GetBoneLocation dereferences NULL -> native crash
    -- right at the kill moment (extremely common in a close-range 2-3 squad rush). Bail out.
    if m.bIsBeingDestroyed == true or m.bPendingKill == true then return end
    -- [SDWxOWNER-AIMBONE] Read the BONE position first (GetBoneLocation is the direct bone
    -- API and is the most accurate for a bone name like "pelvis"). Only if that is missing/
    -- zero do we fall back to GetSocketLocation. Previously GetSocketLocation was tried first
    -- and, when it did not resolve the bone, the scan fell through to the actor-origin
    -- fallback (base.Z + zOff) -> the crosshair could land on the wrong height (e.g. the pelvis).
    local p = nil
    if type(m.GetBoneLocation) == "function" then p = m:GetBoneLocation(_aimBoneName) end
    if (not p or (p.X == 0 and p.Y == 0 and p.Z == 0)) and type(m.GetSocketLocation) == "function" then
        p = m:GetSocketLocation(_aimBoneName)
    end
    _aimPoint = p
end
local _aimLOSPC, _aimLOSActor, _aimLOSOK = nil, nil, true
local function _aimLOSProbe()
    _aimLOSOK = true
    local c = _aimLOSPC
    if type(c.LineOfSightTo) == "function" then _aimLOSOK = (c:LineOfSightTo(_aimLOSActor) == true) end
end
local _aimBaseActor, _aimBase = nil, nil
local function _aimBaseProbe()
    _aimBase = nil
    local a = _aimBaseActor
    if type(a.K2_GetActorLocation) == "function" then _aimBase = a:K2_GetActorLocation() end
end
-- [SDWxOWNER-AIM-FPS] Reusable scratch target for the cheap angle PRE-FILTER (see the aim
-- scan). Using one table avoids allocating a {X,Y,Z} per enemy per tick.
local _aimPreTarget = { X = 0, Y = 0, Z = 0 }
local _aimKM, _aimFromLoc, _aimToPoint, _aimTRot = nil, nil, nil, nil
local function _aimRotProbe()
    _aimTRot = _aimKM.FindLookAtRotation(_aimFromLoc, _aimToPoint)
end
local _aimVehActor, _aimVehOK = nil, false
local function _aimVehProbe() _aimVehOK = slua.isValid(_aimVehActor:GetCurrentVehicle()) end
local _aimCtlPC, _aimCtlRot = nil, nil
local function _aimCtlProbe() _aimCtlRot = _aimCtlPC:GetControlRotation() end
local _aimCamComp, _aimCamLoc = nil, nil
local function _aimCamProbe() _aimCamLoc = _aimCamComp:GetCameraLocation() end
-- [SDWxOWNER-FIRE-LAG FIX] Enemy-list cache (see SDW_CleanAimbotTick). While firing the
-- full multi-source scan is throttled to 10 Hz instead of running every 0.02s tick.
local _SDW_AimEnemyCache, _SDW_AimEnemyCacheT = nil, 0

-- [SDWxOWNER-PERF] Hoisted closures for the 50 Hz aim scan. These replace the remaining
-- inline pcall(function() ... end) bodies (module resolve, controller/pawn resolve, enemy
-- scan, distance probe, velocity lead and the final control-rotation write) so the
-- steady-state aim tick allocates NO closure. Scratch locals are reused; the target vector
-- and output rotator tables are pre-allocated once and mutated in place. Behaviour is
-- byte-for-byte identical: same calls, same guards, same pcall protection.
local _aimReqOK, _aimReqMod = nil, nil
local function _aimRequireProbe()
    _aimReqOK, _aimReqMod = pcall(require, "GameLua.GameCore.Data.GameplayData")
end
local _aimGpd, _aimPC2, _aimPlayer2 = nil, nil, nil
local function _aimResolveProbe()
    local g = _aimGpd
    if g.GetPlayerController then _aimPC2 = g.GetPlayerController() end
    if g.GetPlayerCharacter then _aimPlayer2 = g.GetPlayerCharacter() end
end
local _aimScanFn, _aimScanMaxDist, _aimScanOut = nil, 0, nil
local function _aimScanProbe() _aimScanOut = _aimScanFn(_aimScanMaxDist) end
local _aimDistPlayer, _aimDistActor, _aimDistVal = nil, nil, nil
local function _aimDistProbe() _aimDistVal = _aimDistPlayer:GetDistanceTo(_aimDistActor) end
local _aimVelEnemy, _aimVel = nil, nil
local function _aimVelProbe()
    _aimVel = nil
    local e = _aimVelEnemy
    if type(e.GetVelocity) == "function" then _aimVel = e:GetVelocity() end
end
local _aimWTarget = { X = 0, Y = 0, Z = 0 }
local _aimWOut = { Pitch = 0, Yaw = 0, Roll = 0 }
local _aimWPC, _aimWPlayer, _aimWCamLoc, _aimWCurRot, _aimWKismet, _aimWC = nil, nil, nil, nil, nil, nil
local _aimWX, _aimWY, _aimWZ = 0, 0, 0
-- [SDWxOWNER-SCOPE FIX] Hoisted probes that read the camera POV and the pawn eye FRESH at the
-- moment of the control-rotation write (see _aimWriteProbe). Closure-free, no per-tick garbage.
local _aimWCamMgr, _aimWPovLoc, _aimWPovRot = nil, nil, nil
local function _aimWPovProbe()
    _aimWPovLoc, _aimWPovRot = nil, nil
    local c = _aimWCamMgr
    if c and c.CameraCache and c.CameraCache.POV then
        _aimWPovLoc = c.CameraCache.POV.Location
        _aimWPovRot = c.CameraCache.POV.Rotation
    end
end
local _aimWEyeLoc = nil
local function _aimWEyeProbe()
    _aimWEyeLoc = nil
    local p = _aimWPlayer
    local m = p and p.Mesh
    if m and slua.isValid(m) then
        if type(m.GetSocketLocation) == "function" then _aimWEyeLoc = m:GetSocketLocation("head")
        elseif type(m.GetBoneLocation) == "function" then _aimWEyeLoc = m:GetBoneLocation("head") end
    end
    if _aimWEyeLoc and _aimWEyeLoc.X == 0 and _aimWEyeLoc.Y == 0 and _aimWEyeLoc.Z == 0 then _aimWEyeLoc = nil end
    if not _aimWEyeLoc and type(p.K2_GetActorLocation) == "function" then
        local a = p:K2_GetActorLocation()
        if a and not (a.X == 0 and a.Y == 0 and a.Z == 0) then _aimWEyeLoc = { X = a.X, Y = a.Y, Z = a.Z + 65 } end
    end
end
local function _aimWriteProbe()
    -- [SDWxOWNER-CRASH FIX] Re-validate the controller + camera right before the native write.
    if not (_aimWPC and slua.isValid(_aimWPC)) then return end
    local pl = _aimWPlayer
    if not (pl and slua.isValid(pl)) then return end
    if pl.bIsDying == true or pl.bIsGroggy == true or pl.bIsGrogggy == true or pl.HealthStatus == 1 or pl.HealthStatus == 2 then return end
    -- [SDWxOWNER-CRASH FIX] Re-check the vehicle attachment immediately before the write.
    _aimVehActor = pl; _aimVehOK = false
    pcall(_aimVehProbe)
    if _aimVehOK then return end
    local cam2 = _aimWPC.PlayerCameraManager
    if not (cam2 and slua.isValid(cam2)) then return end

    -- [SDWxOWNER-SCOPE FIX] Read the camera POV (location + rotation) FRESH here instead of the
    -- snapshot taken at the top of the tick. During/right after a scope-in the camera is still
    -- blending from the 3rd-person rig to the scope; the tick-start snapshot can still be the OLD
    -- (behind/above) rig, so aiming from it lands the crosshair down-and-right of the enemy. This
    -- is exactly the "scope aims to the side / below, re-scope fixes it" bug.
    _aimWCamMgr = cam2
    pcall(_aimWPovProbe)
    local camLoc = _aimWPovLoc or _aimWCamLoc
    local camRot = _aimWPovRot

    -- [SDWxOWNER-SCOPE FIX] While scoped the crosshair ray starts at the SCOPE (the pawn eye),
    -- NOT at the 3rd-person rig. The hip rig sits ~200cm BEHIND the head, so aiming from it
    -- points the crosshair off to the SIDE and slightly BELOW the target (the exact "scope aim
    -- lands beside/below the pelvis, re-scope fixes it" bug: on the first scoped tick the camera
    -- is still blending in from the hip rig). While scoped we therefore always aim from the pawn
    -- eye, which is where the scope ray actually originates. The eye read is sanity-guarded
    -- (only trusted when it is plausibly near the camera) so a garbage socket value can never
    -- throw the aim off into the distance.
    local scoped = (pl.bIsGunADS == true)
    if scoped then
        _aimWEyeLoc = nil
        pcall(_aimWEyeProbe)
        local eye = _aimWEyeLoc
        if eye and camLoc then
            local dx = (camLoc.X or 0) - eye.X
            local dy = (camLoc.Y or 0) - eye.Y
            local dz = (camLoc.Z or 0) - eye.Z
            local d2 = dx*dx + dy*dy + dz*dz
            if d2 <= (500*500) then camLoc = eye end
        end
    end

    _aimWTarget.X = _aimWX; _aimWTarget.Y = _aimWY; _aimWTarget.Z = _aimWZ
    -- [SDWxOWNER-RUSH-CRASH FIX] Degenerate-rotator guard. During an enemy RUSH the target can sit
    -- almost exactly ON the camera; FindLookAtRotation then divides by a ~zero look-at vector and
    -- returns NaN. Feeding NaN into SetControlRotation crashes the native camera. Bail out when the
    -- camera location is non-finite or the target is within 1 cm of the camera (the exact rush case).
    if not (camLoc and camLoc.X == camLoc.X and camLoc.Y == camLoc.Y and camLoc.Z == camLoc.Z) then return end
    local _dxT = _aimWTarget.X - camLoc.X
    local _dyT = _aimWTarget.Y - camLoc.Y
    local _dzT = _aimWTarget.Z - camLoc.Z
    if (_dxT * _dxT + _dyT * _dyT + _dzT * _dzT) < 1.0 then return end
    local tRot = _aimWKismet.FindLookAtRotation(camLoc, _aimWTarget)
    if not tRot then return end
    if not (tRot.Pitch == tRot.Pitch and tRot.Yaw == tRot.Yaw) then return end
    -- [SDWxOWNER-SCOPE FIX] Compute the delta against the CAMERA's actual rotation (the real
    -- crosshair direction) and apply it to the control rotation, so the CROSSHAIR lands on the
    -- target even if the camera carries an offset vs the control rotation (recoil / scope sway /
    -- blend). When the two are equal this is a byte-for-byte no-op vs the old behaviour.
    local curRot = _aimWCurRot
    local refRot = camRot or curRot
    local dP = ((tRot.Pitch - refRot.Pitch + 180) % 360) - 180
    local dY = ((tRot.Yaw - refRot.Yaw + 180) % 360) - 180
    -- [SDWxOWNER-SPEED] Scope ON and OFF now use the SAME slider-driven smoothing
    -- (speed/100 per tick). The old hardcoded scoped boost (0.5) is removed so the
    -- Aim Speed slider is consistent in both modes (slider 20 -> 20%/tick).
    -- [SDWxOWNER-SPEED] Hard ceiling: aim speed is capped at 20 (range 5..20), so even a
    -- hand-edited config can never exceed 20%/tick.
    local spd = tonumber(_aimWC.SDWAimSpeed) or 10
    if spd < 5 then spd = 5 end
    if spd > 20 then spd = 20 end
    local factor = math.min(1.0, math.max(0.05, spd * 0.01))
    _aimWOut.Pitch = curRot.Pitch + dP * factor
    _aimWOut.Yaw = curRot.Yaw + dY * factor
    _aimWOut.Roll = 0
    -- [SDWxOWNER-RUSH-CRASH FIX] Final finite gate right before the native write: never push a
    -- NaN/Inf rotator into SetControlRotation (native camera crash on an enemy rush).
    if not (_aimWOut.Pitch == _aimWOut.Pitch and _aimWOut.Yaw == _aimWOut.Yaw) then return end
    _aimWPC:SetControlRotation(_aimWOut, "SDWAim")
end

-- [SDWxOWNER-WEAPONCLASS] Local-player weapon class detector (SHOTGUN / SNIPER / OTHER).
-- Self-contained: it does NOT touch __SDW_ModMain's locals (which sit at the 200-local
-- LuaJIT ceiling) and every native read is pcall-guarded. Result cached 0.4 s so the aim
-- tick never pays for a native weapon read more than ~2x/sec.
do
    local _wcClass, _wcT = "OTHER", 0
    local function _wcWeapon(pawn)
        local w = nil
        local ok, v = pcall(function()
            local mgr = pawn.WeaponManagerComponent
            return mgr and mgr.CurrentWeaponReplicated
        end)
        if ok and v then w = v end
        if not w then
            ok, v = pcall(function() return pawn.CurrentWeapon end)
            if ok and v then w = v end
        end
        if not w then
            ok, v = pcall(function() return pawn:GetCurrentShootWeapon() end)
            if ok and v then w = v end
        end
        if not w then
            ok, v = pcall(function() return pawn:GetCurrentWeapon() end)
            if ok and v then w = v end
        end
        return w
    end
    local function _wcName(w)
        local nm = nil
        local ok, n = pcall(function() return w:GetWeaponName() end)
        if ok and type(n) == "string" and n ~= "" then nm = n end
        if not nm then
            ok, n = pcall(function() return w:GetItemName() end)
            if ok and type(n) == "string" and n ~= "" then nm = n end
        end
        if not nm then
            ok, n = pcall(function() return w.WeaponName end)
            if ok and type(n) == "string" and n ~= "" then nm = n end
        end
        return nm
    end
    function _G.SDW_MyWeaponClass(pawn)
        if not pawn then return "OTHER" end
        local now = os.clock()
        if (now - _wcT) < 0.4 then return _wcClass end
        local cls = "OTHER"
        local w = _wcWeapon(pawn)
        if w then
            -- [SDWxOWNER-SCOPEFREE] Class is read from the WEAPON ITSELF, never from the ADS /
            -- scope state. So the sniper & shotgun aimbot behave exactly like every other gun:
            -- they work hip-fire AND scoped. Engine flags are tried first (cheap + exact), the
            -- name table is the fallback for builds that do not expose them.
            local okF, isSG = pcall(function() return w.bIsShotgun == true or w.bIsShotGun == true end)
            local okF2, isSN = pcall(function() return w.bIsSniper == true or w.bIsSniperRifle == true or w.bIsDMR == true end)
            if okF and isSG then
                cls = "SHOTGUN"
            elseif okF2 and isSN then
                cls = "SNIPER"
            end
        end
        if cls == "OTHER" and w then
            local nm = _wcName(w)
            if nm then
                local l = string.lower(nm)
                if l:find("s686", 1, true) or l:find("s1897", 1, true) or l:find("s12k", 1, true)
                   or l:find("dbs", 1, true) or l:find("m1014", 1, true) or l:find("ns2000", 1, true)
                   or l:find("shotgun", 1, true) then
                    cls = "SHOTGUN"
                elseif l:find("kar98", 1, true) or l:find("m24", 1, true) or l:find("awm", 1, true)
                   or l:find("mosin", 1, true) or l:find("win94", 1, true) or l:find("amr", 1, true)
                   or l:find("sks", 1, true) or l:find("slr", 1, true) or l:find("mini14", 1, true)
                   or l:find("mk14", 1, true) or l:find("qbu", 1, true) or l:find("mk12", 1, true)
                   or l:find("vss", 1, true) or l:find("sniper", 1, true) or l:find("dmr", 1, true) then
                    cls = "SNIPER"
                end
            end
        end
        _wcClass, _wcT = cls, now
        return cls
    end
    -- Shotgun tube-empty check (only called for SHOTGUN, cached with the class read).
    function _G.SDW_MyAmmoEmpty(pawn)
        if not pawn then return false end
        local w = _wcWeapon(pawn)
        if not w then return false end
        local ammo = nil
        local ok, v = pcall(function() return w:GetCurrentAmmo() end)
        if ok and type(v) == "number" then ammo = v end
        if ammo == nil then
            ok, v = pcall(function() return w.CurrentAmmo end)
            if ok and type(v) == "number" then ammo = v end
        end
        if ammo == nil then
            ok, v = pcall(function()
                local sc = w.ShootWeaponComponent
                return sc and sc:GetCurrentAmmo()
            end)
            if ok and type(v) == "number" then ammo = v end
        end
        if ammo == nil then return false end
        return ammo <= 0
    end
end

_G.SDW_CleanAimbotTick = function()
    -- [SDWxOWNER-LOCK] HARD GATE: the aimbot must NEVER run without a valid,
    -- unlocked key. (This was the hole: the aim chain self-arms at load time and
    -- only checked the config flag, so a wrong/expired key still aimed.)
    if not (_G.SDW_IsAuthorized and _G.SDW_IsAuthorized()) then return end
    local C = _G.SDWConfig
    if not C then return end
    if not (C.SDWAimbot == true or C.SDWAimbot == 1 or C.AimbotEnabled == true or C.AimbotEnabled == 1) then return end
    -- [SDWxOWNER-CRASH FIX] Never issue the native control-rotation write while a skin/avatar swap is in flight.
    if _G._SDW_SkinSwapUntil and os.clock() < _G._SDW_SkinSwapUntil then return end

    -- [SDWxOWNER-PERF] Fast idle gate.
    local _nowC = os.clock()
    local pc = _G._SDW_AimPC
    local player = _G._SDW_AimPlayer
    if not (pc and slua.isValid(pc) and player and slua.isValid(player)) or (_nowC - (_G._SDW_AimRefT or 0)) > 0.5 then
        local gpd = _cached_GameplayData or rawget(_G, "GameplayData")
        if not gpd then
            _aimReqOK, _aimReqMod = nil, nil
            pcall(_aimRequireProbe)
            gpd = _aimReqMod
            if _aimReqOK then _cached_GameplayData = gpd end
        end
        pc, player = nil, nil
        if gpd then
            _aimGpd = gpd; _aimPC2 = nil; _aimPlayer2 = nil
            pcall(_aimResolveProbe)
            pc, player = _aimPC2, _aimPlayer2
        end
        _G._SDW_AimPC, _G._SDW_AimPlayer, _G._SDW_AimRefT = pc, player, _nowC
    end
    if not pc or not slua.isValid(pc) then return end
    if not player or not slua.isValid(player) then return end
    -- [SDWxOWNER-CRASH FIX] Never write control rotation for a dead/dying/knocked pawn.
    -- [SDWxOWNER-FIX] hs==1 = knocked (HasLastBreath), hs==2 = dead (FinishedLastBreath).
    if player.bIsDying == true or player.bIsGroggy == true or player.bIsGrogggy == true or player.HealthStatus == 1 or player.HealthStatus == 2 then return end
    -- [SDWxOWNER-CRASH FIX] Never write control rotation in a vehicle (vehicle drives the
    -- camera -> crash). Re-validated before the write.
    local _inVeh = false
    _aimVehActor = player; _aimVehOK = false
    pcall(_aimVehProbe)
    _inVeh = _aimVehOK
    if _inVeh then return end

    -- [SDWxOWNER-WEAPONCLASS] Sniper / Shotgun aimbot gates. Everything else (speed, FOV,
    -- bone, distance, timers, lock) is shared with the main aimbot -- these two switches
    -- only decide whether the aimbot is allowed to run for that weapon class.
    local _wcls = _G.SDW_MyWeaponClass and _G.SDW_MyWeaponClass(player) or "OTHER"
    if _wcls == "SHOTGUN" then
        if C.SDWAimShotgun == false then return end
        -- Shotgun: don't keep aiming on an empty tube -- let the pump/reload run.
        if C.SDWAimSGStopEmpty ~= false and _G.SDW_MyAmmoEmpty and _G.SDW_MyAmmoEmpty(player) then return end
    elseif _wcls == "SNIPER" then
        if C.SDWAimSniper == false then return end
    end

    -- [SDWxOWNER-SCOPEFREE] Fire detection is SCOPE-INDEPENDENT. Hip-fire and ADS fire can
    -- surface on different engine flags depending on the weapon class (a bolt-action sniper
    -- and a pump shotgun do not always set the same bIsFiring flag an AR sets). We therefore
    -- accept ANY of the known "trigger held" flags, plus the weapon's own firing flag, so the
    -- sniper & shotgun aimbot fire exactly like every other gun -- scoped OR unscoped.
    local firing = (player.bIsWeaponFiring == true or player.bIsFiring == true
        or player.bIsFiringWeapon == true or player.bIsWeaponFire == true
        or player.bIsFirePressed == true or player.bIsAttackPressed == true
        or player.bIsLeftFirePressed == true)
    if not firing then
        local _wp = player.Weapon or player.CurrentWeapon
        if _wp then
            local okF, vF = pcall(function() return _wp.bIsFiring == true or _wp.bIsWeaponFiring == true end)
            if okF and vF then firing = true end
        end
    end
    local ads = (player.bIsGunADS == true)
    -- [SDWxOWNER-SHOOTONLY] Trigger is FIXED to SHOOT. The old Shoot/Scope/Any selector is gone:
    -- the aimbot only ever acts while the weapon is actually FIRING, so it can never drag the
    -- camera around while you are just scoping or standing still.
    local trigger = "shoot"
    -- [SDWxOWNER-AIMLOCK] Trigger-Fire LOCK -- SHOOT ONLY.
    -- The lock engages ONLY while the weapon is actually FIRING (bIsWeaponFiring/bIsFiring).
    -- ADS / scope-only aiming NEVER locks: if you are just holding the scope the aimbot
    -- still tracks normally, but the moment you pull the trigger the enemy you were on is
    -- frozen for the whole burst -- no sliding between two enemies mid-spray.
    -- The lock is dropped the instant the trigger is released, the target dies/knocks, or
    -- it leaves range -- so nothing ever gets stuck on a stale pawn.
    -- [SDWxOWNER-LOCKFIXED] LOCK IS ALWAYS ON, ALWAYS SHOOT-ONLY. The old menu selector is gone:
    -- while the trigger is held the target is frozen for the whole burst; the moment it is
    -- released (or the target dies/knocks/leaves range) the lock drops. No config gate at all.
    local fireLock = firing
    if not firing then _G._SDW_AimLock = nil end
    local lockActor = nil
    if fireLock then
        local la = _G._SDW_AimLock
        if la and slua.isValid(la) and la ~= player then lockActor = la else _G._SDW_AimLock = nil end
    end
    if not firing then return end

    local KismetMath = _SDW_CachedKismetMath
    if not KismetMath then KismetMath = import("KismetMathLibrary"); if KismetMath then _SDW_CachedKismetMath = KismetMath end end
    if not KismetMath then return end

    local camLoc, curRot = nil, nil
    local cam = pc.PlayerCameraManager
    if cam and slua.isValid(cam) then
        if cam.CameraCache and cam.CameraCache.POV then camLoc = cam.CameraCache.POV.Location end
        if not camLoc and type(cam.GetCameraLocation) == "function" then
            _aimCamComp = cam; _aimCamLoc = nil
            pcall(_aimCamProbe)
            camLoc = _aimCamLoc
        end
    end
    _aimCtlPC = pc; _aimCtlRot = nil
    pcall(_aimCtlProbe)
    curRot = _aimCtlRot
    if not camLoc or not curRot then return end

    local fovDeg = tonumber(C.SDWAimFOV) or 8
    local maxDistCm = (tonumber(C.SDWAimMaxDist) or 250) * 100
    -- [SDWxOWNER-AIMBONE-LOCK] Aim bone is HARD-LOCKED to PELVIS. The config value is
    -- ignored here (and forced back to 3 on load), so no menu/saved value can change it.
    local boneName = "pelvis"
    local zOff = 5
    local visOnly = (C.SDWAimVisibleOnly ~= false)
    local targetBots = (C.SDWAimTargetBots ~= false)
    local ignoreKnock = (C.SDWAimIgnoreKnock == true)

    local enemies = nil
    -- [SDWxOWNER-FIRE-LAG FIX] The full multi-source enemy scan used to run every 0.02s
    -- tick (50 Hz) while firing - that spike is the "lag when firing" the user feels.
    -- Re-use a cached enemy list for up to 0.1s (10 Hz): ~5x less scan cost, and targets
    -- cannot move meaningfully relative to the FOV within 100 ms, so aim is unchanged.
    local _nowE = os.clock()
    if _SDW_AimEnemyCache and (_nowE - _SDW_AimEnemyCacheT) < 0.1 then
        enemies = _SDW_AimEnemyCache
    elseif _G.GetEnemyTargetsFromActors then
        _aimScanFn = _G.GetEnemyTargetsFromActors; _aimScanMaxDist = maxDistCm; _aimScanOut = nil
        pcall(_aimScanProbe)
        enemies = _aimScanOut
        _SDW_AimEnemyCache = enemies
        _SDW_AimEnemyCacheT = _nowE
    end
    if not enemies or #enemies == 0 then return end

    local bestPoint, bestDist, bestAngle, bestEnemy = nil, nil, fovDeg, nil
    for i = 1, #enemies do
        local e = enemies[i]
        local actor = e and (e.actor or e)
        if actor and slua.isValid(actor) and actor ~= player then
            local bot = false
            if e.isBot ~= nil then bot = e.isBot
            else
                if actor.bIsAI == true or actor.IsAI == true then bot = true end
            end
            -- [SDWxOWNER-KILL-CRASH FIX] NEVER target a dead enemy. A pawn that just died
            -- (hs == 2 / bIsDead) has its skeletal mesh torn down by the engine; reading its
            -- bone/socket (GetSocketLocation) on the next tick is a native use-after-free ->
            -- the crash right at the kill moment (ALL weapons, even with skins OFF). This
            -- check is UNCONDITIONAL (not gated by ignoreKnock) so a corpse is never aimed at.
            local hsNow = actor.HealthStatus
            local isDead = (hsNow == 2) or (hsNow == 3) or (actor.bIsDead == true) or (actor.bDead == true)
                or (type(actor.Health) == "number" and actor.Health <= 0)
            local isKnocked = false
            if ignoreKnock then
                if e.knocked ~= nil then isKnocked = e.knocked
                else
                    -- [SDWxOWNER-FIX] hs == 1 = knocked/downed, hs == 2 = dead.
                    isKnocked = (hsNow == 1) or (actor.bIsGroggy == true) or (actor.bIsGrogggy == true) or (actor.bIsDying == true)
                end
            end
            if (targetBots or not bot) and not isKnocked and not isDead then
                local dist = e.distance
                if not dist then
                    _aimDistPlayer = player; _aimDistActor = actor; _aimDistVal = nil
                    pcall(_aimDistProbe)
                    dist = _aimDistVal
                end
                if dist and dist <= maxDistCm then
                    local skip = false
                    if visOnly then
                        -- [SDWxOWNER-PERF] Per-enemy LOS cache (~0.1s).
                        local _nowL = os.clock()
                        local ok
                        if actor._sdwAimLOS ~= nil and (_nowL - (actor._sdwAimLOST or 0)) < 0.1 then
                            ok = actor._sdwAimLOS
                        else
                            ok = true
                            _aimLOSPC = pc; _aimLOSActor = actor; _aimLOSOK = true
                            pcall(_aimLOSProbe)
                            ok = _aimLOSOK
                            actor._sdwAimLOS = ok
                            actor._sdwAimLOST = _nowL
                        end
                        if not ok then skip = true end
                    end
                    if not skip then
                        -- [SDWxOWNER-KILL-CRASH FIX] Re-check liveness IMMEDIATELY before the
                        -- mesh read: the enemy can die between the top-of-loop check and here,
                        -- and reading a dying mesh's socket is the native crash.
                        local hsChk = actor.HealthStatus
                        if hsChk == 2 or hsChk == 3 or actor.bIsDead == true or actor.bDead == true then skip = true end
                    end
                    if not skip then
                        -- [SDWxOWNER-AIM-FPS] CHEAP ANGLE PRE-FILTER. Reading the bone
                        -- (GetBoneLocation/GetSocketLocation) is the most expensive per-enemy
                        -- native call in the aim scan, and the old code did it for EVERY enemy
                        -- in range on EVERY 50 Hz tick (10 enemies -> ~500 bone reads/sec, right
                        -- when a rush is at 20-30 fps). We first compute the angle to the cheap
                        -- actor ORIGIN; if that is already > FOV + 25 deg it can never beat the
                        -- current best, so we skip the bone read entirely. The 25 deg margin
                        -- guarantees the true bone angle (bone is within ~1 m of origin) is still
                        -- inside the filter, so the chosen target is IDENTICAL to before.
                        local base = nil
                        _aimBaseActor = actor; _aimBase = nil
                        pcall(_aimBaseProbe)
                        base = _aimBase
                        local preOK = true
                        if base then
                            _aimPreTarget.X = base.X; _aimPreTarget.Y = base.Y; _aimPreTarget.Z = base.Z + zOff
                            _aimKM = KismetMath; _aimFromLoc = camLoc; _aimToPoint = _aimPreTarget; _aimTRot = nil
                            pcall(_aimRotProbe)
                            local pRot = _aimTRot
                            if pRot then
                                local pY = ((pRot.Yaw - curRot.Yaw + 180) % 360) - 180
                                local pP = ((pRot.Pitch - curRot.Pitch + 180) % 360) - 180
                                if math.sqrt(pY * pY + pP * pP) > (bestAngle + 25) then preOK = false end
                            end
                        end
                        if preOK then
                        local point = nil
                        -- [SDWxOWNER-KNOCK-CRASH FIX] PRIMARY. The instant an enemy is KNOCKED
                        -- (HealthStatus 0 -> 1) the engine swaps the character to the groggy /
                        -- downed mesh and detaches the weapon. Reading actor.Mesh or calling
                        -- GetSocketLocation on that mesh during the swap is a native
                        -- use-after-free -> the hard crash that fires exactly when you knock a
                        -- player. The enemy-scan list is cached for 0.1 s, so e.knocked can STILL
                        -- read "false" on the knock frame even though the pawn is already down.
                        -- We therefore re-read the fresh knock state here (HealthStatus on this
                        -- exact tick) and, when the pawn is knocked / groggy / dying, SKIP the
                        -- mesh read entirely and aim at the cheap actor ORIGIN (base) instead.
                        -- Aimbot still targets knocked enemies when Ignore-Knock is OFF - it just
                        -- never touches the mesh that is being torn down.
                        local _hsNow2 = actor.HealthStatus
                        local _knockNow = (_hsNow2 == 1) or (actor.bIsGroggy == true)
                            or (actor.bIsGrogggy == true) or (actor.bIsKnocked == true)
                            or (actor.bIsDying == true)
                        local mesh = nil
                        if not _knockNow then
                            mesh = actor.Mesh
                            if mesh and slua.isValid(mesh) then
                                _aimMesh = mesh; _aimBoneName = boneName; _aimPoint = nil
                                pcall(_aimSocketProbe)
                                point = _aimPoint
                            end
                        end
                        if not point or (point.X == 0 and point.Y == 0 and point.Z == 0) then
                            if base then point = { X = base.X, Y = base.Y, Z = base.Z + zOff } end
                        end
                        if point then
                            local tRot = nil
                            _aimKM = KismetMath; _aimFromLoc = camLoc; _aimToPoint = point; _aimTRot = nil
                            pcall(_aimRotProbe)
                            tRot = _aimTRot
                            if tRot then
                                local dY = ((tRot.Yaw - curRot.Yaw + 180) % 360) - 180
                                local dP = ((tRot.Pitch - curRot.Pitch + 180) % 360) - 180
                                local ang = math.sqrt(dY * dY + dP * dP)
                                -- [SDWxOWNER-AIMLOCK] A locked target always wins, even if a
                                -- different enemy is momentarily closer to the crosshair.
                                if lockActor and actor == lockActor then
                                    bestAngle = ang
                                    bestPoint, bestDist, bestEnemy = point, dist, actor
                                elseif ang <= bestAngle then
                                    bestAngle = ang
                                    bestPoint, bestDist, bestEnemy = point, dist, actor
                                end
                            end
                        end
                        end
                    end
                end
            end
        end
    end
    if not bestPoint then return end
    -- [SDWxOWNER-AIMLOCK] Remember the chosen pawn so the next tick of this burst keeps it.
    if fireLock and bestEnemy then _G._SDW_AimLock = bestEnemy end

    local aimX, aimY, aimZ = bestPoint.X, bestPoint.Y, bestPoint.Z
    -- [SDWxOWNER-AIMPOINT] Velocity lead is OPTIONAL and OFF by default. When it was always on,
    -- the crosshair led AHEAD of a moving enemy -> the bullet landed to the SIDE of the pelvis.
    if (C.SDWAimLead == true) and bestEnemy then
        _aimVelEnemy = bestEnemy; _aimVel = nil
        pcall(_aimVelProbe)
        local vel = _aimVel
        if vel and (math.abs(vel.X or 0) > 30 or math.abs(vel.Y or 0) > 30) then
            local tt = bestDist / 85000
            aimX = aimX + (vel.X or 0) * tt
            aimY = aimY + (vel.Y or 0) * tt
            aimZ = aimZ + (vel.Z or 0) * tt
        end
    end
    -- [SDWxOWNER-AIMPOINT] Bullet-drop / recoil compensation is now ON by default so the
    -- aim lands a touch LOWER (on the pelvis), matching eg.lua. The velocity lead above
    -- stays OFF, so the bullet never drifts to the side/right.
    local recoilSet = tonumber(C.SDWAimRecoil) or 1.1
    if (C.SDWAimDrop ~= false) and recoilSet > 0 and firing then
        aimZ = aimZ - ((bestDist / 100.0) * recoilSet)
    end

    _aimWPC = pc; _aimWPlayer = player; _aimWCamLoc = camLoc; _aimWCurRot = curRot
    _aimWKismet = KismetMath; _aimWC = C; _aimWX = aimX; _aimWY = aimY; _aimWZ = aimZ
    pcall(_aimWriteProbe)
end


-- [SDWxOWNER-PERF] Hoisted so the aim chain allocates no closure per tick.
local function _SDW_AimRun()
    if _G.SDW_CleanAimbotTick then _G.SDW_CleanAimbotTick() end
end

-- [SDWxOWNER-AIMCHAIN FIX] SINGLE-CHAIN TOKEN GUARD for the aim chain (mirrors the SNAP
-- snapline driver + the V3 counter driver, which already carry this guard). The aim tick used
-- to be startable from THREE independent places -- the load-time self-arm, the login kick
-- (0.6 s + 1.8 s) and the MainLoop keepalive -- and SDW_AimTick re-armed itself with NO token
-- check. Every extra starter therefore spawned a SECOND live chain, so the aim ran at N x 50 Hz
-- and the Aim Speed slider felt N x stronger (slider 10 behaved like 1.lua's 20). A chain token
-- makes any already-scheduled tick a no-op the instant the token is bumped, so EXACTLY ONE
-- chain can ever be live -- the slider is now predictable/safe, byte-for-byte like 1.lua's
-- single chain.
_G.SDW_Aim = _G.SDW_Aim or {}
local AIM = _G.SDW_Aim
AIM.chain = AIM.chain or 0
AIM.running = AIM.running or false

local function SDW_StopAim()
    -- Bump the token so any already-scheduled tick dies on its next beat and cannot
    -- resurrect a second chain.
    AIM.running = false
    AIM.chain = (AIM.chain or 0) + 1
end
_G.SDW_StopAim = SDW_StopAim

local function SDW_AimTick()
    if _G._SDW_AimAlive == false then return end
    -- Chain-token guard: a tick belonging to a superseded chain is a no-op.
    if not AIM.running then return end
    local myChain = AIM.chain
    -- [SDWxOWNER-FULLMATCH FIX] Heartbeat so the MainLoop keepalive can re-arm this self-arming chain if silent.
    _G._SDW_AimLastTick = os.clock()
    -- [SDWxOWNER-SMOOTH] Idle throttle (ZERO feature/limit change): run the full 50 Hz aim
    -- scan ONLY while the aimbot is authorised AND switched on. When it is off (or the key is
    -- locked/expired) the chain idles at 5 Hz (0.2 s) instead of 50 Hz, removing ~90% of the
    -- idle CPU this chain used to burn for the WHOLE match. The chain stays alive and
    -- self-arming, so the instant the toggle is switched on it resumes the full 0.02 s rate
    -- within one poll (<=0.2 s) - the aimbot behaves exactly as before, just with a quiet idle.
    -- (The MainLoop keepalive also re-arms it, so it can never go permanently silent.)
    local _auth = _G.SDW_IsAuthorized and _G.SDW_IsAuthorized()
    local _C = _G.SDWConfig
    local _aimOn = _auth and _C and (_C.SDWAimbot == true or _C.SDWAimbot == 1 or _C.AimbotEnabled == true or _C.AimbotEnabled == 1)
    if _aimOn then pcall(_SDW_AimRun) end
    local ticker = _G.SDW_GetTicker and _G.SDW_GetTicker()
    -- Reschedule on the global ticker (survives owner invalidation). The chain token
    -- guarantees exactly ONE live chain even across a stop/restart.
    if ticker and AIM.running and AIM.chain == myChain then
        ticker.AddTimerOnce(_aimOn and 0.02 or 0.2, SDW_AimTick)
    end
end

-- [SDWxOWNER-AIMCHAIN FIX] Idempotent starter: only ONE chain ever lives. force=true
-- (used by the MainLoop keepalive) restarts a chain that went silent while running==true.
function _G.SDW_EnsureAim(force)
    if _G._SDW_AimAlive == false then return end
    if AIM.running and not force then return end
    AIM.running = true
    AIM.chain = (AIM.chain or 0) + 1
    _G._SDW_AimLastTick = os.clock()
    pcall(SDW_AimTick)
end
_G.SDW_AimTick = SDW_AimTick
pcall(function() _G.SDW_EnsureAim() end)

do
local _pc = slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController()
_G._SDW_MenuLoadToken = (_G._SDW_MenuLoadToken or 0) + 1
local _menuToken = _G._SDW_MenuLoadToken
pcall(function()
    if _G._SDW_FloatBtn and slua.isValid(_G._SDW_FloatBtn) then pcall(function() _G._SDW_FloatBtn:RemoveFromParent() end) end
    if _G._SDW_MenuPanel and slua.isValid(_G._SDW_MenuPanel) then pcall(function() _G._SDW_MenuPanel:RemoveFromParent() end) end
end)
_G._SDW_FloatBtn = nil
_G._SDW_MenuPanel = nil
if _pc then _G._SDW_MENU_PC = _pc end

local CGame        = _G.CGame or import("CGame")
local FLinearColor = import("LinearColor") or import("/Script/CoreUObject.LinearColor")
local FVector2D    = import("Vector2D") or import("/Script/CoreUObject.Vector2D")
local FAnchors     = import("Anchors") or import("/Script/SlateCore.Anchors")
local FSlateColor  = import("SlateColor") or import("/Script/SlateCore.SlateColor")

local function IV(o) return o and slua and slua.isValid and slua.isValid(o) end
local function IsAttached(w)
    if not (w and IV(w)) then return false end
    local hasParent = false
    local ok, parent = pcall(function()
        if w.GetParent then hasParent = true; return w:GetParent() end
        return nil
    end)
    if not ok then return true end
    if not hasParent then return true end
    return parent ~= nil and IV(parent)
end
local function LC(r,g,b,a) if FLinearColor then return FLinearColor(r,g,b,a or 1.0) end return {R=r,G=g,B=b,A=a or 1.0} end
local function V2(x,y) if FVector2D then return FVector2D(x,y) end return {X=x,Y=y} end
local function AN(a,b,c,d) if FAnchors then return FAnchors(a,b,c,d) end return nil end

-- [SDWxOWNER-THEMES] The NEW premium menu themes (taken from the new menu design) come FIRST
-- so the fresh look is the default; ALL the original themes are kept intact right after.
-- Every theme (old + new) is fully selectable from the THEME tab.
local THEMES = {
    { name = "PREMIUM CRIMSON", a = {0.76, 0.012, 0.019} },  -- NEW (default) - new menu design
    { name = "BLOOD RED",       a = {1.00, 0.16, 0.20} },     -- original
    { name = "OCEAN BLUE",      a = {0.20, 0.55, 1.00} },     -- original
    { name = "PURE WHITE",      a = {0.92, 0.92, 0.96} },     -- original
    { name = "GOLD YELLOW",     a = {1.00, 0.82, 0.12} },     -- original
    { name = "NEON GREEN",      a = {0.15, 0.95, 0.35} },     -- NEW
    { name = "VIP PURPLE",      a = {0.68, 0.22, 1.00} },     -- NEW
    { name = "ICE CYAN",        a = {0.10, 0.90, 0.95} },     -- NEW
    { name = "ROYAL MAGENTA",   a = {1.00, 0.10, 0.60} },     -- NEW
    { name = "SUNSET ORANGE",   a = {1.00, 0.45, 0.10} },     -- NEW
}
local themeIdx = tonumber(_G._SDW_ThemeIdx) or 1
if themeIdx < 1 or themeIdx > #THEMES then themeIdx = 1 end

local C = {}
local function ApplyTheme(i)
    local t = THEMES[i] or THEMES[1]
    local ar, ag, ab = t.a[1], t.a[2], t.a[3]
    local function mul(k) return LC(math.min(1, ar*k), math.min(1, ag*k), math.min(1, ab*k), 1) end
    C.accent        = LC(ar, ag, ab, 1)
    C.accent_bright = LC(math.min(1, ar + 0.22), math.min(1, ag + 0.24), math.min(1, ab + 0.24), 1)
    C.accent_dark   = mul(0.60)
    C.accent_deep   = mul(0.30)
    C.glow          = LC(ar, ag, ab, 0.10)
    C.glow_strong   = LC(ar, ag, ab, 0.22)
    -- [SDWxOWNER-NEWMENU] Deep matte-black glass palette (exact newmenu.lua values,
    -- tinted by the theme accent so every theme keeps the deep matte look).
    C.bg_glass      = LC(math.min(0.02, ar*0.0072), math.min(0.02, ag*0.130), math.min(0.02, ab*0.116), 0.96)
    C.bg_glass2     = LC(math.min(0.02, ar*0.0039), math.min(0.02, ag*0.075), math.min(0.02, ab*0.063), 0.97)
    C.bg_glass3     = LC(math.min(0.02, ar*0.0053), math.min(0.02, ag*0.100), math.min(0.02, ab*0.084), 0.95)
    C.bg_glass_hi   = LC(math.min(0.02, ar*0.0112), math.min(0.02, ag*0.250), math.min(0.02, ab*0.210), 0.96)
    C.bg_black      = LC(0.0015, 0.0006, 0.0008, 0.98)
    C.bg_white      = LC(0.0120, 0.0050, 0.0060, 1.0)
    -- Legacy background keys are remapped onto the deep glass palette so the WHOLE
    -- canvas (main / sidebar / header / tabs / rows / footer / close button) is matte black.
    C.bg_main       = C.bg_glass
    C.bg_header     = C.bg_glass3
    C.bg_header2    = C.bg_glass3
    C.bg_header3    = C.bg_glass_hi
    C.bg_sidebar    = C.bg_glass2
    C.bg_row        = LC(0.0010, 0.0003, 0.0004, 0.55)
    C.bg_row_alt    = LC(0.0030, 0.0009, 0.0012, 0.40)
    C.bg_tab        = C.bg_glass3
    C.bg_tab_active = LC(ar, ag, ab, 0.16)
    C.white         = LC(1.00, 1.00, 1.00, 1)
    C.text_dim      = LC(0.58, 0.58, 0.62, 1)
    C.text_label    = LC(0.93, 0.93, 0.95, 1)
    C.off           = LC(0.30, 0.30, 0.33, 1)
    C.off_deep      = LC(0.22, 0.22, 0.25, 1)
    C.off_bright    = LC(0.72, 0.72, 0.76, 1)
    C.divider       = LC(0.16, 0.16, 0.18, 1)
    C.divider_a     = LC(ar*0.40, ag*0.40, ab*0.40, 1)
    C.border_a      = LC(ar*0.72, ag*0.72, ab*0.72, 1)
    C.border_dark   = LC(0.02, 0.02, 0.03, 1)
    C.box_border    = LC(0.12, 0.055, 0.060, 1)
    C.box_fill      = C.bg_white
    C.check         = LC(1.00, 1.00, 1.00, 1)
    C.box_border_on = LC(ar, ag, ab, 1)
    C.close_bg      = C.bg_glass3
    C.transparent   = LC(0, 0, 0, 0.01)
    C.shadow1       = LC(0, 0, 0, 0.80)
    C.shadow2       = LC(0, 0, 0, 0.55)
    C.shadow3       = LC(0, 0, 0, 0.35)
    C.shadow4       = LC(0, 0, 0, 0.18)
    C.shadow5       = LC(0, 0, 0, 0.10)
    -- [SDWxOWNER-NEWMENU] Extra "premium glass" keys used by the new menu styling
    -- (glass highlight, neon halo, glossy borders, corner brackets, streaks).
    C.accent_glow   = LC(ar, ag, ab, 0.13)
    C.accent_neon   = LC(math.min(1, ar + 0.24), math.min(1, ag + 0.14), math.min(1, ab + 0.18), 0.42)
    C.accent_soft   = LC(ar, ag, ab, 0.30)
    C.glass_hi      = C.bg_glass_hi
    C.border_glass  = LC(math.min(1, ar * 0.90 + 0.09), math.min(1, ag * 0.90 + 0.02), math.min(1, ab * 0.90 + 0.02), 0.85)
    C.border_blue   = LC(math.min(1, ar * 0.85 + 0.04), math.min(1, ag * 0.85 + 0.02), math.min(1, ab * 0.85 + 0.02), 0.92)
    C.corner        = LC(math.min(1, ar + 0.24), math.min(1, ag + 0.06), math.min(1, ab + 0.06), 1)
    C.streak        = LC(math.min(1, ar * 0.5 + 0.5), math.min(1, ag * 0.5 + 0.5), math.min(1, ab * 0.5 + 0.5), 0.05)
    C.streak2       = LC(math.min(1, ar * 0.5 + 0.5), math.min(1, ag * 0.5 + 0.5), math.min(1, ab * 0.5 + 0.5), 0.09)
    C.glass_top     = LC(math.min(1, ar * 0.4 + 0.6), math.min(1, ag * 0.4 + 0.6), math.min(1, ab * 0.4 + 0.6), 0.30)
end
ApplyTheme(themeIdx)

local function D()
    pcall(function()
        _G._ConfigDirty = true
        if _G.SaveModSettings then _G.SaveModSettings(true) end
    end)
    return true
end
local function StartVisuals() if _G.StartVisuals then pcall(_G.StartVisuals) end end
local function InvalidateColors()
    pcall(function()
        if _G.SDWState and _G.SDWState.EnemyMarks then
            for _, d in pairs(_G.SDWState.EnemyMarks) do if d then d.LastColorNewHash = "" end end
        end
    end)
end
local function Cfg() return _G.SDWConfig end
local function Get(k, d) local c = _G.SDWConfig; if c and c[k] ~= nil then return c[k] end return d end
local function Set(k, v) local c = _G.SDWConfig; if c then c[k] = v end; D() end
local function CData() local s = _G.SDWState; if s then s.CustomTextData = s.CustomTextData or {} return s.CustomTextData end return {} end

local function SkinSet(cfgKey, dataKey, mapTable, mapId, maxV, mapId2)
    return function(v)
        v = math.floor((tonumber(v) or 1) + 0.5)
        if v < 1 then v = 1 end
        if maxV and v > maxV then v = maxV end
        local cd = CData(); cd[dataKey] = v
        local maps = _G[mapTable]
        if maps and maps[mapId] and maps[mapId][v] then
            local target = maps[mapId][v]
            if mapTable == "OutfitSkins" then _G.OutfitMap[mapId] = target
            elseif mapTable == "skinIdMappings" then _G.WeaponSkinMap[mapId] = target
            elseif mapTable == "VehicleSkins" then
                _G.VehicleSkinMap[mapId] = target
                if mapId2 then _G.VehicleSkinMap[mapId2] = target end
            end
        end
        D()
    end
end


local colOpts = { "Red", "Cyan", "Yellow", "Green", "Purple", "White" }
local colVals = { 0, 1, 2, 3, 4, 5 }
-- [SDWxOWNER] Enemy Counter text colour list: Yellow default, White removed.
local counterColOpts = { "Red", "Cyan", "Yellow", "Green", "Purple" }
local counterColVals = { 0, 1, 2, 3, 4 }


local function TOG(label, get, set) return { kind = "toggle", label = label, get = get, set = set } end
local function SLD(label, get, set, mn, mx, step, display) return { kind = "slider", label = label, get = get, set = set, min = mn, max = mx, step = step or 1, display = display } end
local function CHC(label, get, set, opts, vals) return { kind = "choice", label = label, get = get, set = set, opts = opts, vals = vals } end

