                elseif _G.SDWState and _G.SDWState.EnemyMarks and _G.UndoColorBodyNew then
                    for _, d in pairs(_G.SDWState.EnemyMarks) do if d and d.enemy then pcall(_G.UndoColorBodyNew, d.enemy, d) end end
                end
            else StartVisuals() end
