local RefreshRow, RebuildMenu, BuildMenu

local function MakeBtn(parent, x, y, w, h, z, onClick)
    local btn = nil
    pcall(function()
        btn = CGame:NewObjectFromPath("/Script/UMG.Button", parent)
        if btn and slua.isValid(btn) then
            pcall(function() btn:SetColorAndOpacity(C.transparent) end)
            pcall(function() btn:SetBackgroundColor(C.transparent) end)
            pcall(function() btn:SetWidgetVisibility(UEnums.ESlateVisibility.Visible) end)
            local slot = parent:AddChildToCanvas(btn)
            if slot then slot:SetAutoSize(false); slot:SetPosition(V2(x, y)); slot:SetSize(V2(w, h)); slot:SetZOrder(z or 900) end
            if onClick then
                pcall(function() if btn.OnClicked then btn.OnClicked:Add(function() pcall(onClick) end) end end)
            end
        end
    end)
    return btn
end

local function Layer(parent, x, y, w, h, color, z)
    local b, slot = nil, nil
    pcall(function()
        b = CGame:NewObjectFromPath("/Script/UMG.Border", parent)
        if b and slua.isValid(b) then
            b:SetBrushColor(color)
            b:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
            slot = parent:AddChildToCanvas(b)
            if slot then slot:SetAutoSize(false); slot:SetPosition(V2(x, y)); slot:SetSize(V2(w, h)); slot:SetZOrder(z or 0) end
        end
    end)
    return b, slot
end

local function Text(parent, txt, x, y, size, color, z, ax, ay)
    local t = nil
    pcall(function()
        t = CGame:NewObjectFromPath("/Script/UMG.TextBlock", parent)
        if t and slua.isValid(t) then
            t:SetText(txt)
            if FSlateColor then t:SetColorAndOpacity(FSlateColor(color)) else t:SetColorAndOpacity(color) end
            if t.Font then local f = t.Font f.Size = size t.Font = f end
            t:SetRenderTransformPivot(V2(ax or 0.5, ay or 0.5))
            t:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
            local slot = parent:AddChildToCanvas(t)
            if slot then slot:SetAutoSize(true); slot:SetAlignment(V2(ax or 0.5, ay or 0.5)); slot:SetPosition(V2(x, y)); slot:SetZOrder(z or 100) end
        end
    end)
    return t
end

local function SetVis(w, vis) if w and IV(w) then pcall(function() w:SetWidgetVisibility(vis) end) end end
local function SetText(w, s) if w and IV(w) then pcall(function() w:SetText(s) end) end end
local function SetColor(w, c)
    if w and IV(w) then
        pcall(function() if FSlateColor then w:SetColorAndOpacity(FSlateColor(c)) else w:SetColorAndOpacity(c) end end)
    end
end

local cachedCanvas = nil
local _cached_InGameUITools = nil
local function GetCanvas(liveOnly)
    local live = nil
    pcall(function()
        local InGameUITools = _cached_InGameUITools
        if not InGameUITools then local ok; ok, InGameUITools = pcall(require, "GameLua.Mod.BaseMod.Common.UI.InGameUITools"); if ok then _cached_InGameUITools = InGameUITools end end
        if not InGameUITools then return end
        local MainUI = InGameUITools.GetMainControlBaseUI()
        if not MainUI or not Game:IsValid(MainUI) then return end
        if MainUI.CanvasPanel_0 and Game:IsValid(MainUI.CanvasPanel_0) then live = MainUI.CanvasPanel_0
        elseif MainUI.CanvasPanel_42 and Game:IsValid(MainUI.CanvasPanel_42) then live = MainUI.CanvasPanel_42 end
    end)
    if live then cachedCanvas = live; return live end
    -- [SDWxOWNER-CRASH-FIX] Only USE an already-existing SnaplineESP canvas.
    pcall(function()
        if _G.SnaplineESP and _G.SnaplineESP.ESPCanvas and IV(_G.SnaplineESP.ESPCanvas) then
            live = _G.SnaplineESP.ESPCanvas
        end
    end)
    if live then cachedCanvas = live; return live end
    -- [SDWxOWNER-MINIMAP-FIX] `_G.PlayerMapMarker` is no longer referenced anywhere in this script.
    if live then cachedCanvas = live; return live end
    if liveOnly then return nil end
    if cachedCanvas and IV(cachedCanvas) then return cachedCanvas end
    cachedCanvas = nil
    return cachedCanvas
end

local function CountActive()
    local n = 0
    for _, tab in ipairs(TABS) do
        for _, r in ipairs(tab.rows) do
            if r.kind == "toggle" then
                local ok, v = pcall(r.get)
                if ok and v then n = n + 1 end
            end
        end
    end
    return n
end

local function ValidityText()
    local ts = tonumber(_G.KEY_EXPIRY)
    if (not ts or ts <= 0) and _G.SDW_NormalizeExpiry then
        ts = _G.SDW_NormalizeExpiry(_G.KEY_EXPIRY, os.time())
    end
    if not ts or ts <= 0 then
        if _G.USER_KEY then return "KEY ACTIVE" end
        return "NO KEY"
    end
    local rem = ts - os.time()
    if rem <= 0 then return "EXPIRED" end
    local d = math.floor(rem / 86400); rem = rem - d * 86400
    local h = math.floor(rem / 3600);  rem = rem - h * 3600
    local m = math.floor(rem / 60)
    return string.format("%dd %dh %dm", d, h, m)
end

-- [SDWxOWNER] Human-readable key EXPIRY DATE (shown directly under the key name in the THEME tab).
local function ExpiryDateText()
    local ts = tonumber(_G.KEY_EXPIRY)
    if (not ts or ts <= 0) and _G.SDW_NormalizeExpiry then
        ts = _G.SDW_NormalizeExpiry(_G.KEY_EXPIRY, os.time())
    end
    if not ts or ts <= 0 then
        if _G.USER_KEY then return "LIFETIME (no expiry)" end
        return "--"
    end
    local ok, s = pcall(os.date, "%d %b %Y  %H:%M", ts)
    if ok and s and s ~= "" then return s end
    return "--"
end

-- [SDWxOWNER] Live handle to the THEME card's EXPIRES text so it refreshes after login.
local themeExpiryText = nil

local function RefreshStatus()
    if activeText and IV(activeText) then SetText(activeText, "ACTIVE: " .. CountActive()) end
    if statusText and IV(statusText) then SetText(statusText, "VALID: " .. ValidityText()) end
    if themeExpiryText and IV(themeExpiryText) then SetText(themeExpiryText, "EXPIRES:  " .. ExpiryDateText()) end
end

local function BuildToggleRow(parent, spec, x, y, w, h, zebra)
    local state = false
    pcall(function() state = spec.get() end)
    local row = { spec = spec, kind = "toggle" }

    row.rowGlow = Layer(parent, x, y, w, h, C.glow, 199)
    if not state then SetVis(row.rowGlow, UEnums.ESlateVisibility.Collapsed) end
    Layer(parent, x, y, w, h, zebra and C.bg_row_alt or C.bg_row, 200)
    Layer(parent, x, y, 4, h, C.accent_deep, 201)
    row.accent = Layer(parent, x + 1, y + 2, 2, h - 4, state and C.accent or C.off_deep, 202)
    Layer(parent, x + 4, y, w - 4, 1, LC(0.12, 0.11, 0.14, 0.5), 201)
    Layer(parent, x, y + h, w, 1, C.divider, 203)
    row.label = Text(parent, spec.label, x + 18, y + h * 0.5, 15, state and C.white or C.text_label, 300, 0, 0.5)

    local bs = 24
    local bx = x + w - bs - 18
    local by = y + h * 0.5 - bs * 0.5
    row.boxBorder = Layer(parent, bx - 2, by - 2, bs + 4, bs + 4, state and C.box_border_on or C.box_border, 299)
    -- [SDWxOWNER-COUNTER] Store the checkbox fill so its colour can be re-synced live
    -- (rowData.boxFill equivalent): crimson when ON, deep matte black when OFF.
    row.boxFill = Layer(parent, bx, by, bs, bs, state and C.accent or C.box_fill, 300)
    row.check = Text(parent, "\u{2713}", bx + bs * 0.5, by + bs * 0.5, 20, C.check, 303, 0.5, 0.5)
    if not state then SetVis(row.check, UEnums.ESlateVisibility.Collapsed) end

    MakeBtn(parent, x, y, w, h, 900, function()
        local cur = false
        pcall(function() cur = spec.get() end)
        pcall(spec.set, not cur)
        RefreshRow(row)
        RefreshStatus()
    end)
    return row
end

function RefreshRow(row)
    if not row or not row.spec then return end
    local state = false
    pcall(function() state = row.spec.get() end)
    if row.accent and IV(row.accent) then pcall(function() row.accent:SetBrushColor(state and C.accent or C.off_deep) end) end
    if row.boxBorder and IV(row.boxBorder) then pcall(function() row.boxBorder:SetBrushColor(state and C.box_border_on or C.box_border) end) end
    -- [SDWxOWNER-COUNTER] Live checkbox fill (rowData.boxFill equivalent).
    if row.boxFill and IV(row.boxFill) then pcall(function() row.boxFill:SetBrushColor(state and C.accent or C.box_fill) end) end
    if row.label and IV(row.label) then SetColor(row.label, state and C.white or C.text_label) end
    SetVis(row.check, state and UEnums.ESlateVisibility.SelfHitTestInvisible or UEnums.ESlateVisibility.Collapsed)
    SetVis(row.rowGlow, state and UEnums.ESlateVisibility.SelfHitTestInvisible or UEnums.ESlateVisibility.Collapsed)
end

-- [SDWxOWNER-COUNTER] Refresh BOTH enemy-counter checkboxes at once so toggling one
-- counter instantly updates the other row's visual state (mutual-exclusivity UI).
-- Both rows are ALWAYS present in the grid (never collapsed) - only their check state
-- (row.check / row.boxFill / row.boxBorder) is re-synced here.
SDW_SyncCounterRows = function()
    for _, row in ipairs(toggleRows) do
        if row and row.spec and row.spec.label then
            local lbl = row.spec.label
            if lbl == "Enemy Counter V2" or lbl == "Enemy Counter Text Only (Best)" or lbl == "Enemy Counter For iOS" or lbl == "v4 enemy counter" or lbl == "v5 enemy counter" then
                pcall(RefreshRow, row)
            end
        end
    end
end

-- [SDWxOWNER-SLIDER] Shared draggable slider track.  It is drawn BELOW the +/- (or </>)
-- buttons of a row (requested: "uske niche ek slider bhi lgao").  `getFrac` returns the
-- current 0..1 position and `applyFrac(frac)` commits a new value/index.  The drag itself
-- is driven by the ~60 Hz pointer loop further down (_SliderDragStep) so it stays smooth
-- and never blocks the menu.
local function BuildRowSlider(parent, row, x, y, w, getFrac, applyFrac)
    local tx0 = x + 18
    local tx1 = x + w - 18
    local tw  = math.max(1, tx1 - tx0)
    local tcy = y + 46
    local th  = 7
    -- dark rail + subtle top hairline
    Layer(parent, tx0, tcy - th * 0.5, tw, th, LC(0.10, 0.09, 0.12, 0.95), 297)
    Layer(parent, tx0, tcy - th * 0.5, tw, 1, C.divider_a, 298)
    -- filled portion (left edge -> handle)
    local _, fillSlot = Layer(parent, tx0, tcy - th * 0.5, 1, th, C.accent, 299)
    -- handle + glossy top edge
    local hw, hh = 14, 16
    local _, handleSlot = Layer(parent, tx0 - hw * 0.5, tcy - hh * 0.5, hw, hh, C.accent_bright, 301)
    Layer(parent, tx0 - hw * 0.5 + 2, tcy - hh * 0.5 + 2, hw - 4, 2, C.white, 302)
    -- transparent, hit-testable strip over the whole track: it consumes the touch so a
    -- slider drag can never also rotate the game camera (the pointer loop reads the raw
    -- touch state independently, so dragging still works).
    MakeBtn(parent, tx0 - 8, tcy - 8, tw + 16, 18, 998, nil)

    local function paint()
        local frac = getFrac()
        if frac ~= frac then frac = 0 end            -- NaN guard
        if frac < 0 then frac = 0 elseif frac > 1 then frac = 1 end
        local hx = tx0 + frac * tw
        pcall(function() if fillSlot then fillSlot:SetSize(V2(math.max(1, hx - tx0), th)) end end)
        pcall(function() if handleSlot then handleSlot:SetPosition(V2(hx - hw * 0.5, tcy - hh * 0.5)) end end)
    end
    row.track = { x0 = tx0, x1 = tx1, y = tcy, hh = hh, tw = tw }
    row.paintSlider = paint
    row.applyFrac = applyFrac
    paint()
    return row
end

local function BuildSliderRow(parent, spec, x, y, w, h, zebra)
    local row = { spec = spec, kind = "slider" }
    Layer(parent, x, y, w, h, zebra and C.bg_row_alt or C.bg_row, 200)
    Layer(parent, x, y, 4, h, C.accent_deep, 201)
    Layer(parent, x + 1, y + 2, 2, h - 4, C.accent_dark, 202)
    Layer(parent, x + 4, y, w - 4, 1, LC(0.12, 0.11, 0.14, 0.5), 201)
    Layer(parent, x, y + h, w, 1, C.divider, 203)

    local topCY = y + 18
    Text(parent, spec.label, x + 18, topCY, 14, C.text_label, 300, 0, 0.5)

    -- [SDWxOWNER] valStr supports an optional per-row `display` formatter so a slider can
    -- render a friendly label (e.g. "4 Head") instead of a bare number.
    local function valStr(v)
        if v == nil then local ok, g = pcall(spec.get); v = ok and g or spec.min end
        v = tonumber(v) or spec.min
        if spec.display then
            local ok2, s = pcall(spec.display, v)
            if ok2 and s ~= nil then return tostring(s) end
        end
        return tostring(math.floor(v + 0.5))
    end
    row.valStr = valStr
    row.valText = Text(parent, valStr(), x + w - 134, topCY, 14, C.accent_bright, 300, 1, 0.5)

    local bw, bh = 32, 32
    local by = topCY - bh * 0.5
    local mx = x + w - 86
    local px = x + w - 42

    local function clampVal(v)
        v = tonumber(v) or spec.min
        if v < spec.min then v = spec.min elseif v > spec.max then v = spec.max end
        return v
    end
    local function applyVal(v, snap)
        v = clampVal(v)
        if snap then
            local st = tonumber(spec.step) or 1
            if st > 0 then v = spec.min + math.floor((v - spec.min) / st + 0.5) * st end
            v = clampVal(v)
        end
        pcall(spec.set, v)
        SetText(row.valText, valStr(v))
        if row.paintSlider then row.paintSlider() end
    end
    row.applyVal = applyVal

    local function step(dir)
        local ok, cur = pcall(spec.get); if not ok then cur = spec.min end
        cur = tonumber(cur) or spec.min
        local nv = cur + dir * (tonumber(spec.step) or 1)
        if nv > spec.max then nv = spec.min end
        if nv < spec.min then nv = spec.max end
        applyVal(nv, false)
        RefreshStatus()
    end

    Layer(parent, mx - 1, by - 1, bw + 2, bh + 2, C.accent_deep, 298)
    Layer(parent, mx, by, bw, bh, C.bg_tab, 299)
    Text(parent, "-", mx + bw * 0.5, by + bh * 0.5, 22, C.off_bright, 400, 0.5, 0.5)
    MakeBtn(parent, mx - 3, by - 3, bw + 6, bh + 6, 999, function() step(-1) end)

    Layer(parent, px - 1, by - 1, bw + 2, bh + 2, C.accent_deep, 298)
    Layer(parent, px, by, bw, bh, C.bg_tab, 299)
    Text(parent, "+", px + bw * 0.5, by + bh * 0.5, 22, C.accent_bright, 400, 0.5, 0.5)
    MakeBtn(parent, px - 3, by - 3, bw + 6, bh + 6, 999, function() step(1) end)

    -- [SDWxOWNER-NOSLIDER] The draggable slider track below the +/- buttons was REMOVED
    -- on request ("slider remove kro, pehle ki trah +/- hi sahi tha").  Only the +/-
    -- steppers remain, so a value can never be changed by accident while panning the menu.
    return row
end

local function BuildChoiceRow(parent, spec, x, y, w, h, zebra)
    local row = { spec = spec, kind = "choice" }
    Layer(parent, x, y, w, h, zebra and C.bg_row_alt or C.bg_row, 200)
    Layer(parent, x, y, 4, h, C.accent_deep, 201)
    Layer(parent, x + 1, y + 2, 2, h - 4, C.accent_dark, 202)
    Layer(parent, x + 4, y, w - 4, 1, LC(0.12, 0.11, 0.14, 0.5), 201)
    Layer(parent, x, y + h, w, 1, C.divider, 203)

    local topCY = y + 18
    Text(parent, spec.label, x + 18, topCY, 14, C.text_label, 300, 0, 0.5)

    local n = #spec.opts
    local vals = spec.vals
    local function curIdx()
        local ok, v = pcall(spec.get); if not ok then v = nil end
        if vals then
            for i = 1, n do if vals[i] == v then return i end end
            return 1
        end
        v = tonumber(v) or 1
        if v < 1 then v = 1 end
        if v > n then v = n end
        return v
    end
    local function curName() return spec.opts[curIdx()] end
    row.valText = Text(parent, curName(), x + w - 134, topCY, 14, C.accent_bright, 300, 1, 0.5)

    local bw, bh = 32, 32
    local by = topCY - bh * 0.5
    local mx = x + w - 86
    local px = x + w - 42

    local function applyIdx(ci)
        if ci < 1 then ci = 1 elseif ci > n then ci = n end
        pcall(spec.set, vals and vals[ci] or ci)
        SetText(row.valText, spec.opts[ci])
        if row.paintSlider then row.paintSlider() end
    end
    row.applyIdx = applyIdx

    local function step(dir)
        local ci = curIdx() + dir
        if ci < 1 then ci = n end
        if ci > n then ci = 1 end
        applyIdx(ci)
    end

    Layer(parent, mx - 1, by - 1, bw + 2, bh + 2, C.accent_deep, 298)
    Layer(parent, mx, by, bw, bh, C.bg_tab, 299)
    Text(parent, "<", mx + bw * 0.5, by + bh * 0.5, 20, C.off_bright, 400, 0.5, 0.5)
    MakeBtn(parent, mx - 3, by - 3, bw + 6, bh + 6, 999, function() step(-1) end)

    Layer(parent, px - 1, by - 1, bw + 2, bh + 2, C.accent_deep, 298)
    Layer(parent, px, by, bw, bh, C.bg_tab, 299)
    Text(parent, ">", px + bw * 0.5, by + bh * 0.5, 20, C.accent_bright, 400, 0.5, 0.5)
    MakeBtn(parent, px - 3, by - 3, bw + 6, bh + 6, 999, function() step(1) end)

    -- [SDWxOWNER-NOSLIDER] Draggable slider track REMOVED on request; only the </> steppers
    -- remain (see BuildSliderRow).  The row still reports its value via row.valText.
    return row
end

-- =====================================================================
-- [SDWxOWNER-SLIDER] Pointer-driven slider drag (smooth, ~60 Hz).
-- =====================================================================
-- Screen -> menu-local mapping uses the menu panel's OWN cached geometry
-- (SlateBlueprintLibrary.AbsoluteToLocal), independent of the ESP canvas transform,
-- so the handle tracks the finger exactly.
local function _MenuLocalFromScreen(sx, sy)
    if not (bgPanel and IV(bgPanel)) then return nil end
    local SBL = _G._SDW_SBL
    if not SBL then
        pcall(function() SBL = import("SlateBlueprintLibrary") or import("/Script/UMG.SlateBlueprintLibrary") end)
        _G._SDW_SBL = SBL
    end
    if not (SBL and SBL.AbsoluteToLocal) then return nil end
    local FV2 = _G._SDW_FV2
    if not FV2 then
        pcall(function() FV2 = import("Vector2D") or import("/Script/CoreUObject.Vector2D") end)
        _G._SDW_FV2 = FV2
    end
    local out = nil
    pcall(function()
        local cg = bgPanel:GetCachedGeometry()
        if not cg then return end
        if not _G._SDW_SldSP then _G._SDW_SldSP = (FV2 and FV2(0, 0)) or { X = 0, Y = 0 } end
        local sp = _G._SDW_SldSP
        sp.X = sx; sp.Y = sy
        out = SBL.AbsoluteToLocal(cg, sp)
    end)
    if not out then return nil end
    return out.X, out.Y
end

-- Returns true if (tx,ty) lands on a slider track; starts a drag bound to `idx`
-- (touch index, or -1 for the mouse).  Vertical band is kept strictly BELOW the +/-
-- hit area (which ends ~y+37) and inside the row, so a button tap is never a drag.
local function _SliderTryHit(tx, ty, idx)
    if not (tx and ty) then return false end
    if tx == 0 and ty == 0 then return false end
    local mx, my = _MenuLocalFromScreen(tx, ty)
    if not mx then return false end
    for _, row in ipairs(toggleRows) do
        local t = row.track
        if t and row.applyFrac and (row.kind == "slider" or row.kind == "choice") then
            if mx >= t.x0 - 8 and mx <= t.x1 + 8 and my >= t.y - 8 and my <= t.y + 10 then
                _G._SDW_SliderDrag = { row = row, idx = idx }
                pcall(row.applyFrac, (mx - t.x0) / math.max(1, t.tw))
                return true
            end
        end
    end
    return false
end

local function _SliderDragStep()
    if not menuOpen then _G._SDW_SliderDrag = nil; return end
    if not (bgPanel and IV(bgPanel)) then return end
    local PC = _G.SDW_GetPC and _G.SDW_GetPC()
    if not PC then return end

    local drag = _G._SDW_SliderDrag
    if drag then
        -- continue the ACTIVE drag from its own finger (multi-touch safe: the movement
        -- thumb on the joystick can never steal the slider).
        local tx, ty, bp = nil, nil, false
        if drag.idx == -1 then
            pcall(function() tx, ty, bp = LoginUI.GetPointer() end)
        else
            pcall(function() tx, ty, bp = PC:GetInputTouchState(drag.idx, 0.0, 0.0, false) end)
        end
        if tx and bp == true then
            local mx = _MenuLocalFromScreen(tx, ty)
            if mx and drag.row and drag.row.track then
                local t = drag.row.track
                pcall(drag.row.applyFrac, (mx - t.x0) / math.max(1, t.tw))
            end
        else
            _G._SDW_SliderDrag = nil
            pcall(RefreshStatus)
        end
        return
    end

    -- no active drag: scan every pressed touch for a fresh grab on a slider track
    if PC.GetInputTouchState then
        for i = 0, 9 do
            local ok, tx, ty, bp = pcall(PC.GetInputTouchState, PC, i, 0.0, 0.0, false)
            if ok and bp == true and _SliderTryHit(tx, ty, i) then return end
        end
    end
    -- mouse fallback (desktop / emulator)
    local mx2, my2, mp = nil, nil, false
    pcall(function() mx2, my2, mp = LoginUI.GetPointer() end)
    if mp == true then _SliderTryHit(mx2, my2, -1) end
end

-- Self-sustaining drag timer.  It stays armed for the life of this module load and
-- early-returns while the menu is closed; it disarms itself only when a NEWER module
-- load supersedes it (new match / reload), so a reopened menu always resumes dragging.
local function _EnsureSliderTimer()
    if _G._SDW_SliderTimer then return end
    local PC = _G.SDW_GetPC and _G.SDW_GetPC()
    if not (PC and PC.AddGameTimer) then return end
    local owner = PC
    local id = nil
    pcall(function()
        id = PC:AddGameTimer(0.016, true, function()
            if _menuToken ~= _G._SDW_MenuLoadToken then
                _G._SDW_SliderDrag = nil
                if _G._SDW_SliderTimer and owner and owner.RemoveGameTimer then
                    pcall(function() owner:RemoveGameTimer(_G._SDW_SliderTimer) end)
                end
                _G._SDW_SliderTimer = nil
                return
            end
            if not menuOpen then _G._SDW_SliderDrag = nil; return end
            pcall(_SliderDragStep)
        end)
    end)
    if id then _G._SDW_SliderTimer = id end
end

local contentRoot = nil

local function BuildContent()
    if contentRoot and IV(contentRoot) then pcall(function() contentRoot:RemoveFromParent() end) end
    contentRoot = nil
    toggleRows = {}
    themeExpiryText = nil
    -- [SDWxOWNER-SLIDER] rows are rebuilt -> drop any in-flight drag + arm the drag timer.
    _G._SDW_SliderDrag = nil
    pcall(_EnsureSliderTimer)

    local tab = TABS[activeTab]
    if not tab then return end

    local canvas = bgPanel
    if not canvas or not IV(canvas) then return end

    local contentX = SIDEBAR_W + 10
    local contentW = M_W - contentX - 10
    local startY = 10
    local contentH = M_H - startY - FOOTER_H - 8

    local panel = nil
    pcall(function()
        panel = CGame:NewObjectFromPath("/Script/UMG.CanvasPanel", canvas)
        if panel and slua.isValid(panel) then
            local slot = canvas:AddChildToCanvas(panel)
            if slot then slot:SetAutoSize(false); slot:SetPosition(V2(contentX, startY)); slot:SetSize(V2(contentW, contentH)); slot:SetZOrder(10) end
        end
    end)
    if not panel or not slua.isValid(panel) then return end
    contentRoot = panel

    local cw = contentW

    Layer(panel, 0, 0, cw, 30, C.bg_header2, 200)
    Layer(panel, 0, 0, cw, 15, C.bg_header3, 200)
    Layer(panel, 0, 0, 4, 30, C.accent, 201)
    Layer(panel, 4, 0, 1, 30, C.accent_bright, 201)
    Text(panel, tab.name .. " SYSTEM", 15, 15, 13, C.accent_neon, 299, 0, 0.5)
    Text(panel, tab.name .. " SYSTEM", 14, 15, 13, C.white, 300, 0, 0.5)
    Layer(panel, 0, 30, cw, 1, C.divider_a, 202)
    Layer(panel, 0, 31, cw, 1, C.accent_glow, 202)

    if tab.name == "THEME" then
        -- [SDWxOWNER-THEMES] Compact 2-column grid so ALL themes (old + new) fit cleanly.
        local ty = 44
        local thRowH = 30
        local colW = math.floor((cw - 6) / 2)
        for i, th in ipairs(THEMES) do
            local col = (i - 1) % 2
            local row = math.floor((i - 1) / 2)
            local rx = col * (colW + 6)
            local ry = ty + row * (thRowH + 4)
            local active = (i == themeIdx)
            Layer(panel, rx, ry, colW, thRowH, active and C.bg_row_alt or C.bg_row, 200)
            Layer(panel, rx, ry, 3, thRowH, C.accent, 201)
            Layer(panel, rx + 10, ry + thRowH * 0.5 - 8, 16, 16, LC(th.a[1], th.a[2], th.a[3], 1), 300)
            Layer(panel, rx + 8, ry + thRowH * 0.5 - 10, 20, 20, C.border_dark, 299)
            Text(panel, th.name, rx + 34, ry + thRowH * 0.5, 11, active and C.accent_bright or C.text_label, 300, 0, 0.5)
            if active then Text(panel, "ON", rx + colW - 8, ry + thRowH * 0.5, 10, C.accent_bright, 300, 1, 0.5) end
            local idx = i
            MakeBtn(panel, rx, ry, colW, thRowH, 900, function()
                themeIdx = idx
                _G._SDW_ThemeIdx = idx
                ApplyTheme(idx)
                if FloatOpenerClear then FloatOpenerClear() end
                if floatBtn and IV(floatBtn) then pcall(function() floatBtn:RemoveFromParent() end) end
                floatBtn, floatText, floatLogoPanel = nil, nil, nil
                floatGen = -1
                RebuildMenu()
            end)
        end
        local thRows = math.ceil(#THEMES / 2)
        ty = ty + thRows * (thRowH + 4) + 8
        Layer(panel, 0, ty, cw, 1, C.divider_a, 200)
        ty = ty + 8
        -- [SDWxOWNER-PHASE2] Watermark position is HARD-LOCKED to the default (Left-Right)
        -- layout. The UP/LEFT/DOWN/RIGHT nudge buttons + RESET were removed so the watermark
        -- can never be moved or hidden. Only the text SIZE stays adjustable (SETTINGS tab).
        Text(panel, "WATERMARK LOCKED", 14, ty + 8, 11, C.text_dim, 400, 0, 0.5)
        Text(panel, "FIXED POSITION", cw - 14, ty + 8, 11, C.accent_bright, 400, 1, 0.5)

        ty = ty + 30
        Layer(panel, 0, ty, cw, 1, C.divider_a, 200)
        Text(panel, "SDWxOWNER  PREMIUM EDITION  v4.6", cw * 0.5, ty + 18, 13, C.accent, 400, 0.5, 0.5)
        Text(panel, "Key validity: " .. ValidityText(), cw * 0.5, ty + 38, 12, C.text_dim, 400, 0.5, 0.5)
        Text(panel, "User: " .. tostring(_G.USER_KEY or "-"), cw * 0.5, ty + 56, 11, C.text_dim, 400, 0.5, 0.5)
        -- [SDWxOWNER] Key EXPIRY DATE shown directly below the key name (premium crimson pill).
        local ey = ty + 78
        Layer(panel, cw * 0.5 - 118, ey - 11, 236, 22, C.bg_row, 300)
        Layer(panel, cw * 0.5 - 118, ey - 11, 3, 22, C.accent_bright, 301)
        Layer(panel, cw * 0.5 - 118, ey - 11, 236, 1, C.accent_glow, 301)
        themeExpiryText = Text(panel, "EXPIRES:  " .. ExpiryDateText(), cw * 0.5 + 2, ey, 11, C.accent_bright, 302, 0.5, 0.5)
        return
    end

    -- [SDWxOWNER-NEWMENU] Two-column grid (matches the new menu layout).
    local colGap = 14
    local colW = math.floor((cw - colGap) / 2)
    local gridTop = 38
    local rowsPerCol = math.max(1, math.floor((contentH - gridTop - 40) / ROW_H))
    local perPage = rowsPerCol * 2
    local total = #tab.rows
    local pages = math.max(1, math.ceil(total / perPage))
    if activePage > pages then activePage = pages end
    if activePage < 1 then activePage = 1 end
    local from = (activePage - 1) * perPage + 1
    local to = math.min(total, from + perPage - 1)

    -- [SDWxOWNER-ESP CONSOLIDATED] Per-tab fill order. Default is row-major (left/right
    -- alternating). Tabs flagged `columnMajor` fill Column 1 top-to-bottom first, then
    -- Column 2 - used by the consolidated ESP tab so its two columns match the spec.
    local colMajor = (tab.columnMajor == true)
    for i = from, to do
        local spec = tab.rows[i]
        local k = i - from
        local col, r
        if colMajor then
            col = math.floor(k / rowsPerCol)
            r = k % rowsPerCol
            if col > 1 then col = 1 end
        else
            col = k % 2
            r = math.floor(k / 2)
        end
        local rx = col * (colW + colGap)
        local ry = gridTop + r * ROW_H
        local zebra = (i % 2 == 0)
        local row
        if spec.kind == "toggle" then row = BuildToggleRow(panel, spec, rx, ry, colW, ROW_H, zebra)
        elseif spec.kind == "slider" then row = BuildSliderRow(panel, spec, rx, ry, colW, ROW_H, zebra)
        elseif spec.kind == "choice" then row = BuildChoiceRow(panel, spec, rx, ry, colW, ROW_H, zebra) end
        if row then toggleRows[#toggleRows+1] = row end
    end
    local cY = gridTop + rowsPerCol * ROW_H

    if pages > 1 then
        local py = cY + 4
        Layer(panel, 0, py, cw, 32, C.bg_tab, 200)
        Layer(panel, 0, py, cw, 1, C.divider_a, 201)
        Layer(panel, 6, py + 4, 60, 24, C.accent_deep, 299)
        Text(panel, "< PREV", 36, py + 16, 11, C.text_label, 400, 0.5, 0.5)
        MakeBtn(panel, 6, py + 4, 60, 24, 900, function() activePage = activePage - 1; if activePage < 1 then activePage = pages end; BuildContent() end)
        Text(panel, "PAGE " .. activePage .. " / " .. pages, cw * 0.5, py + 16, 11, C.accent_bright, 400, 0.5, 0.5)
        Layer(panel, cw - 66, py + 4, 60, 24, C.accent_deep, 299)
        Text(panel, "NEXT >", cw - 36, py + 16, 11, C.text_label, 400, 0.5, 0.5)
        MakeBtn(panel, cw - 66, py + 4, 60, 24, 900, function() activePage = activePage + 1; if activePage > pages then activePage = 1 end; BuildContent() end)
    end
end

local menuPosX, menuPosY = 18, 60
local menuSlotRef = nil


local function SwitchTab(idx)
    activeTab = idx
    activePage = 1
    for i, tw in ipairs(tabWidgets) do
        local on = (i == idx)
        if tw.bg and IV(tw.bg) then pcall(function() tw.bg:SetBrushColor(on and C.accent_soft or C.transparent) end) end
        SetVis(tw.glow, on and UEnums.ESlateVisibility.SelfHitTestInvisible or UEnums.ESlateVisibility.Collapsed)
        SetVis(tw.accent, on and UEnums.ESlateVisibility.SelfHitTestInvisible or UEnums.ESlateVisibility.Collapsed)
        SetVis(tw.edgeT, on and UEnums.ESlateVisibility.SelfHitTestInvisible or UEnums.ESlateVisibility.Collapsed)
        SetVis(tw.edgeB, on and UEnums.ESlateVisibility.SelfHitTestInvisible or UEnums.ESlateVisibility.Collapsed)
        SetVis(tw.edgeR, on and UEnums.ESlateVisibility.SelfHitTestInvisible or UEnums.ESlateVisibility.Collapsed)
        SetVis(tw.gl, on and UEnums.ESlateVisibility.SelfHitTestInvisible or UEnums.ESlateVisibility.Collapsed)
        SetColor(tw.txt, on and C.white or C.text_label)
        if tw.ic then SetColor(tw.ic, on and C.white or C.text_dim) end
    end
    BuildContent()
end

function RebuildMenu()
    if bgPanel and IV(bgPanel) then pcall(function() bgPanel:RemoveFromParent() end) end
    bgPanel = nil
    menuBuilt = false
    menuOpen = true
    cachedCanvas = nil
    BuildMenu()
end

function BuildMenu()
    if menuBuilt and bgPanel and IV(bgPanel) and IsAttached(bgPanel) then SetVis(bgPanel, UEnums.ESlateVisibility.SelfHitTestInvisible); menuOpen = true; return end
    local canvas = GetCanvas()
    if not canvas then return end

    pcall(function()
        bgPanel = CGame:NewObjectFromPath("/Script/UMG.CanvasPanel", canvas)
        if bgPanel and slua.isValid(bgPanel) then
            local slot = canvas:AddChildToCanvas(bgPanel)
            if slot then
                slot:SetAutoSize(false)
                slot:SetZOrder(10000)
                slot:SetAnchors(AN(0.5, 0.5, 0.5, 0.5))
                slot:SetAlignment(V2(0.5, 0.5))
                slot:SetPosition(V2(0, 0))
                slot:SetSize(V2(M_W, M_H))
                menuSlotRef = slot
            end
        end
    end)
    if not bgPanel or not slua.isValid(bgPanel) then return end

    -- [SDWxOWNER-NEWMENU] Premium frame: soft shadow + DOUBLE neon halo + glossy crimson border.
    Layer(bgPanel, -20, -20, M_W + 40, M_H + 40, C.shadow5, -7)
    Layer(bgPanel, -14, -14, M_W + 28, M_H + 28, C.shadow4, -6)
    Layer(bgPanel, -8, -8, M_W + 16, M_H + 16, C.shadow3, -5)
    Layer(bgPanel, -4, -4, M_W + 8, M_H + 8, C.shadow2, -4)
    Layer(bgPanel, -2, -2, M_W + 4, M_H + 4, C.shadow1, -3)
    Layer(bgPanel, -6, -6, M_W + 12, M_H + 12, C.accent_glow, -3)
    Layer(bgPanel, -3, -3, M_W + 6, M_H + 6, C.accent_glow, -2)
    Layer(bgPanel, -2, -2, M_W + 4, M_H + 4, C.border_blue, -1)
    Layer(bgPanel, -1, -1, M_W + 2, M_H + 2, C.border_glass, 0)
    Layer(bgPanel, 0, 0, M_W, M_H, C.bg_glass, 1)
    -- subtle 3-band vertical gradient (light -> main -> dark) + glossy metallic top edge
    Layer(bgPanel, 0, 0, M_W, M_H * 0.38, C.bg_glass_hi, 1)
    Layer(bgPanel, 0, M_H * 0.72, M_W, M_H * 0.28, C.bg_glass3, 1)
    Layer(bgPanel, 0, 0, M_W, 1, C.glass_top, 2)
    Layer(bgPanel, 0, 1, M_W, 2, C.border_glass, 2)
    Layer(bgPanel, 0, M_H - 4, M_W, 4, LC(0.0, 0.0, 0.0, 0.60), 2)
    Layer(bgPanel, 0, M_H - 3, M_W, 3, LC(0.0, 0.0, 0.0, 0.55), 2)

    -- premium esports corner brackets (L-shaped)
    local cbS = 18
    Layer(bgPanel, 0, 0, cbS, 3, C.corner, 15)
    Layer(bgPanel, 0, 0, 3, cbS, C.corner, 15)
    Layer(bgPanel, M_W - cbS, 0, cbS, 3, C.corner, 15)
    Layer(bgPanel, M_W - 3, 0, 3, cbS, C.corner, 15)
    Layer(bgPanel, 0, M_H - 3, cbS, 3, C.corner, 15)
    Layer(bgPanel, 0, M_H - cbS, 3, cbS, C.corner, 15)
    Layer(bgPanel, M_W - cbS, M_H - 3, cbS, 3, C.corner, 15)
    Layer(bgPanel, M_W - 3, M_H - cbS, 3, cbS, C.corner, 15)

    -- ===== LEFT SIDEBAR (full height, premium - matches the new design) =====
    local sbH = M_H - FOOTER_H
    Layer(bgPanel, 0, 0, SIDEBAR_W, sbH, C.bg_glass2, 2)
    Layer(bgPanel, 0, 0, SIDEBAR_W, sbH * 0.30, C.bg_glass3, 2)
    Layer(bgPanel, 0, 0, SIDEBAR_W, 2, C.border_glass, 3)
    Layer(bgPanel, SIDEBAR_W - 2, 0, 1, sbH, C.border_glass, 3)
    Layer(bgPanel, SIDEBAR_W, 0, 1, sbH, C.accent_glow, 3)
    Layer(bgPanel, SIDEBAR_W + 2, 0, 2, sbH, C.accent_glow, 3)

    -- circular logo (crimson-framed disc + SDWxOWNER wordmark) - replaces the old photo
    local logoSize = math.min(62, SIDEBAR_W - 30)
    local logoX = (SIDEBAR_W - logoSize) * 0.5
    local logoY = 16
    Layer(bgPanel, logoX - 5, logoY - 5, logoSize + 10, logoSize + 10, C.accent_glow, 3)
    Layer(bgPanel, logoX - 1, logoY - 1, logoSize + 2, logoSize + 2, C.accent_deep, 4)
    Layer(bgPanel, logoX, logoY, logoSize, logoSize, C.bg_header, 5)
    Layer(bgPanel, logoX, logoY, logoSize, 2, C.accent, 6)
    Layer(bgPanel, logoX, logoY + logoSize - 2, logoSize, 2, C.accent_dark, 6)
    Text(bgPanel, "SDW", logoX + logoSize * 0.5, logoY + logoSize * 0.5 - 7, 16, C.accent_bright, 7, 0.5, 0.5)
    Text(bgPanel, "OWNER", logoX + logoSize * 0.5, logoY + logoSize * 0.5 + 10, 8, C.white, 7, 0.5, 0.5)

    -- wordmark + rule under the logo
    Text(bgPanel, "SDWxOWNER", SIDEBAR_W * 0.5, logoY + logoSize + 15, 12, C.accent_bright, 8, 0.5, 0.5)
    Layer(bgPanel, SIDEBAR_W * 0.5 - 34, logoY + logoSize + 26, 68, 1, C.divider, 8)

    -- nav items (full-width crimson pill when active)
    tabWidgets = {}
    -- [SDWxOWNER-GLYPH-FIX] Universal, engine-safe glyphs only (Geometric Shapes
    -- block + plain ASCII) so NO tab can ever fall back to a "?" box on iOS/iPad
    -- fonts. Order matches TABS: ESP, WALLHACK, AIMBOT, SETTINGS, SKINS, THEME.
    --   ESP V1=\u25C6  ESP V2=\u25A3  WALLHACK=\u25B6  AIMBOT=\u25CE  EXTRA=\u2726  SKINS=\u25A0  THEME=\u25C8
    local navIcons = { "\u{25C6}", "\u{25A3}", "\u{25B6}", "\u{25CE}", "\u{2726}", "\u{25A0}", "\u{25C8}" }
    local navStartY = logoY + logoSize + 40
    local navAvail = sbH - navStartY - 28
    local navItemH = math.min(NAV_H, math.floor(navAvail / #TABS))
    if navItemH < 34 then navItemH = 34 end
    for i, tab in ipairs(TABS) do
        local iy = navStartY + (i - 1) * navItemH
        local rowH = navItemH - 2
        local on = (i == activeTab)
        -- [SDWxOWNER-NEWMENU] Active tab = sleek glowing crimson OUTLINE (no solid red
        -- block) so the deep matte-black background stays visible behind it.
        local glow = Layer(bgPanel, 0, iy, SIDEBAR_W, rowH, C.accent_glow, 4)
        if not on then SetVis(glow, UEnums.ESlateVisibility.Collapsed) end
        local bg = Layer(bgPanel, 0, iy, SIDEBAR_W, rowH, on and C.accent_soft or C.transparent, 5)
        -- crisp crimson border outline (left / top / bottom / right)
        local acc = Layer(bgPanel, 0, iy, 3, rowH, C.accent_bright, 7)                 -- left edge
        local eT  = Layer(bgPanel, 0, iy, SIDEBAR_W, 2, C.accent_bright, 6)            -- top edge
        local eB  = Layer(bgPanel, 0, iy + rowH - 2, SIDEBAR_W, 2, C.accent_bright, 6) -- bottom edge
        local eR  = Layer(bgPanel, SIDEBAR_W - 2, iy, 2, rowH, C.accent_bright, 6)     -- right edge
        if not on then
            SetVis(acc, UEnums.ESlateVisibility.Collapsed)
            SetVis(eT, UEnums.ESlateVisibility.Collapsed)
            SetVis(eB, UEnums.ESlateVisibility.Collapsed)
            SetVis(eR, UEnums.ESlateVisibility.Collapsed)
        end
        local ic = Text(bgPanel, navIcons[i] or "\u{25C6}", 26, iy + rowH * 0.5, 14, on and C.white or C.text_dim, 8, 0.5, 0.5)
        local gl = Text(bgPanel, tab.name, 48, iy + rowH * 0.5, 13, C.accent_neon, 7, 0, 0.5)
        if not on then SetVis(gl, UEnums.ESlateVisibility.Collapsed) end
        -- [SDWxOWNER-TABFIT] Long names ("ESP V2 & COUNTERS", "EXTRA FEATURES") are auto-fitted
        -- so they can never overflow the 194 px sidebar.
        local _tsz = 13
        local _maxLabel = SIDEBAR_W - 52
        while _tsz > 8 and (#tab.name * _tsz * 0.58) > _maxLabel do _tsz = _tsz - 1 end
        local txt = Text(bgPanel, tab.name, 46, iy + rowH * 0.5, _tsz, on and C.white or C.text_label, 8, 0, 0.5)
        local idx = i
        MakeBtn(bgPanel, 0, iy, SIDEBAR_W, rowH, 900, function() SwitchTab(idx) end)
        tabWidgets[i] = { bg = bg, txt = txt, glow = glow, accent = acc, ic = ic, gl = gl,
                          edgeT = eT, edgeB = eB, edgeR = eR }
    end

    -- sidebar version badge
    Text(bgPanel, "v4.6 PREMIUM", SIDEBAR_W * 0.5, sbH - 14, 10, C.accent_bright, 8, 0.5, 0.5)

    -- ===== CLOSE BUTTON (top-right) =====
    -- [SDWxOWNER-CLOSEFIX] The old X was a 40x40 visual / 42x42 hitbox at y=4..46, which
    -- sat only ~2px above the first option row (y~=48). A tap on the X could therefore also
    -- land on the row's +/- control directly below it (e.g. Suit 49 -> 50). Fixed by:
    --   (1) shrinking the X to a compact 26px button,
    --   (2) nudging it up so its 32x32 hitbox ends at y~=37 (a clear gap above the rows),
    --   (3) giving it a very high z-order (5000) so it ALWAYS wins any overlap with the
    --       row controls (which use z=999) - the X can never leak into the option below.
    local cX, cY = M_W - 42, 8
    Layer(bgPanel, cX - 2, cY - 2, 30, 30, C.accent_deep, 300)
    Layer(bgPanel, cX, cY, 26, 26, C.accent_dark, 301)
    Layer(bgPanel, cX + 2, cY + 2, 22, 22, C.close_bg, 302)
    Layer(bgPanel, cX + 4, cY + 4, 18, 18, C.bg_header, 303)
    Text(bgPanel, "X", cX + 13, cY + 13, 14, C.white, 304, 0.5, 0.5)
    MakeBtn(bgPanel, cX - 3, cY - 3, 32, 32, 5000, function() menuOpen = false; SetVis(bgPanel, UEnums.ESlateVisibility.Collapsed) end)

    local fy = M_H - FOOTER_H
    Layer(bgPanel, 0, fy, M_W, 1, C.accent_deep, 5)
    Layer(bgPanel, 0, fy + 1, M_W, 2, C.accent, 5)
    Layer(bgPanel, 0, fy + 3, M_W, FOOTER_H - 3, C.bg_header, 1)
    Layer(bgPanel, 0, fy + 3, M_W, (FOOTER_H - 3) / 2, C.bg_header2, 1)
    activeText = Text(bgPanel, "ACTIVE: " .. CountActive(), 12, fy + FOOTER_H * 0.5 + 1, 10, C.accent_bright, 400, 0, 0.5)
    Text(bgPanel, "THEME: " .. ((THEMES[themeIdx] and THEMES[themeIdx].name) or ""), M_W * 0.5, fy + FOOTER_H * 0.5 + 1, 10, C.text_label, 400, 0.5, 0.5)
    statusText = Text(bgPanel, "VALID: " .. ValidityText(), M_W - 12, fy + FOOTER_H * 0.5 + 1, 10, C.text_dim, 400, 1, 0.5)

    menuBuilt = IsAttached(bgPanel)
    menuOpen = true
    _G._SDW_MenuPanel = bgPanel
    BuildContent()
end

local function GetViewportSize()
    local w, h = 2400, 1080
    pcall(function()
        local ui_util = require("client.common.ui_util")
        local vp = ui_util and ui_util.GetViewportSize and ui_util.GetViewportSize()
        if vp and vp.X and vp.Y and vp.X > 0 and vp.Y > 0 then w, h = vp.X, vp.Y end
    end)
    return w, h
end

local function FloatOpenerClear()
    for i = 1, #floatOpenerParts do
        local w = floatOpenerParts[i]
        if w and IV(w) then pcall(function() w:RemoveFromParent() end) end
        floatOpenerParts[i] = nil
    end
    -- [FIX] Purge the MASTER registry too (button + small tab + any widget left on
    -- a previous canvas) so a rebuild can never leave a duplicate opener behind.
    for i = 1, #_openerAll do
        local w = _openerAll[i]
        if w and IV(w) then pcall(function() w:RemoveFromParent() end) end
        _openerAll[i] = nil
    end
    floatBtn, floatText, floatLogoPanel = nil, nil, nil
    floatReopenPanel, floatReopenText, floatReopenBtn = nil, nil, nil
    -- [SDWxOWNER-OPENER-ROUND v2] Drop the reopen strip group too (its widgets were
    -- already RemoveFromParent'd by the _openerAll sweep above).
    _G.SDW_ReopenParts = nil
end
local function FloatOpenerVis(vis)
    for i = 1, #floatOpenerParts do
        local w = floatOpenerParts[i]
        if w and IV(w) then pcall(function() w:SetWidgetVisibility(vis) end) end
    end
end
local function FloatOpenerAdd(w)
    if w then
        floatOpenerParts[#floatOpenerParts + 1] = w
        _openerAll[#_openerAll + 1] = w
    end
    return w
end

-- [SDWxOWNER-OPENER-ROUND] V5-style rounded geometry for the menu opener.
-- The V5 enemy counter draws its capsule as a stack of horizontal scanline strips whose
-- left/right insets follow a circular arc (see _v5RoundStrips). The opener used to be a
-- plain rectangle (Border) with straight accent lines, so it looked boxy next to the V5
-- counter. These two helpers reproduce the SAME arc maths in canvas units, so the opener
-- now has identical round edges. Purely cosmetic: same size, same position, same hit area,
-- same z-order band, same click handler -- only the silhouette changes.
-- NOTE: stored on _G (not as locals) because this chunk is already at the LuaJIT 200-local
-- ceiling; a global costs zero local slots and keeps the build compiling.
function _G.SDW_OpenerRoundStrips(w, h, r, k)
    local s = {}
    if r > h * 0.5 then r = h * 0.5 end
    if r < 0 then r = 0 end
    for i = 0, k - 1 do
        local y0 = r * i / k
        local y1 = r * (i + 1) / k
        local ym = (y0 + y1) * 0.5
        local dy = r - ym
        local ins = r - math.sqrt(math.max(0, r * r - dy * dy))
        s[#s + 1] = { x1 = ins, y1 = y0, x2 = w - ins, y2 = y1 }
    end
    s[#s + 1] = { x1 = 0, y1 = r, x2 = w, y2 = h - r }
    for i = 0, k - 1 do
        local y0 = (h - r) + r * i / k
        local y1 = (h - r) + r * (i + 1) / k
        local ym = (y0 + y1) * 0.5
        local dy = ym - (h - r)
        local ins = r - math.sqrt(math.max(0, r * r - dy * dy))
        s[#s + 1] = { x1 = ins, y1 = y0, x2 = w - ins, y2 = y1 }
    end
    return s
end

-- Draws one rounded rect out of strips and registers every strip with the opener registry
-- (so FloatOpenerClear / FloatOpenerVis still manage them). `ov` is a tiny vertical overlap
-- that hides sub-pixel seams between strips; keep it 0 for translucent layers so the alpha
-- does not double-blend into visible bands.
-- [SDWxOWNER-OPENER-ROUND v2] `group`: when given, the strips are collected into THAT table
-- instead of floatOpenerParts. Needed because the small "SDW" reopen tab is now MANY strips
-- (not one Border), so it must be hidden/shown as a GROUP. Previously only the first strip
-- was collapsed and the other ~17 stayed visible ON TOP of the big button -> a black block
-- covered the "SDW" part of the opener text (the "text ke upar black" bug).
function _G.SDW_OpenerRound(parent, x, y, w, h, r, color, z, k, ov, group)
    local main = nil
    local strips = _G.SDW_OpenerRoundStrips(w, h, r, k or 8)
    local grow = ov or 0
    for i = 1, #strips do
        local st = strips[i]
        local sw = st.x2 - st.x1
        local sh = (st.y2 - st.y1) + grow
        if sw > 0.4 and sh > 0 then
            local b = Layer(parent, x + st.x1, y + st.y1, sw, sh, color, z)
            if b then
                if group then
                    group[#group + 1] = b
                    -- Still register in the master list so FloatOpenerClear's sweep can
                    -- RemoveFromParent it (otherwise the reopen strips would leak).
                    _openerAll[#_openerAll + 1] = b
                else
                    FloatOpenerAdd(b)
                end
                if not main then main = b end
            end
        end
    end
    return main
end

-- Show / hide a whole rounded-rect group (reopen tab).
function _G.SDW_OpenerGroupVis(group, vis)
    if not group then return end
    for i = 1, #group do
        local w = group[i]
        if w and IV(w) then pcall(function() w:SetWidgetVisibility(vis) end) end
    end
end

local function CreateFloat(forceCanvas)
    if floatBtn and IV(floatBtn) and IsAttached(floatBtn) then return end
    -- [FIX] Purge the previous opener (button + visual parts + small tab) BEFORE building a new one.
    FloatOpenerClear()
    floatBtn, floatText = nil, nil
    pcall(function()
        local canvas = forceCanvas or GetCanvas()
        if not canvas then return end
        floatCanvas = canvas
        -- [SDWxOWNER-OPENER-CLASSIC] ORIGINAL flat rectangular opener, ORIGINAL size
        -- (122 x 34) and ORIGINAL position (58, 62). The bar is NOT widened -- the label is
        -- auto-fitted to the 122 px width instead, so it fits exactly like before.
        local fW, fH = 122, 34
        local fX, fY = 58, 62
        local oZ = 12000

        FloatOpenerAdd(Layer(canvas, fX + 2, fY + 2, fW, fH, C.shadow1, oZ))
        floatLogoPanel = FloatOpenerAdd(Layer(canvas, fX, fY, fW, fH, C.bg_header2, oZ + 1))
        FloatOpenerAdd(Layer(canvas, fX, fY, fW, 2, C.accent, oZ + 2))
        FloatOpenerAdd(Layer(canvas, fX, fY + fH - 2, fW, 2, C.accent_dark, oZ + 2))
        FloatOpenerAdd(Layer(canvas, fX, fY, 4, fH, C.accent, oZ + 3))
        FloatOpenerAdd(Layer(canvas, fX + 4, fY, 1, fH, C.accent_bright, oZ + 3))

        -- [SDWxOWNER-OPENER-TEXT] Label is the Telegram handle. The bar stays at its ORIGINAL
        -- 122 px width, so the font is AUTO-FITTED to that width: start at 15 and shrink until
        -- the estimated advance fits inside fW - 12 px. Result at 122 px: font 11 -- the whole
        -- handle sits inside the bar with a small margin on each side. No clipping, no wrap.
        local OPENER_TXT = "TG :- @SDWxOWNER"
        local _fit = 15
        local _maxW = fW - 12
        while _fit > 8 and (#OPENER_TXT * _fit * 0.58) > _maxW do _fit = _fit - 1 end
        floatText = FloatOpenerAdd(Text(canvas, OPENER_TXT, fX + fW * 0.5, fY + fH * 0.5, _fit, C.white, oZ + 4, 0.5, 0.5))
        pcall(function()
            if floatText and IV(floatText) then
                -- Never wrap: a wrapped label would push the second line outside the bar.
                if floatText.SetAutoWrapText then floatText:SetAutoWrapText(false) end
                if floatText.SetShadowOffset then floatText:SetShadowOffset(V2(1.5, 1.5)) end
                if floatText.SetShadowColorAndOpacity then floatText:SetShadowColorAndOpacity(C.shadow1) end
            end
        end)

        floatBtn = _openerTrack(MakeBtn(canvas, fX, fY, fW, fH, oZ + 5, function()
            if not _G.LOGIN_OK then return end
            if not menuBuilt or not (bgPanel and IV(bgPanel) and IsAttached(bgPanel)) then
                BuildMenu()
            else
                if menuOpen then menuOpen = false; SetVis(bgPanel, UEnums.ESlateVisibility.Collapsed)
                else menuOpen = true; SetVis(bgPanel, UEnums.ESlateVisibility.SelfHitTestInvisible) end
            end
        end))

        -- [FIX] Small "SDW" reopen tab.
        local rW, rH = 46, 22
        local rX, rY = 58, 62
        floatReopenPanel = _openerTrack(Layer(canvas, rX, rY, rW, rH, C.bg_header2, oZ + 6))
        floatReopenText  = _openerTrack(Text(canvas, "SDW", rX + rW * 0.5, rY + rH * 0.5, 13, C.white, oZ + 7, 0.5, 0.5))
        floatReopenBtn = _openerTrack(MakeBtn(canvas, rX, rY, rW, rH, oZ + 8, function()
            _G.SDWConfig.MenuOpenerEnabled = true
            if _G.SaveSDWConfig then pcall(_G.SaveSDWConfig) end
        end))
        -- [FIX] Hidden by default so it can never flash / show alongside the big
        -- opener. Tick shows it ONLY when the big opener is toggled OFF.
        -- [SDWxOWNER] Registered as a group so "Menu Opener Hide" can collapse it atomically.
        _G.SDW_ReopenParts = { floatReopenPanel }
        SetVis(floatReopenPanel, UEnums.ESlateVisibility.Collapsed)
        SetVis(floatReopenText, UEnums.ESlateVisibility.Collapsed)
        SetVis(floatReopenBtn, UEnums.ESlateVisibility.Collapsed)
    end)
    _G._SDW_FloatBtn = floatBtn
end

local function Tick()
    -- [SDWxOWNER-iOS] Never build/refresh the menu widgets while the game is still on the
    -- loading screen — creating UMG widgets during loading is a native crash on iOS.
    local _sdwReady = false
    pcall(function() _sdwReady = _G.SDW_LoginReady and _G.SDW_LoginReady() end)
    if not _sdwReady then return end

    -- [SDWxOWNER-PERF] De-duplicate the menu refresh.
    local _nowTick = os.clock()
    if _G._SDW_MenuTickLast and (_nowTick - _G._SDW_MenuTickLast) < 0.85 then return end
    _G._SDW_MenuTickLast = _nowTick

    if not _G.LOGIN_OK then
        if floatBtn and IV(floatBtn) then pcall(function() floatBtn:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end) end
        if floatText and IV(floatText) then pcall(function() floatText:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end) end
        if floatLogoPanel and IV(floatLogoPanel) then pcall(function() floatLogoPanel:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end) end
        FloatOpenerVis(UEnums.ESlateVisibility.Collapsed)
        -- [FIX] Keep the small reopen tab hidden during login too (it used to stay
        -- visible here because this early-return block never collapsed it).
        if floatReopenPanel and IV(floatReopenPanel) then pcall(function() floatReopenPanel:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end) end
        if floatReopenText and IV(floatReopenText) then pcall(function() floatReopenText:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end) end
        if floatReopenBtn and IV(floatReopenBtn) then pcall(function() floatReopenBtn:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end) end
        if bgPanel and IV(bgPanel) then SetVis(bgPanel, UEnums.ESlateVisibility.Collapsed) end
        return
    end
    pcall(function()
        local pc = slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController()
        if pc and IV(pc) and pc.AddGameTimer and _G._SDW_MenuTimerPC ~= pc then
            _G._SDW_MenuTimerPC = pc
            pcall(pc.AddGameTimer, pc, 3, true, function() if _menuToken == _G._SDW_MenuLoadToken then pcall(Tick) end end)
        end
    end)
    local gen = _G._SDW_MatchGen or 0
    local liveCanvas = GetCanvas(true)
    local floatStale = (not floatBtn) or (not IV(floatBtn)) or (not IsAttached(floatBtn))
        or (not floatLogoPanel) or (not IV(floatLogoPanel)) or (not IsAttached(floatLogoPanel))
        or (floatGen ~= gen)
        or (liveCanvas and floatCanvas and floatCanvas ~= liveCanvas)
    local panelStale = (not bgPanel) or (not IV(bgPanel)) or (not IsAttached(bgPanel)) or (menuGen ~= gen)
        or (liveCanvas and menuCanvas and menuCanvas ~= liveCanvas)
    if liveCanvas then
        if floatStale or panelStale then
            if bgPanel and IV(bgPanel) then pcall(function() bgPanel:RemoveFromParent() end) end
            bgPanel = nil; menuBuilt = false
            if floatBtn and IV(floatBtn) then pcall(function() floatBtn:RemoveFromParent() end) end
            if floatLogoPanel and IV(floatLogoPanel) then pcall(function() floatLogoPanel:RemoveFromParent() end) end
            if floatReopenBtn and IV(floatReopenBtn) then pcall(function() floatReopenBtn:RemoveFromParent() end) end
            if floatReopenPanel and IV(floatReopenPanel) then pcall(function() floatReopenPanel:RemoveFromParent() end) end
            if floatReopenText and IV(floatReopenText) then pcall(function() floatReopenText:RemoveFromParent() end) end
            FloatOpenerClear()
            floatBtn, floatText, floatLogoPanel = nil, nil, nil
            floatReopenBtn, floatReopenText, floatReopenPanel = nil, nil, nil
            floatCanvas = nil
            cachedCanvas = nil
        end
        menuGen = gen
        if not floatBtn or not IV(floatBtn) or not IsAttached(floatBtn) then
            CreateFloat(liveCanvas)
            if floatBtn and IV(floatBtn) and IsAttached(floatBtn) then floatGen = gen; floatCanvas = liveCanvas end
        end
        if menuOpen and (not menuBuilt or not bgPanel or not IV(bgPanel) or not IsAttached(bgPanel)) then
            pcall(BuildMenu)
            if menuBuilt then menuCanvas = liveCanvas end
        end
    end
    -- [FIX] Menu Opener ON/OFF toggle (EXTRA FEATURES -> "Menu Opener Decrease Size").
    -- [SDWxOWNER] "Menu Opener Hide" (MenuOpenerHidden) FULLY hides the opener: the big
    -- button, its visual parts AND the small "SDW" reopen tab. It can only be brought back
    -- from the opener settings (native Settings menu -> ModMenu -> "Menu Opener Hide" OFF).
    local _openerHidden = (_G.SDWConfig and _G.SDWConfig.MenuOpenerHidden == true)
    local _openerOn = not (_G.SDWConfig and _G.SDWConfig.MenuOpenerEnabled == false)
    if _openerHidden then
        if floatBtn and IV(floatBtn) then pcall(function() floatBtn:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end) end
        if floatText and IV(floatText) then pcall(function() floatText:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end) end
        if floatLogoPanel and IV(floatLogoPanel) then pcall(function() floatLogoPanel:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end) end
        FloatOpenerVis(UEnums.ESlateVisibility.Collapsed)
        _G.SDW_OpenerGroupVis(_G.SDW_ReopenParts, UEnums.ESlateVisibility.Collapsed)
        if floatReopenPanel and IV(floatReopenPanel) then pcall(function() floatReopenPanel:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end) end
        if floatReopenText and IV(floatReopenText) then pcall(function() floatReopenText:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end) end
        if floatReopenBtn and IV(floatReopenBtn) then pcall(function() floatReopenBtn:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end) end
    else
    if floatBtn and IV(floatBtn) then pcall(function() floatBtn:SetWidgetVisibility(UEnums.ESlateVisibility.Visible) end) end
    if floatText and IV(floatText) then pcall(function() floatText:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible) end) end
    if floatLogoPanel and IV(floatLogoPanel) then pcall(function() floatLogoPanel:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible) end) end
    FloatOpenerVis(UEnums.ESlateVisibility.SelfHitTestInvisible)
    if _openerOn then
        _G.SDW_OpenerGroupVis(_G.SDW_ReopenParts, UEnums.ESlateVisibility.Collapsed)
        if floatReopenPanel and IV(floatReopenPanel) then pcall(function() floatReopenPanel:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end) end
        if floatReopenText and IV(floatReopenText) then pcall(function() floatReopenText:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end) end
        if floatReopenBtn and IV(floatReopenBtn) then pcall(function() floatReopenBtn:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end) end
    else
        if floatBtn and IV(floatBtn) then pcall(function() floatBtn:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end) end
        if floatText and IV(floatText) then pcall(function() floatText:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end) end
        if floatLogoPanel and IV(floatLogoPanel) then pcall(function() floatLogoPanel:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end) end
        FloatOpenerVis(UEnums.ESlateVisibility.Collapsed)
        _G.SDW_OpenerGroupVis(_G.SDW_ReopenParts, UEnums.ESlateVisibility.SelfHitTestInvisible)
        if floatReopenPanel and IV(floatReopenPanel) then pcall(function() floatReopenPanel:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible) end) end
        if floatReopenText and IV(floatReopenText) then pcall(function() floatReopenText:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible) end) end
        if floatReopenBtn and IV(floatReopenBtn) then pcall(function() floatReopenBtn:SetWidgetVisibility(UEnums.ESlateVisibility.Visible) end) end
    end
    end
    if menuBuilt and bgPanel and IV(bgPanel) and menuOpen then
        for _, row in ipairs(toggleRows) do
            if row.kind == "toggle" then RefreshRow(row)
            elseif row.valText and IV(row.valText) then
                local ok, v = pcall(row.spec.get)
                if ok and v ~= nil then
                    if row.kind == "slider" then
                        -- [SDWxOWNER] honour the optional `display` formatter (e.g. "CHEST")
                        -- instead of always printing the raw number.
                        local txt = nil
                        if row.spec.display then
                            local ok2, s = pcall(row.spec.display, v)
                            if ok2 and s ~= nil then txt = tostring(s) end
                        end
                        SetText(row.valText, txt or tostring(math.floor((tonumber(v) or 0) + 0.5)))
                        if row.paintSlider then pcall(row.paintSlider) end
                    elseif row.kind == "choice" then
                        local opts = row.spec.opts; local n = #opts; local vi
                        local vals = row.spec.vals
                        if vals then
                            vi = 1
                            for i = 1, n do if vals[i] == v then vi = i break end end
                        else
                            vi = tonumber(v) or 1
                            if vi < 1 then vi = 1 end; if vi > n then vi = n end
                        end
                        SetText(row.valText, opts[vi])
                        if row.paintSlider then pcall(row.paintSlider) end
                    end
                end
            end
        end
        RefreshStatus()
    end
end

local function MenuDriver()
    if _menuToken ~= _G._SDW_MenuLoadToken then return end
    pcall(Tick)
    pcall(function()
        local ok, t = pcall(require, "common.time_ticker")
        if ok and t and t.AddTimerOnce then t.AddTimerOnce(1.0, MenuDriver) end
    end)
end

pcall(function()
    -- [SDWxOWNER-iOS] CreateFloat() builds the floating opener widget — never do that
    -- during the loading screen (native crash on iOS). Defer until the game is ready.
    local _menuReady = false
    pcall(function() _menuReady = _G.SDW_LoginReady and _G.SDW_LoginReady() end)
    if _menuReady then
        pcall(CreateFloat)
    else
        local function _deferredFloat()
            local r = false
            pcall(function() r = _G.SDW_LoginReady and _G.SDW_LoginReady() end)
            if r then pcall(CreateFloat) return end
            pcall(function()
                local t = require("common.time_ticker")
                if t and t.AddTimerOnce then t.AddTimerOnce(1.0, _deferredFloat) end
            end)
        end
        pcall(_deferredFloat)
    end
    local g = _G.Game or Game
    if not (g and g.AddGameTimer) then
        pcall(function() g = slua_GameFrontendHUD and slua_GameFrontendHUD:GetGameInstance() end)
    end
    if g and g.AddGameTimer then
        pcall(g.AddGameTimer, g, 1.0, true, function() if _menuToken == _G._SDW_MenuLoadToken then pcall(Tick) end end)
    end
    local pc = slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController()
    if pc and IV(pc) and pc.AddGameTimer then
        _G._SDW_MenuTimerPC = pc
        pcall(pc.AddGameTimer, pc, 3, true, function() if _menuToken == _G._SDW_MenuLoadToken then pcall(Tick) end end)
    end
    pcall(MenuDriver)
    pcall(function()
        local function menuDriverD()
            if _menuToken ~= _G._SDW_MenuLoadToken then return end
            if not _G.LOGIN_OK then return end
            pcall(Tick)
            pcall(function()
                local t = require("timer")
                if t and t.SetGameTimer then t.SetGameTimer(1.0, false, menuDriverD); return end
                local tt = require("common.time_ticker")
                if tt and tt.AddTimerOnce then tt.AddTimerOnce(1.0, menuDriverD) end
            end)
        end
        pcall(menuDriverD)
    end)
end)

_G.SDW_MenuTick = Tick
_G.SDW_MenuRebuild = RebuildMenu
end

do
    -- [SDWxOWNER-CRASH FIX] Watermark state is kept on the GLOBAL table so it survives the
    -- per-match module re-load. Previously `local WM` was recreated fresh on the 2nd match, so
    -- the old widget was orphaned (leaked) and a NEW one was stacked on top of it -> the
    -- "TELEGRAM :- @SDWxOWNER" watermark appeared DOUBLED / doubled-doubled on match 2.
    local WM = _G._SDW_WM
    if not WM then
        WM = { Widget = nil, Slot = nil, Gen = -1, All = {} }
        _G._SDW_WM = WM
    end
    -- [SDWxOWNER-FIX] Forward-declare so the earlier nudge/reset functions can call them
    -- (they previously captured a nil global -> watermark only moved on next tick).
    local WM_ApplyLayout
    local WM_GetSlot

    local function WM_FontSize()
        local s = tonumber(_G.SDWConfig and _G.SDWConfig.WatermarkFontSize) or 14
        if s < 8 then s = 8 elseif s > 30 then s = 30 end
        return math.floor(s + 0.5)
    end

    -- [SDWxOWNER] Watermark style: same look as the text counter (no outline, no
    -- shadow, no letter-spacing) with an adjustable font size.
    local function WM_Style(txt)
        if not (txt and slua.isValid(txt)) then return end
        local FLinearColor = import("LinearColor") or _G.FLinearColor
        local FSlateColor = import("SlateColor") or _G.FSlateColor
        local FVector2D = import("Vector2D") or _G.FVector2D
        pcall(function() txt:SetText("TELEGRAM :- @SDWxOWNER") end)
        -- [SDWxOWNER-FIX] Never let the TextBlock auto-wrap.
        pcall(function() if txt.SetAutoWrapText then txt:SetAutoWrapText(false) end end)
        pcall(function() txt.AutoWrapText = false end)
        pcall(function() if txt.SetWrappingPolicy then txt:SetWrappingPolicy(0) end end)
        local yellow = (FLinearColor and FLinearColor(1.0, 0.92, 0.05, 1.0)) or { R = 255, G = 235, B = 13, A = 255 }
        if FSlateColor then
            pcall(function() txt:SetColorAndOpacity(FSlateColor(yellow)) end)
        else
            pcall(function() txt:SetColorAndOpacity(yellow) end)
        end
        pcall(function()
            local fi = txt.Font
            if fi then
                -- [SDWxOWNER-FIX] Text-based like the HUD counter: keep the default font (no custom FontObject).
                fi.Size = WM_FontSize()
                if fi.OutlineSettings then
                    fi.OutlineSettings.OutlineSize = 0
                    if FLinearColor then pcall(function() fi.OutlineSettings.OutlineColor = FLinearColor(0, 0, 0, 0) end) end
                    pcall(function() fi.OutlineSettings.bApplyOutlineToDropShadows = false end)
                end
                pcall(function() fi.LetterSpacing = 0 end)
                txt:SetFont(fi)
            end
        end)
        if FLinearColor then pcall(function() txt:SetShadowColorAndOpacity(FLinearColor(0, 0, 0, 0)) end) end
        if FVector2D then pcall(function() txt:SetShadowOffset(FVector2D(0, 0)) end) end
        pcall(function()
            local J = nil
            if UEnums and UEnums.ETextJustify then J = UEnums.ETextJustify.Center or UEnums.ETextJustify["Center"] end
            if J == nil then J = 1 end
            if txt.SetJustification then txt:SetJustification(J) end
            txt.Justification = J
        end)
        pcall(function() txt:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible) end)
    end

    -- [SDWxOWNER] Live font-size update from the menu (no match restart needed).
    function _G.SDW_ApplyWatermarkSize()
        pcall(function()
            if WM.Widget and slua.isValid(WM.Widget) then WM_Style(WM.Widget) end
        end)
    end

    -- [SDWxOWNER] Move the watermark by (dx,dy) pixels and re-apply the layout live.
    function _G.SDW_NudgeWatermark(dx, dy)
        pcall(function()
            local c = _G.SDWConfig
            if not c then return end
            c.WatermarkOffsetX = (tonumber(c.WatermarkOffsetX) or 0) + (tonumber(dx) or 0)
            c.WatermarkOffsetY = (tonumber(c.WatermarkOffsetY) or 0) + (tonumber(dy) or 0)
            if WM.Widget and slua.isValid(WM.Widget) then
                if not (WM.Slot and WM.Slot.SetPosition) then WM.Slot = WM_GetSlot(WM.Widget, nil) end
                WM_ApplyLayout(WM.Slot)
            end
        end)
    end

    -- [SDWxOWNER] Set the watermark offset to an absolute (x,y) and re-apply the layout
    -- live. Used by the "Watermark X/Y Offset" sliders (native + custom menus).
    function _G.SDW_SetWatermarkOffset(x, y)
        pcall(function()
            local c = _G.SDWConfig
            if not c then return end
            if x ~= nil then c.WatermarkOffsetX = tonumber(x) or 0 end
            if y ~= nil then c.WatermarkOffsetY = tonumber(y) or 0 end
            if WM.Widget and slua.isValid(WM.Widget) then
                if not (WM.Slot and WM.Slot.SetPosition) then WM.Slot = WM_GetSlot(WM.Widget, nil) end
                WM_ApplyLayout(WM.Slot)
            end
        end)
    end

    -- [SDWxOWNER] Reset the watermark back to its default position.
    function _G.SDW_ResetWatermarkPos()
        pcall(function()
            local c = _G.SDWConfig
            if c then c.WatermarkOffsetX = 0; c.WatermarkOffsetY = 0 end
            if WM.Widget and slua.isValid(WM.Widget) then
                if not (WM.Slot and WM.Slot.SetPosition) then WM.Slot = WM_GetSlot(WM.Widget, nil) end
                WM_ApplyLayout(WM.Slot)
            end
        end)
    end

    -- [SDWxOWNER] Current watermark offset (used by the THEME tab readout).
    function _G.SDW_GetWatermarkOffset()
        local c = _G.SDWConfig
        return (c and tonumber(c.WatermarkOffsetX)) or 0, (c and tonumber(c.WatermarkOffsetY)) or 0
    end

    -- [SDWxOWNER] Force a re-position of the watermark (used by the THEME tab sliders).
    function _G.SDW_RepositionWatermark()
        pcall(function()
            if WM.Widget and slua.isValid(WM.Widget) then pcall(function() WM.Widget:RemoveFromParent() end) end
            WM.Widget = nil
            WM.Slot = nil
            WM.Gen = -1
            if _G.SDW_EnsurePaidWatermark then pcall(_G.SDW_EnsurePaidWatermark) end
        end)
    end

    local function WM_GetCanvas()
        local canvas = nil
        pcall(function()
            local InGameUITools = require("GameLua.Mod.BaseMod.Common.UI.InGameUITools")
            local MCB = InGameUITools and InGameUITools.GetMainControlBaseUI and InGameUITools.GetMainControlBaseUI()
            if MCB and slua.isValid(MCB) then
                if MCB.CanvasPanel_0 and slua.isValid(MCB.CanvasPanel_0) then canvas = MCB.CanvasPanel_0
                elseif MCB.CanvasPanel_42 and slua.isValid(MCB.CanvasPanel_42) then canvas = MCB.CanvasPanel_42 end
            end
        end)
        return canvas
    end

    -- [SDWxOWNER] Apply the bottom-right layout to the watermark's canvas slot.
    -- [SDWxOWNER-ZEROLAG] ONLY the import()/require() lookups are cached now. The geometry
    -- code below is the ORIGINAL, byte-for-byte: same targetX/targetY (vp*0.92 / vp*0.94),
    -- same AbsoluteToLocal conversion, same hardcoded offsets (168 / 26), same SetSize /
    -- SetPosition calls on EVERY frame. So the watermark lands in EXACTLY the same place it
    -- always did -- nothing about its position or size changed.
    local _wmFVec2D, _wmFAnchors, _wmSBL, _wmUIUtil = nil, nil, nil, nil

    WM_ApplyLayout = function(slot)
        if not (slot and slot.SetPosition) then return end
        pcall(function()
            -- ---- one-time import/require resolution (cached forever; pure lookups) ----
            if not _wmFVec2D then
                _wmFVec2D = import("Vector2D") or _G.FVector2D
                _wmFAnchors = import("Anchors") or _G.FAnchors
                _wmSBL = import("SlateBlueprintLibrary") or import("/Script/UMG.SlateBlueprintLibrary")
            end
            local FVector2D = _wmFVec2D
            local FAnchors = _wmFAnchors
            local SBL = _wmSBL
            if not _wmUIUtil then
                _wmUIUtil = package.loaded["client.common.ui_util"] or require("client.common.ui_util")
            end
            local ui_util = _wmUIUtil

            -- [SDWxOWNER-FIX] Fixed-size box + bottom-right anchors (mirrors the working on-screen text counter).
            if slot.SetAutoSize then pcall(function() slot:SetAutoSize(false) end) end
            if FAnchors and slot.SetAnchors then pcall(function() slot:SetAnchors(FAnchors(1.0, 1.0, 1.0, 1.0)) end) end
            -- Bottom-right alignment => the widget's pivot sits at its own
            -- bottom-right, so the position marks the widget's bottom-right.
            if FVector2D then slot:SetAlignment(FVector2D(1.0, 1.0)) end
            local _wmFS = WM_FontSize()
            if FVector2D and slot.SetSize then pcall(function() slot:SetSize(FVector2D(math.max(360, _wmFS * 26), math.max(26, _wmFS * 2.6))) end) end
            slot:SetZOrder(9999)
            -- [SDWxOWNER-FIX] Mirror the SDWxOWNER WM_Place exactly.
            local vp = ui_util and ui_util.GetViewportSize and ui_util.GetViewportSize()
            if not (vp and FVector2D and vp.X and vp.Y) then return end
            local targetX = vp.X * 0.92
            local targetY = vp.Y * 0.94
            local parentCanvas = WM.Widget and WM.Widget.GetParent and WM.Widget:GetParent()
            if parentCanvas and slua.isValid(parentCanvas) then
                local cg = parentCanvas:GetCachedGeometry()
                if cg and SBL and SBL.AbsoluteToLocal then
                    local pt = SBL.AbsoluteToLocal(cg, FVector2D(targetX, targetY))
                    if pt then targetX, targetY = pt.X, pt.Y end
                end
            end
            -- [SDWxOWNER-PHASE2] Watermark position is HARD-LOCKED to the default (Left-Right)
            -- layout (X 168, Y 26). The offsets are hardcoded here so no saved config, slider,
            -- or THEME D-pad nudge can ever drag the watermark off-screen to hide it.
            local offX = _G.SDW_WM_DEF_X or 168
            local offY = _G.SDW_WM_DEF_Y or 26
            slot:SetPosition(FVector2D(targetX + offX, targetY + offY))
        end)
    end

    -- [SDWxOWNER] Resolve the REAL canvas slot for a widget (AddChildToCanvas's return
    -- is NOT a canvas slot in this binding -> SetPosition was a silent no-op).
    WM_GetSlot = function(widget, fallback)
        local slot = nil
        pcall(function()
            local WLL = import("WidgetLayoutLibrary") or import("/Script/UMG.WidgetLayoutLibrary")
            if WLL and WLL.SlotAsCanvasSlot then slot = WLL.SlotAsCanvasSlot(widget) end
        end)
        if not slot then slot = fallback end
        if not slot then pcall(function() slot = widget.Slot end) end
        return slot
    end

    function _G.SDW_EnsurePaidWatermark()
        pcall(function()
            -- [SDWxOWNER-PHASE2] Hard-lock: the watermark can never be disabled. Force the
            -- flag true on every ensure so no external write can turn it off.
            if _G.SDWConfig then _G.SDWConfig.WatermarkEnabled = true end
            local gen = _G._SDW_MatchGen or 0
            if WM.Widget and slua.isValid(WM.Widget) and WM.Gen == gen then
                -- Already alive for this match: keep it visible and RE-PIN it to the bottom-right every tick.
                pcall(function() WM.Widget:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible) end)
                if not (WM.Slot and WM.Slot.SetPosition) then WM.Slot = WM_GetSlot(WM.Widget, nil) end
                WM_ApplyLayout(WM.Slot)
                return
            end
            if WM.Gen ~= gen then WM.Widget = nil; WM.Slot = nil end

            -- Destroy any stale instances so we always keep exactly ONE clean watermark widget.
            if WM.All then
                for i = 1, #WM.All do
                    local w = WM.All[i]
                    pcall(function() if w and slua.isValid(w) and w.RemoveFromParent then w:RemoveFromParent() end end)
                end
            end
            WM.All = {}

            -- [SDWxOWNER] Same parent canvas the OLD watermark used (the full-screen
            -- main canvas) so the position is the OLD bottom-right spot again.
            local ParentCanvas = WM_GetCanvas()
            if not ParentCanvas then return end

            local txt = nil
            pcall(function()
                local cg = rawget(_G, "CGame") or import("CGame")
                if cg and cg.NewObjectFromPath then txt = cg:NewObjectFromPath("/Script/UMG.TextBlock", ParentCanvas) end
            end)
            if not txt or not slua.isValid(txt) then return end

            WM_Style(txt)

            -- [SDWxOWNER-FIX] Add the widget to the main canvas, then pin it bottom-right (absolute positioning).
            local addedSlot = ParentCanvas:AddChildToCanvas(txt)
            -- Get the REAL canvas slot the SAME way the counter widget does:
            -- WidgetLayoutLibrary.SlotAsCanvasSlot(widget).
            local slot = WM_GetSlot(txt, addedSlot)
            WM.Slot = slot
            WM.Widget = txt
            WM.Gen = gen
            WM_ApplyLayout(slot)
            if WM.All then WM.All[#WM.All + 1] = txt end
        end)
    end

    -- [SDWxOWNER-CRASH FIX] Explicit watermark teardown. Called from the match-change reset so
    -- the old widget is removed from its parent BEFORE the next match builds a fresh one. Without
    -- this the orphan widget survived the map change and the new one stacked on it (the doubling).
    function _G.SDW_DestroyWatermark()
        pcall(function()
            local W = _G._SDW_WM
            if not W then return end
            if W.All then
                for i = 1, #W.All do
                    local w = W.All[i]
                    if w and slua.isValid(w) and w.RemoveFromParent then pcall(function() w:RemoveFromParent() end) end
                end
            end
            if W.Widget and slua.isValid(W.Widget) and W.Widget.RemoveFromParent then pcall(function() W.Widget:RemoveFromParent() end) end
            W.Widget = nil; W.Slot = nil; W.Gen = -1; W.All = {}
        end)
    end

    -- [SDWxOWNER-CRASH FIX] Idempotent MainLoop hook: wrap _G.MainLoop only ONCE. On every match
    -- the module re-loads and used to wrap _G.MainLoop AGAIN (each wrapper calling the previous),
    -- so the chain grew by one layer per match and SDW_EnsurePaidWatermark ran N times per frame.
    local _origMainLoop = _G.MainLoop
    -- [SDWxOWNER-FIX] _G.MainLoop is a FUNCTION, so `_origMainLoop._sdwWMHook` threw
    -- "attempt to index a function value" and aborted the rest of the module. Guard with
    -- type() + a global flag instead (same single-wrap behaviour, no crash).
    if type(_origMainLoop) == "function" and not _G._sdwWMHookInstalled then
        _G._sdwWMHookInstalled = true
        local function _sdwMainLoopWMHook(...)
            local a, b = _origMainLoop(...)
            pcall(_G.SDW_EnsurePaidWatermark)
            return a, b
        end
        _G.MainLoop = _sdwMainLoopWMHook
    end
end




-- [SDWxOWNER-4.6 CLEAN] End of feature + menu module (the injector declares the class).
end
__SDW_ModMain()

